/* TOEIC単語帳 1500語（ref/toeic-words.js から tools/convert.js で生成） */
const WORDS = [{"set":1,"word":"invoice","pos":"名詞","meaning":"請求書","example":"Please pay the attached invoice within thirty days of receiving it.","exampleJa":"添付の請求書は、受領後30日以内にお支払いください。","hint":"月末に取引先へ送り、支払いを求める紙。pay an invoice / issue an invoice のセットで覚える"},{"set":1,"word":"deadline","pos":"名詞","meaning":"締め切り","example":"The marketing team worked overtime to meet the deadline for the new brochure.","exampleJa":"マーケティングチームは、新しいパンフレットの締め切りに間に合わせるため残業した。","hint":"dead+line。過ぎたらアウトという線のイメージ。meet a deadline で「間に合わせる」"},{"set":1,"word":"renovation","pos":"名詞","meaning":"改装、改修","example":"The hotel lobby will close for renovation from March through May.","exampleJa":"ホテルのロビーは、3月から5月まで改装のため閉鎖されます。","hint":"re+novel(新しい)と同じ仲間で「もう一度新しく」。ホテルやロビーの改装工事の場面で覚える"},{"set":1,"word":"contractor","pos":"名詞","meaning":"請負業者","example":"We hired a licensed contractor to rebuild the warehouse roof.","exampleJa":"私たちは倉庫の屋根を造り直すため、資格を持つ請負業者を雇った。","hint":"contract(契約)+or(人)。工事現場で「契約して請け負う側」の人をイメージ"},{"set":1,"word":"estimate","pos":"名詞","meaning":"見積もり","example":"The contractor gave us a written estimate for the office repairs.","exampleJa":"請負業者は、オフィスの修繕について書面の見積もりを私たちに出してくれた。","hint":"修理や工事の前にもらう「ざっくり見積書」。get an estimate で定番。動詞だと発音が変わる"},{"set":1,"word":"budget","pos":"名詞","meaning":"予算","example":"The project went over budget because of unexpected material costs.","exampleJa":"予想外の材料費のせいで、そのプロジェクトは予算を超過した。","hint":"財布(bougette＝小さな袋)が語源とされる説あり。使える金額の枠。over budget は「予算超過」"},{"set":1,"word":"quarterly","pos":"形容詞","meaning":"四半期の","example":"The finance department prepares a quarterly report for the board of directors.","exampleJa":"財務部は取締役会向けに四半期報告書を作成する。","hint":"quarter(4分の1)+ly。決算発表の「Q1・Q2…」を思い出す"},{"set":1,"word":"revenue","pos":"名詞","meaning":"収益、歳入","example":"Online sales accounted for most of the company's revenue last year.","exampleJa":"昨年は、オンライン販売が会社の収益の大部分を占めた。","hint":"会社に入ってくるお金の総額。expense(出ていく)と対にして覚える"},{"set":1,"word":"expense","pos":"名詞","meaning":"費用、経費","example":"Employees must submit all business expenses by the end of the month.","exampleJa":"従業員は、すべての業務経費を月末までに提出しなければならない。","hint":"出張や接待で使うお金。複数形 expenses で「経費」。revenue と対"},{"set":1,"word":"reimburse","pos":"動詞","meaning":"払い戻す","example":"The company will reimburse you for your train fare to the client's office.","exampleJa":"会社は、顧客のオフィスまでの電車代をあなたに払い戻します。","hint":"立て替えた出張費を会社が返してくれる場面。reimburse A for B の形で覚える"},{"set":1,"word":"receipt","pos":"名詞","meaning":"領収書、受領","example":"You must show your receipt if you want to exchange the item.","exampleJa":"商品を交換したい場合は、領収書を提示しなければなりません。","hint":"pは発音しない(「リシート」)。経費精算の必須アイテム。keep your receipt"},{"set":1,"word":"refund","pos":"名詞","meaning":"返金","example":"Customers can request a full refund within thirty days of purchase.","exampleJa":"お客様は、購入後30日以内であれば全額返金を請求できます。","hint":"買った物を返すと戻ってくるお金。a full refund(全額返金)で一語のように覚える"},{"set":1,"word":"shipment","pos":"名詞","meaning":"発送品、出荷","example":"Our latest shipment of laptops arrived at the warehouse this morning.","exampleJa":"最新のノートパソコンの出荷品が、今朝倉庫に到着した。","hint":"ship+ment。荷物が届く・出る場面で使う。船便とは限らない。「出荷」と「出荷品」の両方"},{"set":1,"word":"inventory","pos":"名詞","meaning":"在庫、在庫目録","example":"The store manager checks the inventory every Friday afternoon.","exampleJa":"店長は毎週金曜の午後に在庫を確認する。","hint":"倉庫で棚卸しをする場面。check inventory / out of inventory（在庫切れ）"},{"set":1,"word":"warehouse","pos":"名詞","meaning":"倉庫","example":"All online orders are packed and shipped from our central warehouse.","exampleJa":"オンライン注文はすべて、当社の中央倉庫で梱包・発送されます。","hint":"ware(商品)+house。商品をしまっておく家という分解で覚えやすい"},{"set":1,"word":"supplier","pos":"名詞","meaning":"供給業者","example":"We are looking for a new supplier that can deliver parts more quickly.","exampleJa":"私たちは、もっと迅速に部品を納品できる新しい供給業者を探している。","hint":"supply(供給する)+er。部品や材料を納めてくれる取引先。vendor とも近い"},{"set":1,"word":"merchandise","pos":"名詞","meaning":"商品","example":"All merchandise in the clearance section is marked down by half.","exampleJa":"処分品コーナーの商品はすべて半額に値下げされています。","hint":"merchant(商人)が扱うもの、と結びつける。数えない名詞で a merchandise とは言わない"},{"set":1,"word":"purchase","pos":"動詞","meaning":"購入する","example":"Employees may purchase office supplies directly from the approved vendor.","exampleJa":"従業員は、承認された業者から事務用品を直接購入してよい。","hint":"buyの硬い言い方。領収書や契約書に出てくる語感。proof of purchase(購入証明)"},{"set":1,"word":"order","pos":"名詞","meaning":"注文","example":"Your order will be delivered within three business days of payment.","exampleJa":"ご注文の品は、お支払いから3営業日以内にお届けします。","hint":"ネット通販の「注文確定」画面。place an order(注文する) / back order(取り寄せ)"},{"set":1,"word":"discount","pos":"名詞","meaning":"割引","example":"Members receive a ten percent discount on all conference registrations.","exampleJa":"会員は、すべての会議参加登録が10%割引になります。","hint":"dis(分離)+count。値札から数を引くイメージ。a 10% discount のように使う"},{"set":1,"word":"subscription","pos":"名詞","meaning":"定期購読、会費","example":"Your annual subscription includes unlimited access to all of our online articles.","exampleJa":"年間購読には、当社のオンライン記事すべてへの無制限アクセスが含まれます。","hint":"subscribe(申し込む)の名詞。動画配信や雑誌の「サブスク」とそのまま同じ"},{"set":1,"word":"venue","pos":"名詞","meaning":"会場","example":"We booked a downtown hotel as the venue for the annual dinner.","exampleJa":"私たちは、年次夕食会の会場として市内中心部のホテルを予約した。","hint":"コンサートや会議が開かれる場所。「ベニュー」。ホテルの宴会場など開催地を指す"},{"set":1,"word":"agenda","pos":"名詞","meaning":"議題、予定表","example":"Please review the agenda before tomorrow's staff meeting begins.","exampleJa":"明日のスタッフ会議が始まる前に、議題に目を通しておいてください。","hint":"会議の冒頭で配られる紙。on the agenda(議題に上がっている)で定番"},{"set":1,"word":"attendee","pos":"名詞","meaning":"出席者","example":"Each attendee will receive a name tag at the registration desk.","exampleJa":"各出席者は、受付で名札を受け取ります。","hint":"attend+ee(〜される人ではなく、〜する人)。employee・trainee と同じ -ee 仲間"},{"set":1,"word":"conference","pos":"名詞","meaning":"会議、協議会","example":"She presented her research at an international conference in Singapore.","exampleJa":"彼女はシンガポールでの国際会議で研究を発表した。","hint":"業界の大規模な会議。meeting より大きく、泊まりがけで参加するイメージ"},{"set":1,"word":"postpone","pos":"動詞","meaning":"延期する","example":"We had to postpone the product demonstration because of the storm.","exampleJa":"私たちは、嵐のため製品のデモンストレーションを延期せざるを得なかった。","hint":"「ポストにしまって後回し」という語呂の連想。postpone ＝ put off。cancel との違いは「後日やる」点"},{"set":1,"word":"reschedule","pos":"動詞","meaning":"予定を変更する","example":"Could we reschedule our meeting for Thursday afternoon instead?","exampleJa":"打ち合わせを代わりに木曜の午後に変更できますか。","hint":"re(再び)+schedule。会議の日程を組み直す。reschedule for ~ は日時を指定"},{"set":1,"word":"itinerary","pos":"名詞","meaning":"旅程表","example":"Your itinerary includes a flight to Chicago and two client meetings.","exampleJa":"あなたの旅程には、シカゴへのフライトと二件の顧客との打ち合わせが含まれています。","hint":"出張前にもらう、飛行機・ホテル・会議の予定が並んだ一枚。travel itinerary"},{"set":1,"word":"accommodation","pos":"名詞","meaning":"宿泊施設","example":"The company arranges accommodation for all visiting trainers.","exampleJa":"会社は、来訪するすべての研修講師の宿泊先を手配する。","hint":"accommodate(収容する)の名詞。出張で「泊まる所」。米国では複数形 accommodations が多い"},{"set":1,"word":"reservation","pos":"名詞","meaning":"予約","example":"I'd like to make a reservation for six people at seven o'clock.","exampleJa":"7時に6名で予約をお願いしたいのですが。","hint":"reserve(取っておく)の名詞。レストランやホテルの席・部屋を押さえること"},{"set":1,"word":"confirm","pos":"動詞","meaning":"確認する","example":"Please confirm your attendance by replying to this email.","exampleJa":"このメールに返信して、出席の確認をお願いします。","hint":"firm(固い)が入っていると考える。予約や日程を「確定させる」。confirmation email が届く場面"},{"set":1,"word":"applicant","pos":"名詞","meaning":"応募者","example":"Over fifty applicants responded to the advertisement for the sales position.","exampleJa":"営業職の求人広告には、50人を超える応募者が応じた。","hint":"apply(応募する)+ant(人)。求人に応募してきた人たちの列を想像する"},{"set":1,"word":"candidate","pos":"名詞","meaning":"候補者","example":"The hiring committee chose the most qualified candidate for the manager position.","exampleJa":"採用委員会は、管理職の最も適任な候補者を選んだ。","hint":"面接の最終選考に残った人。応募者(applicant)より絞り込まれた感じ"},{"set":1,"word":"résumé","pos":"名詞","meaning":"履歴書","example":"Please attach your résumé and a cover letter to the application form.","exampleJa":"応募用紙に、履歴書と送付状を添付してください。","hint":"アクセント付きで見たら履歴書。フランス語由来の語。submit a résumé／send a résumé と cover letter のセット"},{"set":1,"word":"qualification","pos":"名詞","meaning":"資格、適性","example":"A degree in accounting is the main qualification for this position.","exampleJa":"会計学の学位が、この職に求められる主な資格です。","hint":"qualify(資格を得る)の名詞。求人票の「応募資格」欄。複数形で学位や免許を指すことも"},{"set":1,"word":"recruit","pos":"動詞","meaning":"採用する","example":"We plan to recruit ten engineers for the new research center.","exampleJa":"私たちは、新しい研究センターのために10人の技術者を採用する予定だ。","hint":"リクルートスーツ・リクルート活動の「リクルート」。人材を集めて採用する"},{"set":1,"word":"hire","pos":"動詞","meaning":"雇う","example":"The restaurant decided to hire two more servers for the busy season.","exampleJa":"そのレストランは、繁忙期に向けてさらに2人の接客係を雇うことにした。","hint":"給料を払って雇う、短く強い動詞。hire と fire(解雇)を対で覚える"},{"set":1,"word":"promotion","pos":"名詞","meaning":"昇進、販売促進","example":"Ms. Tanaka received a promotion to regional sales director this spring.","exampleJa":"田中さんは今春、地域営業部長に昇進した。","hint":"人事発表の「昇進」と、セール告知の「販売促進」。どちらの場面かで意味を判断"},{"set":1,"word":"colleague","pos":"名詞","meaning":"同僚","example":"I asked a colleague from the accounting team to review my report.","exampleJa":"私は経理チームの同僚に、自分の報告書を見直してもらうよう頼んだ。","hint":"同じ職場で働く仲間。coworker より少し丁寧。「コリーグ」と発音し、最後の-ueは読まない"},{"set":1,"word":"supervisor","pos":"名詞","meaning":"上司、監督者","example":"Please report any equipment problems to your supervisor immediately.","exampleJa":"機器の不具合は、直ちに上司に報告してください。","hint":"super(上)に vis(見る)が入る点は video と同じ系統。現場で部下を見守る上司"},{"set":1,"word":"personnel","pos":"名詞","meaning":"人事部、職員","example":"All personnel must wear identification badges inside the factory.","exampleJa":"全職員は、工場内では身分証バッジを着用しなければならない。","hint":"person の集合体で会社の「人員」。Personnel Department は人事部。nn は発音注意でアクセントは最後"},{"set":1,"word":"employee","pos":"名詞","meaning":"従業員","example":"Every new employee attends an orientation session on the first day.","exampleJa":"新入社員は全員、初日にオリエンテーションに参加する。","hint":"employ(雇う)+ee。-eeは受ける側で、雇う側は employer"},{"set":1,"word":"retire","pos":"動詞","meaning":"退職する","example":"Mr. Brown will retire from the company after thirty years of service.","exampleJa":"ブラウンさんは、30年の勤務を経て会社を退職する。","hint":"定年退職のパーティーの場面で覚える。retire from ~ で「〜を退職する」"},{"set":1,"word":"transfer","pos":"動詞","meaning":"異動させる、移す","example":"The firm decided to transfer her to the Paris office next month.","exampleJa":"会社は来月、彼女をパリ事務所に異動させることを決めた。","hint":"trans(越えて)+fer(運ぶ)。人を別の支店や部署へ移す。口座の振込にも同じ動詞"},{"set":1,"word":"assignment","pos":"名詞","meaning":"任務、割り当て","example":"His first assignment was to update the customer database.","exampleJa":"彼の最初の任務は、顧客データベースを更新することだった。","hint":"assign(割り当てる)の名詞。上司から振られた仕事や、出張の任務というイメージ"},{"set":1,"word":"responsibility","pos":"名詞","meaning":"責任、職務","example":"Managing the budget is one of her main responsibilities.","exampleJa":"予算管理は、彼女の主な職務の一つだ。","hint":"respond(応える)+ability と分解すると「応える力」。job responsibilities は「職務」"},{"set":1,"word":"department","pos":"名詞","meaning":"部署","example":"She transferred from the sales department to the legal department.","exampleJa":"彼女は営業部から法務部に異動した。","hint":"会社を部分に分けた単位。デパート(department store)も売り場が部門ごとに分かれた店"},{"set":1,"word":"headquarters","pos":"名詞","meaning":"本社","example":"The company's headquarters are located in downtown Seattle.","exampleJa":"その会社の本社は、シアトルの中心街にある。","hint":"本社は「頭」の拠点と覚える。末尾の-sは常に付く。主語としては単数・複数どちらも可"},{"set":1,"word":"branch","pos":"名詞","meaning":"支店","example":"The bank plans to open a new branch near the train station.","exampleJa":"その銀行は、駅の近くに新しい支店を開設する予定だ。","hint":"木の枝のように幹(本社)から伸びた支店。branch office / bank branch"},{"set":1,"word":"facility","pos":"名詞","meaning":"施設、設備","example":"The new research facility will open to staff early next year.","exampleJa":"新しい研究施設は、来年初めに職員向けに開所する。","hint":"工場・病院・スポーツジムなど用途のある建物や設備。数えられる名詞で、複数形も頻出"},{"set":1,"word":"equipment","pos":"名詞","meaning":"機器、設備","example":"All laboratory equipment must be inspected before it is used.","exampleJa":"すべての実験室機器は、使用前に点検されなければならない。","hint":"機械や道具の総称。数えない名詞なので an equipment や equipments は誤り"},{"set":1,"word":"maintenance","pos":"名詞","meaning":"保守、整備","example":"The elevator will be unavailable during routine maintenance on Sunday.","exampleJa":"エレベーターは、日曜日の定期整備中はご利用いただけません。","hint":"maintain(維持する)の名詞。エレベーターの「点検中」の貼り紙を想像。ai の綴りに注意"},{"set":1,"word":"repair","pos":"動詞","meaning":"修理する","example":"The technician came to repair the broken photocopier this morning.","exampleJa":"技術者が、故障したコピー機を修理するために今朝来た。","hint":"re(再び)+pair は「整える」。壊れた機械を直す場面。have + 物 + repaired の形も頻出"},{"set":1,"word":"install","pos":"動詞","meaning":"設置する","example":"The IT staff will install the new software on every computer.","exampleJa":"IT担当者が、すべてのコンピューターに新しいソフトウェアをインストールする。","hint":"ソフトを「インストール」する語感のまま。機器を取り付ける意味でも使う"},{"set":1,"word":"construction","pos":"名詞","meaning":"建設、工事","example":"Construction of the new bridge is expected to finish in October.","exampleJa":"新しい橋の建設は、10月に完了する見込みだ。","hint":"construct(建てる)の名詞。工事現場の看板 under construction で「工事中」"},{"set":1,"word":"blueprint","pos":"名詞","meaning":"設計図、青写真","example":"The engineers studied the blueprint before starting work on the site.","exampleJa":"技術者たちは、現場で作業を始める前に設計図を詳しく調べた。","hint":"青焼きの図面が由来で、建築の設計図。転じて「詳細な計画」。blue+print と分解"},{"set":1,"word":"architect","pos":"名詞","meaning":"建築家","example":"The architect presented three design options for the new library.","exampleJa":"建築家は、新しい図書館のために3つの設計案を提示した。","hint":"建物を設計する専門職。語尾の -ect で「アーキテクト」。IT分野の「システム設計者」も同語"},{"set":1,"word":"property","pos":"名詞","meaning":"不動産、所有物","example":"The company purchased a large property near the airport for its new plant.","exampleJa":"その会社は、新工場のために空港近くの広い土地を購入した。","hint":"土地や建物などの不動産。real estate と近い。ほかに「所有物」の意味"},{"set":1,"word":"tenant","pos":"名詞","meaning":"賃借人、テナント","example":"Each tenant in the building is responsible for paying its own utility bills.","exampleJa":"ビルの各テナントは、自分たちの光熱費を支払う責任がある。","hint":"ビルの入居者、アパートの借り手。貸す側の landlord とペアで覚える"},{"set":1,"word":"lease","pos":"名詞","meaning":"賃貸借契約","example":"Our lease on the downtown office expires at the end of June.","exampleJa":"市内中心部のオフィスの賃貸契約は、6月末で期限が切れる。","hint":"オフィスや車を一定期間借りる契約。sign a lease / lease agreement。動詞「賃借する」も同形"},{"set":1,"word":"landlord","pos":"名詞","meaning":"家主","example":"The landlord agreed to repaint the office before we moved in.","exampleJa":"家主は、私たちが入居する前にオフィスを塗り直すことに同意した。","hint":"land(土地)+lord(主)。土地や建物を貸す人。tenant の相手役"},{"set":1,"word":"contract","pos":"名詞","meaning":"契約（書）","example":"Both parties signed the contract at the lawyer's office on Monday.","exampleJa":"両当事者は月曜日に、弁護士事務所で契約書に署名した。","hint":"契約書にサインする場面。名詞はアクセント前、動詞「縮む」はアクセント後ろ(con-tráct)"},{"set":1,"word":"agreement","pos":"名詞","meaning":"合意、契約","example":"After weeks of talks, the two firms reached an agreement on pricing.","exampleJa":"数週間の協議の末、両社は価格について合意に達した。","hint":"agree の名詞。交渉が終わって握手する場面。reach an agreement / sign an agreement"},{"set":1,"word":"negotiate","pos":"動詞","meaning":"交渉する","example":"We negotiated with the supplier to lower the price of raw materials.","exampleJa":"私たちは、原材料の価格を下げるよう供給業者と交渉した。","hint":"契約書の条件をめぐって話し合う場面。negotiate with 相手 / negotiate a deal"},{"set":1,"word":"proposal","pos":"名詞","meaning":"提案（書）","example":"Her proposal for a new training program was approved by management.","exampleJa":"新しい研修プログラムに関する彼女の提案は、経営陣に承認された。","hint":"propose(提案する)の名詞。企画書を出す場面。submit a proposal、結婚の「プロポーズ」も同じ語"},{"set":1,"word":"approve","pos":"動詞","meaning":"承認する","example":"The board approved the plan to open two additional stores.","exampleJa":"取締役会は、さらに2店舗を開設する計画を承認した。","hint":"稟議書に「承認」の判子を押す場面。approve of ~ は「〜に賛成する」で別の使い方"},{"set":1,"word":"authorize","pos":"動詞","meaning":"権限を与える、認可する","example":"Only managers are authorized to approve purchases over one thousand dollars.","exampleJa":"1,000ドルを超える購入を承認する権限があるのは、管理職だけだ。","hint":"author(権威)+ize。上司が部下に権限を与えるイメージ。authorization は「許可」"},{"set":1,"word":"regulation","pos":"名詞","meaning":"規則、規制","example":"The factory must follow strict safety regulations at all times.","exampleJa":"その工場は、常に厳しい安全規則に従わなければならない。","hint":"役所や業界が定めた決まり。規則を守る(regular)ように、と連想。複数形でよく使う"},{"set":1,"word":"compliance","pos":"名詞","meaning":"（法令）遵守","example":"The audit confirmed that the firm is in compliance with tax laws.","exampleJa":"監査により、その会社が税法を遵守していることが確認された。","hint":"comply(従う)の名詞。コンプライアンス研修の「コンプライアンス」そのもの"},{"set":1,"word":"policy","pos":"名詞","meaning":"方針、保険証券","example":"Under our return policy, unopened items can be exchanged within two weeks.","exampleJa":"当社の返品規定では、未開封の商品は2週間以内であれば交換できます。","hint":"社内規定や返品ルールなど、組織が決めた方針。return policy / privacy policy で覚える"},{"set":1,"word":"procedure","pos":"名詞","meaning":"手順","example":"Please follow the standard procedure when reporting a workplace injury.","exampleJa":"職場での負傷を報告する際は、標準の手順に従ってください。","hint":"proceed(進む)に近い語。マニュアルの「手順」。follow the procedure と言う"},{"set":1,"word":"requirement","pos":"名詞","meaning":"必要条件","example":"Two years of experience is a basic requirement for this job.","exampleJa":"2年の経験が、この仕事の基本的な必要条件だ。","hint":"require(必要とする)の名詞。募集要項の「応募条件」。meet the requirements の形で"},{"set":1,"word":"submit","pos":"動詞","meaning":"提出する","example":"Applicants must submit their documents to the personnel office by Friday.","exampleJa":"応募者は金曜日までに、書類を人事部に提出しなければならない。","hint":"書類を窓口へ「差し出す」感覚。ネットフォームの Submit ボタンを思い出す"},{"set":1,"word":"complete","pos":"動詞","meaning":"完了させる","example":"Please complete the questionnaire and return it at the front desk.","exampleJa":"アンケートに記入して、受付に返却してください。","hint":"空欄を全部埋めて終わらせる。complete a form は「用紙に記入する」。fill out と同義"},{"set":1,"word":"implement","pos":"動詞","meaning":"実施する","example":"The company will implement a flexible working schedule next quarter.","exampleJa":"会社は来四半期に、柔軟な勤務時間制度を実施する。","hint":"決めた計画を実際に動かす。implement a plan / a policy / a system が定番の組み合わせ"},{"set":1,"word":"launch","pos":"動詞","meaning":"開始する、発売する","example":"The firm plans to launch its new smartphone in September.","exampleJa":"その会社は、9月に新しいスマートフォンを発売する予定だ。","hint":"ロケットの打ち上げのように、新製品や事業を世に出す。launch event は発売イベント"},{"set":1,"word":"expand","pos":"動詞","meaning":"拡大する","example":"The restaurant chain intends to expand into several Asian markets.","exampleJa":"そのレストランチェーンは、アジアのいくつかの市場へ拡大するつもりだ。","hint":"風船が膨らむように事業や店舗を広げる。expand into ~ で「〜に進出する」"},{"set":1,"word":"merger","pos":"名詞","meaning":"合併","example":"The merger of the two banks created the region's largest lender.","exampleJa":"2つの銀行の合併により、地域最大の金融機関が誕生した。","hint":"merge(合流する)の名詞。高速道路の合流(merge)と同じ動き。M&A の M"},{"set":1,"word":"acquisition","pos":"名詞","meaning":"買収、取得","example":"The software firm announced its acquisition of a small start-up.","exampleJa":"そのソフトウェア会社は、小さなスタートアップの買収を発表した。","hint":"acquire(手に入れる)の名詞。会社を買い取る場面。M&A の A"},{"set":1,"word":"competitor","pos":"名詞","meaning":"競合他社","example":"Our main competitor has just lowered the prices of its products.","exampleJa":"当社の主な競合他社が、自社製品の価格を引き下げたばかりだ。","hint":"compete(競う)+or。同じ市場でお客を奪い合う相手。ライバル会社"},{"set":1,"word":"client","pos":"名詞","meaning":"顧客、依頼人","example":"The consultant met with a client to discuss the new advertising campaign.","exampleJa":"コンサルタントは、新しい広告キャンペーンについて話し合うため顧客と会った。","hint":"弁護士・広告代理店・コンサルなど、サービスを依頼する側。customer より継続的な関係"},{"set":1,"word":"complaint","pos":"名詞","meaning":"苦情","example":"We received several complaints about the delayed delivery last week.","exampleJa":"先週は、配送の遅れについて数件の苦情が寄せられた。","hint":"complain(文句を言う)の名詞。お客様相談窓口に届く声。file a complaint(苦情を申し立てる)"},{"set":1,"word":"inquiry","pos":"名詞","meaning":"問い合わせ","example":"Thank you for your inquiry about our corporate membership plans.","exampleJa":"当社の法人会員プランについてのお問い合わせ、ありがとうございます。","hint":"inquire(尋ねる)の名詞。メールの冒頭 Thank you for your inquiry. が定番。enquiry は英国式の綴り"},{"set":1,"word":"feedback","pos":"名詞","meaning":"意見、反応","example":"We value your feedback and use it to improve our service.","exampleJa":"私たちはお客様のご意見を大切にし、サービスの改善に役立てています。","hint":"feed(与える)+back(戻す)。送った物事への反応が返ってくる。数えない名詞"},{"set":1,"word":"survey","pos":"名詞","meaning":"調査、アンケート","example":"The company conducted a survey to find out what customers want.","exampleJa":"その会社は、顧客が何を求めているかを知るために調査を行った。","hint":"顧客満足度アンケートの場面。アクセントは名詞が前(súrvey)、動詞は後ろ。conduct a survey"},{"set":1,"word":"analysis","pos":"名詞","meaning":"分析","example":"A careful analysis of sales data revealed a seasonal pattern.","exampleJa":"売上データを注意深く分析した結果、季節的なパターンが明らかになった。","hint":"analyze の名詞。複数形は analyses(アナリシーズ)で形が変わる。market analysis"},{"set":1,"word":"figure","pos":"名詞","meaning":"数値、図","example":"The latest sales figures exceeded our expectations for the quarter.","exampleJa":"最新の売上数値は、今四半期の私たちの予想を上回った。","hint":"グラフや表に並ぶ数字。sales figures は「売上高」。「図」の意味もある"},{"set":1,"word":"increase","pos":"名詞","meaning":"増加","example":"The report shows a sharp increase in online orders this year.","exampleJa":"報告書は、今年のオンライン注文の急激な増加を示している。","hint":"名詞は前にアクセント(íncrease)、動詞は後ろ(incréase)。an increase in ~ の形で使う"},{"set":1,"word":"decline","pos":"動詞","meaning":"減少する、断る","example":"Sales in the retail sector declined slightly during the summer months.","exampleJa":"小売部門の売上は、夏の数か月間にわずかに減少した。","hint":"グラフが右下がりに下がる、またはお誘いを丁寧に断る。人は decline an offer、売上は declined"},{"set":1,"word":"significant","pos":"形容詞","meaning":"かなりの、重要な","example":"The new system led to a significant reduction in processing time.","exampleJa":"新しいシステムにより、処理時間が大幅に短縮された。","hint":"数字の変化が「無視できないほど」大きい時に使う。significant change / difference"},{"set":1,"word":"substantial","pos":"形容詞","meaning":"相当な","example":"The company made a substantial investment in new production equipment.","exampleJa":"会社は、新しい生産設備に相当な額の投資を行った。","hint":"substance(中身)があるので量が「たっぷり」。substantial amount / profit は金額が大きいときの定番"},{"set":1,"word":"efficient","pos":"形容詞","meaning":"効率的な","example":"The new filing system is more efficient than the old paper method.","exampleJa":"新しいファイリングシステムは、従来の紙の方法より効率的だ。","hint":"ムダが少なく、時間・費用・エネルギーを上手に使う様子。efficient method / energy-efficient"},{"set":1,"word":"available","pos":"形容詞","meaning":"利用可能な、手が空いている","example":"The manager is available to meet with you on Wednesday morning.","exampleJa":"部長は、水曜日の午前ならお会いできます。","hint":"店頭では「在庫あり・利用可」、人には「今手が空いている」。Is she available? の定番"},{"set":1,"word":"eligible","pos":"形容詞","meaning":"資格のある","example":"Employees with one year of service are eligible for paid training leave.","exampleJa":"勤続1年の従業員は、有給の研修休暇を取得する資格がある。","hint":"制度の条件を満たし「申し込める」資格。be eligible for ~ / to do の形でセット暗記"},{"set":1,"word":"mandatory","pos":"形容詞","meaning":"義務的な","example":"Attendance at the safety training session is mandatory for all staff.","exampleJa":"安全研修への出席は、全スタッフに義務づけられている。","hint":"「マンダ(命令)」と聞こえる連想で、守るべき義務。optional(任意)と対"},{"set":1,"word":"temporary","pos":"形容詞","meaning":"一時的な","example":"We hired temporary workers to help during the holiday rush.","exampleJa":"私たちは、年末の繁忙期を手伝ってもらうため臨時の従業員を雇った。","hint":"temp(派遣社員)の元の語。期間限定の仕事や措置。permanent(恒久的)と対"},{"set":1,"word":"previous","pos":"形容詞","meaning":"以前の","example":"Do you have previous experience working in a customer service role?","exampleJa":"接客業務での勤務経験はこれまでにありますか。","hint":"前(pre)と同じ頭。履歴書の「前職」や前回の会議。previous experience / the previous meeting"},{"set":1,"word":"upcoming","pos":"形容詞","meaning":"今度の、近づいている","example":"Details about the upcoming training session will be sent by email.","exampleJa":"今度の研修会の詳細は、メールでお送りします。","hint":"up+coming。「近づいてくる」ので、まだ先の予定を告知する時に使う。upcoming event"},{"set":1,"word":"promptly","pos":"副詞","meaning":"迅速に、時間通りに","example":"Please reply to customer emails promptly to maintain good relationships.","exampleJa":"良好な関係を保つため、顧客からのメールには迅速に返信してください。","hint":"prompt(すばやい)+ly。メールに「遅れず」返信する、会議を時間どおり始めるときに使う"},{"set":1,"word":"approximately","pos":"副詞","meaning":"およそ","example":"The trip from the airport to the hotel takes approximately forty minutes.","exampleJa":"空港からホテルまでの移動には、およそ40分かかります。","hint":"数字の前に置く「およそ」。about よりかたい語。ビジネス文書や案内で頻出"},{"set":2,"word":"appointment","pos":"名詞","meaning":"予約、約束、任命","example":"I'd like to make an appointment with Dr. Lee for next Tuesday morning.","exampleJa":"来週火曜日の午前中にリー先生の予約を取りたいのですが。","hint":"歯医者や商談の「何時にお会いします」という約束。make/cancel an appointment の形で覚える"},{"set":2,"word":"brochure","pos":"名詞","meaning":"パンフレット","example":"The receptionist handed me a brochure describing the company's new service plans.","exampleJa":"受付係は、会社の新しいサービスプランを説明したパンフレットを私に手渡してくれた。","hint":"展示会ブースやホテルの受付に置いてある、折りたたみの案内冊子をイメージ"},{"set":2,"word":"catering","pos":"名詞","meaning":"仕出し、ケータリング","example":"The catering for the annual conference will be provided by a local restaurant.","exampleJa":"年次会議の仕出しは、地元のレストランが提供する予定です。","hint":"会議やパーティーに料理を届けるサービス。cater は「料理を提供する」という動詞"},{"set":2,"word":"commute","pos":"動詞","meaning":"通勤する","example":"Many employees commute to the downtown office by train every morning.","exampleJa":"多くの従業員が毎朝、電車で市内中心部のオフィスへ通勤している。","hint":"満員電車で毎日往復する場面を想像。commute to work の形で定番"},{"set":2,"word":"courier","pos":"名詞","meaning":"宅配業者、配達人","example":"We sent the signed contract to the client by courier this afternoon.","exampleJa":"署名済みの契約書を、今日の午後、宅配便で取引先に送りました。","hint":"急ぎの書類をバイクで運ぶ配達員の絵。「クーリエ便」という日本語でも耳にする"},{"set":2,"word":"delegate","pos":"動詞","meaning":"（仕事を）任せる","example":"A good manager knows when to delegate routine tasks to the team.","exampleJa":"優れた管理職は、いつ日常業務をチームに任せるべきかを心得ている。","hint":"動詞は「デレゲイト」、名詞は「デリゲット」と発音が違う。上司が部下に仕事を振る場面"},{"set":2,"word":"defective","pos":"形容詞","meaning":"欠陥のある","example":"Please return the defective item and we will send a replacement immediately.","exampleJa":"欠陥のある商品をご返送いただければ、すぐに代替品をお送りします。","hint":"defect＝欠陥。返品・交換の連絡で出る定番語。a defective part（不良部品）"},{"set":2,"word":"dedicated","pos":"形容詞","meaning":"熱心な、専用の","example":"Our dedicated customer support team is available around the clock to help you.","exampleJa":"当社の専任カスタマーサポートチームが、24時間体制でお客様をお手伝いします。","hint":"「専用の」と「熱心な」の2義。a dedicated line と a dedicated staff member をセットで"},{"set":2,"word":"distribute","pos":"動詞","meaning":"配布する","example":"Please distribute the revised agenda to all attendees before the meeting starts.","exampleJa":"会議が始まる前に、修正した議題を全出席者に配布してください。","hint":"会議の冒頭で資料をみんなに配る場面。distribute A to B の形"},{"set":2,"word":"donation","pos":"名詞","meaning":"寄付","example":"The company made a generous donation to the local children's hospital last year.","exampleJa":"その会社は昨年、地元の小児病院に多額の寄付をした。","hint":"募金箱やチャリティーのイメージ。make a donation to ~ で覚える"},{"set":2,"word":"enclose","pos":"動詞","meaning":"同封する","example":"I have enclosed a copy of the invoice with this letter.","exampleJa":"この手紙に請求書の写しを同封いたしました。","hint":"手紙に請求書や書類を一緒に入れる場面。Please find enclosed ~ はビジネスレターの定型"},{"set":2,"word":"enroll","pos":"動詞","meaning":"登録する、入学する","example":"Several new employees enrolled in the language course offered by the company.","exampleJa":"数名の新入社員が、会社が提供する語学講座に登録した。","hint":"enroll in ~ で「~に登録する」。講座や学校の申込書に名前を書く場面"},{"set":2,"word":"evaluate","pos":"動詞","meaning":"評価する","example":"Managers will evaluate each employee's performance at the end of the year.","exampleJa":"管理職は年末に各従業員の業績を評価する。","hint":"value（価値）が入っている。人事面談で成績を査定する場面"},{"set":2,"word":"exhibition","pos":"名詞","meaning":"展示会","example":"Our company will present its latest products at the trade exhibition in May.","exampleJa":"当社は5月の見本市で最新製品を披露する予定です。","hint":"見本市や美術展の会場。exhibit（展示する）の名詞形。hold an exhibition"},{"set":2,"word":"expire","pos":"動詞","meaning":"期限が切れる","example":"Your membership will expire at the end of this month unless you renew it.","exampleJa":"更新しない限り、あなたの会員資格は今月末で期限が切れます。","hint":"クーポンや会員証の「有効期限」が切れる場面。後ろに目的語は取らない"},{"set":2,"word":"extension","pos":"名詞","meaning":"内線、延長","example":"Please call me at extension 305 if you have any questions about the schedule.","exampleJa":"日程についてご質問がありましたら、内線305番までお電話ください。","hint":"電話で「内線番号は?」と聞かれる場面と、締切の延長の2義。extend の名詞形"},{"set":2,"word":"fare","pos":"名詞","meaning":"運賃","example":"The airline announced that round-trip fares to Seoul will be reduced next month.","exampleJa":"その航空会社は、来月からソウルへの往復運賃を値下げすると発表した。","hint":"バス・電車・飛行機など「乗り物」の料金専用。bus fare, airfare。サービス料のfeeと区別"},{"set":2,"word":"fiscal","pos":"形容詞","meaning":"会計の、財政の","example":"The company expects its profits to rise in the next fiscal year.","exampleJa":"その会社は、次の会計年度に利益が増えると見込んでいる。","hint":"fiscal year（会計年度）のセットで覚える。決算や予算の話で登場"},{"set":2,"word":"forward","pos":"動詞","meaning":"転送する","example":"Could you forward the client's e-mail to me before noon today?","exampleJa":"今日の正午までに、その顧客のメールを私に転送していただけますか。","hint":"受け取ったメールを他の人へ回す「転送」ボタン。forward A to B の形"},{"set":2,"word":"fluctuate","pos":"動詞","meaning":"変動する","example":"Exchange rates fluctuate daily, which makes budgeting for overseas projects difficult.","exampleJa":"為替レートは日々変動するため、海外プロジェクトの予算を立てるのは難しい。","hint":"為替や株価がグラフ上でギザギザ上下する場面。「フラクチュエイト」の響きもゆらゆら"},{"set":2,"word":"generous","pos":"形容詞","meaning":"気前のよい、寛大な","example":"We are grateful for the generous support of our sponsors this year.","exampleJa":"今年のスポンサーの皆様の寛大なご支援に感謝しております。","hint":"高額の寄付や太っ腹な割引を見て「気前がいい!」と言う場面。a generous offer"},{"set":2,"word":"grant","pos":"名詞","meaning":"助成金","example":"The university received a grant to build a new research facility.","exampleJa":"その大学は、新しい研究施設を建設するための助成金を受け取った。","hint":"返さなくてよい公的なお金。research grant。動詞の「認める」も一緒に覚える"},{"set":2,"word":"identify","pos":"動詞","meaning":"特定する、確認する","example":"The engineers worked overnight to identify the cause of the system failure.","exampleJa":"技術者たちは、システム障害の原因を特定するために一晩中作業した。","hint":"identity（身元）と同じ系統。原因や身元を「これだ」と突き止める場面"},{"set":2,"word":"incentive","pos":"名詞","meaning":"報奨、動機づけ","example":"The company offers a cash incentive to employees who exceed their sales targets.","exampleJa":"その会社は、販売目標を超えた従業員に現金の報奨を出している。","hint":"営業成績に応じたボーナスなど「やる気スイッチ」になる特典。sales incentive"},{"set":2,"word":"inspection","pos":"名詞","meaning":"検査、点検","example":"The factory passed its annual safety inspection without any problems.","exampleJa":"その工場は、年1回の安全点検を問題なく通過した。","hint":"工場や建物に検査官が来て隅々までチェックする場面。pass an inspection"},{"set":2,"word":"insurance","pos":"名詞","meaning":"保険","example":"All full-time employees are covered by the company's health insurance plan.","exampleJa":"正社員は全員、会社の健康保険制度に加入している。","hint":"万一に備える保険。health/travel insurance。保険料は premium"},{"set":2,"word":"interrupt","pos":"動詞","meaning":"中断する、さえぎる","example":"Please do not interrupt the speaker until the question period begins.","exampleJa":"質疑応答の時間が始まるまで、講演者の話をさえぎらないでください。","hint":"プレゼン中に話をさえぎられる場面。Sorry to interrupt, but ~ は会話の定番"},{"set":2,"word":"investment","pos":"名詞","meaning":"投資","example":"The firm made a large investment in new manufacturing equipment this year.","exampleJa":"その会社は今年、新しい製造設備に多額の投資をした。","hint":"お金を出して将来の利益を狙うこと。an investment in ~ の形。投資家は investor"},{"set":2,"word":"keynote","pos":"名詞","meaning":"基調（講演）","example":"The CEO will deliver the keynote speech at the opening of the conference.","exampleJa":"最高経営責任者が、会議の開会時に基調講演を行う予定だ。","hint":"学会や大会の冒頭に行う、全体の方向を示す講演。keynote speech / speaker"},{"set":2,"word":"laboratory","pos":"名詞","meaning":"研究所、実験室","example":"The new laboratory will allow our scientists to test products more quickly.","exampleJa":"新しい研究所のおかげで、当社の研究者は製品をより迅速に試験できるようになる。","hint":"白衣を着て実験する場所。日常では短縮形の lab をよく使う"},{"set":2,"word":"legislation","pos":"名詞","meaning":"法律、立法","example":"New legislation will require all businesses to report their carbon emissions.","exampleJa":"新しい法律により、すべての企業が二酸化炭素排出量を報告する必要が出てくる。","hint":"国会で成立する法律のこと。new legislation（新しい法律）で覚える。数えない名詞"},{"set":2,"word":"logistics","pos":"名詞","meaning":"物流、ロジスティクス","example":"She manages the logistics of shipping our products to stores across the country.","exampleJa":"彼女は、当社製品を全国の店舗へ出荷する物流を管理している。","hint":"倉庫・輸送・配送をまとめて管理する物流の仕事。-s が付く名詞"},{"set":2,"word":"luggage","pos":"名詞","meaning":"手荷物","example":"Passengers must collect their luggage from the carousel before passing through customs.","exampleJa":"乗客は、税関を通る前に回転コンベアから手荷物を受け取らなければならない。","hint":"空港で預けるスーツケースの山を想像。数えられないので a piece of luggage"},{"set":2,"word":"manufacturer","pos":"名詞","meaning":"製造業者、メーカー","example":"The manufacturer promised to deliver the replacement parts within two weeks.","exampleJa":"そのメーカーは、交換部品を2週間以内に納品すると約束した。","hint":"工場で製品を作る会社。manufacture（製造する）+ -er。car manufacturer"},{"set":2,"word":"minutes","pos":"名詞","meaning":"議事録","example":"Ms. Tanaka will take the minutes and circulate them after the meeting.","exampleJa":"田中さんが議事録を取り、会議の後で回覧します。","hint":"会議の記録係が書く議事録。常に複数形。take the minutes（記録を取る）"},{"set":2,"word":"nominate","pos":"動詞","meaning":"推薦する、指名する","example":"Her colleagues nominated her for the employee of the year award.","exampleJa":"同僚たちは、彼女を年間最優秀社員賞に推薦した。","hint":"表彰や役職の候補に名前を挙げる場面。be nominated for ~ の受け身で頻出"},{"set":2,"word":"notify","pos":"動詞","meaning":"通知する","example":"We will notify all customers of the schedule change by e-mail.","exampleJa":"スケジュール変更については、メールですべてのお客様にお知らせします。","hint":"notify A of B「AにBを知らせる」。note（注意）に近い響きで覚える連想"},{"set":2,"word":"occupancy","pos":"名詞","meaning":"入居率、占有","example":"Hotel occupancy reached ninety percent during the weekend of the festival.","exampleJa":"祭りの週末には、ホテルの客室稼働率が90パーセントに達した。","hint":"ホテルの稼働率や賃貸物件の入居状況を表す。occupancy rate が定番"},{"set":2,"word":"outstanding","pos":"形容詞","meaning":"未払いの、優れた","example":"Please pay the outstanding balance on your account by the end of the month.","exampleJa":"口座の未払い残高を、今月末までにお支払いください。","hint":"請求書では「未払いの」、人や成績では「傑出した」。文脈で見分ける2面性の語"},{"set":2,"word":"overtime","pos":"名詞","meaning":"残業","example":"Employees who work overtime will be paid one and a half times their hourly wage.","exampleJa":"残業をした従業員には、時給の1.5倍が支払われる。","hint":"定時を過ぎて働く場面。work overtime, overtime pay（残業代）"},{"set":2,"word":"participant","pos":"名詞","meaning":"参加者","example":"Each participant in the workshop will receive a certificate of completion.","exampleJa":"研修会の参加者には全員、修了証が渡される。","hint":"セミナーや研修の「参加者」。participate in ~ とセットで覚える"},{"set":2,"word":"patron","pos":"名詞","meaning":"常連客、後援者","example":"The library thanks its patrons for their support during the renovation.","exampleJa":"図書館は、改装期間中の利用者の皆様のご支援に感謝いたします。","hint":"レストランや劇場に通い続ける常連。「ひいきにしてくれる人」というイメージ"},{"set":2,"word":"payroll","pos":"名詞","meaning":"給与支払い、給与台帳","example":"The payroll department will process everyone's salary by the twenty-fifth.","exampleJa":"給与課は、25日までに全員の給与を処理する予定だ。","hint":"毎月の給与計算を扱う業務や名簿。payroll department は経理系の部署名"},{"set":2,"word":"pharmacy","pos":"名詞","meaning":"薬局","example":"You can pick up your prescription at the pharmacy next to the clinic.","exampleJa":"処方薬は、診療所の隣の薬局で受け取れます。","hint":"処方箋を持って薬をもらいに行く店。ファーマシーという日本語でも見かける"},{"set":2,"word":"premises","pos":"名詞","meaning":"敷地、構内","example":"Smoking is not permitted anywhere on the premises of the company.","exampleJa":"会社の敷地内では、どこでも喫煙は許可されていません。","hint":"建物とその敷地をひとまとめにした語。複数形が基本。on the premises は掲示の定番"},{"set":2,"word":"preliminary","pos":"形容詞","meaning":"予備の、準備の","example":"The preliminary report suggests that sales improved slightly in the third quarter.","exampleJa":"予備報告によると、第3四半期の売上はわずかに改善したようだ。","hint":"本番の前段階。preliminary results（速報の結果）、preliminary meeting（予備会議）"},{"set":2,"word":"productivity","pos":"名詞","meaning":"生産性","example":"The new software has significantly increased our team's productivity.","exampleJa":"その新しいソフトウェアのおかげで、私たちのチームの生産性は大幅に上がった。","hint":"同じ時間でどれだけ成果が出せるか。improve/boost productivity の形で頻出"},{"set":2,"word":"projection","pos":"名詞","meaning":"予測、見積もり","example":"According to the projection, revenue will grow by five percent next year.","exampleJa":"予測によれば、来年の収益は5パーセント増える見込みだ。","hint":"グラフの先を点線で延ばした「今後の予測」。sales projection。プロジェクターの投影と同じ系統の語"},{"set":2,"word":"prospective","pos":"形容詞","meaning":"見込みのある、将来の","example":"We invited several prospective clients to tour our new showroom.","exampleJa":"私たちは、見込み客を数社招いて新しいショールームを案内した。","hint":"「これから客になりそう」な人。prospective customer/employer。名詞 prospect も近い"},{"set":2,"word":"publicity","pos":"名詞","meaning":"宣伝、評判","example":"The film festival generated a lot of publicity for the small theater.","exampleJa":"その映画祭は、小さな劇場に大きな宣伝効果をもたらした。","hint":"新製品を世間に知らせるための広報活動。advertising より報道寄りのイメージ"},{"set":2,"word":"quote","pos":"名詞","meaning":"見積もり（額）","example":"Could you send me a quote for printing five hundred copies of the flyer?","exampleJa":"チラシを500部印刷する場合の見積もりを送っていただけますか。","hint":"業者に「いくらですか?」と頼んで出してもらう金額。get a quote。estimate とほぼ同意"},{"set":2,"word":"real estate","pos":"名詞","meaning":"不動産","example":"She works for a real estate company that specializes in commercial properties.","exampleJa":"彼女は、商業用物件を専門に扱う不動産会社に勤めている。","hint":"土地と建物のこと。real estate agent（不動産業者）は街の不動産屋さん"},{"set":2,"word":"recipient","pos":"名詞","meaning":"受取人","example":"The recipient of this year's award will be announced at tomorrow's ceremony.","exampleJa":"今年の受賞者は、明日の式典で発表される。","hint":"プレゼントや手紙を「受け取る側」。受賞者・受取人。receive と音が近い"},{"set":2,"word":"recommend","pos":"動詞","meaning":"勧める、推薦する","example":"I would recommend booking the conference room at least a week in advance.","exampleJa":"会議室は少なくとも1週間前に予約することをお勧めします。","hint":"レストランや人を「おすすめします」と推す場面。recommend A to B / recommend -ing"},{"set":2,"word":"refreshments","pos":"名詞","meaning":"軽食、飲み物","example":"Light refreshments will be served in the lobby after the presentation.","exampleJa":"発表の後、ロビーで軽食と飲み物が提供されます。","hint":"会議やイベントで出る飲み物と軽いお菓子。通常は複数形。Refreshments will be provided"},{"set":2,"word":"registration","pos":"名詞","meaning":"登録、受付","example":"Online registration for the seminar closes on Friday at five o'clock.","exampleJa":"セミナーのオンライン登録は、金曜日の5時に締め切られます。","hint":"イベント会場の「受付」で名前を記入する場面も含む。registration desk / fee"},{"set":2,"word":"relocate","pos":"動詞","meaning":"移転する","example":"The company plans to relocate its headquarters to a larger building next spring.","exampleJa":"その会社は、来春に本社をより大きな建物へ移転する計画だ。","hint":"オフィスや社員が別の場所へ引っ越す。relocate to ~。転勤の話でも使う"},{"set":2,"word":"remind","pos":"動詞","meaning":"思い出させる","example":"This message is to remind you that your appointment is tomorrow at ten.","exampleJa":"このメッセージは、明日の10時にご予約があることをお知らせするためのものです。","hint":"リマインダーメールの「リマインド」。remind A of/about B、remind A to do の形"},{"set":2,"word":"replace","pos":"動詞","meaning":"取り替える、後任になる","example":"We need to replace the old copy machine with a faster model.","exampleJa":"私たちは、古いコピー機をより速い機種に取り替える必要がある。","hint":"古いプリンターを新品に入れ替える、または前任者の後を継ぐ。replace A with B"},{"set":2,"word":"representative","pos":"名詞","meaning":"担当者、代表者","example":"A customer service representative will contact you within two business days.","exampleJa":"カスタマーサービスの担当者が、2営業日以内にご連絡いたします。","hint":"会社や顧客の窓口になる人。sales representative は略して sales rep とも言う"},{"set":2,"word":"resign","pos":"動詞","meaning":"辞職する","example":"The marketing director resigned from her position to start her own business.","exampleJa":"マーケティング部長は、自分の事業を始めるために職を辞した。","hint":"退職願を出して役職を離れる。resign from ~。自動詞で使うのが基本"},{"set":2,"word":"revise","pos":"動詞","meaning":"修正する、改訂する","example":"Please revise the budget proposal and submit it again by Friday.","exampleJa":"予算案を修正して、金曜日までに再提出してください。","hint":"文書や計画を読み直して直す。revised edition（改訂版）、revised schedule"},{"set":2,"word":"scaffolding","pos":"名詞","meaning":"（建設現場の）足場","example":"Workers put up scaffolding around the building before painting the exterior walls.","exampleJa":"作業員たちは、外壁を塗装する前に建物の周りに足場を組んだ。","hint":"工事中のビルの外側に組まれた金属パイプの足場を思い浮かべる。数えられない名詞"},{"set":2,"word":"shortage","pos":"名詞","meaning":"不足","example":"A shortage of raw materials has delayed the production of our new model.","exampleJa":"原材料の不足により、新モデルの生産が遅れている。","hint":"人手や部品が「足りない」状況。a shortage of ~。反対は surplus（余剰）"},{"set":2,"word":"specification","pos":"名詞","meaning":"仕様（書）","example":"The supplier must deliver parts that meet the specifications in the contract.","exampleJa":"納入業者は、契約書の仕様を満たす部品を納品しなければならない。","hint":"製品の寸法・性能を細かく書いた仕様書。複数形 specifications（specs）でよく使う"},{"set":2,"word":"sponsor","pos":"動詞","meaning":"後援する、協賛する","example":"A local bank agreed to sponsor the charity marathon again this year.","exampleJa":"地元の銀行が、今年もチャリティーマラソンに協賛することに同意した。","hint":"イベントの費用を出して名前を掲げる協賛企業。日本語の「スポンサー」と同じだが動詞でも使う"},{"set":2,"word":"stationery","pos":"名詞","meaning":"文房具","example":"Please order more stationery, since we are almost out of envelopes and pens.","exampleJa":"封筒とペンがほとんどなくなりそうなので、文房具を追加で注文してください。","hint":"ペンや封筒など。紙(paper)の e と覚えるのは連想。stationary(静止した)と綴り違いに注意"},{"set":2,"word":"storage","pos":"名詞","meaning":"保管、倉庫","example":"We rented additional storage space to hold the extra inventory.","exampleJa":"私たちは、余った在庫を置くために追加の保管スペースを借りた。","hint":"倉庫や物置に物を保管すること。storage space / cloud storage（データの保管場所にも）"},{"set":2,"word":"subsidiary","pos":"名詞","meaning":"子会社","example":"The firm opened a subsidiary in Singapore to expand its business in Asia.","exampleJa":"その企業は、アジアでの事業を拡大するためにシンガポールに子会社を設立した。","hint":"親会社の傘下にある会社。a subsidiary of ~ の形で使う。parent company と対にする"},{"set":2,"word":"suspend","pos":"動詞","meaning":"一時停止する","example":"Train service was suspended for two hours because of the heavy snow.","exampleJa":"大雪のため、列車の運行は2時間停止された。","hint":"運行や業務が一時ストップする。ニュースで「運転を見合わせ」という場面。受け身で頻出"},{"set":2,"word":"tentative","pos":"形容詞","meaning":"仮の、暫定的な","example":"The tentative agreement must be approved by the board of directors.","exampleJa":"暫定的な合意は、取締役会の承認を受けなければならない。","hint":"「とりあえず仮押さえ」の予定や合意。tentative schedule/agreement。確定は confirmed"},{"set":2,"word":"tuition","pos":"名詞","meaning":"授業料","example":"The firm will reimburse the tuition for courses related to employees' jobs.","exampleJa":"会社は、従業員の職務に関連する講座の授業料を払い戻す。","hint":"大学や講座に払う授業料。tuition fee。社内の学費補助 tuition reimbursement も出る"},{"set":2,"word":"utility","pos":"名詞","meaning":"公共料金（電気・ガス・水道）","example":"The monthly rent includes all utilities, such as water and electricity.","exampleJa":"月々の家賃には、水道や電気などすべての公共料金が含まれている。","hint":"電気・ガス・水道。毎月届く utility bill（光熱費の請求書）で覚える"},{"set":2,"word":"vacancy","pos":"名詞","meaning":"空き、欠員","example":"There is a vacancy in the accounting department, so we are accepting applications.","exampleJa":"経理部に欠員があるため、応募を受け付けています。","hint":"ホテルの「空室あり」の看板と、求人の「欠員」の2場面。job vacancy"},{"set":2,"word":"valid","pos":"形容詞","meaning":"有効な","example":"You must show a valid ID card to enter the building.","exampleJa":"建物に入るには、有効な身分証明書を提示しなければならない。","hint":"チケットや身分証が「まだ使える」状態。valid passport / valid until ~。反対は invalid"},{"set":2,"word":"vendor","pos":"名詞","meaning":"販売業者、売り手","example":"We are looking for a new vendor to supply our office furniture.","exampleJa":"私たちは、オフィス家具を納入してくれる新しい販売業者を探している。","hint":"屋台の売り手や、会社に商品を納める取引業者。vending machine（自販機）と同じ系統"},{"set":2,"word":"warranty","pos":"名詞","meaning":"保証（書）","example":"The laptop is still under warranty, so the repair will not cost anything.","exampleJa":"そのノートパソコンはまだ保証期間中なので、修理は無料です。","hint":"家電の箱に付いている「無料修理の保証書」。under warranty＝保証期間中"},{"set":2,"word":"workshop","pos":"名詞","meaning":"研修会、作業場","example":"Employees are invited to attend a workshop on effective presentation skills.","exampleJa":"従業員は、効果的なプレゼンテーション技術に関する研修会への参加が呼びかけられている。","hint":"講義だけでなく参加者が手を動かす研修会。attend/hold a workshop"},{"set":2,"word":"accurate","pos":"形容詞","meaning":"正確な","example":"Accurate records are essential for preparing the company's annual tax report.","exampleJa":"正確な記録は、会社の年次納税報告書を作成するうえで欠かせない。","hint":"数字や情報にミスがない。accurate data/information。反対は inaccurate"},{"set":2,"word":"adjacent","pos":"形容詞","meaning":"隣接した","example":"The conference hall is adjacent to the main hotel lobby.","exampleJa":"会議場は、ホテルのメインロビーに隣接している。","hint":"壁一枚隣、すぐ横に接している。adjacent to ~。near より「くっついている」感じ"},{"set":2,"word":"affordable","pos":"形容詞","meaning":"手頃な価格の","example":"The store offers affordable furniture for young families and first-time buyers.","exampleJa":"その店は、若い家族や初めて購入する人向けに手頃な価格の家具を提供している。","hint":"afford（余裕がある）+ able。「懐に優しい」値段。affordable price/housing"},{"set":2,"word":"annual","pos":"形容詞","meaning":"年1回の、毎年の","example":"The annual company picnic will be held at the riverside park in June.","exampleJa":"毎年恒例の会社のピクニックは、6月に川沿いの公園で開かれる。","hint":"年に1回あるもの。annual report（年次報告書）、annual meeting。毎月は monthly"},{"set":2,"word":"complimentary","pos":"形容詞","meaning":"無料の、ほめる","example":"Guests receive a complimentary breakfast and free access to the fitness center.","exampleJa":"宿泊客は、無料の朝食とフィットネスセンターの無料利用を受けられる。","hint":"ホテルの「朝食無料」サービス。compliment(賛辞)と綴りが近いが、無料は i でなく -ary と連想"},{"set":2,"word":"comprehensive","pos":"形容詞","meaning":"包括的な","example":"The report provides a comprehensive review of our sales results this year.","exampleJa":"その報告書は、今年の当社の販売実績を包括的に検証している。","hint":"漏れなく全部カバーした。comprehensive insurance/guide/review。「総合」の感覚"},{"set":2,"word":"convenient","pos":"形容詞","meaning":"便利な、都合のよい","example":"Please let us know a convenient time for you to visit our office.","exampleJa":"当社のオフィスにお越しいただくのに都合のよいお時間をお知らせください。","hint":"駅から近くて「ちょうどいい」。convenient location。日程調整の if it is convenient for you も定番"},{"set":2,"word":"durable","pos":"形容詞","meaning":"耐久性のある","example":"This durable backpack is made from waterproof material that lasts for years.","exampleJa":"この丈夫なバックパックは、何年も長持ちする防水素材でできている。","hint":"何年も使える丈夫な素材や製品。durable goods（耐久財）。duration（期間）と近い連想"},{"set":2,"word":"exclusive","pos":"形容詞","meaning":"独占的な、高級な","example":"Members receive an exclusive discount that is not available to the general public.","exampleJa":"会員は、一般の方が利用できない限定割引を受けられる。","hint":"会員だけ、一社だけの限定。exclusive offer/rights。「他は入れない」イメージ"},{"set":2,"word":"extensive","pos":"形容詞","meaning":"広範囲の","example":"She has extensive experience in international sales and project management.","exampleJa":"彼女は、国際営業とプロジェクト管理において幅広い経験を持っている。","hint":"幅広く、範囲が大きい。extensive experience/research。extend（広げる）の仲間"},{"set":2,"word":"flexible","pos":"形容詞","meaning":"柔軟な","example":"Our firm offers flexible working hours so employees can balance work and family.","exampleJa":"当社は、従業員が仕事と家庭を両立できるよう、柔軟な勤務時間を提供している。","hint":"曲げられる体操選手のイメージ。flexible schedule（融通のきく勤務時間）が求人広告の定番"},{"set":2,"word":"renowned","pos":"形容詞","meaning":"有名な","example":"The hotel is renowned for its excellent service and beautiful garden.","exampleJa":"そのホテルは、優れたサービスと美しい庭園で有名だ。","hint":"世界的に名の知れた。be renowned for ~ の形。famous の硬い言い方"},{"set":2,"word":"spacious","pos":"形容詞","meaning":"広々とした","example":"The company moved into a spacious office with plenty of natural light.","exampleJa":"その会社は、自然光がたっぷり入る広々としたオフィスに移った。","hint":"space（空間）に形容詞語尾が付いた形。広い部屋や車内の広告に出る"},{"set":2,"word":"accordingly","pos":"副詞","meaning":"それに応じて","example":"If the schedule changes, we will adjust our delivery dates accordingly.","exampleJa":"日程が変わった場合は、それに応じて納期を調整します。","hint":"状況に合わせた対応を示す。「それに従って」。文末の adjust accordingly が定番"},{"set":2,"word":"currently","pos":"副詞","meaning":"現在","example":"Our sales manager is currently traveling overseas and will return next Monday.","exampleJa":"当社の営業部長は現在海外出張中で、来週の月曜日に戻ります。","hint":"current（今の）の副詞。「今まさに」。進行形や現在形と相性がよい"},{"set":2,"word":"immediately","pos":"副詞","meaning":"すぐに","example":"Please contact the security office immediately if you find a suspicious package.","exampleJa":"不審な荷物を見つけた場合は、直ちに警備室へ連絡してください。","hint":"待たずに「今すぐ」。effective immediately（即日発効）は通知文の定番"},{"set":2,"word":"occasionally","pos":"副詞","meaning":"時々","example":"Our team occasionally works from home when the office is being cleaned.","exampleJa":"私たちのチームは、オフィスの清掃中には時々在宅で勤務する。","hint":"たまに起こる。頻度は always > usually > often > occasionally > rarely の真ん中あたり"},{"set":2,"word":"primarily","pos":"副詞","meaning":"主に","example":"The new software is primarily designed for small businesses with limited budgets.","exampleJa":"この新しいソフトウェアは、主に予算が限られた小規模事業者向けに設計されている。","hint":"「一番の理由は」と言いたい場面。mainly と同意。primarily responsible for ~ の形"},{"set":2,"word":"recently","pos":"副詞","meaning":"最近","example":"The bank recently introduced a mobile app for managing customer accounts.","exampleJa":"その銀行は最近、顧客の口座を管理するためのモバイルアプリを導入した。","hint":"ここ最近の出来事。過去形・現在完了と一緒に使う。recently opened/launched"},{"set":2,"word":"shortly","pos":"副詞","meaning":"まもなく","example":"The flight will depart shortly, so please fasten your seat belts.","exampleJa":"この便はまもなく出発いたしますので、シートベルトをお締めください。","hint":"「もうすぐ」の意味。shortly after/before ~ と、アナウンスの We will arrive shortly を覚える"},{"set":2,"word":"thoroughly","pos":"副詞","meaning":"徹底的に","example":"All machines are thoroughly inspected before they leave the factory.","exampleJa":"すべての機械は、工場から出荷される前に徹底的に検査される。","hint":"隅々まで抜けなく。check/clean/review thoroughly。through（通り抜けて）と綴りが似る連想"},{"set":2,"word":"unfortunately","pos":"副詞","meaning":"あいにく、残念ながら","example":"Unfortunately, the item you ordered is temporarily out of stock.","exampleJa":"あいにく、ご注文の商品は一時的に在庫切れとなっております。","hint":"悪い知らせを切り出す前置き。お詫びのメールの冒頭によく出る"},{"set":3,"word":"abroad","pos":"副詞","meaning":"海外に、外国へ","example":"Many of our engineers have worked abroad for at least two years.","exampleJa":"当社の技術者の多くは、少なくとも2年間は海外で働いた経験があります。","hint":"「海外出張で abroad へ」と、go abroad の形で覚える。前置詞toは不要で副詞単独で使う"},{"set":3,"word":"accessible","pos":"形容詞","meaning":"利用しやすい、行きやすい","example":"The new office is easily accessible by subway and bus.","exampleJa":"新しいオフィスは地下鉄とバスで簡単に行くことができます。","hint":"「駅から近くて accessible」「車椅子でも accessible」と、行きやすさ・使いやすさの両方に使う"},{"set":3,"word":"acknowledge","pos":"動詞","meaning":"認める、受け取ったことを知らせる","example":"Please acknowledge receipt of this email by replying before noon.","exampleJa":"正午までに返信して、このメールの受領をお知らせください。","hint":"メールで「受け取りました」と返す場面を想像。acknowledge receipt of ~ の形で頻出"},{"set":3,"word":"adequate","pos":"形容詞","meaning":"十分な、適切な","example":"The storage room does not provide adequate space for the new inventory.","exampleJa":"その倉庫は新しい在庫を置くのに十分なスペースがありません。","hint":"「ぎりぎり足りる」ニュアンス。adequate space/staff/funding の組み合わせで覚える"},{"set":3,"word":"adjust","pos":"動詞","meaning":"調整する","example":"We had to adjust the meeting schedule because the client arrived late.","exampleJa":"顧客の到着が遅れたため、会議の予定を調整しなければなりませんでした。","hint":"椅子の高さ、時間割、設定をちょうどよく合わせる場面。adjust to ~ なら「慣れる」の意味にもなる"},{"set":3,"word":"administration","pos":"名詞","meaning":"管理、運営、管理部門","example":"The administration will announce the new security policy next Monday.","exampleJa":"管理部門は来週月曜日に新しいセキュリティ方針を発表する予定です。","hint":"会社の「総務・管理部門」や大学の事務局のイメージ。the administration office は頻出の表現"},{"set":3,"word":"advertisement","pos":"名詞","meaning":"広告","example":"The company placed an advertisement in the newspaper to attract new customers.","exampleJa":"その会社は新規顧客を集めるために新聞に広告を出しました。","hint":"短縮形 ad が会話では普通。「新聞に advertisement を載せる」の形で覚える"},{"set":3,"word":"advise","pos":"動詞","meaning":"助言する、知らせる","example":"Passengers are advised that the train will be delayed by twenty minutes.","exampleJa":"乗客の皆様にお知らせします。列車は20分遅れております。","hint":"動詞は advise（ズ）、名詞は advice（ス）。つづりと発音の違いに注意。be advised that ~ は「お知らせします」"},{"set":3,"word":"allocate","pos":"動詞","meaning":"割り当てる、配分する","example":"The manager allocated more funds to the marketing department this quarter.","exampleJa":"部長は今四半期、マーケティング部門により多くの資金を割り当てました。","hint":"部署ごとに予算や人員を「配る」場面。allocate A to B の形でセットで覚える"},{"set":3,"word":"alternative","pos":"名詞","meaning":"代わりのもの、代替案","example":"If the supplier cannot deliver, we need an alternative to this plan.","exampleJa":"仕入先が納品できない場合に備え、この計画の代替案が必要です。","hint":"「A案がだめなら alternative（B案）」。alternative to ~ の形で使う。音の連想は「オルタナ」ロック"},{"set":3,"word":"amenity","pos":"名詞","meaning":"（快適な）設備、アメニティ","example":"The hotel offers amenities such as a fitness center and free breakfast.","exampleJa":"そのホテルはフィットネスセンターや無料の朝食などの設備を提供しています。","hint":"ホテルの宿泊案内にある「設備一覧」を連想。ふつう複数形 amenities で使う"},{"set":3,"word":"anticipate","pos":"動詞","meaning":"予期する、楽しみに待つ","example":"We anticipate a sharp increase in orders during the holiday season.","exampleJa":"私たちは、休暇シーズンに注文が急増すると予想しています。","hint":"「先回りして予測し備える」場面。expect より準備のニュアンスが強い。anticipate -ing もよく使う"},{"set":3,"word":"eventually","pos":"副詞","meaning":"最終的に、結局","example":"After months of negotiation, the two firms eventually signed the contract.","exampleJa":"数か月に及ぶ交渉の末、両社は最終的に契約を結びました。","hint":"紆余曲折のすえ「結局は」。文頭・動詞の前に置き、時間がかかった感じを出す。actually と混同しないこと"},{"set":3,"word":"appliance","pos":"名詞","meaning":"家電製品、器具","example":"The store offers a ten percent discount on all kitchen appliances this week.","exampleJa":"その店は今週、すべてのキッチン家電を10パーセント割引で販売しています。","hint":"冷蔵庫・洗濯機・電子レンジなど、家庭用の電気製品を並べて思い浮かべる。home appliances の形で使う"},{"set":3,"word":"appreciate","pos":"動詞","meaning":"感謝する、正しく評価する","example":"We appreciate your patience while we repair the system.","exampleJa":"システムを修理している間、お待ちいただきありがとうございます。","hint":"I appreciate ~ で「〜に感謝します」。thank と違い、人ではなく事柄を目的語にとる。価値を認める気持ちを表す"},{"set":3,"word":"appropriate","pos":"形容詞","meaning":"適切な","example":"Employees must wear appropriate clothing when meeting clients.","exampleJa":"従業員は顧客と会うときには適切な服装をしなければなりません。","hint":"面接に「適切な服装」で行く場面。as appropriate は「必要に応じて」で、書類でよく見る"},{"set":3,"word":"assemble","pos":"動詞","meaning":"組み立てる、集まる","example":"Workers assemble about two hundred units on this line every day.","exampleJa":"作業員たちはこのラインで毎日約200台を組み立てています。","hint":"工場で部品を組み立てる場面。「集まる」の意味もあり、名詞 assembly（組立・集会）とセットで覚える"},{"set":3,"word":"asset","pos":"名詞","meaning":"資産、強み","example":"Her language skills are a valuable asset to our international sales team.","exampleJa":"彼女の語学力は、当社の海外営業チームにとって貴重な財産です。","hint":"貸借対照表の「資産」の欄を連想。人材に使うと「頼れる戦力」の意味になる"},{"set":3,"word":"assist","pos":"動詞","meaning":"手伝う","example":"Our staff will assist guests with luggage at the front entrance.","exampleJa":"スタッフが正面玄関でお客様の荷物のお手伝いをいたします。","hint":"assistant（助手）の動詞形。assist A with B で「AのBを手伝う」。help より少しかたい"},{"set":3,"word":"attach","pos":"動詞","meaning":"添付する、取り付ける","example":"I have attached the revised budget for your review.","exampleJa":"ご確認いただくため、修正した予算書を添付しました。","hint":"メールにファイルをクリップで留めるイメージ。attached file、attachment の形で頻出。反対は detach"},{"set":3,"word":"audit","pos":"名詞","meaning":"監査","example":"An outside firm will conduct an audit of our accounts in March.","exampleJa":"外部の会社が3月に当社の会計の監査を行う予定です。","hint":"決算期に外部の人が帳簿をチェックしに来る場面。audit の発音は「オーディット」。an annual audit の形で"},{"set":3,"word":"bulk","pos":"名詞","meaning":"大量、大部分","example":"We receive a discount when we purchase office supplies in bulk.","exampleJa":"事務用品を大量にまとめて購入すると、割引を受けられます。","hint":"倉庫型店舗でトイレットペーパーをどっさり買う場面。in bulk は「大量に」、bulk order は「大口注文」"},{"set":3,"word":"campaign","pos":"名詞","meaning":"（組織的な）運動、キャンペーン","example":"The marketing team launched a campaign to promote the new smartphone.","exampleJa":"マーケティングチームは新しいスマートフォンを宣伝するキャンペーンを開始しました。","hint":"選挙運動や広告キャンペーンのように、期間と目標のある一連の活動。launch a campaign の組み合わせで覚える"},{"set":3,"word":"cancellation","pos":"名詞","meaning":"取り消し、キャンセル","example":"A cancellation made within 24 hours of the event incurs a fee.","exampleJa":"イベントの24時間以内にキャンセルされた場合は、料金がかかります。","hint":"cancel の名詞形。ll が2つ並ぶつづりに注意（cancelation も米国では可）。cancellation policy / fee で頻出"},{"set":3,"word":"capacity","pos":"名詞","meaning":"収容能力、能力","example":"The conference hall has a seating capacity of three hundred people.","exampleJa":"その会議場の座席数は300人分あります。","hint":"ホールの収容人数や工場の生産能力など「入る・できる上限」。at full capacity は「満員・フル稼働」"},{"set":3,"word":"certificate","pos":"名詞","meaning":"証明書、修了証","example":"Participants will receive a certificate after completing the training course.","exampleJa":"参加者は研修コースを修了すると、修了証を受け取ります。","hint":"修了証や商品券など「公式な紙」のイメージ。動詞 certify（証明する）と区別。gift certificate は商品券"},{"set":3,"word":"charge","pos":"名詞","meaning":"料金、責任","example":"There is no additional charge for shipping on orders over fifty dollars.","exampleJa":"50ドルを超えるご注文には、追加の送料はかかりません。","hint":"名詞は「料金」と「責任」の2つ。free of charge は無料、in charge of は「〜の担当」で対比して覚える"},{"set":3,"word":"circulate","pos":"動詞","meaning":"回覧する、循環する","example":"Please circulate the meeting notes to everyone in the department.","exampleJa":"会議の議事録を部署の全員に回覧してください。","hint":"回覧板がぐるっと回る場面。circle（円）と音が似ているという連想。memo や report を回すときに使う"},{"set":3,"word":"regularly","pos":"副詞","meaning":"定期的に","example":"The machines are inspected regularly to prevent unexpected breakdowns.","exampleJa":"予期せぬ故障を防ぐため、機械は定期的に点検されています。","hint":"毎週の定例会議のように、決まった間隔で繰り返す感じ。regularly scheduled ~ は「定期的な」"},{"set":3,"word":"collaborate","pos":"動詞","meaning":"協力する、共同で取り組む","example":"Our design team collaborates with engineers on every new product.","exampleJa":"当社のデザインチームは、すべての新製品でエンジニアと協力して取り組んでいます。","hint":"共同プロジェクトで他社と手を組む場面。collaborate with 人 on 事柄 の形。labor（労働）を含むのが手がかり"},{"set":3,"word":"commercial","pos":"形容詞","meaning":"商業の、営利の","example":"The company plans to build a commercial complex near the station.","exampleJa":"その会社は駅の近くに商業施設を建設する計画です。","hint":"テレビの CM（commercial）と同じ語。形容詞では「商業用の」で、commercial district は商業地区"},{"set":3,"word":"commission","pos":"名詞","meaning":"手数料、委託","example":"Sales representatives earn a commission of five percent on each contract.","exampleJa":"営業担当者は、契約ごとに5パーセントの手数料を受け取ります。","hint":"営業職が売上に応じてもらう「歩合」を想像。on commission は「歩合制で」"},{"set":3,"word":"committee","pos":"名詞","meaning":"委員会","example":"The budget committee will review the proposal on Thursday afternoon.","exampleJa":"予算委員会は木曜日の午後にその提案を審査します。","hint":"つづりは m と t が2つずつ（mm, tt, ee）。「コミッティー」と読み、会議で決定を担う少人数の集まり"},{"set":3,"word":"compensation","pos":"名詞","meaning":"報酬、補償","example":"The firm offers competitive compensation, including bonuses and health insurance.","exampleJa":"その会社は賞与や健康保険を含む、他社に負けない待遇を提供しています。","hint":"給与や手当、または損害の埋め合わせ。「求人広告の compensation は給与条件」と「事故の補償」の2場面で覚える"},{"set":3,"word":"component","pos":"名詞","meaning":"部品、構成要素","example":"A supplier in Malaysia delivers the key components for our printers.","exampleJa":"マレーシアの仕入先が、当社のプリンターの主要部品を納入しています。","hint":"完成品を構成するパーツの1つ。工場・製造の話題で出る。electronic components の形で覚える"},{"set":3,"word":"consecutive","pos":"形容詞","meaning":"連続した","example":"The store has recorded record sales for five consecutive months.","exampleJa":"その店は5か月連続で過去最高の売上を記録しています。","hint":"「3日連続」のように途切れず続く場面。two consecutive days のように数字とセットで使う"},{"set":3,"word":"consult","pos":"動詞","meaning":"相談する、参照する","example":"Please consult the user manual before contacting customer support.","exampleJa":"カスタマーサポートに連絡する前に、取扱説明書を参照してください。","hint":"専門家や資料に意見を求める場面。consult with 人 / consult 資料 の形。consultant（相談役）と関連づける"},{"set":3,"word":"consumer","pos":"名詞","meaning":"消費者","example":"Consumer spending rose sharply after the government cut taxes.","exampleJa":"政府が減税を行った後、消費者支出は大きく伸びました。","hint":"「消費する人」。customer が特定の店の客なのに対し、consumer は商品を使う一般の人というイメージ"},{"set":3,"word":"correspondence","pos":"名詞","meaning":"通信、文書のやり取り","example":"All correspondence regarding the contract should be sent to the legal department.","exampleJa":"契約に関する書簡はすべて法務部に送ってください。","hint":"手紙やメールのやり取り全般。不可算名詞なので a や複数形 s は付けない点に注意"},{"set":3,"word":"coverage","pos":"名詞","meaning":"報道、（保険の）補償範囲","example":"Our insurance coverage includes damage caused by fire and flooding.","exampleJa":"当社の保険の補償範囲には、火災や洪水による損害が含まれます。","hint":"ニュースの「報道量」と保険の「補償範囲」の2場面。cover（覆う）範囲、と考える"},{"set":3,"word":"crew","pos":"名詞","meaning":"作業員、乗組員","example":"The cleaning crew arrives at six every evening to prepare the offices.","exampleJa":"清掃班は毎晩6時に到着し、オフィスを整えます。","hint":"工事現場の作業チームや船・飛行機の乗組員。construction crew、cleaning crew のように「〜班」で使う"},{"set":3,"word":"deposit","pos":"名詞","meaning":"手付金、預金","example":"Customers must pay a deposit to reserve the meeting room.","exampleJa":"会議室を予約するには、お客様に手付金をお支払いいただく必要があります。","hint":"部屋を借りる時の「敷金・手付金」と銀行の「預金」。どちらも「先に預けるお金」と考える"},{"set":3,"word":"designate","pos":"動詞","meaning":"指定する","example":"Smoking is permitted only in the designated area behind the building.","exampleJa":"喫煙は建物の裏の指定された場所でのみ許可されています。","hint":"「喫煙エリアに指定」のように、場所や人を正式に決める。designated area / driver の形で覚える"},{"set":3,"word":"detour","pos":"名詞","meaning":"迂回路、回り道","example":"Drivers must take a detour because the main bridge is closed for repairs.","exampleJa":"本橋が補修のため閉鎖されているので、運転手は迂回しなければなりません。","hint":"道路工事で通行止め、矢印の看板に従って遠回り。「デトゥア」と読む。take a detour の形"},{"set":3,"word":"diverse","pos":"形容詞","meaning":"多様な","example":"Our company offers a diverse range of services to small businesses.","exampleJa":"当社は中小企業向けに多様なサービスを提供しています。","hint":"さまざまな国籍・経歴の人が集まる職場を想像。diverse workforce / range の形。名詞は diversity"},{"set":3,"word":"domestic","pos":"形容詞","meaning":"国内の、家庭の","example":"Domestic sales grew by eight percent while overseas sales declined.","exampleJa":"国内の売上は8パーセント伸びましたが、海外の売上は減少しました。","hint":"国内線 (domestic flight) と国際線 (international) を対比。「家庭内の」の意味もある"},{"set":3,"word":"draft","pos":"名詞","meaning":"下書き、草案","example":"I will send you the first draft of the report by Friday.","exampleJa":"金曜日までに報告書の初稿をお送りします。","hint":"完成前の「たたき台」を同僚に回す場面。first draft（初稿）、final draft（最終稿）の形で"},{"set":3,"word":"duplicate","pos":"名詞","meaning":"複製、控え","example":"Please keep a duplicate of the signed form for your records.","exampleJa":"署名済みの書式の控えを、記録としてお手元に保管してください。","hint":"名詞は「デュープリケット」と発音し、動詞は語尾が「エイト」。in duplicate は「正副2通で」"},{"set":3,"word":"emphasize","pos":"動詞","meaning":"強調する","example":"The director emphasized the importance of meeting every deadline.","exampleJa":"部長はすべての締め切りを守ることの重要性を強調しました。","hint":"プレゼンで大事な点を強く言う場面。emphasize the importance of ~ の形。名詞 emphasis とつづりを比べる"},{"set":3,"word":"encourage","pos":"動詞","meaning":"奨励する、励ます","example":"Managers encourage employees to take part in the training sessions.","exampleJa":"管理職は従業員に研修会への参加を奨励しています。","hint":"encourage 人 to do の形。社内通知の Employees are encouraged to ~ は「〜することが推奨されます」"},{"set":3,"word":"endorse","pos":"動詞","meaning":"支持する、推薦する","example":"A famous athlete agreed to endorse our new line of running shoes.","exampleJa":"有名なアスリートが、当社の新しいランニングシューズシリーズの推薦を引き受けてくれました。","hint":"有名人が商品を「推薦」する広告を連想。小切手の裏書きの意味もある。endorse a product の形"},{"set":3,"word":"ensure","pos":"動詞","meaning":"確実にする","example":"Please ensure that all windows are closed before you leave the office.","exampleJa":"退社する前に、すべての窓が閉まっていることを必ず確認してください。","hint":"ensure that ~ で「確実に〜となるようにする」。insure（保険をかける）と形が似ているので混同しない"},{"set":3,"word":"entrepreneur","pos":"名詞","meaning":"起業家","example":"The young entrepreneur started her own software company at the age of twenty-five.","exampleJa":"その若い起業家は25歳で自分のソフトウェア会社を立ち上げました。","hint":"スタートアップを立ち上げる人。つづりが長く難しいので、「アントレプレナー」と音で区切って覚える"},{"set":3,"word":"exceed","pos":"動詞","meaning":"超える","example":"Last quarter's profits exceeded our original forecast by ten percent.","exampleJa":"前四半期の利益は、当初の予測を10パーセント上回りました。","hint":"目標や予算の線を「越える」。exceed expectations / the limit / the budget の組み合わせで覚える"},{"set":3,"word":"executive","pos":"名詞","meaning":"重役、幹部","example":"The company's executives will meet shareholders at the annual conference.","exampleJa":"会社の幹部たちは、年次総会で株主と面会します。","hint":"名刺の「役員」の肩書きを連想。executive director、executive meeting のように役職や会議に使う"},{"set":3,"word":"consistently","pos":"副詞","meaning":"一貫して、常に","example":"Our products have consistently received high ratings from customers.","exampleJa":"当社の製品は、お客様から一貫して高い評価を受けています。","hint":"毎回ぶれずに同じ水準を保つ場面。consistently high quality / good results のように「安定して」の意味"},{"set":3,"word":"flyer","pos":"名詞","meaning":"チラシ","example":"Volunteers handed out flyers advertising the grand opening of the store.","exampleJa":"ボランティアの人たちが、店のグランドオープンを知らせるチラシを配りました。","hint":"駅前でチラシを配る場面。fly（飛ぶ）のように何枚も配られる、という連想。leaflet とほぼ同じ"},{"set":3,"word":"fragile","pos":"形容詞","meaning":"壊れやすい","example":"Please wrap the fragile items carefully before placing them in the box.","exampleJa":"壊れやすい品物は、箱に入れる前に丁寧に包んでください。","hint":"荷物に貼られる「取扱注意」のシール。ガラス製品の箱を思い浮かべる。Fragile: Handle with care. とセットで"},{"set":3,"word":"fundraising","pos":"名詞","meaning":"資金集め、募金","example":"The charity held a fundraising dinner to support the new community center.","exampleJa":"その慈善団体は、新しいコミュニティセンターを支援するための資金集めの晩餐会を開きました。","hint":"fund（資金）を raise（集める）。チャリティーの募金活動のイメージ。fundraising dinner / campaign の形"},{"set":3,"word":"hesitate","pos":"動詞","meaning":"ためらう","example":"Please do not hesitate to call me if you have any questions.","exampleJa":"ご質問がございましたら、遠慮なく私にお電話ください。","hint":"メールの結びの Don't hesitate to contact us. が定番。「ためらわずに連絡して」の意味"},{"set":3,"word":"inclement","pos":"形容詞","meaning":"（天候が）荒れた","example":"The outdoor concert was postponed due to inclement weather.","exampleJa":"野外コンサートは悪天候のため延期されました。","hint":"in は「否定」で、悪天候のお知らせに出る。inclement weather の決まった形で覚える"},{"set":3,"word":"indicate","pos":"動詞","meaning":"示す","example":"Survey results indicate that most customers prefer online ordering.","exampleJa":"調査結果は、ほとんどの顧客がオンライン注文を好むことを示しています。","hint":"グラフや調査結果が「〜を示す」場面。indicator（指標）と並べて覚える。show よりかたい表現"},{"set":3,"word":"ingredient","pos":"名詞","meaning":"材料、成分","example":"The restaurant uses only fresh ingredients from local farms.","exampleJa":"そのレストランは、地元の農場の新鮮な食材だけを使っています。","hint":"レストランのレシピに並ぶ食材。比喩的に「成功の要素」にも使う。fresh ingredients の形で"},{"set":3,"word":"innovative","pos":"形容詞","meaning":"革新的な","example":"The firm is known for its innovative approach to product design.","exampleJa":"その会社は製品デザインへの革新的な取り組みで知られています。","hint":"新製品の宣伝文句によく出る。「イノベーション」の形容詞形。innovative technology / design の形"},{"set":3,"word":"intend","pos":"動詞","meaning":"〜するつもりである","example":"We intend to open two new branches in Asia next year.","exampleJa":"私たちは来年、アジアに新しい支店を2つ開設するつもりです。","hint":"計画を語る場面。intend to do の形で「〜するつもり」。名詞 intention とつなげて覚える"},{"set":3,"word":"intersection","pos":"名詞","meaning":"交差点","example":"The bank is located at the intersection of Main Street and Oak Avenue.","exampleJa":"その銀行はメインストリートとオーク通りの交差点にあります。","hint":"道案内で「次の交差点を右へ」と言う場面。section（区切り）の間に inter が入る、という連想"},{"set":3,"word":"issue","pos":"名詞","meaning":"問題、（雑誌の）号","example":"The technical team is working to resolve the issue with the login page.","exampleJa":"技術チームは、ログインページの問題を解決するために取り組んでいます。","hint":"「問題」と「雑誌の号」の2つ。address an issue（問題に対処する）、the May issue（5月号）で対比して覚える"},{"set":3,"word":"frequently","pos":"副詞","meaning":"頻繁に、しばしば","example":"Customers frequently ask whether we offer free delivery.","exampleJa":"お客様からは、無料配送があるかどうかをよく尋ねられます。","hint":"FAQ の F は frequently。「何度も聞かれる」。often より少しかたい。frequent の副詞"},{"set":3,"word":"lucrative","pos":"形容詞","meaning":"もうかる","example":"Signing the overseas contract turned out to be a lucrative decision.","exampleJa":"海外との契約を結んだのは、結果的にもうかる決断となりました。","hint":"「大もうけできる」という感じで、lucrative deal / contract / career の形で使う。くだけた profitable より強い響き"},{"set":3,"word":"malfunction","pos":"名詞","meaning":"故障、不具合","example":"A malfunction in the printer delayed the distribution of the documents.","exampleJa":"プリンターの故障のため、書類の配布が遅れました。","hint":"mal- は「悪い」の意味を持つ接頭辞（malnutrition など）。機械が突然止まる場面で使う"},{"set":3,"word":"mention","pos":"動詞","meaning":"言及する","example":"The manager mentioned that the deadline might be extended.","exampleJa":"部長は、締め切りが延長されるかもしれないと述べました。","hint":"「〜に言及する」。mention that ~ の形で、about は付けない。Don't mention it.（どういたしまして）も覚える"},{"set":3,"word":"modify","pos":"動詞","meaning":"修正する、変更する","example":"We need to modify the contract before both parties sign it.","exampleJa":"双方が署名する前に、契約書を修正する必要があります。","hint":"完成後に少し手直しする場面。modified design（修正版）。大幅な変更ではなく部分的な変更のイメージ"},{"set":3,"word":"monitor","pos":"動詞","meaning":"監視する、注意して見る","example":"A project manager will monitor the progress of each team weekly.","exampleJa":"プロジェクトマネージャーが、毎週各チームの進捗を見守ります。","hint":"名詞は「画面」でおなじみ。動詞では、画面を見張るように経過を「監視する」。monitor progress の形"},{"set":3,"word":"objective","pos":"名詞","meaning":"目的、目標","example":"The main objective of this workshop is to improve teamwork.","exampleJa":"この研修会の主な目的は、チームワークを向上させることです。","hint":"会議の冒頭に示される「この会議の目標」。goal より正式。主に複数形 objectives で、形容詞では「客観的な」"},{"set":3,"word":"obtain","pos":"動詞","meaning":"得る、手に入れる","example":"Visitors must obtain a badge from the front desk before entering.","exampleJa":"来訪者は、入場する前に受付で入館証を受け取らなければなりません。","hint":"許可証や情報を苦労して手に入れる場面。obtain permission / approval / a license の形。get のかたい言い方"},{"set":3,"word":"occupation","pos":"名詞","meaning":"職業","example":"Please write your name, address, and occupation on the application form.","exampleJa":"申込用紙に、お名前、ご住所、ご職業をご記入ください。","hint":"申込書の「職業」欄を思い浮かべる。occupy（占める）から、「時間を占める仕事」と考える。job よりかたい"},{"set":3,"word":"operate","pos":"動詞","meaning":"操作する、営業する","example":"Only trained staff are allowed to operate the heavy machinery.","exampleJa":"訓練を受けたスタッフだけが、その重機を操作することを許可されています。","hint":"機械を「操作する」のと、店が「営業する」の2つ。operate machinery / operate 24 hours で対比"},{"set":3,"word":"outlet","pos":"名詞","meaning":"直販店、コンセント","example":"The company opened a new factory outlet near the highway.","exampleJa":"その会社は幹線道路の近くに新しい直販店を開きました。","hint":"郊外のアウトレットモールを連想。「コンセント」の意味もあるので、電気の話題では要注意"},{"set":3,"word":"oversee","pos":"動詞","meaning":"監督する","example":"Ms. Chen will oversee the construction of the new warehouse.","exampleJa":"チェンさんが新しい倉庫の建設を監督します。","hint":"現場監督が上から全体を見渡す場面。over（上から）+ see（見る）で、語の構成そのままの意味"},{"set":3,"word":"periodical","pos":"名詞","meaning":"定期刊行物","example":"The library subscribes to several business periodicals and academic journals.","exampleJa":"その図書館は、いくつかのビジネス定期刊行物や学術雑誌を定期購読しています。","hint":"図書館の雑誌コーナーを連想。週刊・月刊など決まった周期で出る雑誌や新聞の総称"},{"set":3,"word":"permit","pos":"名詞","meaning":"許可証","example":"You need a parking permit to leave your car in this lot.","exampleJa":"この駐車場に車を置くには、駐車許可証が必要です。","hint":"名詞は「パーミット」と前にアクセント、動詞は「パーミット」と後ろに。駐車許可証や建築許可証で出る"},{"set":3,"word":"persuade","pos":"動詞","meaning":"説得する","example":"She persuaded the client to extend the contract for another year.","exampleJa":"彼女は顧客を説得して、契約をさらに1年延長してもらいました。","hint":"persuade 人 to do の形で、粘り強く説得して動かす場面。convince と違い、行動まで促す"},{"set":3,"word":"portfolio","pos":"名詞","meaning":"作品集、ポートフォリオ","example":"Applicants for the design position must submit a portfolio of recent work.","exampleJa":"デザイナー職の応募者は、最近の作品をまとめた作品集を提出しなければなりません。","hint":"デザイナーや投資家が持つ「作品集・資産一覧」の厚いファイルを思い浮かべる。面接での提出物としても頻出"},{"set":3,"word":"practical","pos":"形容詞","meaning":"実用的な、現実的な","example":"The job requires practical experience in managing large budgets.","exampleJa":"その職務には、大きな予算を管理する実務経験が求められます。","hint":"理論より「役に立つ」。practical experience（実務経験）は求人広告の定番。practice の形容詞"},{"set":3,"word":"precaution","pos":"名詞","meaning":"予防措置、用心","example":"As a precaution, the staff evacuated the building during the fire drill.","exampleJa":"念のため、スタッフは防火訓練中に建物から避難しました。","hint":"災害や事故の前に備える「念のため」の措置。as a precaution は「念のため」、take precautions は「予防措置を取る」"},{"set":3,"word":"prior","pos":"形容詞","meaning":"前の、事前の","example":"Please submit your expense report prior to the end of the month.","exampleJa":"月末までに経費報告書をご提出ください。","hint":"prior to ~ は before のかたい言い方で、案内文によく出る。prior experience は「これまでの経験」"},{"set":3,"word":"punctual","pos":"形容詞","meaning":"時間厳守の","example":"Our manager values employees who are punctual and well prepared.","exampleJa":"当社の部長は、時間に正確で準備の整った従業員を高く評価しています。","hint":"電車の遅延が多い国では特に褒められる「時間通り」。be punctual for ~ の形。「パンクチュアル」と音に注意"},{"set":3,"word":"questionnaire","pos":"名詞","meaning":"アンケート用紙","example":"Customers were asked to complete a short questionnaire about our service.","exampleJa":"お客様には、当社のサービスに関する短いアンケートへの記入をお願いしました。","hint":"つづりは question に -naire。「ケスチョネア」と読む。顧客満足度調査の紙を思い浮かべる"},{"set":3,"word":"reasonable","pos":"形容詞","meaning":"手頃な、妥当な","example":"The restaurant offers high-quality lunches at reasonable prices.","exampleJa":"そのレストランは質の高いランチを手頃な価格で提供しています。","hint":"値段が「高すぎず安すぎず納得できる」場面。reasonable price / rate。cheap と違い悪い意味がない"},{"set":3,"word":"receptionist","pos":"名詞","meaning":"受付係","example":"The receptionist will give you a visitor pass and direct you upstairs.","exampleJa":"受付係が来訪者用の入館証をお渡しし、上の階へご案内します。","hint":"会社の入口で来客を迎える人。reception（受付）に -ist（〜する人）が付いた形"},{"set":3,"word":"reference","pos":"名詞","meaning":"推薦状、参照","example":"Please keep this receipt for future reference.","exampleJa":"今後の参考のために、この領収書を保管しておいてください。","hint":"転職時に前の上司が書く「推薦状」や、資料を見る「参照」。for future reference は「今後の参考のために」"},{"set":3,"word":"reliable","pos":"形容詞","meaning":"信頼できる","example":"We are looking for a reliable supplier who can deliver on time.","exampleJa":"私たちは、時間通りに納品できる信頼できる仕入先を探しています。","hint":"「頼れる配送業者」「故障しない車」のように、期待を裏切らないものに使う。rely on（〜を頼る）と一緒に"},{"set":3,"word":"remodel","pos":"動詞","meaning":"改装する","example":"The owners plan to remodel the lobby before the summer season.","exampleJa":"所有者は夏のシーズン前にロビーを改装する予定です。","hint":"古い店や台所を作り直す工事の場面。renovate とほぼ同じ意味。re-（再び）の接頭辞が付く"},{"set":3,"word":"renew","pos":"動詞","meaning":"更新する","example":"You must renew your membership before it expires at the end of May.","exampleJa":"会員資格は5月末に失効するので、その前に更新する必要があります。","hint":"期限が来た契約・会員証・パスポートを更新する場面。new に re- が付いた形。renew a contract / subscription"},{"set":3,"word":"retail","pos":"名詞","meaning":"小売","example":"The retail industry usually hires many temporary workers during the holidays.","exampleJa":"小売業界は、休暇シーズンに多くの臨時従業員を雇うのが普通です。","hint":"店頭で消費者に売るのが小売、問屋から大量に買うのが wholesale と対比。retail price は小売価格"},{"set":3,"word":"sufficient","pos":"形容詞","meaning":"十分な","example":"The account does not have sufficient funds to cover the payment.","exampleJa":"その口座には、支払いをまかなうのに十分な資金がありません。","hint":"enough のかたい言い方で、契約書や案内文に出る。sufficient funds（十分な残高）。反対は insufficient"},{"set":3,"word":"transaction","pos":"名詞","meaning":"取引","example":"Every transaction is recorded in the company's accounting system.","exampleJa":"すべての取引は会社の会計システムに記録されます。","hint":"銀行やネット通販での1回ごとの「取引」。transaction record は取引明細。trans- は「越えて」で、やり取りの感じ"},{"set":3,"word":"undergo","pos":"動詞","meaning":"（検査・改修などを）受ける","example":"The main building will undergo major renovation next spring.","exampleJa":"本館は来年の春に大規模な改装を受ける予定です。","hint":"工場や建物が「改修を受ける」、人が「検査を受ける」場面。undergo repairs / renovation / training"},{"set":3,"word":"unanimous","pos":"形容詞","meaning":"満場一致の","example":"The board reached a unanimous decision to approve the merger.","exampleJa":"取締役会は合併を承認するという満場一致の決定に達しました。","hint":"役員会で全員が賛成する場面。uni（1つ）の連想で「全員が1つの意見」と覚える。unanimous vote / decision"},{"set":3,"word":"voucher","pos":"名詞","meaning":"引換券、クーポン","example":"Each participant received a meal voucher valid at the hotel restaurant.","exampleJa":"参加者はそれぞれ、ホテルのレストランで使える食事券を受け取りました。","hint":"レストランやホテルで代金の代わりに渡せる券。gift card に近い。meal voucher / discount voucher"},{"set":4,"word":"accomplish","pos":"動詞","meaning":"成し遂げる","example":"The sales team accomplished all of its targets before the end of the fiscal year.","exampleJa":"営業チームは会計年度末までにすべての目標を達成した。","hint":"「目標をaccomplish」と覚える定番コロケーション。complete(完了)と似た響きで「やり遂げる」と連想"},{"set":4,"word":"accountant","pos":"名詞","meaning":"会計士","example":"Our accountant will review the quarterly expense reports before they are submitted.","exampleJa":"当社の会計士が、四半期の経費報告書を提出前に確認します。","hint":"account(会計・勘定)+人を表す-ant。数字の帳尻を合わせる人の姿を思い浮かべよう"},{"set":4,"word":"acquire","pos":"動詞","meaning":"取得する、買収する","example":"The company plans to acquire a smaller competitor to expand its market share.","exampleJa":"その会社は市場シェアを拡大するため、より小規模な競合会社を買収する予定だ。","hint":"M&Aのニュースで「A社がB社をacquire」とよく見る語。「手に入れる」の硬い言い方"},{"set":4,"word":"adhere","pos":"動詞","meaning":"(規則を)守る、くっつく","example":"All employees must adhere to the safety regulations while working in the factory.","exampleJa":"全従業員は、工場内で作業する間、安全規則を守らなければならない。","hint":"adhesive tape(接着テープ)の仲間と連想。「規則にぴったり貼りつく」→ adhere to ~"},{"set":4,"word":"advance","pos":"名詞","meaning":"進歩、前進","example":"Please submit your vacation request at least two weeks in advance.","exampleJa":"休暇申請は少なくとも2週間前までに提出してください。","hint":"「in advance(前もって)」が最頻出。advance notice、advance ticketもセットで"},{"set":4,"word":"affiliate","pos":"名詞","meaning":"系列会社、関連団体","example":"Our overseas affiliate will handle customer support for the Asian market.","exampleJa":"当社の海外関連会社が、アジア市場向けの顧客サポートを担当します。","hint":"本社の「身内」にあたる会社。parent company(親会社)と対で覚える"},{"set":4,"word":"aisle","pos":"名詞","meaning":"通路","example":"Frozen foods are located in aisle six, next to the dairy section.","exampleJa":"冷凍食品は乳製品売り場の隣の6番通路にあります。","hint":"sがつづりだけで発音しない(アイル)。飛行機のaisle seatや店の棚の間を連想"},{"set":4,"word":"ambitious","pos":"形容詞","meaning":"野心的な","example":"The CEO announced an ambitious plan to open fifty new stores next year.","exampleJa":"CEOは、来年50店舗を新規出店するという野心的な計画を発表した。","hint":"「アンビシャス」はそのまま日本語でも使う音。Boys, be ambitious! の野心的なイメージ"},{"set":4,"word":"apparel","pos":"名詞","meaning":"衣料品","example":"The apparel retailer launched a new line of winter jackets this month.","exampleJa":"そのアパレル小売業者は、今月冬物ジャケットの新シリーズを発売した。","hint":"アパレル業界でおなじみ。日本語の「アパレル」がそのまま英語の衣料品"},{"set":4,"word":"applause","pos":"名詞","meaning":"拍手","example":"The audience gave the keynote speaker a long round of applause.","exampleJa":"聴衆は基調講演者に長い拍手を送った。","hint":"applaud(拍手する)の名詞形。講演後の「a round of applause」を情景で覚える"},{"set":4,"word":"assess","pos":"動詞","meaning":"評価する、査定する","example":"An inspector will assess the damage to the warehouse tomorrow morning.","exampleJa":"検査員が明日の朝、倉庫の被害状況を査定します。","hint":"保険の損害査定員が現場でassessする場面を想像。assessmentは「評価・査定」"},{"set":4,"word":"assure","pos":"動詞","meaning":"保証する、安心させる","example":"I can assure you that your order will arrive by Friday.","exampleJa":"ご注文品は金曜日までに必ず届くことをお約束します。","hint":"sure(確か)が語中にある。「I assure you」で相手に確かだと言い切る。insure(保険)・ensureと区別"},{"set":4,"word":"attire","pos":"名詞","meaning":"服装","example":"Business attire is required for all employees attending the client meeting.","exampleJa":"顧客との会議に出席する全従業員には、ビジネスにふさわしい服装が求められます。","hint":"tire(疲れる)ではなく「服装」。dress codeの案内にある「business attire」を連想"},{"set":4,"word":"attract","pos":"動詞","meaning":"引きつける","example":"The new loyalty program is designed to attract more first-time customers.","exampleJa":"新しいポイント制度は、より多くの初めての顧客を引きつけるよう設計されている。","hint":"磁石が鉄を引き寄せる図。attraction(呼び物・魅力)もセットで覚える"},{"set":4,"word":"auditorium","pos":"名詞","meaning":"講堂、ホール","example":"The annual shareholders' meeting will be held in the main auditorium.","exampleJa":"年次株主総会は、メインの講堂で開催される。","hint":"audio(音)と似た綴りから「話を聞く大きな場所」と連想。入学式や講演会の大ホール"},{"set":4,"word":"authentic","pos":"形容詞","meaning":"本物の","example":"The restaurant is famous for its authentic Mexican dishes made from local ingredients.","exampleJa":"そのレストランは、地元の食材で作る本格的なメキシコ料理で有名だ。","hint":"レストラン広告の「authentic Italian」の定番。fake(偽物)の反対"},{"set":4,"word":"beverage","pos":"名詞","meaning":"飲み物","example":"Complimentary beverages will be served to all guests during the reception.","exampleJa":"レセプションの間、すべてのお客様に無料の飲み物が提供されます。","hint":"メニューや機内サービスで見る「drinkの改まった言い方」。food and beverageで一組"},{"set":4,"word":"bid","pos":"名詞","meaning":"入札、付け値","example":"Our firm submitted a bid for the city's new bridge construction project.","exampleJa":"当社は、市の新しい橋の建設事業に入札した。","hint":"オークションで手を挙げて値を言う場面。win a bid(落札)、submit a bid(入札)"},{"set":4,"word":"boost","pos":"動詞","meaning":"押し上げる、高める","example":"The advertising campaign helped boost online sales by twenty percent.","exampleJa":"その広告キャンペーンは、オンライン売上を20パーセント押し上げるのに役立った。","hint":"ブースター(増強装置)の音から「ぐいっと押し上げる」と連想。boost morale、boost sales"},{"set":4,"word":"cafeteria","pos":"名詞","meaning":"社員食堂","example":"The cafeteria on the second floor closes at three o'clock every afternoon.","exampleJa":"2階の食堂は、毎日午後3時に閉まります。","hint":"カフェ+テリア、と音で区切ると覚えやすい。社内のトレーを持って並ぶ食堂を連想"},{"set":4,"word":"clarify","pos":"動詞","meaning":"明らかにする","example":"Could you clarify the deadline for submitting the project proposal?","exampleJa":"プロジェクト提案書の提出期限をはっきりさせていただけますか。","hint":"clear(明確な)と音が近い。clar-が「明るい・はっきり」の目印。会議で「Could you clarify?」"},{"set":4,"word":"clerk","pos":"名詞","meaning":"店員、事務員","example":"The hotel clerk handed me the room key and a map of the city.","exampleJa":"ホテルの係員は私に部屋の鍵と市内の地図を手渡した。","hint":"イギリス式は「クラーク」でなく「クラーク」に近い音(米は「クラーク」)。ホテルのfront desk clerkを連想"},{"set":4,"word":"coincide","pos":"動詞","meaning":"同時に起こる","example":"The product launch will coincide with the opening of the trade show.","exampleJa":"製品の発売は、見本市の開幕と重なる予定だ。","hint":"co-(共に)+incident(出来事)のような響き、と音で連想。日程がかぶる時に使う(coincide with ~)"},{"set":4,"word":"comparable","pos":"形容詞","meaning":"同等の、匹敵する","example":"We offer a salary comparable to those of other firms in the industry.","exampleJa":"当社は、業界内の他社に匹敵する給与を提示しています。","hint":"compare(比べる)+-able。「比べられる」→「同程度の」。comparable salaryで同等の給与"},{"set":4,"word":"concise","pos":"形容詞","meaning":"簡潔な","example":"Please keep your presentation concise so that everyone has time for questions.","exampleJa":"全員が質問する時間を持てるよう、発表は簡潔にまとめてください。","hint":"scissors(はさみ)と音が似ていると連想し、余分を切り落とした文章をイメージ"},{"set":4,"word":"conduct","pos":"動詞","meaning":"(調査などを)行う","example":"We will conduct a customer satisfaction survey at the end of the month.","exampleJa":"当社は月末に顧客満足度調査を実施します。","hint":"conductor(指揮者・車掌)と同じ仲間。仕事を取り仕切って「行う」。conduct a survey/interview"},{"set":4,"word":"conservation","pos":"名詞","meaning":"保護、保存","example":"The company has invested heavily in water conservation across its facilities.","exampleJa":"その会社は、全施設で水資源の保全に多額の投資をしてきた。","hint":"conserve(守る)の名詞。保存料のpreservativeと混同せず、自然や資源を守る場面で"},{"set":4,"word":"convert","pos":"動詞","meaning":"変える、改装する","example":"The firm decided to convert the old warehouse into modern office space.","exampleJa":"その会社は古い倉庫を最新のオフィススペースに改装することを決めた。","hint":"con+vert。「コンバーチブル(屋根が変形する車)」と連想。形や用途を変える"},{"set":4,"word":"convince","pos":"動詞","meaning":"納得させる","example":"She convinced the board that the new software would save time and money.","exampleJa":"彼女は、新しいソフトウェアが時間と費用の節約になると役員会を納得させた。","hint":"「コンビンス＝納得」と音で。convince 人 of/that ~の形。persuade(説得)との違いは結果の納得に重点"},{"set":4,"word":"cordially","pos":"副詞","meaning":"心から","example":"You are cordially invited to attend our company's twentieth anniversary dinner.","exampleJa":"当社の創立20周年記念ディナーに、謹んでご招待申し上げます。","hint":"招待状の決まり文句「You are cordially invited」。心(cor-)を込めた丁寧さと連想"},{"set":4,"word":"credential","pos":"名詞","meaning":"資格、経歴","example":"All applicants must provide proof of their teaching credentials.","exampleJa":"応募者は全員、教員としての資格の証明を提出しなければならない。","hint":"credit(信用)と綴りが近い。履歴書や免許など「信用を裏づける資格・経歴」。複数形で使うことが多い"},{"set":4,"word":"custodian","pos":"名詞","meaning":"管理人、清掃員","example":"The custodian locks all the doors in the building every night at ten.","exampleJa":"管理人は毎晩10時に建物のすべてのドアに鍵をかける。","hint":"customer ではなく custody(保管・管理)の仲間と連想。学校やビルを守り管理する人"},{"set":4,"word":"decade","pos":"名詞","meaning":"10年間","example":"The firm has doubled its revenue over the past decade.","exampleJa":"その会社は過去10年間で売上を倍増させた。","hint":"デカ=10を連想。デカスロン(十種競技)と同じ「10」の仲間。ニュースの「this past decade」"},{"set":4,"word":"dedication","pos":"名詞","meaning":"献身","example":"The manager praised the team for their dedication during the busy season.","exampleJa":"マネージャーは、繁忙期のチームの献身ぶりをたたえた。","hint":"本の冒頭の「献辞」もdedication。dedicate(捧げる)から、仕事に身を捧げる姿勢をイメージ"},{"set":4,"word":"demonstrate","pos":"動詞","meaning":"実演する、示す","example":"The sales representative will demonstrate how the new copier works.","exampleJa":"営業担当者が、新しいコピー機の使い方を実演します。","hint":"デモ(demo)の元の形。店頭デモや商品説明会で実際にやって見せる場面"},{"set":4,"word":"dependable","pos":"形容詞","meaning":"頼りになる","example":"We are looking for a dependable assistant who can work flexible hours.","exampleJa":"私たちは、柔軟な勤務時間で働ける頼りになるアシスタントを探しています。","hint":"depend on(頼る)+able=頼れる。reliableの言い換えとしてPart 5でも狙われる"},{"set":4,"word":"dimension","pos":"名詞","meaning":"寸法、大きさ","example":"Please check the dimensions of the desk before ordering it for the office.","exampleJa":"オフィス用に注文する前に、その机の寸法を確認してください。","hint":"家具や荷物の購入時に確認する「縦×横×高さ」。複数形のdimensionsで使うのが定番"},{"set":4,"word":"dine","pos":"動詞","meaning":"食事をする","example":"Clients will dine with our executives at a downtown restaurant on Thursday.","exampleJa":"顧客は木曜日に、市内中心部のレストランで当社の役員と食事をします。","hint":"dinner(夕食)と綴りが似ている。dine outは外で食事、dining roomは食堂"},{"set":4,"word":"disclose","pos":"動詞","meaning":"公表する、明かす","example":"The company refused to disclose the details of the merger agreement.","exampleJa":"その会社は、合併契約の詳細を公表することを拒否した。","hint":"dis-(反対)+close(閉じる)。閉じていたものを開けて見せる。情報や財務の開示"},{"set":4,"word":"dispose","pos":"動詞","meaning":"処分する","example":"Employees should dispose of confidential documents using the shredder.","exampleJa":"従業員は機密書類をシュレッダーで処分すること。","hint":"dispose of ~の形で「~を処分する」。ofを忘れず。disposable(使い捨ての)も関連"},{"set":4,"word":"dock","pos":"名詞","meaning":"波止場、荷積み場","example":"The delivery truck is waiting at the loading dock for the shipment.","exampleJa":"配達トラックは、荷物を受け取るため荷積み場で待機している。","hint":"港や倉庫の荷物の積み下ろし場。loading dockが頻出の組み合わせ"},{"set":4,"word":"eager","pos":"形容詞","meaning":"熱心な、しきりに〜したがる","example":"Our new interns are eager to learn about the logistics industry.","exampleJa":"当社の新しいインターンは、物流業界について学ぶことに意欲的だ。","hint":"be eager to ~の形。前のめりで待ちきれない様子。「イーガー」は「イーッ!と待ちきれない」と音で連想"},{"set":4,"word":"economical","pos":"形容詞","meaning":"経済的な、節約になる","example":"Taking the train is more economical than renting a car for the trip.","exampleJa":"その出張には、レンタカーを借りるより電車で行くほうが経済的だ。","hint":"economic(経済の)と区別。「節約になる」はeconomical、「経済の」はeconomic"},{"set":4,"word":"electronically","pos":"副詞","meaning":"電子的に","example":"Invoices can be submitted electronically through the company's online portal.","exampleJa":"請求書は、会社のオンラインポータルから電子的に提出できます。","hint":"電子メールやオンラインフォームでの手続きを連想。submit/send electronicallyの形で出る"},{"set":4,"word":"enhance","pos":"動詞","meaning":"高める、強化する","example":"The new training program should enhance the quality of our customer service.","exampleJa":"新しい研修プログラムは、当社の顧客サービスの質を高めるはずだ。","hint":"en-(〜にする)+高める。品質や評判をさらに一段上げる場面。improveより少し硬い"},{"set":4,"word":"enthusiastic","pos":"形容詞","meaning":"熱心な","example":"Customers gave an enthusiastic response to the redesigned mobile app.","exampleJa":"顧客は、刷新されたモバイルアプリに熱烈な反応を示した。","hint":"enthusiasm(熱意)の形容詞。ファンの熱烈な歓声のような反応を連想"},{"set":4,"word":"envelope","pos":"名詞","meaning":"封筒","example":"Please place the signed contract in the envelope and mail it today.","exampleJa":"署名済みの契約書を封筒に入れ、本日中に郵送してください。","hint":"アンベロープに近い発音もある。手紙を包む。develop(発展させる)とは別語、と区別"},{"set":4,"word":"estimated","pos":"形容詞","meaning":"推定の、見積もりの","example":"The estimated cost of the renovation is around fifty thousand dollars.","exampleJa":"改装の見積費用は約5万ドルです。","hint":"estimateの過去分詞形で「見積もられた」。estimated arrival time(到着予定時刻)の形で覚える"},{"set":4,"word":"exceptional","pos":"形容詞","meaning":"並外れた","example":"She received an award for her exceptional performance in customer relations.","exampleJa":"彼女は顧客対応における並外れた働きぶりで表彰された。","hint":"exception(例外)の形容詞。例外的に飛び抜けて良い、と連想。exceptional serviceは称賛の定番"},{"set":4,"word":"exhausted","pos":"形容詞","meaning":"疲れ切った、使い果たした","example":"Our supply of printer paper was exhausted by the end of the week.","exampleJa":"プリンター用紙の在庫は、週末までに底をついた。","hint":"疲れ切った人だけでなく、在庫・資金が尽きる意味もある。徹夜明けの人と空っぽの倉庫を両方想像"},{"set":4,"word":"expedite","pos":"動詞","meaning":"早める、促進する","example":"We can expedite your order for an additional shipping fee.","exampleJa":"追加の送料をいただければ、ご注文品の発送を早めることができます。","hint":"急ぎの荷物の「速達」のイメージ。手続きや発送を前に進めて早める。expediteの名詞形はexpedition(遠征)"},{"set":4,"word":"expertise","pos":"名詞","meaning":"専門知識","example":"We hired a consultant with extensive expertise in financial planning.","exampleJa":"当社は、財務計画に関する豊富な専門知識を持つコンサルタントを雇った。","hint":"expert(専門家)に-iseがついた形で、専門家が持つ知識。発音はエクスパティーズ"},{"set":4,"word":"fabric","pos":"名詞","meaning":"布地","example":"The designer chose a lightweight fabric for the summer collection.","exampleJa":"デザイナーは夏物コレクションに軽い生地を選んだ。","hint":"ファブリック素材のカーテンやソファでおなじみ。日本語でも「布地」の意味で使う"},{"set":4,"word":"faculty","pos":"名詞","meaning":"教職員、能力","example":"The university faculty voted to adopt a new schedule for the next semester.","exampleJa":"大学の教員たちは、次の学期の新しい日程を採用することに投票した。","hint":"大学の「学部」を表すfaculty(日本の学部の名前にも出てくる)から、そこに属する教員全体を指す"},{"set":4,"word":"finalize","pos":"動詞","meaning":"最終決定する","example":"We hope to finalize the contract with the supplier by next Friday.","exampleJa":"来週の金曜日までに、仕入先との契約をまとめたいと考えています。","hint":"final+-ize(〜にする)。契約・計画の最終版を決める。完了直前の「詰めの作業」を連想"},{"set":4,"word":"fixture","pos":"名詞","meaning":"備え付け品","example":"The landlord will replace the old light fixtures in the lobby next week.","exampleJa":"家主は来週、ロビーの古い照明器具を交換する予定だ。","hint":"fix(固定する)から。天井の照明やトイレなど、取り外さない備え付けの設備"},{"set":4,"word":"fleet","pos":"名詞","meaning":"(車・船の)一団","example":"The courier service recently added electric vans to its delivery fleet.","exampleJa":"その宅配会社は最近、配送用の車両群に電気自動車を加えた。","hint":"海軍の艦隊が元の意味で、配送会社の車両全体にも使う。a fleet of ~の形"},{"set":4,"word":"garment","pos":"名詞","meaning":"衣服","example":"Each garment is inspected carefully before it leaves the factory.","exampleJa":"各衣類は、工場を出る前に念入りに検査される。","hint":"服の「1着1着」を指す硬めの語で、工場や商品説明で使う。garment industryは衣料産業"},{"set":4,"word":"gratitude","pos":"名詞","meaning":"感謝","example":"We would like to express our gratitude to everyone who attended the event.","exampleJa":"イベントにご参加くださったすべての皆様に、感謝申し上げます。","hint":"grateful(感謝している)と同じgrat-が目印。「感謝」の気持ちを表す名詞。express gratitudeの形で"},{"set":4,"word":"gross","pos":"形容詞","meaning":"総計の","example":"The company reported a gross profit of two million dollars last quarter.","exampleJa":"その会社は、前四半期に総利益200万ドルを計上したと報告した。","hint":"「グロい」ではなく総額。給料の「額面」で、手取りのnetと対にして覚える"},{"set":4,"word":"hands-on","pos":"形容詞","meaning":"実地の、実践的な","example":"The workshop offers hands-on experience with the latest design software.","exampleJa":"そのワークショップでは、最新のデザインソフトを実際に使う体験ができます。","hint":"手(hands)をその上に置く、つまり実際に触れて体験する研修を思い浮かべよう"},{"set":4,"word":"hospitality","pos":"名詞","meaning":"もてなし、接客業","example":"She has worked in the hospitality industry for more than ten years.","exampleJa":"彼女は10年以上、接客業界で働いている。","hint":"hotel、hospitalと同じく「客を迎える」系の語感。ホテル・飲食業界を表すhospitality industry"},{"set":4,"word":"household","pos":"名詞","meaning":"世帯","example":"The survey asked about monthly spending in each household.","exampleJa":"その調査は、各世帯の毎月の支出について尋ねたものだ。","hint":"house(家)+hold(保つ)。家族で暮らす単位。household appliancesは家電"},{"set":4,"word":"incur","pos":"動詞","meaning":"(費用・損失を)負う","example":"Customers who cancel late will incur a fee of fifty dollars.","exampleJa":"直前にキャンセルした顧客には、50ドルの手数料が発生します。","hint":"費用・損失・罰金などマイナスのものが「降りかかる」時に使う。incur costs/debts/lossesの形"},{"set":4,"word":"insight","pos":"名詞","meaning":"洞察","example":"The report provides valuable insight into changing consumer preferences.","exampleJa":"その報告書は、変化する消費者の好みについて貴重な洞察を提供している。","hint":"in+sight。目に見えない内側まで見抜く力のイメージ。市場分析で「貴重な洞察」"},{"set":4,"word":"inspire","pos":"動詞","meaning":"鼓舞する、着想を与える","example":"The founder's speech inspired employees to pursue even higher goals.","exampleJa":"創業者のスピーチは、従業員がさらに高い目標を追求するよう鼓舞した。","hint":"インスピレーション(ひらめき)の動詞形。人にやる気や発想を与える場面で"},{"set":4,"word":"instruct","pos":"動詞","meaning":"指示する","example":"The manager instructed the staff to update the inventory list by noon.","exampleJa":"マネージャーはスタッフに、正午までに在庫リストを更新するよう指示した。","hint":"instruction(指示・説明書)の動詞形。instruct 人 to ~の形で、上司が部下に指示する場面"},{"set":4,"word":"integrate","pos":"動詞","meaning":"統合する","example":"We plan to integrate the new software with our existing accounting system.","exampleJa":"私たちは、新しいソフトウェアを既存の会計システムに統合する予定です。","hint":"integration(統合)の動詞形。別々のシステムやチームを一つにつなぐ場面で"},{"set":4,"word":"interactive","pos":"形容詞","meaning":"双方向の","example":"The training session was interactive, with plenty of time for group discussion.","exampleJa":"その研修は双方向型で、グループ討論の時間が十分にあった。","hint":"inter-(相互の)+active。セミナーやウェブ教材で、参加者とやり取りできる様子"},{"set":4,"word":"interval","pos":"名詞","meaning":"間隔","example":"Inspections are carried out at regular intervals throughout the year.","exampleJa":"点検は、年間を通じて一定の間隔で実施される。","hint":"コンサートの「休憩(interval)」でも使う。時間や距離の間隔。at regular intervals"},{"set":4,"word":"janitor","pos":"名詞","meaning":"用務員、清掃員","example":"Please inform the janitor if the restroom needs to be cleaned.","exampleJa":"トイレの清掃が必要な場合は、用務員にお知らせください。","hint":"ビルのjanitorは、鍵を持って掃除・管理する人。ビル内の問い合わせ先として出る"},{"set":4,"word":"lobby","pos":"名詞","meaning":"ロビー","example":"Visitors must check in at the front desk in the main lobby.","exampleJa":"来訪者は、メインロビーの受付で手続きをしなければならない。","hint":"ホテルや会社の入り口すぐの広間。待ち合わせ場所として会話に出やすい"},{"set":4,"word":"loyalty","pos":"名詞","meaning":"忠誠、愛顧","example":"The airline rewards customer loyalty with free upgrades and bonus miles.","exampleJa":"その航空会社は、顧客の愛顧に対し、無料アップグレードやボーナスマイルで報いている。","hint":"loyal(忠実な)の名詞。ポイントカードのloyalty programで、常連客を大切にするイメージ"},{"set":4,"word":"mentor","pos":"名詞","meaning":"指導者","example":"Each new employee is paired with a mentor during the first six months.","exampleJa":"新入社員はそれぞれ、最初の6か月間は指導役の先輩と組まされる。","hint":"新人の相談に乗る先輩のイメージ。mentor program(メンター制度)は社内研修で頻出"},{"set":4,"word":"municipal","pos":"形容詞","meaning":"市の、市営の","example":"The municipal government approved funding for a new public park.","exampleJa":"市当局は、新しい公園のための資金提供を承認した。","hint":"市役所や市立の施設で使う。municipal library、municipal governmentのように「市の」と覚える"},{"set":4,"word":"needy","pos":"形容詞","meaning":"困窮した","example":"The charity provides free meals to needy families in the community.","exampleJa":"その慈善団体は、地域の困窮した家庭に無料の食事を提供している。","hint":"need(必要)+-y。生活に必要なものが足りない人々。the needyで「困窮者」"},{"set":4,"word":"obligation","pos":"名詞","meaning":"義務","example":"The free trial comes with no obligation to purchase the product afterward.","exampleJa":"無料体験には、その後商品を購入する義務は一切ありません。","hint":"契約書の「義務」。no obligation to buyで「購入義務なし」。広告でもよく出る"},{"set":4,"word":"obsolete","pos":"形容詞","meaning":"時代遅れの","example":"Much of the factory's equipment is obsolete and needs to be replaced.","exampleJa":"工場の設備の多くは時代遅れで、交換が必要だ。","hint":"古い機械やソフトが廃れて使えなくなった様子。outdatedより強く「もう使われない」"},{"set":4,"word":"on-site","pos":"形容詞","meaning":"現場の、敷地内の","example":"The hotel offers free on-site parking for all registered guests.","exampleJa":"そのホテルは、宿泊客全員に敷地内の無料駐車場を提供している。","hint":"site(現場・敷地)の上で、と直訳。on-site parking、on-site trainingなど「その場所で」"},{"set":4,"word":"opponent","pos":"名詞","meaning":"相手、反対者","example":"Our main opponent in the bidding process has a lower price.","exampleJa":"入札における私たちの主な競争相手は、より低い価格を提示している。","hint":"反対側に立つ人を連想。試合・選挙・議論の相手。コロケーションはa strong opponent"},{"set":4,"word":"ownership","pos":"名詞","meaning":"所有(権)","example":"The restaurant is now under new ownership and has a fresh menu.","exampleJa":"そのレストランは現在、新しいオーナーのもとで、一新されたメニューを出している。","hint":"owner(所有者)+-ship(状態)。店の看板の「Under new ownership」は経営者交代の合図"},{"set":4,"word":"pamphlet","pos":"名詞","meaning":"パンフレット","example":"Visitors can pick up a free pamphlet at the information desk.","exampleJa":"来場者は、案内所で無料のパンフレットを受け取れる。","hint":"展示会や観光案内所で受け取る薄い小冊子。brochureより素朴な手作り感のある冊子と連想"},{"set":4,"word":"paperwork","pos":"名詞","meaning":"書類事務","example":"Please complete all the paperwork before your first day of work.","exampleJa":"初出勤日の前に、すべての書類手続きを済ませてください。","hint":"paper+work。契約や申請などの書類手続きのこと。数えられない名詞で、a paperworkとは言わない"},{"set":4,"word":"patent","pos":"名詞","meaning":"特許","example":"The inventor filed a patent for the new water-saving device.","exampleJa":"発明者は、新しい節水装置の特許を出願した。","hint":"発明を守る特許。「パテント」はそのまま日本語でも使う。apply for/hold a patentの形"},{"set":4,"word":"pedestrian","pos":"名詞","meaning":"歩行者","example":"The city built a new bridge exclusively for pedestrian traffic.","exampleJa":"市は、歩行者専用の新しい橋を建設した。","hint":"ペダル(pedal)と同じped-は「足」の仲間と連想。歩く人をイメージ。pedestrian crossingは横断歩道"},{"set":4,"word":"perishable","pos":"形容詞","meaning":"腐りやすい","example":"Perishable items must be stored in the refrigerator immediately upon arrival.","exampleJa":"傷みやすい品物は、到着後ただちに冷蔵庫に保管しなければならない。","hint":"perish(滅びる)+able。生鮮食品の配送で、「腐りやすいので早く届ける」場面を連想"},{"set":4,"word":"plumber","pos":"名詞","meaning":"配管工","example":"We called a plumber to repair the leaking pipe in the kitchen.","exampleJa":"私たちは、キッチンの水漏れしている配管を直してもらうため、配管工を呼んだ。","hint":"bは発音しない(プラマー)。水漏れや排水の修理に呼ぶ人を連想"},{"set":4,"word":"prestigious","pos":"形容詞","meaning":"名声のある","example":"The architect won a prestigious award for her design of the museum.","exampleJa":"その建築家は、美術館の設計で権威ある賞を受賞した。","hint":"prestige(名声)の形容詞。名門大学や権威ある賞を連想。ブランドの格を表す"},{"set":4,"word":"profitable","pos":"形容詞","meaning":"利益になる","example":"The new product line became profitable within its first six months.","exampleJa":"新しい製品ラインは、最初の6か月以内に利益を生むようになった。","hint":"profit(利益)+able。「儲かる」。会社の決算や事業の話で頻出"},{"set":4,"word":"prolonged","pos":"形容詞","meaning":"長引いた","example":"A prolonged power outage forced the factory to halt production.","exampleJa":"長引く停電のため、工場は生産を停止せざるを得なかった。","hint":"long(長い)が語中にあるprolong(延ばす)の過去分詞。長引いた雨・遅れ・議論を連想"},{"set":4,"word":"prototype","pos":"名詞","meaning":"試作品","example":"The engineers presented a working prototype of the electric scooter.","exampleJa":"技術者たちは、電動スクーターの実際に動く試作品を披露した。","hint":"proto(最初の)+type(型)。製品が量産される前に作られる第1号の試作品"},{"set":4,"word":"quota","pos":"名詞","meaning":"割り当て、ノルマ","example":"Every sales representative must meet a monthly quota to earn the bonus.","exampleJa":"営業担当者は全員、ボーナスを得るために毎月のノルマを達成しなければならない。","hint":"営業のノルマや輸入の割当枠。「クォータ」の音で、一定数の枠を割り当てられるイメージ"},{"set":4,"word":"ratio","pos":"名詞","meaning":"比率","example":"The ratio of male to female employees in the department is almost equal.","exampleJa":"その部署の男女の従業員の比率はほぼ同じだ。","hint":"「レシオ」の音でそのまま日本語にもある。割合を2つの数の比で表す。student-teacher ratioなど"},{"set":4,"word":"redeem","pos":"動詞","meaning":"(券を)引き換える","example":"You can redeem your points for gift cards at any of our stores.","exampleJa":"貯まったポイントは、当社のどの店舗でもギフトカードと引き換えられます。","hint":"クーポンやポイントを商品と引き換える場面。redeem a coupon/voucher/pointsの形で"},{"set":4,"word":"refurbish","pos":"動詞","meaning":"改装する、一新する","example":"The hotel was closed for two months to refurbish its guest rooms.","exampleJa":"そのホテルは客室を改装するため、2か月間休業した。","hint":"re-(再び)がつく。古い建物や機器をきれいに整えて新品同様にするイメージ。refurbished laptopは整備済み品"},{"set":4,"word":"solicit","pos":"動詞","meaning":"求める、募る","example":"The marketing team plans to solicit feedback from customers after the launch.","exampleJa":"マーケティングチームは、発売後に顧客から意見を募る予定だ。","hint":"相手に意見や寄付をお願いして集める場面。solicit feedback/donations/bidsの形で"},{"set":4,"word":"streamline","pos":"動詞","meaning":"合理化する","example":"We hired a consultant to help streamline our hiring process.","exampleJa":"私たちは、採用プロセスを合理化するためにコンサルタントを雇った。","hint":"stream(流れ)+line(線)。流れるような流線形から、無駄のない形にするイメージ"},{"set":4,"word":"tailor","pos":"動詞","meaning":"合わせて作る","example":"Our consultants tailor each training program to the needs of the client.","exampleJa":"当社のコンサルタントは、顧客のニーズに合わせて各研修プログラムを調整します。","hint":"仕立て屋(テーラー)がスーツを体に合わせて作る図。tailor A to B(AをBに合わせる)"},{"set":4,"word":"tribute","pos":"名詞","meaning":"賛辞、記念","example":"The employees paid tribute to the retiring director at the ceremony.","exampleJa":"従業員たちは式典で、退任する取締役に敬意を表した。","hint":"尊敬や感謝を形にして示すこと。pay tribute to ~で「~に敬意を表す」。送別会や追悼の場で"},{"set":4,"word":"vacate","pos":"動詞","meaning":"(部屋・場所を)空ける、明け渡す","example":"Guests are asked to vacate their rooms by eleven o'clock on the day of departure.","exampleJa":"宿泊客は、出発日の11時までに部屋を空けていただくようお願いします。","hint":"vacant(空いている)の動詞形。ホテルのチェックアウトや退去期限で使う。vacation(休暇)も「空ける」から連想"},{"set":5,"word":"absence","pos":"名詞","meaning":"不在、欠席","example":"Her absence from the meeting meant the decision had to be postponed.","exampleJa":"彼女が会議を欠席したため、決定は延期せざるを得なかった。","hint":"ab-(離れて)+sence(いる)。absent の名詞。leave of absence(休職)の形で頻出"},{"set":5,"word":"absolutely","pos":"副詞","meaning":"まったく、絶対に","example":"We are absolutely committed to delivering the order on time.","exampleJa":"当社は注文品を期限どおりに届けることを絶対にお約束します。","hint":"上司の提案に「Absolutely!」と即答する場面。強い同意・強調の定番"},{"set":5,"word":"accept","pos":"動詞","meaning":"受け入れる、受け取る","example":"The restaurant only accepts cash, so please bring enough money.","exampleJa":"そのレストランは現金のみ受け付けているので、十分なお金をお持ちください。","hint":"ac-(〜へ)+cept(取る)。手を伸ばして受け取る。accept credit cards の形で覚える"},{"set":5,"word":"access","pos":"名詞","meaning":"利用(する権利)、接近","example":"All employees have access to the shared database from their desks.","exampleJa":"全従業員が自分の机から共有データベースを利用できる。","hint":"ac-(〜へ)+cess(行く)。access to ～ で「〜を利用する権利」。ログイン場面を連想"},{"set":5,"word":"accident","pos":"名詞","meaning":"事故","example":"The factory manager reported that no one was hurt in the accident.","exampleJa":"工場長は、その事故で負傷者は出なかったと報告した。","hint":"階段で転ぶ、車がぶつかる、そんな「思いがけない出来事」。by accident は「偶然」"},{"set":5,"word":"account","pos":"名詞","meaning":"口座、取引先","example":"Our sales team manages several key accounts in the Asian market.","exampleJa":"当社の営業チームはアジア市場で複数の重要な取引先を担当している。","hint":"銀行の口座開設の場面。「口座」と「大口取引先」の2義を押さえる"},{"set":5,"word":"accounting","pos":"名詞","meaning":"経理、会計","example":"Please send all receipts to the accounting department by Friday.","exampleJa":"領収書はすべて金曜日までに経理部へ送ってください。","hint":"月末に帳簿を締める経理部の風景。accounting department/firm の形で頻出"},{"set":5,"word":"achieve","pos":"動詞","meaning":"達成する","example":"The team worked overtime to achieve its quarterly sales target.","exampleJa":"チームは四半期の売上目標を達成するために残業した。","hint":"目標達成の場面で使う。achieve a goal/target と目的語がセット"},{"set":5,"word":"activate","pos":"動詞","meaning":"有効にする、起動する","example":"You must activate your new credit card before making any purchases.","exampleJa":"購入する前に、新しいクレジットカードを有効にする必要があります。","hint":"active(活動中)から。新しいカードやアカウントのスイッチをオンにするイメージ"},{"set":5,"word":"actual","pos":"形容詞","meaning":"実際の","example":"The actual cost of the project was higher than we estimated.","exampleJa":"プロジェクトの実際の費用は私たちの見積もりより高かった。","hint":"見積もりと「実際」の差を言う場面。the actual cost と estimated の対比で覚える"},{"set":5,"word":"addition","pos":"名詞","meaning":"追加、加わった人","example":"In addition to her regular duties, she trains new employees.","exampleJa":"通常業務に加えて、彼女は新入社員の研修も行っている。","hint":"足し算の add の名詞。in addition to ～(〜に加えて)が最頻出の形"},{"set":5,"word":"additional","pos":"形容詞","meaning":"追加の","example":"Additional fees may apply for deliveries outside the metropolitan area.","exampleJa":"都市圏外への配送には追加料金がかかる場合があります。","hint":"追加料金や追加資料など「プラスα」を示す語。additional charge の形で定着させる"},{"set":5,"word":"address","pos":"動詞","meaning":"(問題に)取り組む、演説する","example":"The CEO will address the concerns of shareholders at tomorrow's meeting.","exampleJa":"CEOは明日の会議で株主の懸念に対応する予定だ。","hint":"「住所」の語を動詞で使うと、問題に言葉を向けて「取り組む」。address the issue が定番"},{"set":5,"word":"admission","pos":"名詞","meaning":"入場(料)、入学","example":"Admission to the museum is free for children under twelve.","exampleJa":"12歳未満の子どもは美術館への入場が無料です。","hint":"美術館の入口で払う「入場料」。admit(入れる)の名詞。admission fee で覚える"},{"set":5,"word":"admit","pos":"動詞","meaning":"入場を認める、認める","example":"The patient was admitted to the hospital late last night.","exampleJa":"その患者は昨夜遅くに入院した。","hint":"病院に入院させる「入れる」と、過ちを「認める」の2義。be admitted to ～ の受け身が頻出"},{"set":5,"word":"adopt","pos":"動詞","meaning":"採用する","example":"The company decided to adopt a more flexible working policy.","exampleJa":"会社はより柔軟な勤務方針を採用することを決めた。","hint":"養子を迎えるように、新しい方法を自社に迎え入れる。adopt a policy/strategy"},{"set":5,"word":"advantage","pos":"名詞","meaning":"利点、有利","example":"Customers can take advantage of the discount until the end of May.","exampleJa":"お客様は5月末まで割引をご利用いただけます。","hint":"take advantage of ～(〜を活用する)の形で頻出。セール告知の定番表現"},{"set":5,"word":"affect","pos":"動詞","meaning":"影響する","example":"The sudden rise in fuel prices will affect our shipping costs.","exampleJa":"燃料価格の急な上昇は当社の輸送費に影響するだろう。","hint":"天候や遅延が業務に「作用する」。effect(名詞)と混同注意、affect は動詞"},{"set":5,"word":"afford","pos":"動詞","meaning":"(費用・時間の)余裕がある","example":"Our small company cannot afford to hire any more staff this year.","exampleJa":"当社のような小さな会社は、今年はこれ以上人を雇う余裕がない。","hint":"can afford ～ の形が基本。予算が厳しいときの「余裕がない」といった否定形でよく登場"},{"set":5,"word":"agency","pos":"名詞","meaning":"代理店、機関","example":"The travel agency booked all our flights and hotel rooms.","exampleJa":"その旅行代理店が私たちの航空券とホテルをすべて予約してくれた。","hint":"旅行会社や人材派遣会社など「代理で動く会社」。travel agency が最頻出"},{"set":5,"word":"aim","pos":"動詞","meaning":"目指す、狙う","example":"We aim to reduce our energy consumption by twenty percent this year.","exampleJa":"私たちは今年、エネルギー消費を20パーセント削減することを目指している。","hint":"矢を的に向けるように目標へ狙いを定める。aim to do / aim at ～ の2形"},{"set":5,"word":"alert","pos":"動詞","meaning":"警告する、知らせる","example":"The system will alert users to any unusual activity on their accounts.","exampleJa":"そのシステムは、アカウントの不審な動きがあればユーザーに警告する。","hint":"警報(alert)を鳴らして知らせる動作。alert A to B の形で使う"},{"set":5,"word":"allow","pos":"動詞","meaning":"許す、可能にする","example":"Please allow five business days for your refund to be processed.","exampleJa":"返金の処理には5営業日ほどお見込みください。","hint":"許可の場面で使う。allow A to do の形と、Allow 3 days for ～ の用法に注意"},{"set":5,"word":"alter","pos":"動詞","meaning":"変更する、(服を)直す","example":"We had to alter the schedule because the speaker arrived late.","exampleJa":"講演者の到着が遅れたため、予定を変更しなければならなかった。","hint":"スーツの丈を直す仕立て屋を連想。計画や予定を「部分的に変える」ときも使う"},{"set":5,"word":"amount","pos":"名詞","meaning":"量、金額","example":"A large amount of data was lost during the server failure.","exampleJa":"サーバー障害の際に、大量のデータが失われた。","hint":"数えられない量や金額に使う。a large amount of ～ の形で覚える(many ではなく much 系)"},{"set":5,"word":"announce","pos":"動詞","meaning":"発表する","example":"The company will announce its new product line next Tuesday.","exampleJa":"同社は来週の火曜日に新しい製品ラインを発表する予定だ。","hint":"記者会見で新製品を「発表する」場面を連想。be pleased to announce が定番"},{"set":5,"word":"announcement","pos":"名詞","meaning":"発表、お知らせ","example":"The manager made an announcement about the upcoming office renovation.","exampleJa":"部長は近く行われるオフィス改装について発表を行った。","hint":"空港や駅の構内放送のように、Part 4 でよく流れる「お知らせ」。make an announcement で覚える"},{"set":5,"word":"apologize","pos":"動詞","meaning":"謝る","example":"We apologize for the delay and thank you for your patience.","exampleJa":"遅れましたことをお詫び申し上げるとともに、ご辛抱いただき感謝いたします。","hint":"apology(謝罪)の動詞。apologize for ～ の形で、お詫びメールの定番"},{"set":5,"word":"apparently","pos":"副詞","meaning":"どうやら〜らしい","example":"Apparently, the shipment was delayed because of bad weather.","exampleJa":"どうやら、悪天候のせいで荷物の到着が遅れたようだ。","hint":"「見たところ〜らしい」と伝聞や推測を述べる副詞。文頭で使うことが多い"},{"set":5,"word":"appeal","pos":"動詞","meaning":"訴える、心を引く","example":"The new advertising campaign is designed to appeal to young consumers.","exampleJa":"新しい広告キャンペーンは、若い消費者の心に訴えるよう作られている。","hint":"広告が若者の心に「訴えかける」。appeal to ～ の形で、広告・販促の文脈"},{"set":5,"word":"appear","pos":"動詞","meaning":"現れる、〜のようだ","example":"The printer appears to be broken, so please call the technician.","exampleJa":"プリンターは故障しているようなので、技術者に連絡してください。","hint":"舞台に姿を現す意味と、to不定詞を伴う「〜のようだ」の2用法を区別する"},{"set":5,"word":"application","pos":"名詞","meaning":"申し込み(書)、アプリ","example":"Please submit your application along with a copy of your résumé.","exampleJa":"履歴書の写しを添えて、申込書をご提出ください。","hint":"apply の名詞。求人への「応募書類」とスマホの「アプリ」、2つの意味を押さえる"},{"set":5,"word":"apply","pos":"動詞","meaning":"申し込む、適用する","example":"Interested candidates should apply for the position before the end of June.","exampleJa":"関心のある候補者は、6月末までにその職に応募してください。","hint":"apply for(応募する)と apply to(適用される)で前置詞が意味を決める"},{"set":5,"word":"appoint","pos":"動詞","meaning":"任命する","example":"Ms. Tanaka was appointed as the new head of the marketing division.","exampleJa":"田中さんはマーケティング部門の新しい責任者に任命された。","hint":"人事発表で「〜に任命された」と受け身で出る。be appointed (as) ～ の形"},{"set":5,"word":"approach","pos":"名詞","meaning":"取り組み方、接近","example":"The consultant suggested a new approach to managing customer complaints.","exampleJa":"コンサルタントは、顧客の苦情に対処する新しい手法を提案した。","hint":"近づく意味から、問題への「接近の仕方」＝取り組み方に。a new approach to ～ で覚える"},{"set":5,"word":"approval","pos":"名詞","meaning":"承認","example":"The budget requires approval from the finance director before we proceed.","exampleJa":"予算は、進める前に財務部長の承認が必要だ。","hint":"上司の承認印をもらう場面を連想。approve の名詞。get/receive approval"},{"set":5,"word":"arrange","pos":"動詞","meaning":"手配する、並べる","example":"My assistant will arrange a meeting with the client next week.","exampleJa":"私のアシスタントが来週、顧客との打ち合わせを手配します。","hint":"会議や出張の段取りを整える動作。arrange for ～ / arrange to do の形も押さえる"},{"set":5,"word":"arrangement","pos":"名詞","meaning":"手配、準備","example":"We have made arrangements for a shuttle bus to the conference venue.","exampleJa":"会議会場までのシャトルバスを手配しました。","hint":"arrange の名詞。出張などの「手配」は複数形 arrangements で使うことが多い"},{"set":5,"word":"arrival","pos":"名詞","meaning":"到着","example":"Please show your passport to the staff upon arrival at the hotel.","exampleJa":"ホテルに到着したら、スタッフにパスポートをご提示ください。","hint":"空港の「到着ロビー」を連想。arrive の名詞で、upon arrival(到着時に)が頻出"},{"set":5,"word":"aspect","pos":"名詞","meaning":"側面、観点","example":"The manager reviewed every aspect of the project before approving it.","exampleJa":"部長は承認する前に、プロジェクトのあらゆる面を検討した。","hint":"物事をある角度から見た「一面」。every aspect of ～(〜のあらゆる面)の形が便利"},{"set":5,"word":"assistance","pos":"名詞","meaning":"援助、手助け","example":"Please contact the front desk if you need any assistance.","exampleJa":"お手伝いが必要でしたら、フロントまでご連絡ください。","hint":"assist の名詞。案内係の「お手伝いしましょうか」を連想。need assistance の形"},{"set":5,"word":"associate","pos":"名詞","meaning":"仲間、同僚、準〜","example":"A sales associate will help you find the right size.","exampleJa":"販売スタッフが、ぴったりのサイズ探しをお手伝いします。","hint":"仕事上の「仲間」。名詞では sales associate(販売員)や business associate が頻出"},{"set":5,"word":"association","pos":"名詞","meaning":"協会、団体","example":"She is an active member of the local business association.","exampleJa":"彼女は地元の商業協会の活発な会員だ。","hint":"同業者が集まる「協会」。the Medical Association のように固有名にもよく入る"},{"set":5,"word":"assume","pos":"動詞","meaning":"引き受ける、思い込む","example":"He will assume the role of project manager next month.","exampleJa":"彼は来月、プロジェクトマネージャーの役割を引き受ける。","hint":"「責任を引き受ける」と「〜だと思い込む」の2義。assume responsibility は定番"},{"set":5,"word":"attempt","pos":"名詞","meaning":"試み","example":"The firm lowered its prices in an attempt to attract more customers.","exampleJa":"その会社は、より多くの顧客を引きつけようとして価格を下げた。","hint":"成否は別として「やってみること」。in an attempt to do(〜しようとして)の形"},{"set":5,"word":"attend","pos":"動詞","meaning":"出席する","example":"All department heads are required to attend the quarterly meeting.","exampleJa":"全部門の責任者は四半期会議に出席しなければならない。","hint":"attend は他動詞で、attend a meeting と前置詞を入れない。on を付けたくなる誤りに注意"},{"set":5,"word":"attendance","pos":"名詞","meaning":"出席(者数)","example":"Attendance at the training session is mandatory for all new staff.","exampleJa":"研修への出席は、すべての新入社員に義務づけられている。","hint":"イベントの出席者数や出勤状況。attend の名詞で、record attendance(過去最高の参加者数)も覚える"},{"set":5,"word":"attention","pos":"名詞","meaning":"注意、注目","example":"May I have your attention, please? The presentation will start shortly.","exampleJa":"皆様にお知らせします。まもなくプレゼンテーションが始まります。","hint":"場内放送の「May I have your attention, please?」を連想。手紙の宛名の Attention も同語"},{"set":5,"word":"attractive","pos":"形容詞","meaning":"魅力的な","example":"The bank is offering an attractive interest rate for new customers.","exampleJa":"その銀行は新規顧客向けに魅力的な金利を提示している。","hint":"人を引きつける力がある。attractive offer/price など「お得で魅力的」な場面で使う"},{"set":5,"word":"audience","pos":"名詞","meaning":"聴衆、観客","example":"The speaker kept the audience interested with several practical examples.","exampleJa":"講演者はいくつもの実用的な例で聴衆の関心を引きつけ続けた。","hint":"講演会場の客席を連想。人の集まりなので target audience(対象層)のようにも使う"},{"set":5,"word":"author","pos":"名詞","meaning":"著者","example":"The author will sign copies of her new book at the store.","exampleJa":"著者は店で新刊にサインを行う予定だ。","hint":"本を書いた人。the author of ～ の形で出る。-or で終わる人を表す名詞"},{"set":5,"word":"automatic","pos":"形容詞","meaning":"自動の","example":"Your subscription will be renewed through automatic payment each month.","exampleJa":"ご契約は毎月、自動引き落としで更新されます。","hint":"自動引き落としや自動ドアなど「勝手に動く」仕組み。automatic payment/renewal"},{"set":5,"word":"availability","pos":"名詞","meaning":"空き状況、入手可能性","example":"Please check the availability of rooms before booking your trip.","exampleJa":"ご旅行を予約する前に、客室の空き状況をご確認ください。","hint":"available の名詞。ホテル予約で「空室はありますか」と尋ねる場面。subject to availability も頻出"},{"set":5,"word":"avoid","pos":"動詞","meaning":"避ける","example":"To avoid confusion, please label every box clearly before shipping.","exampleJa":"混乱を避けるため、発送前にすべての箱にはっきりとラベルを貼ってください。","hint":"後ろは動名詞(avoid -ing)。不定詞は続けない、という文法の定番"},{"set":5,"word":"aware","pos":"形容詞","meaning":"気づいて、知って","example":"Please be aware that the office will be closed on Monday.","exampleJa":"月曜日は事務所が休みとなりますのでご承知おきください。","hint":"be aware of ～ / be aware that ～ の形。「ご承知おきください」の注意書きで使う"},{"set":5,"word":"baggage","pos":"名詞","meaning":"手荷物","example":"Passengers must collect their baggage at the carousel after landing.","exampleJa":"乗客は着陸後、ターンテーブルで手荷物を受け取らなければならない。","hint":"空港の手荷物受取所を連想。bag の仲間だが不可算名詞で、a baggage とは言わない"},{"set":5,"word":"balance","pos":"名詞","meaning":"残高、釣り合い","example":"You can check your account balance through the mobile banking app.","exampleJa":"口座残高はモバイルバンキングのアプリで確認できます。","hint":"天秤の釣り合いから、収支の釣り合い＝「残高」に。口座の balance と work-life balance の2場面"},{"set":5,"word":"banquet","pos":"名詞","meaning":"宴会、祝宴","example":"The annual awards banquet will be held at the downtown hotel.","exampleJa":"毎年恒例の表彰晩餐会は、市内中心部のホテルで開催される。","hint":"ホテルの宴会場で行う正式な夕食会。表彰式や歓迎会の場面で出る"},{"set":5,"word":"bargain","pos":"名詞","meaning":"お買い得品","example":"At that price, the laptop is a real bargain for small businesses.","exampleJa":"その価格なら、そのノートパソコンは中小企業にとって本当にお買い得だ。","hint":"定価より安く買えた「掘り出し物」。a real bargain の形で覚える"},{"set":5,"word":"basis","pos":"名詞","meaning":"基準、根拠","example":"The team meets on a weekly basis to review its progress.","exampleJa":"チームは進捗を確認するため、毎週会合を開いている。","hint":"on a ～ basis の形で「〜ごとに・〜の方式で」。daily/weekly/regular basis で頻出"},{"set":5,"word":"benefit","pos":"名詞","meaning":"利益、福利厚生","example":"Full-time employees receive health insurance and other generous benefits.","exampleJa":"正社員は健康保険やその他の手厚い福利厚生を受けられる。","hint":"給与とは別の「福利厚生」。employee benefits の複数形が求人広告の定番"},{"set":5,"word":"billing","pos":"名詞","meaning":"請求(業務)","example":"Please contact the billing department if you notice an error on your invoice.","exampleJa":"請求書に誤りがありましたら、経理の請求担当部署までご連絡ください。","hint":"請求書を発行する業務。billing address(請求先住所)や billing department の形"},{"set":5,"word":"board","pos":"名詞","meaning":"取締役会、板","example":"The board of directors approved the merger after a long discussion.","exampleJa":"取締役会は長い議論の末、合併を承認した。","hint":"会議テーブルを囲む人々→「取締役会」。on board は「搭乗して」の別義で、どちらも頻出"},{"set":5,"word":"briefly","pos":"副詞","meaning":"手短に","example":"Let me briefly explain the main changes in the new policy.","exampleJa":"新しい方針の主な変更点を手短に説明させてください。","hint":"brief(短い)の副詞。会議で「手短に説明します」と切り出す場面"},{"set":5,"word":"broadcast","pos":"動詞","meaning":"放送する","example":"The network will broadcast the CEO's speech live this evening.","exampleJa":"そのネットワークは今夜、CEOの演説を生放送する予定だ。","hint":"ラジオ・テレビで電波に乗せて流す。活用は broadcast-broadcast-broadcast で形が変わらない"},{"set":5,"word":"browse","pos":"動詞","meaning":"見て回る、閲覧する","example":"Feel free to browse our online catalog before placing an order.","exampleJa":"ご注文の前に、どうぞ自由にオンラインカタログをご覧ください。","hint":"店内を目的なくぶらぶら見る、ウェブを流し読みする。目的が決まっていない閲覧の感覚"},{"set":5,"word":"bulletin","pos":"名詞","meaning":"掲示、会報","example":"The new safety rules were posted on the company bulletin board.","exampleJa":"新しい安全規則は社内の掲示板に貼り出された。","hint":"社内の掲示板に貼る短い知らせ。bulletin board の形で覚える"},{"set":5,"word":"bureau","pos":"名詞","meaning":"局、事務所","example":"The tourist bureau provides free maps and hotel information to visitors.","exampleJa":"観光案内所は、訪問者に無料の地図とホテル情報を提供している。","hint":"官庁や案内所などの「局・部署」。tourist/travel bureau のように複合で出る"},{"set":5,"word":"cabinet","pos":"名詞","meaning":"戸棚","example":"Please store all customer files in the locked filing cabinet.","exampleJa":"顧客ファイルはすべて、鍵のかかる書類棚に保管してください。","hint":"オフィスの引き出し付き収納家具。filing cabinet(書類キャビネット)で覚える"},{"set":5,"word":"calculate","pos":"動詞","meaning":"計算する","example":"The software can calculate the total cost of the project automatically.","exampleJa":"そのソフトウェアは、プロジェクトの総費用を自動で計算できる。","hint":"電卓(calculator)で数字を出す動作。calculate the cost/total の形"},{"set":5,"word":"capable","pos":"形容詞","meaning":"有能な、〜できる","example":"Our new server is capable of handling thousands of requests at once.","exampleJa":"当社の新しいサーバーは、一度に数千件のリクエストを処理できる。","hint":"be capable of -ing の形で「〜する能力がある」。able to との言い換えを意識"},{"set":5,"word":"career","pos":"名詞","meaning":"職業、経歴","example":"She began her career as an assistant at a small law firm.","exampleJa":"彼女は小さな法律事務所の助手としてキャリアを始めた。","hint":"職歴を重ねていく道のり。career fair(就職説明会)や career change の形"},{"set":5,"word":"carry","pos":"動詞","meaning":"運ぶ、(在庫を)置いている","example":"Unfortunately, our store does not carry that brand of printer.","exampleJa":"あいにく当店ではその銘柄のプリンターは取り扱っておりません。","hint":"運ぶ意味から、店が「商品を取り扱っている」意味に広がる。店員のセリフで出る"},{"set":5,"word":"cashier","pos":"名詞","meaning":"レジ係","example":"The cashier handed me the receipt and wished me a good day.","exampleJa":"レジ係は私にレシートを渡し、よい一日をと声をかけてくれた。","hint":"cash(現金)を扱う人。スーパーやショップのレジ係で、会計の場面に出る"},{"set":5,"word":"cause","pos":"動詞","meaning":"引き起こす","example":"Heavy snow caused a long delay at the airport yesterday.","exampleJa":"昨日は大雪のため、空港で長い遅延が生じた。","hint":"原因となって結果を生む。cause a delay/problem など、悪い事柄を目的語に取りやすい"},{"set":5,"word":"celebrate","pos":"動詞","meaning":"祝う","example":"The company will celebrate its twentieth anniversary with a special event.","exampleJa":"会社は創立20周年を特別なイベントで祝う予定だ。","hint":"周年や成功を皆で祝う場面。celebrate the 10th anniversary の形"},{"set":5,"word":"celebration","pos":"名詞","meaning":"祝賀(会)","example":"Everyone is invited to the retirement celebration in the main hall.","exampleJa":"どなたでも、大ホールで行われる退職祝いの会にご参加いただけます。","hint":"celebrate の名詞。パーティーや記念行事を指す。anniversary celebration で覚える"},{"set":5,"word":"ceremony","pos":"名詞","meaning":"式典","example":"The opening ceremony for the new library starts at ten o'clock.","exampleJa":"新しい図書館の開館式は10時に始まる。","hint":"決まった段取りで行う式。opening/awards/graduation ceremony など"},{"set":5,"word":"chairperson","pos":"名詞","meaning":"議長","example":"The chairperson asked everyone to vote on the proposed budget.","exampleJa":"議長は全員に、提案された予算案について採決するよう求めた。","hint":"会議で議事を進める議長。chairman より性別を問わない言い方"},{"set":5,"word":"challenge","pos":"名詞","meaning":"課題、難題","example":"Finding qualified staff remains the biggest challenge for our company.","exampleJa":"資格のある人材を見つけることが、当社にとって依然として最大の課題だ。","hint":"乗り越えるべき壁。face a challenge の形で使う。problem の前向きな言い換え"},{"set":5,"word":"characteristic","pos":"名詞","meaning":"特徴","example":"Durability is the most important characteristic of this product.","exampleJa":"耐久性は、この製品の最も重要な特徴だ。","hint":"character(性格・特性)の仲間。製品や人の「目立つ特徴」を言う名詞"},{"set":5,"word":"checkout","pos":"名詞","meaning":"会計(所)、チェックアウト","example":"Checkout time at the hotel is eleven o'clock in the morning.","exampleJa":"そのホテルのチェックアウト時刻は午前11時だ。","hint":"ホテルの「チェックアウト」と、スーパーのレジ。checkout counter で会計場面を連想"},{"set":5,"word":"claim","pos":"名詞","meaning":"請求、主張","example":"You can file an insurance claim online within thirty days of the accident.","exampleJa":"事故から30日以内であれば、オンラインで保険金を請求できます。","hint":"空港の baggage claim(手荷物受取所)と保険の「請求」。当然の権利として求めるイメージ"},{"set":5,"word":"classified","pos":"形容詞","meaning":"分類された、機密の","example":"She found the apartment by reading the classified ads in the newspaper.","exampleJa":"彼女は新聞の分類広告を読んで、そのアパートを見つけた。","hint":"分類された→新聞の「分類広告(classified ads)」。「機密の」の意味もある"},{"set":5,"word":"clearance","pos":"名詞","meaning":"在庫一掃、許可","example":"The store is holding a clearance sale on all winter clothing.","exampleJa":"その店では冬物衣料すべてを対象に在庫一掃セールを行っている。","hint":"売り場を空ける→「在庫一掃」。clearance sale の形で、店の広告に頻出"},{"set":5,"word":"climate","pos":"名詞","meaning":"気候、情勢","example":"The current economic climate makes it difficult to expand the business.","exampleJa":"現在の経済情勢では、事業を拡大するのは難しい。","hint":"天気の長期的な傾向が原義。economic climate(経済情勢)のように比喩でも使う"},{"set":5,"word":"closure","pos":"名詞","meaning":"閉鎖","example":"A temporary road closure will cause delays on Main Street.","exampleJa":"一時的な道路閉鎖により、メインストリートで遅れが生じる見込みだ。","hint":"close の名詞。road closure(通行止め)や factory closure(工場閉鎖)の告知で出る"},{"set":5,"word":"clothing","pos":"名詞","meaning":"衣類","example":"The factory produces protective clothing for workers in the chemical industry.","exampleJa":"その工場は化学産業の作業員向けに防護服を製造している。","hint":"衣類全体を指す不可算名詞。a clothing は不可で、a piece of clothing と言う"},{"set":5,"word":"coach","pos":"名詞","meaning":"長距離バス、エコノミー席","example":"Tickets in coach are much cheaper than those in business class.","exampleJa":"エコノミークラスの航空券は、ビジネスクラスよりずっと安い。","hint":"もとは馬車。長距離バスや飛行機のエコノミー席(coach class)の意味を押さえる"},{"set":5,"word":"code","pos":"名詞","meaning":"規定、暗号","example":"Our company's dress code allows casual clothing on Fridays.","exampleJa":"当社の服装規定では、金曜日はカジュアルな服装が認められている。","hint":"決まりごとの集まり。dress code(服装規定)が定番。割引コードやプログラムの意味もある"},{"set":5,"word":"collect","pos":"動詞","meaning":"集める","example":"Please collect your luggage from the carousel before heading to customs.","exampleJa":"税関へ向かう前に、ターンテーブルでお荷物をお受け取りください。","hint":"データや手荷物など散らばったものを集める。collect your luggage は空港の定番"},{"set":5,"word":"collection","pos":"名詞","meaning":"収集品、回収","example":"The designer will present her new spring collection next month.","exampleJa":"そのデザイナーは来月、新しい春のコレクションを発表する予定だ。","hint":"集めたもの→ファッションの新作コレクション。ごみの「回収」も同語"},{"set":5,"word":"combine","pos":"動詞","meaning":"組み合わせる","example":"We plan to combine the two departments to improve efficiency.","exampleJa":"効率を高めるために、2つの部署を統合する計画だ。","hint":"2つを一つにまとめる。combine A with B の形。出張と観光を組み合わせる場面など"},{"set":5,"word":"comfortable","pos":"形容詞","meaning":"快適な","example":"The hotel offers spacious rooms with comfortable beds and quiet surroundings.","exampleJa":"そのホテルは、快適なベッドと静かな環境を備えた広い客室を提供している。","hint":"座り心地のよい椅子や、居心地のよい環境。feel comfortable は「気が楽だ」"},{"set":5,"word":"commitment","pos":"名詞","meaning":"献身、確約","example":"Our commitment to customer satisfaction has never been stronger than today.","exampleJa":"お客様満足への当社の取り組みは、今ほど強いときはありません。","hint":"約束して打ち込む姿勢。commitment to ～ の形で、企業理念の文によく出る"},{"set":5,"word":"communicate","pos":"動詞","meaning":"伝える、連絡を取る","example":"Managers should communicate clearly with their teams about any schedule changes.","exampleJa":"管理職は、スケジュールの変更について部下にはっきり伝えるべきだ。","hint":"communicate with ～ で「〜と連絡を取る」。メールや電話でのやりとりの場面"},{"set":5,"word":"community","pos":"名詞","meaning":"地域社会","example":"The company donated money to support the local community center.","exampleJa":"その会社は地域のコミュニティセンターを支援するために寄付を行った。","hint":"同じ地域に住む人々のまとまり。local community や community center の形"},{"set":5,"word":"competition","pos":"名詞","meaning":"競争、競技会","example":"Competition in the smartphone market has become extremely fierce this year.","exampleJa":"今年、スマートフォン市場の競争はきわめて激しくなった。","hint":"競合他社との競争、またはコンテスト。fierce competition(激しい競争)が定番"},{"set":5,"word":"competitive","pos":"形容詞","meaning":"競争力のある","example":"We offer competitive salaries and excellent training opportunities to all employees.","exampleJa":"当社はすべての従業員に、競争力のある給与と優れた研修の機会を提供している。","hint":"他社に負けない強さ。competitive price/salary は「他に引けを取らない」ことを示す"},{"set":5,"word":"complain","pos":"動詞","meaning":"苦情を言う","example":"Several customers complained about the long wait at the front desk.","exampleJa":"数人の顧客が、フロントでの長い待ち時間について苦情を述べた。","hint":"complain about ～ で「〜について不満を言う」。苦情対応の場面で頻出"},{"set":6,"word":"completion","pos":"名詞","meaning":"完成","example":"The contractor expects completion of the office renovation by the end of March.","exampleJa":"請負業者は3月末までにオフィス改装が完成すると見込んでいる。","hint":"complete+-ion。「upon completion(完了次第)」で契約書や工事の場面を思い出そう"},{"set":6,"word":"concern","pos":"名詞","meaning":"懸念、関心事","example":"Several employees raised concerns about the new overtime policy during the meeting.","exampleJa":"会議中、数人の従業員が新しい残業規定について懸念を示した。","hint":"会議で「I have a concern about...」と切り出す場面。raise a concern の形で覚える"},{"set":6,"word":"conference room","pos":"名詞","meaning":"会議室","example":"Please reserve the conference room for our client presentation on Friday afternoon.","exampleJa":"金曜の午後の顧客向けプレゼンのために会議室を予約してください。","hint":"conference(会議)+room。社内の予約表に「Conference Room B」と載っている光景"},{"set":6,"word":"connect","pos":"動詞","meaning":"つなぐ","example":"Please connect your laptop to the projector before the presentation begins.","exampleJa":"プレゼンが始まる前にノートパソコンをプロジェクターにつないでください。","hint":"Wi-Fiやケーブルを「つなぐ」場面。connect A to B の形で"},{"set":6,"word":"connection","pos":"名詞","meaning":"接続、乗り継ぎ、縁","example":"Heavy fog caused me to miss my connection in Chicago yesterday.","exampleJa":"濃霧のせいで、昨日シカゴで乗り継ぎ便に乗り遅れた。","hint":"ネット接続・乗り継ぎ・人脈の3つ。「connection が切れた／間に合わない」と場面で区別"},{"set":6,"word":"consider","pos":"動詞","meaning":"検討する","example":"We are considering moving our headquarters to a larger building downtown.","exampleJa":"当社は本社を市内中心部のより大きなビルに移すことを検討している。","hint":"企画書を前に腕組みして考える姿。consider -ing の形を取る点が頻出"},{"set":6,"word":"considerable","pos":"形容詞","meaning":"かなりの","example":"The new software saved the accounting team a considerable amount of time.","exampleJa":"その新しいソフトのおかげで、経理チームはかなりの時間を節約できた。","hint":"consider(考える)+-able。「考慮に値する→かなりの」と連想。considerable amount の形で"},{"set":6,"word":"consideration","pos":"名詞","meaning":"検討、配慮","example":"Your application is under consideration, and we will contact you next week.","exampleJa":"あなたの応募は検討中で、来週ご連絡いたします。","hint":"consider の名詞形。「Thank you for your consideration.」は応募メールの締め言葉"},{"set":6,"word":"consist","pos":"動詞","meaning":"成り立つ","example":"The project team consists of two designers, three engineers, and one manager.","exampleJa":"そのプロジェクトチームはデザイナー2名、エンジニア3名、マネージャー1名で構成されている。","hint":"consist of で「〜から成る」とセット暗記。構成メンバー紹介の場面を思い浮かべる"},{"set":6,"word":"contact","pos":"動詞","meaning":"連絡する","example":"Please contact the personnel office if you have questions about your benefits.","exampleJa":"福利厚生についてご質問があれば、人事部までご連絡ください。","hint":"名刺の「Contact」欄をイメージ。動詞でも名詞でも同形で、直接目的語を取る(contact him)"},{"set":6,"word":"contain","pos":"動詞","meaning":"含む","example":"This report contains confidential information and must not be shared outside the company.","exampleJa":"この報告書には機密情報が含まれており、社外に共有してはならない。","hint":"箱や書類の「中に入っている」。contents(中身)と同じ仲間と覚える"},{"set":6,"word":"container","pos":"名詞","meaning":"容器","example":"Dozens of shipping containers were unloaded at the port this morning.","exampleJa":"今朝、港で数十個の貨物コンテナが荷降ろしされた。","hint":"contain(入れる)+-er＝入れ物。タッパーから貨物コンテナまで"},{"set":6,"word":"content","pos":"名詞","meaning":"内容、中身","example":"Our marketing team reviews all website content before it is published.","exampleJa":"当社のマーケティングチームは、公開前にすべてのウェブサイトの内容を確認する。","hint":"「中身」の意味はアクセントが前(cóntent)。ウェブサイトのコンテンツを思い浮かべる"},{"set":6,"word":"contribute","pos":"動詞","meaning":"貢献する、寄付する","example":"Every member of the sales team contributed to this quarter's record results.","exampleJa":"営業チームの全員が、今四半期の過去最高の業績に貢献した。","hint":"contribute to で「〜に貢献する」。チームや募金に力や金を出す場面で"},{"set":6,"word":"contribution","pos":"名詞","meaning":"貢献、寄付","example":"The CEO thanked Ms. Park for her outstanding contribution to the merger.","exampleJa":"CEOはパク氏の合併への多大な貢献に感謝した。","hint":"contribute の名詞。表彰式の「功績に感謝」や寄付金のイメージ"},{"set":6,"word":"control","pos":"名詞","meaning":"管理、統制","example":"The quality control department inspects every product before it leaves the factory.","exampleJa":"品質管理部は、工場から出荷される前にすべての製品を検査する。","hint":"「quality control(品質管理)」と工場の管理室をセットで。under control で「制御下」"},{"set":6,"word":"convention","pos":"名詞","meaning":"大会、慣習","example":"Thousands of dentists will attend the annual convention in Seattle this June.","exampleJa":"今年6月、数千人の歯科医がシアトルでの年次大会に参加する予定だ。","hint":"業界の大規模な集まりは convention center で開く。「慣習」の意味もある"},{"set":6,"word":"cooperation","pos":"名詞","meaning":"協力","example":"We appreciate your cooperation while the main elevator is out of service.","exampleJa":"メインエレベーターが停止中のご協力に感謝いたします。","hint":"co-(共に)+operation。掲示の「ご協力をお願いします」が定番"},{"set":6,"word":"coordinate","pos":"動詞","meaning":"調整する","example":"Ms. Lopez will coordinate travel arrangements for all conference attendees.","exampleJa":"ロペスさんが、会議の全参加者の出張手配を調整する。","hint":"イベント担当者(coordinator)が日程や人を調整して回す姿を想像"},{"set":6,"word":"corporate","pos":"形容詞","meaning":"企業の","example":"The corporate headquarters will relocate to a new building next spring.","exampleJa":"本社は来春、新しいビルに移転する予定だ。","hint":"名詞の前に置いて「企業の」。corporate headquarters(本社)、corporate card など"},{"set":6,"word":"corporation","pos":"名詞","meaning":"法人、企業","example":"The corporation announced plans to open three new factories overseas.","exampleJa":"その企業は海外に3つの新工場を開設する計画を発表した。","hint":"社名の後ろの「Corp.」。Inc. と並ぶ法人の表記として覚える"},{"set":6,"word":"correct","pos":"形容詞","meaning":"正しい","example":"Please make sure the shipping address you entered is correct before submitting.","exampleJa":"送信する前に、入力した配送先住所が正しいことを確認してください。","hint":"テストの「正解」と同じ感覚。動詞「訂正する」もあるが、ここは形容詞"},{"set":6,"word":"counter","pos":"名詞","meaning":"売り場、カウンター","example":"Please pick up your boarding pass at the check-in counter on the second floor.","exampleJa":"搭乗券は2階のチェックインカウンターでお受け取りください。","hint":"空港のチェックインカウンターや店のレジ台を思い浮かべる"},{"set":6,"word":"coupon","pos":"名詞","meaning":"割引券","example":"Customers can redeem this coupon for ten percent off their next purchase.","exampleJa":"お客様は、このクーポンで次回のお買い物が10パーセント割引になります。","hint":"雑誌から切り取る割引券の光景。redeem a coupon(使う)とセット"},{"set":6,"word":"cover","pos":"動詞","meaning":"含む、担当する、費用を賄う","example":"The company will cover all travel expenses for employees attending the training.","exampleJa":"会社は、研修に参加する従業員の出張費をすべて負担する。","hint":"「上から覆う」感覚。費用を賄う、保険が対象にする、など範囲に収める意味へ広がる"},{"set":6,"word":"create","pos":"動詞","meaning":"作り出す","example":"The new factory will create more than two hundred jobs in the region.","exampleJa":"新工場は、地域に200以上の雇用を生み出す。","hint":"creative(創造的な)と並べて覚える。アカウントや雇用を「生み出す」"},{"set":6,"word":"credit","pos":"名詞","meaning":"信用、クレジット、功績","example":"The manager gave credit to the entire team for the successful product launch.","exampleJa":"マネージャーは、製品発売の成功をチーム全体の功績とした。","hint":"クレジットカードは「信用」で後払いできる仕組み。「功績」の意味もある"},{"set":6,"word":"critic","pos":"名詞","meaning":"批評家","example":"A well-known food critic gave the new restaurant an excellent review.","exampleJa":"著名な料理評論家が、その新しいレストランに素晴らしい評価を与えた。","hint":"映画や料理の評論家。critical(批判的な)と同じ仲間の語"},{"set":6,"word":"critical","pos":"形容詞","meaning":"重大な、批判的な","example":"It is critical that we finish the safety inspection before the factory reopens.","exampleJa":"工場が再開する前に安全検査を終えることが極めて重要だ。","hint":"「重大な」と「批判的な」の2面。critical issue は一刻を争う問題の場面"},{"set":6,"word":"crowded","pos":"形容詞","meaning":"混雑した","example":"The convention hall was so crowded that many visitors had to stand.","exampleJa":"会場は非常に混雑しており、多くの来場者が立ったままだった。","hint":"crowd(群衆)+-ed。ラッシュ時の電車やセール会場を思い浮かべる"},{"set":6,"word":"cuisine","pos":"名詞","meaning":"料理(法)","example":"The hotel restaurant is famous for its authentic regional cuisine.","exampleJa":"そのホテルのレストランは、本格的な郷土料理で有名だ。","hint":"レストランのメニューに書かれる「Italian cuisine」。発音は「クイジーン」(音の連想)"},{"set":6,"word":"current","pos":"形容詞","meaning":"現在の","example":"Please update your current address in the employee database by Friday.","exampleJa":"金曜までに、従業員データベースの現住所を更新してください。","hint":"currency(通貨)や電流(current)と同じ綴り。「今流れている→現在の」と連想"},{"set":6,"word":"custom","pos":"形容詞","meaning":"特注の","example":"We specialize in custom furniture designed to fit small office spaces.","exampleJa":"当社は、小さなオフィス空間に合わせて設計した特注家具を専門としている。","hint":"オーダーメイドの靴やスーツ。名詞の前で「特注の」と使う(custom-made)"},{"set":6,"word":"customer service","pos":"名詞","meaning":"顧客サービス(部門)","example":"Our customer service team is available around the clock to answer your questions.","exampleJa":"当社の顧客サービスチームは、24時間いつでもご質問にお答えします。","hint":"客からの電話や苦情に対応するコールセンターを想像。representative とよく組む"},{"set":6,"word":"customize","pos":"動詞","meaning":"特注で作る、好みに合わせる","example":"Users can customize the dashboard to display the reports they need most.","exampleJa":"ユーザーは、最も必要なレポートが表示されるようにダッシュボードをカスタマイズできる。","hint":"custom(特注)に動詞語尾 -ize が付いた形。画面設定を自分好みに変える場面"},{"set":6,"word":"deal","pos":"名詞","meaning":"取引","example":"After weeks of negotiation, the two firms finally closed the deal.","exampleJa":"数週間の交渉の末、両社はついに取引をまとめた。","hint":"契約成立の握手の場面。a great deal of(多量の)や deal with(対処する)も頻出"},{"set":6,"word":"dealer","pos":"名詞","meaning":"販売店","example":"The authorized dealer will deliver the new vehicle to your office next week.","exampleJa":"正規販売店が来週、新車をあなたのオフィスに届けます。","hint":"deal(取引)をする人。車のディーラーが代表的な場面"},{"set":6,"word":"debate","pos":"名詞","meaning":"討論","example":"There was a lively debate about whether to expand into the European market.","exampleJa":"欧州市場に進出すべきかどうかについて、活発な議論が交わされた。","hint":"テレビの討論会や社内の賛否が割れる議論の場面"},{"set":6,"word":"decrease","pos":"動詞","meaning":"減少する","example":"Website traffic decreased sharply after the company changed its homepage design.","exampleJa":"会社がホームページのデザインを変更した後、ウェブサイトのアクセス数が急減した。","hint":"increase の反対。売上や人数がグラフで右下がりになる場面。アクセントは動詞だと後ろ"},{"set":6,"word":"definitely","pos":"副詞","meaning":"間違いなく","example":"I will definitely send you the revised contract by tomorrow morning.","exampleJa":"修正した契約書を、明日の朝までに必ずお送りします。","hint":"「絶対行きます」と力強く返事する場面。definite(明確な)の副詞"},{"set":6,"word":"degree","pos":"名詞","meaning":"学位、程度","example":"This position requires a bachelor's degree in business or a related field.","exampleJa":"この職務には、経営学または関連分野の学士号が必要です。","hint":"履歴書の学歴欄(bachelor's degree)と、温度の「度」を同じ単語として結びつける"},{"set":6,"word":"delay","pos":"名詞","meaning":"遅延","example":"A delay in the delivery of parts postponed the product launch.","exampleJa":"部品の納品の遅れにより、製品の発売が延期された。","hint":"空港の電光掲示板の「DELAYED」を思い浮かべる。名詞も動詞も同形"},{"set":6,"word":"delighted","pos":"形容詞","meaning":"喜んで","example":"We are delighted to announce that Mr. Tanaka has been promoted to director.","exampleJa":"田中氏が部長に昇進したことをお知らせでき、嬉しく思います。","hint":"プレスリリースの定番「We are delighted to announce...」で覚える"},{"set":6,"word":"deliver","pos":"動詞","meaning":"配達する、(講演を)する","example":"The courier will deliver the package to your office before noon.","exampleJa":"配達員が正午までに荷物をあなたのオフィスに届けます。","hint":"荷物を届ける、スピーチ(speech)を届ける、約束を果たす、の3場面で"},{"set":6,"word":"delivery","pos":"名詞","meaning":"配達","example":"Standard delivery takes three to five business days within the country.","exampleJa":"通常配送は、国内で3〜5営業日かかります。","hint":"宅配の「配達」。free delivery、delivery date を通販サイトの画面で連想"},{"set":6,"word":"demand","pos":"名詞","meaning":"需要、要求","example":"Demand for electric vehicles has grown rapidly over the past few years.","exampleJa":"電気自動車の需要は、ここ数年で急速に伸びている。","hint":"supply(供給)と対で。「in demand」で人気がある、売り手が忙しい場面"},{"set":6,"word":"dental","pos":"形容詞","meaning":"歯の","example":"The company's health plan includes dental checkups for all full-time employees.","exampleJa":"会社の健康保険には、全正社員の歯科検診が含まれている。","hint":"dentist(歯科医)の仲間。歯科検診や保険(dental insurance)の場面"},{"set":6,"word":"departure","pos":"名詞","meaning":"出発","example":"Passengers should arrive at the gate thirty minutes before the scheduled departure.","exampleJa":"乗客は、出発予定時刻の30分前に搭乗口へ来てください。","hint":"空港の「Departures」表示と arrival(到着)をセットで。depart の名詞形"},{"set":6,"word":"depend","pos":"動詞","meaning":"頼る、次第である","example":"Our final budget will depend on how many people attend the seminar.","exampleJa":"最終的な予算は、セミナーの参加人数次第で決まる。","hint":"depend on で「〜次第」。「It depends.」と答を保留する会話の場面"},{"set":6,"word":"describe","pos":"動詞","meaning":"説明する","example":"Could you describe the problem you are having with your account?","exampleJa":"お客様のアカウントで起きている問題について説明していただけますか。","hint":"describe A to B の形。状況や商品の特徴を言葉で説明する場面"},{"set":6,"word":"description","pos":"名詞","meaning":"説明","example":"The job description lists the main duties and required qualifications.","exampleJa":"職務記述書には、主な業務内容と必要な資格が記載されている。","hint":"describe の名詞。求人票の job description、商品ページの説明文"},{"set":6,"word":"design","pos":"動詞","meaning":"設計する","example":"This laptop was designed to be lightweight and easy to carry.","exampleJa":"このノートパソコンは、軽くて持ち運びやすいように設計された。","hint":"デザイナーが図面を描く姿。be designed to do(〜するよう設計されている)が頻出"},{"set":6,"word":"destination","pos":"名詞","meaning":"目的地","example":"Lisbon has become a popular destination for international business conferences.","exampleJa":"リスボンは、国際ビジネス会議の人気の開催地になっている。","hint":"カーナビに入れる「目的地」。出張や観光の行き先の場面"},{"set":6,"word":"detail","pos":"名詞","meaning":"詳細","example":"Please visit our website for more details about the registration process.","exampleJa":"登録手続きの詳細については、当社のウェブサイトをご覧ください。","hint":"「for more details」はチラシの定番。複数形 details で使うことが多い"},{"set":6,"word":"determine","pos":"動詞","meaning":"決定する、突き止める","example":"The engineers are trying to determine the cause of the system failure.","exampleJa":"技術者たちは、システム障害の原因を突き止めようとしている。","hint":"調査の結果「原因を特定する」感覚。determine whether/what の節を取る"},{"set":6,"word":"develop","pos":"動詞","meaning":"開発する","example":"Our research team developed a more efficient battery for mobile devices.","exampleJa":"当社の研究チームは、モバイル機器向けにより効率的なバッテリーを開発した。","hint":"商品や技術を開発する場面。developer(開発者)、developing countries にも展開"},{"set":6,"word":"development","pos":"名詞","meaning":"開発、展開","example":"The firm invests heavily in research and development every single year.","exampleJa":"その会社は毎年、研究開発に多額の投資をしている。","hint":"R&D(研究開発)の D。「新たな展開」「住宅開発」の意味にも広がる"},{"set":6,"word":"device","pos":"名詞","meaning":"装置、機器","example":"Employees may not connect personal devices to the company network without approval.","exampleJa":"従業員は、承認なしに私物の機器を社内ネットワークに接続してはならない。","hint":"スマホやタブレットなど「機器」。発音は「ディヴァイス」で、動詞 devise とは綴りと音が違う点に注意"},{"set":6,"word":"direct","pos":"動詞","meaning":"案内する、指揮する","example":"The receptionist directed the visitors to the conference room on the third floor.","exampleJa":"受付係は、来訪者を3階の会議室へ案内した。","hint":"道を聞かれて「あちらです」と案内する場面。映画監督が役者を指揮するのも同じ動詞"},{"set":6,"word":"direction","pos":"名詞","meaning":"方向、指示","example":"Follow the directions on the screen to complete the installation.","exampleJa":"画面の指示に従って、インストールを完了してください。","hint":"道順(directions)は複数形が定番。「in the right direction」で方向性の意味も"},{"set":6,"word":"director","pos":"名詞","meaning":"部長、取締役、監督","example":"The director of finance will present next year's budget at the board meeting.","exampleJa":"財務部長が、取締役会で来年度の予算を発表する。","hint":"部門の長や取締役、映画監督まで。名刺の肩書き(Marketing Director)で見かける"},{"set":6,"word":"directory","pos":"名詞","meaning":"名簿、案内板","example":"You can find her extension number in the online staff directory.","exampleJa":"彼女の内線番号は、オンラインの社員名簿に載っています。","hint":"ビルのロビーにある入居テナント一覧板や、社内の電話帳をイメージ"},{"set":6,"word":"disappointed","pos":"形容詞","meaning":"がっかりして","example":"Many customers were disappointed with the long wait times at the store.","exampleJa":"多くの客が、店での長い待ち時間にがっかりした。","hint":"期待外れの結果に肩を落とす表情。be disappointed with/at/by とセット"},{"set":6,"word":"discontinue","pos":"動詞","meaning":"生産を中止する","example":"The manufacturer decided to discontinue the older model next month.","exampleJa":"メーカーは、来月その旧型モデルの生産を中止することを決めた。","hint":"dis-(否定)+continue。人気が落ちた商品が「製造中止」になる場面"},{"set":6,"word":"display","pos":"名詞","meaning":"展示","example":"The latest smartphones are on display near the entrance of the store.","exampleJa":"最新のスマートフォンが、店の入口付近に展示されている。","hint":"ショーウィンドウや展示会のブース。on display(展示されて)の形で名詞"},{"set":6,"word":"distribution","pos":"名詞","meaning":"配布、流通","example":"The company's distribution network covers more than thirty countries worldwide.","exampleJa":"同社の流通網は、世界30か国以上に及んでいる。","hint":"distribute(配る)の名詞。工場から店へ商品を流す流通網を想像"},{"set":6,"word":"district","pos":"名詞","meaning":"地区","example":"Our new office is located in the city's central business district.","exampleJa":"当社の新しいオフィスは、市の中心部のビジネス街にある。","hint":"街の一区画。business district(ビジネス街)が定番"},{"set":6,"word":"document","pos":"名詞","meaning":"書類","example":"Please sign the attached document and return it to us by Monday.","exampleJa":"添付の書類に署名し、月曜までにご返送ください。","hint":"契約書や報告書など「書類」。動詞(記録する)ではアクセントが少し弱くなる点に注意"},{"set":6,"word":"due","pos":"形容詞","meaning":"期限の、〜する予定で","example":"The final report is due on the fifteenth of next month.","exampleJa":"最終報告書の提出期限は来月15日だ。","hint":"締切の due date、「〜する予定」be due to do、due to(〜が原因で)の3つを区別"},{"set":6,"word":"duty","pos":"名詞","meaning":"職務、義務","example":"Her main duties include answering phone calls and scheduling client appointments.","exampleJa":"彼女の主な職務は、電話応対と顧客との予約の調整だ。","hint":"求人票の「Duties include...」。on duty(勤務中)/ off duty(非番)とセット"},{"set":6,"word":"earn","pos":"動詞","meaning":"稼ぐ、得る","example":"Employees earn extra vacation days for every year of continuous service.","exampleJa":"従業員は、勤続1年ごとに追加の休暇日数を得られる。","hint":"給料や信頼など、働いて「得る」。earn a living(生計を立てる)が定番"},{"set":6,"word":"earnings","pos":"名詞","meaning":"収益、所得","example":"The company will report its quarterly earnings on Thursday afternoon.","exampleJa":"同社は木曜の午後に四半期の決算を発表する予定だ。","hint":"決算発表のニュースで聞く「earnings report」。複数形で使う"},{"set":6,"word":"economy","pos":"名詞","meaning":"経済、節約","example":"The global economy is expected to recover slowly over the next year.","exampleJa":"世界経済は今後1年でゆるやかに回復すると見込まれている。","hint":"国の経済のほか、economy class(エコノミー席)の「安い・節約」の意味も同じ語"},{"set":6,"word":"edition","pos":"名詞","meaning":"版","example":"The third edition of the guidebook includes updated maps and restaurant listings.","exampleJa":"そのガイドブックの第3版には、更新された地図とレストラン情報が載っている。","hint":"書籍の「第3版」や雑誌の特別号。「limited edition」は限定版"},{"set":6,"word":"editor","pos":"名詞","meaning":"編集者","example":"The editor asked the writer to shorten the article by two hundred words.","exampleJa":"編集者は、その記事を200語短くするよう執筆者に頼んだ。","hint":"edit(編集する)+-or。出版社や新聞社の編集者、editor-in-chief は編集長"},{"set":6,"word":"effect","pos":"名詞","meaning":"効果、影響","example":"The new safety regulations will take effect on the first of July.","exampleJa":"新しい安全規則は、7月1日に発効する。","hint":"「take effect」は法律や規則が「発効する」。affect(動詞)と混同しない"},{"set":6,"word":"effective","pos":"形容詞","meaning":"効果的な、有効な","example":"The new pricing policy is effective as of January first.","exampleJa":"新しい価格方針は、1月1日付で有効となる。","hint":"「効果的な」と「effective May 1(5月1日付で)」の2用法。後者は通知文の定番"},{"set":6,"word":"effort","pos":"名詞","meaning":"努力","example":"The firm is making every effort to reduce energy consumption in its offices.","exampleJa":"その会社は、オフィスのエネルギー消費を減らすためあらゆる努力をしている。","hint":"make an effort(努力する)。「in an effort to do」で「〜しようと努めて」"},{"set":6,"word":"elect","pos":"動詞","meaning":"選出する","example":"Ms. Chen was elected chairperson of the committee by a large majority.","exampleJa":"チェン氏は、大差で委員会の委員長に選出された。","hint":"選挙の場面。be elected president(社長・会長に選出される)の形で"},{"set":6,"word":"element","pos":"名詞","meaning":"要素","example":"Clear communication is a key element of any successful team.","exampleJa":"明確なコミュニケーションは、成功するチームに欠かせない重要な要素だ。","hint":"成功の要素や化学の元素。「key element」で、全体を構成する大切な部品の感覚"},{"set":6,"word":"eliminate","pos":"動詞","meaning":"取り除く","example":"The new process helped us eliminate unnecessary steps in order handling.","exampleJa":"新しい工程のおかげで、注文処理の不要な手順をなくすことができた。","hint":"ミスやムダをゼロにしたい改善活動の場面。「消し去る」感覚で"},{"set":6,"word":"emergency","pos":"名詞","meaning":"緊急事態","example":"In case of emergency, please use the stairs instead of the elevator.","exampleJa":"緊急の場合は、エレベーターではなく階段をご利用ください。","hint":"emergency exit(非常口)の緑の標識を思い浮かべる。in case of emergency"},{"set":6,"word":"employ","pos":"動詞","meaning":"雇う","example":"The factory employs nearly five hundred people from the surrounding area.","exampleJa":"その工場は、周辺地域から500人近くを雇用している。","hint":"社員を雇う場面。employee(従業員)、employer(雇用主)と同じ家族"},{"set":6,"word":"employer","pos":"名詞","meaning":"雇用主","example":"Your employer must provide a safe and healthy working environment.","exampleJa":"雇用主は、安全で健康的な労働環境を提供しなければならない。","hint":"employee(雇われる側)の反対で、雇う側。-er は「する人」、-ee は「される人」"},{"set":6,"word":"employment","pos":"名詞","meaning":"雇用、職","example":"The agency helps recent graduates find employment in the technology industry.","exampleJa":"その斡旋会社は、新卒者がIT業界で職を見つける手助けをしている。","hint":"employment agency(職業紹介所)や求人情報の見出しで見かける"},{"set":6,"word":"enable","pos":"動詞","meaning":"可能にする","example":"The new system enables staff to access files from any location.","exampleJa":"その新システムのおかげで、スタッフはどこからでもファイルにアクセスできる。","hint":"enable A to do「Aが〜できるようにする」の形。新機能や制度が主語になりやすい"},{"set":6,"word":"encounter","pos":"動詞","meaning":"遭遇する","example":"Users may encounter errors if they do not update the application.","exampleJa":"アプリケーションを更新しないと、ユーザーはエラーに遭遇することがある。","hint":"道中で思いがけず出くわすイメージ。encounter a problem(問題に直面)が定番"},{"set":6,"word":"engineering","pos":"名詞","meaning":"工学、技術部門","example":"The engineering team is testing a new design for the cooling system.","exampleJa":"技術チームは、冷却システムの新しい設計を試験している。","hint":"engineer(技術者)の仕事分野。「engineering department」で技術部門"},{"set":6,"word":"entertainment","pos":"名詞","meaning":"娯楽","example":"The hotel offers live entertainment in its lobby every Saturday evening.","exampleJa":"そのホテルでは、毎週土曜の夜にロビーで生の演奏などの催しを行っている。","hint":"映画・音楽・ライブなどの娯楽。ホテルや船の広告に出る live entertainment"},{"set":6,"word":"entire","pos":"形容詞","meaning":"全体の","example":"The entire staff was invited to the retirement party for Mr. Evans.","exampleJa":"スタッフ全員が、エバンズ氏の退職記念パーティーに招待された。","hint":"the entire staff のように the の直後に置く。「丸ごと全部」と強調する感覚"},{"set":6,"word":"entrance","pos":"名詞","meaning":"入口","example":"Visitors must check in at the main entrance before entering the building.","exampleJa":"来訪者は、建物に入る前に正面入口で受付をしなければならない。","hint":"建物の「入口」。exit(出口)と対。発音は「エントランス」で、動詞 enter の仲間"},{"set":6,"word":"entry","pos":"名詞","meaning":"入場、応募作品","example":"All entries for the photography contest must be submitted by October thirty-first.","exampleJa":"写真コンテストの応募作品はすべて、10月31日までに提出しなければならない。","hint":"コンテスト応募作品、入場、データ入力(data entry)と場面別に覚える"},{"set":6,"word":"environment","pos":"名詞","meaning":"環境","example":"We are committed to creating a positive and supportive work environment.","exampleJa":"私たちは、前向きで支え合える職場環境づくりに取り組んでいる。","hint":"自然環境だけでなく、work environment(職場環境)の意味も重要"},{"set":6,"word":"environmental","pos":"形容詞","meaning":"環境の","example":"The report examines the environmental impact of the proposed highway.","exampleJa":"その報告書は、計画中の高速道路が環境に与える影響を検証している。","hint":"environment の形容詞。環境保護や環境影響評価の資料に出てくる"},{"set":6,"word":"error","pos":"名詞","meaning":"誤り","example":"A billing error caused several customers to be charged twice.","exampleJa":"請求ミスにより、複数の顧客が二重に請求された。","hint":"パソコンの「エラーメッセージ」でおなじみ。billing error(請求ミス)も頻出"},{"set":6,"word":"essential","pos":"形容詞","meaning":"不可欠な","example":"Strong communication skills are essential for this customer-facing position.","exampleJa":"この顧客対応の職務には、優れたコミュニケーション能力が不可欠だ。","hint":"「なくてはならない」。essential for/to ~ の形で、必須条件を述べる場面"},{"set":6,"word":"establish","pos":"動詞","meaning":"設立する","example":"The company was established in 1985 and now employs over two thousand workers.","exampleJa":"その会社は1985年に設立され、現在2,000人以上の従業員を雇用している。","hint":"会社や制度を設立する。「Established 1990」とロゴに入る創業年の表記を連想"},{"set":6,"word":"estate","pos":"名詞","meaning":"地所、財産","example":"She works for a real estate company that manages commercial properties downtown.","exampleJa":"彼女は、市内中心部の商業物件を管理する不動産会社に勤めている。","hint":"real estate(不動産)の形でほぼ登場。不動産会社の広告を思い浮かべる"},{"set":6,"word":"event","pos":"名詞","meaning":"行事、出来事","example":"The annual company event will take place at the city park in June.","exampleJa":"毎年恒例の会社行事は、6月に市立公園で開催される。","hint":"社内の懇親会や展示会。「in the event of ~」(〜の場合は)は掲示の定番"},{"set":6,"word":"examine","pos":"動詞","meaning":"調べる","example":"Inspectors will examine each machine carefully before it is approved for use.","exampleJa":"検査員は、使用を承認する前に各機械を丁寧に調べる。","hint":"医者や検査員が細かく調べる姿。exam(試験)と同じ仲間の語"},{"set":7,"word":"excellent","pos":"形容詞","meaning":"優れた","example":"The hotel received excellent reviews for its friendly staff and clean rooms.","exampleJa":"そのホテルは、親切なスタッフと清潔な客室で非常に高い評価を受けた。","hint":"レビュー欄の「Excellent!」の星5を思い浮かべる。in excellent conditionは中古品の定番表現"},{"set":7,"word":"exchange","pos":"名詞","meaning":"交換","example":"We discussed the exchange of contract documents during this morning's meeting.","exampleJa":"私たちは今朝の会議で、契約書類の交換について話し合った。","hint":"空港の両替所の「Currency Exchange」の看板。change(変える)を含む点も覚えやすい"},{"set":7,"word":"excited","pos":"形容詞","meaning":"わくわくして","example":"Our team is excited about launching the new product next month.","exampleJa":"私たちのチームは、来月の新製品発売にわくわくしている。","hint":"人が主語なら-ed。「I'm excited」で自分がわくわくする側。物が主語ならexcitingとの対比で覚える"},{"set":7,"word":"exhibit","pos":"名詞","meaning":"展示(品)","example":"The new exhibit at the science museum draws thousands of visitors each week.","exampleJa":"科学博物館の新しい展示は、毎週何千人もの来場者を集めている。","hint":"美術館の「Special Exhibit」の展示室を想像。exhibition(展覧会)と並べて覚える"},{"set":7,"word":"expansion","pos":"名詞","meaning":"拡大","example":"The company announced an expansion into three new overseas markets this year.","exampleJa":"その会社は、今年新たに3つの海外市場へ進出すると発表した。","hint":"expand(広げる)の名詞形。店舗が増え地図上で広がる「事業拡大」の場面で覚える"},{"set":7,"word":"expect","pos":"動詞","meaning":"予期する、期待する","example":"We expect the shipment to arrive at the warehouse by Thursday.","exampleJa":"出荷品は木曜日までに倉庫へ到着する見込みです。","hint":"「be expected to do」で「〜することになっている」。到着予定や期待を表す頻出パターン"},{"set":7,"word":"expectation","pos":"名詞","meaning":"期待、予想","example":"The quarterly sales results exceeded the expectations of every board member.","exampleJa":"四半期の売上結果は、すべての取締役の予想を上回った。","hint":"exceed / meet / fall short of expectationsの3点セットで覚える"},{"set":7,"word":"experienced","pos":"形容詞","meaning":"経験豊富な","example":"We are looking for an experienced accountant to join our finance team.","exampleJa":"当社の財務チームに加わっていただく、経験豊富な会計士を募集しています。","hint":"求人広告の「Experienced chef wanted」。経験を積んだ人というイメージ"},{"set":7,"word":"expert","pos":"名詞","meaning":"専門家","example":"An expert in cybersecurity will speak at the industry conference next week.","exampleJa":"来週の業界会議で、サイバーセキュリティの専門家が講演する。","hint":"expert in / on ～で「〜の専門家」。セミナー講師の紹介文で見かける語"},{"set":7,"word":"explain","pos":"動詞","meaning":"説明する","example":"Could you explain the new expense reporting procedure to the interns?","exampleJa":"新しい経費報告の手順をインターン生に説明していただけますか。","hint":"「explain+物+to+人」の語順に注意。×explain him the planとは言えない"},{"set":7,"word":"explore","pos":"動詞","meaning":"探る、探検する","example":"The committee will explore several options for reducing office energy costs.","exampleJa":"委員会は、オフィスのエネルギー費用を削減するいくつかの方法を検討する予定だ。","hint":"explore optionsで「選択肢を検討する」。地図を片手に未知の場所を歩く探検の感覚"},{"set":7,"word":"export","pos":"動詞","meaning":"輸出する","example":"The firm exports high-quality machine parts to more than twenty countries.","exampleJa":"その会社は、高品質の機械部品を20か国以上に輸出している。","hint":"港から船が出ていく図。アクセントは動詞で後ろ(exPORT)、名詞で前(EXport)になる傾向"},{"set":7,"word":"express","pos":"動詞","meaning":"表現する、(形)速達の","example":"I would like to express my sincere gratitude for your generous support.","exampleJa":"ご厚意あるご支援に、心より感謝申し上げます。","hint":"「express delivery」は速達。気持ちを表す意味と速さの意味の両方が出題される"},{"set":7,"word":"extend","pos":"動詞","meaning":"延長する、伸ばす","example":"The organizers agreed to extend the registration deadline until the end of May.","exampleJa":"主催者は、登録の締め切りを5月末まで延長することに同意した。","hint":"extend a deadline(期限延長)とextend an invitation(招待する)の二大コロケーション"},{"set":7,"word":"external","pos":"形容詞","meaning":"外部の","example":"An external consultant will review our accounting procedures next quarter.","exampleJa":"来四半期に、外部のコンサルタントが当社の会計手続きを見直す予定だ。","hint":"internalの反対。「外部監査」「外付けドライブ」と、会社の外側から来るものに使う"},{"set":7,"word":"extra","pos":"形容詞","meaning":"追加の","example":"Overnight shipping is available for an extra charge of ten dollars.","exampleJa":"翌日配送は、追加料金10ドルでご利用いただけます。","hint":"レストランの「Extra charge」。at no extra costで「追加料金なし」と広告で頻出"},{"set":7,"word":"extremely","pos":"副詞","meaning":"非常に","example":"Our customer service team has been extremely busy since the holiday sale began.","exampleJa":"年末セールが始まってから、カスタマーサービスのチームは非常に忙しい。","hint":"veryより強い「極端に」。形容詞の前に置く強調語として、extremely importantなど"},{"set":7,"word":"fabulous","pos":"形容詞","meaning":"素晴らしい","example":"The conference center offers a fabulous view of the harbor from every room.","exampleJa":"そのカンファレンスセンターは、どの部屋からも港の素晴らしい眺めが楽しめる。","hint":"旅行パンフレットの「fabulous view」。ほめ言葉としてgreatより華やかな響きの連想で覚える"},{"set":7,"word":"factory","pos":"名詞","meaning":"工場","example":"The new factory will create about two hundred jobs in the region.","exampleJa":"新しい工場は、この地域に約200人分の雇用を生み出す見込みだ。","hint":"「factory tour(工場見学)」や「factory worker」の場面で覚える。manufacture(製造)の連想も有効"},{"set":7,"word":"fail","pos":"動詞","meaning":"失敗する、〜しない","example":"The supplier failed to deliver the materials before the agreed deadline.","exampleJa":"その納入業者は、合意した期限までに資材を納品できなかった。","hint":"fail to doは「〜しそこなう」で、後ろは動詞の原形。fail to meet the deadlineが定番"},{"set":7,"word":"failure","pos":"名詞","meaning":"失敗、故障","example":"A power failure forced the data center to shut down for two hours.","exampleJa":"停電のため、そのデータセンターは2時間の停止を余儀なくされた。","hint":"power failure(停電)、equipment failure(機器故障)。「失敗」より「故障」の意味が重要"},{"set":7,"word":"fair","pos":"名詞","meaning":"見本市、展示会","example":"Our company will have a booth at the international trade fair in Osaka.","exampleJa":"当社は、大阪で開かれる国際見本市にブースを出す予定だ。","hint":"trade fair(見本市)・job fair(就職説明会)。「公平な」のfairとは別の意味として区別する"},{"set":7,"word":"familiar","pos":"形容詞","meaning":"よく知っている","example":"Are you familiar with the new accounting software our department adopted?","exampleJa":"私たちの部署が導入した新しい会計ソフトには慣れていますか。","hint":"be familiar with ～は「〜をよく知っている」。前置詞withとセットで覚える"},{"set":7,"word":"fasten","pos":"動詞","meaning":"締める、留める","example":"Passengers are reminded to fasten their seat belts while the sign is on.","exampleJa":"乗客の皆様は、サインが点灯している間はシートベルトをお締めください。","hint":"機内アナウンスの「Please fasten your seat belt.」の場面で覚える。tは発音しない"},{"set":7,"word":"fault","pos":"名詞","meaning":"責任、欠陥","example":"Technicians found a fault in the wiring that caused the power outage.","exampleJa":"技術者たちは、停電の原因となった配線の欠陥を見つけた。","hint":"「It's not my fault.」の責任と、a fault in the systemの欠陥の2つの意味を対で覚える"},{"set":7,"word":"favorable","pos":"形容詞","meaning":"好意的な、有利な","example":"The product received favorable reviews from several leading technology magazines.","exampleJa":"その製品は、いくつかの有力な技術雑誌から好意的な評価を受けた。","hint":"favorable reviews(好評)。favor(好意)が形容詞になった形で、結果や条件が「好ましい」"},{"set":7,"word":"feature","pos":"名詞","meaning":"特徴、特集記事","example":"The new smartphone has several features designed for business travelers.","exampleJa":"その新型スマートフォンには、出張者向けに作られた機能がいくつかある。","hint":"商品の「key features(主な特徴)」と、雑誌の「feature article(特集記事)」の両方で出る"},{"set":7,"word":"fee","pos":"名詞","meaning":"料金、手数料","example":"A small service fee will be added to every online ticket purchase.","exampleJa":"オンラインでのチケット購入には、少額の手数料が加算されます。","hint":"admission fee(入場料)、late fee(延滞料)。サービスに支払う料金。priceやcostと使い分ける"},{"set":7,"word":"field","pos":"名詞","meaning":"分野、現場","example":"She has worked in the field of environmental engineering for fifteen years.","exampleJa":"彼女は環境工学の分野で15年間働いてきた。","hint":"「in the field of ～」で「〜の分野で」。field tripなら現場に出かける意味"},{"set":7,"word":"file","pos":"動詞","meaning":"提出する、整理保存する","example":"Employees must file their expense reports by the fifth of every month.","exampleJa":"従業員は、毎月5日までに経費報告書を提出しなければならない。","hint":"書類を棚にとじるイメージから、書類を正式に出す意味へ。file a complaint / file a reportが定番"},{"set":7,"word":"fill","pos":"動詞","meaning":"満たす、(職を)埋める","example":"We hope to fill the vacant marketing manager position by the end of June.","exampleJa":"6月末までに、空いているマーケティング部長の職を埋めたいと考えている。","hint":"fill out a form(記入する)とfill a position(欠員を補充する)をセットで覚える"},{"set":7,"word":"finance","pos":"名詞","meaning":"財務、金融","example":"The finance department is preparing the annual budget for next fiscal year.","exampleJa":"財務部は、来年度の年間予算を作成しているところだ。","hint":"会社の「finance department(経理・財務部)」。お金の管理を扱う部署の連想"},{"set":7,"word":"financial","pos":"形容詞","meaning":"財務の、金融の","example":"The financial report shows steady growth in revenue over the past year.","exampleJa":"財務報告書は、過去1年間にわたる収益の着実な伸びを示している。","hint":"financial report(財務報告)、financial advisor(ファイナンシャルアドバイザー)。名詞の前に置く"},{"set":7,"word":"firm","pos":"名詞","meaning":"会社、事務所","example":"She joined a well-known law firm after graduating from university.","exampleJa":"彼女は大学を卒業後、有名な法律事務所に入った。","hint":"law firm(法律事務所)、consulting firm(コンサル会社)。専門職の会社に使うことが多い"},{"set":7,"word":"fit","pos":"動詞","meaning":"合う、取り付ける","example":"This conference table is too large to fit in the meeting room.","exampleJa":"この会議用テーブルは大きすぎて、会議室に収まらない。","hint":"服がぴったり合う場面から、条件や予算に合う意味へ。fit your budgetは「予算に合う」"},{"set":7,"word":"fitness","pos":"名詞","meaning":"健康、フィットネス","example":"The hotel has a fitness center that guests can use free of charge.","exampleJa":"そのホテルにはフィットネスセンターがあり、宿泊客は無料で利用できる。","hint":"fitness center(ジム)は福利厚生の紹介文によく出る。fit+-nessで「健康な状態」"},{"set":7,"word":"fix","pos":"動詞","meaning":"修理する、固定する","example":"A technician came to fix the broken printer on the third floor.","exampleJa":"技術者が、3階の壊れたプリンターを修理しに来た。","hint":"「プリンターを直す」の場面で覚える。fixed priceのように「固定された」の意味もある"},{"set":7,"word":"flight","pos":"名詞","meaning":"便、飛行","example":"Your flight to Singapore has been delayed by about forty minutes.","exampleJa":"シンガポール行きのお客様の便は、約40分遅れています。","hint":"空港の電光掲示板の「Flight 305」。connecting flight(乗り継ぎ便)、flight attendantなど"},{"set":7,"word":"focus","pos":"動詞","meaning":"集中する","example":"We need to focus on improving the quality of our customer support.","exampleJa":"私たちは、カスタマーサポートの質を向上させることに集中する必要がある。","hint":"カメラのピントを合わせる動きから。focus on ～と、前置詞onを使う点がTOEICの狙い目"},{"set":7,"word":"following","pos":"形容詞","meaning":"次の、以下の","example":"Please bring the following documents to your interview on Monday morning.","exampleJa":"月曜の朝の面接には、以下の書類をお持ちください。","hint":"the following itemsで「以下の項目」。案内文や通知文の書き出しで頻出"},{"set":7,"word":"force","pos":"名詞","meaning":"力、部隊","example":"The company's sales force doubled in size after the merger last year.","exampleJa":"昨年の合併後、その会社の営業部隊は規模が2倍になった。","hint":"sales force(営業部隊)、workforce(労働力)のように「人の集まり」を表す使い方を押さえる"},{"set":7,"word":"forecast","pos":"名詞","meaning":"予報、予測","example":"The forecast predicts a ten percent increase in sales this quarter.","exampleJa":"予測では、今四半期の売上は10パーセント増加する見込みだ。","hint":"天気予報のweather forecastが基本。sales forecast(売上予測)にも広げて覚える"},{"set":7,"word":"form","pos":"名詞","meaning":"用紙、形","example":"Please complete the application form and return it to the front desk.","exampleJa":"申込用紙にご記入のうえ、受付までご返送ください。","hint":"order form(注文用紙)、application form(申込書)。fill out a formの形でよく出る"},{"set":7,"word":"formal","pos":"形容詞","meaning":"正式な","example":"The company will make a formal announcement about the merger on Friday.","exampleJa":"会社は金曜日に、合併について正式な発表を行う予定だ。","hint":"formal attire(正装)は式典の案内で見る語。反意語はinformal(くだけた)"},{"set":7,"word":"former","pos":"形容詞","meaning":"前の、元の","example":"Our former manager now works for a competitor in the same industry.","exampleJa":"私たちの元部長は、今は同業の競合他社で働いている。","hint":"former president(前社長)のように名詞の前に置く。反対はcurrent。the formerは「前者」"},{"set":7,"word":"found","pos":"動詞","meaning":"設立する","example":"The company was founded in 1985 by two former university classmates.","exampleJa":"その会社は、大学時代の元同級生2人によって1985年に設立された。","hint":"過去形foundと同形で紛らわしい。「be founded in 1985」の受け身で「〜年創業」と覚える"},{"set":7,"word":"founder","pos":"名詞","meaning":"創業者","example":"The founder of the company will give the opening speech tonight.","exampleJa":"その会社の創業者が、今夜の開会のスピーチを行う。","hint":"found(設立する)+-erで「設立した人」。会社紹介のthe company's founderの形で出る"},{"set":7,"word":"freight","pos":"名詞","meaning":"貨物(運送)","example":"Freight charges will be calculated according to the weight of the shipment.","exampleJa":"運送料は、荷物の重量に応じて計算されます。","hint":"貨物船やトラックで運ぶ大きな荷物。freight chargesは運送料。cargoと近い意味"},{"set":7,"word":"fuel","pos":"名詞","meaning":"燃料","example":"Rising fuel costs have increased the price of delivery services this year.","exampleJa":"燃料費の高騰により、今年は配送サービスの料金が上がった。","hint":"ガソリンスタンドのイメージ。fuel costs(燃料費)やfuel-efficient(低燃費の)で覚える"},{"set":7,"word":"function","pos":"名詞","meaning":"機能、行事","example":"The annual dinner is the main social function of the company's year.","exampleJa":"年次夕食会は、その会社にとって一年で最も大きな社交行事だ。","hint":"機械の「機能」と、social functionのような「行事・催し」の2つの意味を押さえる"},{"set":7,"word":"fund","pos":"名詞","meaning":"資金","example":"The charity organized a gala dinner to raise funds for the new library.","exampleJa":"その慈善団体は、新しい図書館の資金を集めるため、祝賀晩さん会を開いた。","hint":"ファンド(投資信託)というカタカナ語から連想。raise funds(資金を集める)が定番"},{"set":7,"word":"furniture","pos":"名詞","meaning":"家具","example":"All office furniture must be delivered before the staff move in on Monday.","exampleJa":"スタッフが月曜に入居する前に、オフィス家具はすべて搬入されなければならない。","hint":"不可算名詞なので×furnitures。a piece of furnitureで数える点が文法問題で狙われる"},{"set":7,"word":"gather","pos":"動詞","meaning":"集める、集まる","example":"Please gather in the main lobby at nine for the safety briefing.","exampleJa":"安全説明のため、9時に1階の正面ロビーに集合してください。","hint":"散らばったものが一か所に集まる動き。情報を集める用法と、人が集まる用法の両方で出る"},{"set":7,"word":"general","pos":"形容詞","meaning":"一般的な、全体の","example":"The general manager approved the plan after reviewing the budget details.","exampleJa":"総支配人は、予算の詳細を確認したうえで、その計画を承認した。","hint":"general manager(総支配人)、in general(一般に)。「総〜」と「概して」の語感で覚える"},{"set":7,"word":"generate","pos":"動詞","meaning":"生み出す","example":"The new online store has generated significant revenue within six months.","exampleJa":"新しいオンラインストアは、6か月以内に大きな収益を生み出した。","hint":"電気を作る「発電機(generator)」から連想。generate revenueで「収益を生む」"},{"set":7,"word":"goods","pos":"名詞","meaning":"商品","example":"The store sells a wide range of household goods at reasonable prices.","exampleJa":"その店は、さまざまな家庭用品を手ごろな価格で販売している。","hint":"常に複数形のsを付ける。consumer goods(消費財)、sporting goodsなど店の看板で目にする語"},{"set":7,"word":"graduate","pos":"動詞","meaning":"卒業する","example":"He graduated from a business school in Boston before joining our firm.","exampleJa":"彼はボストンのビジネススクールを卒業してから、当社に入社した。","hint":"graduate from ～と前置詞fromを使う。×graduate universityとは言わない点に注意"},{"set":7,"word":"grocery","pos":"名詞","meaning":"食料雑貨(店)","example":"The grocery chain plans to open ten new stores across the region.","exampleJa":"その食料品チェーンは、地域全体で10店舗を新規出店する計画だ。","hint":"スーパーの「grocery store」。groceriesと複数形にすると「食料雑貨類」の意味"},{"set":7,"word":"growth","pos":"名詞","meaning":"成長","example":"The report highlights strong growth in the company's overseas business.","exampleJa":"その報告書は、同社の海外事業における力強い成長を強調している。","hint":"grow(育つ)の名詞形。グラフが右肩上がりになる「economic growth」の絵で覚える"},{"set":7,"word":"guarantee","pos":"名詞","meaning":"保証","example":"This product comes with a one-year guarantee against manufacturing defects.","exampleJa":"この製品には、製造上の欠陥に対する1年間の保証が付いています。","hint":"家電の保証書。money-back guarantee(返金保証)など。guaranteeは保証する意味の動詞でも使う"},{"set":7,"word":"guide","pos":"名詞","meaning":"案内人、手引き","example":"A local guide will lead the group through the old city district.","exampleJa":"地元のガイドが、一行を旧市街地区へ案内する。","hint":"人の「tour guide」と、本の「user guide」の2種類をイメージ。道案内する存在"},{"set":7,"word":"guideline","pos":"名詞","meaning":"指針","example":"All staff must follow the safety guidelines when operating the machinery.","exampleJa":"全従業員は、機械を操作する際、安全指針に従わなければならない。","hint":"guide(導く)+line(線)の合成語。follow the guidelinesで「指針に従う」"},{"set":7,"word":"handle","pos":"動詞","meaning":"扱う、対処する","example":"Ms. Park will handle all customer complaints while the manager is away.","exampleJa":"部長が不在の間は、パクさんがすべての顧客の苦情に対応する。","hint":"「Handle with care」の荷物ラベルを思い出す。苦情などを「処理する」にも使う"},{"set":7,"word":"handout","pos":"名詞","meaning":"配布資料","example":"Please refer to the handout for a summary of today's presentation.","exampleJa":"本日の発表の要約は、配布資料をご覧ください。","hint":"会議で手渡される紙の資料。handと out(配る)の合成語。「Please refer to the handout」"},{"set":7,"word":"heavily","pos":"副詞","meaning":"大いに、激しく","example":"The restaurant relies heavily on tourists during the summer season.","exampleJa":"そのレストランは、夏の時期は観光客に大きく頼っている。","hint":"heavy(重い)の副詞形。rely heavily on ～で「〜に大きく依存する」"},{"set":7,"word":"highly","pos":"副詞","meaning":"非常に、高く","example":"The candidate is highly qualified and has excellent references from past employers.","exampleJa":"その候補者は非常に優れた資格を持ち、前職の雇用主から素晴らしい推薦も得ている。","hint":"「高い所に」ではなく「非常に」の意味。highly recommended / highly qualifiedの形で覚える"},{"set":7,"word":"historic","pos":"形容詞","meaning":"歴史的に重要な","example":"The hotel is located in a historic building near the central station.","exampleJa":"そのホテルは、中央駅の近くにある歴史的建造物の中にある。","hint":"historicは「歴史的に重要な」で、historical(歴史に関する)と区別する。historic buildingは保存建物"},{"set":7,"word":"hold","pos":"動詞","meaning":"開催する、保つ","example":"We will hold the annual shareholders' meeting at the convention center in May.","exampleJa":"年次株主総会は、5月にコンベンションセンターで開催する予定だ。","hint":"hold a meeting(会議を開く)。電話の「Please hold.」(切らずにお待ちください)も頻出"},{"set":7,"word":"host","pos":"動詞","meaning":"主催する","example":"Our city will host the international design conference next spring.","exampleJa":"私たちの市は、来年の春に国際デザイン会議を主催する。","hint":"パーティーの主人役(ホスト)から。host a conferenceで「会議を主催する」"},{"set":7,"word":"hourly","pos":"形容詞","meaning":"1時間ごとの","example":"Part-time employees receive an hourly wage plus a transportation allowance.","exampleJa":"パートタイム従業員には、時給に加えて交通費が支給される。","hint":"hourly wage(時給)。反対に日給はdaily、月給はmonthly。-lyが付いても形容詞"},{"set":7,"word":"housing","pos":"名詞","meaning":"住宅","example":"The city plans to build more affordable housing near the business district.","exampleJa":"市は、ビジネス街の近くに手ごろな価格の住宅をさらに建設する計画だ。","hint":"affordable housing(手ごろな住宅)、housing market(住宅市場)。ニュース記事によく出る"},{"set":7,"word":"human resources","pos":"名詞","meaning":"人事部","example":"Please send your résumé to the human resources department by Friday.","exampleJa":"金曜日までに、履歴書を人事部へ送ってください。","hint":"略してHR。採用や研修を担当する「人事部」。人を「資源」と見る発想で覚える"},{"set":7,"word":"ideal","pos":"形容詞","meaning":"理想的な","example":"This location is ideal for a small business that serves local customers.","exampleJa":"この立地は、地元の顧客を相手にする小規模な事業に最適だ。","hint":"ideal candidate(理想的な候補者)は求人でよく出る。ideal for ～で「〜に最適な」"},{"set":7,"word":"identification","pos":"名詞","meaning":"身分証明(書)","example":"Visitors must show photo identification at the reception desk before entering.","exampleJa":"来訪者は、入館前に受付で写真付きの身分証を提示しなければならない。","hint":"略称はID。photo identification(写真付き身分証)と受付での提示場面で覚える"},{"set":7,"word":"immediate","pos":"形容詞","meaning":"即座の、直属の","example":"Please report any safety concerns to your immediate supervisor right away.","exampleJa":"安全上の懸念は、直ちに直属の上司に報告してください。","hint":"immediate supervisor(直属の上司)。「すぐの」と「間に誰もいない」の両方の感覚で覚える"},{"set":7,"word":"impact","pos":"名詞","meaning":"影響","example":"The new tax policy will have a major impact on small businesses.","exampleJa":"新しい税制は、中小企業に大きな影響を与えるだろう。","hint":"have an impact on ～(〜に影響を与える)で使う。衝突の衝撃が転じて強い影響を表す"},{"set":7,"word":"import","pos":"動詞","meaning":"輸入する","example":"The retailer imports fresh fruit from several countries in South America.","exampleJa":"その小売業者は、南米のいくつかの国から新鮮な果物を輸入している。","hint":"exportの反対。港に荷が入ってくる図。imported goods(輸入品)の形でも出る"},{"set":7,"word":"impress","pos":"動詞","meaning":"感心させる","example":"The new intern impressed everyone with her quick and accurate work.","exampleJa":"新しいインターンは、迅速で正確な仕事ぶりで皆を感心させた。","hint":"受け身の「be impressed with[by] ～」(〜に感心する)が頻出。人が主語ならimpressed"},{"set":7,"word":"impression","pos":"名詞","meaning":"印象","example":"A neat appearance can make a good impression during a job interview.","exampleJa":"きちんとした身だしなみは、就職面接で好印象を与えることがある。","hint":"first impression(第一印象)、make a good impression(好印象を与える)は面接の定番"},{"set":7,"word":"impressive","pos":"形容詞","meaning":"印象的な、見事な","example":"The sales team delivered an impressive performance in the final quarter.","exampleJa":"営業チームは、最終四半期に見事な業績を上げた。","hint":"impress(感心させる)の形容詞形。物や成果が主語で「見事な」。人が主語ならimpressed"},{"set":7,"word":"improve","pos":"動詞","meaning":"改善する","example":"We hope to improve efficiency by introducing a new scheduling system.","exampleJa":"私たちは、新しいスケジュール管理システムの導入で効率を高めたいと考えている。","hint":"improve efficiency(効率を上げる)、improve service(サービスを向上させる)など、職場の目標でよく使う"},{"set":7,"word":"improvement","pos":"名詞","meaning":"改善","example":"Customers have noticed a clear improvement in our delivery speed this year.","exampleJa":"顧客は、今年になって当社の配送速度が明らかに改善したことに気づいている。","hint":"improve(改善する)の名詞形。home improvementは住宅の改修やDIYの意味"},{"set":7,"word":"include","pos":"動詞","meaning":"含む","example":"The monthly fee includes internet access and use of the meeting rooms.","exampleJa":"月額料金には、インターネット接続と会議室の利用が含まれている。","hint":"「Tax is included.」のように含まれる場合に使う。including ～は前置詞的に「〜を含めて」"},{"set":7,"word":"income","pos":"名詞","meaning":"収入","example":"Her annual income increased after she was promoted to senior engineer.","exampleJa":"上級エンジニアに昇進してから、彼女の年収は増えた。","hint":"in(入る)+come(来る)なので、入ってくるお金。annual income(年収)、income tax(所得税)"},{"set":7,"word":"inconvenience","pos":"名詞","meaning":"不便、迷惑","example":"We apologize for any inconvenience caused by the temporary closure of the entrance.","exampleJa":"入口の一時閉鎖によりご迷惑をおかけしましたことを、お詫び申し上げます。","hint":"お詫び文の「We apologize for any inconvenience.」で覚える。convenient(便利な)の否定の感覚"},{"set":7,"word":"indeed","pos":"副詞","meaning":"実に、本当に","example":"It was indeed a pleasure to work with such a talented team.","exampleJa":"これほど才能あるチームと働けたことは、本当に喜びでした。","hint":"文末や強調で使う。「Thank you very much indeed.」(本当にありがとう)の形で覚える"},{"set":7,"word":"independent","pos":"形容詞","meaning":"独立した","example":"The company hired an independent contractor to redesign its website.","exampleJa":"その会社は、ウェブサイトの再設計のため、個人事業の請負業者を雇った。","hint":"independent contractor(個人事業の請負人)。be independent of ～の形で前置詞ofを使う"},{"set":7,"word":"individual","pos":"名詞","meaning":"個人","example":"Each individual must complete the safety training before using the equipment.","exampleJa":"各個人は、機器を使用する前に安全研修を修了しなければならない。","hint":"グループや会社ではなく「一人ひとり」。individual needsは「個々のニーズ」の意味"},{"set":7,"word":"industry","pos":"名詞","meaning":"業界、産業","example":"She has worked in the travel industry for more than ten years.","exampleJa":"彼女は10年以上、旅行業界で働いている。","hint":"the hotel industry(ホテル業界)のように業界全体を指す。工場の「工業」だけではない"},{"set":7,"word":"inform","pos":"動詞","meaning":"知らせる","example":"Please inform the front desk of any changes to your travel plans.","exampleJa":"ご旅行の予定に変更があった場合は、フロントまでお知らせください。","hint":"inform A of B(AにBを知らせる)の型で出る。informationとのつながりも意識する"},{"set":7,"word":"initial","pos":"形容詞","meaning":"最初の","example":"The initial cost of the project was lower than we had expected.","exampleJa":"そのプロジェクトの初期費用は、私たちの予想より低かった。","hint":"initial cost(初期費用)。名前の頭文字を意味するinitialsは複数形で使う点も覚える"},{"set":7,"word":"initiative","pos":"名詞","meaning":"取り組み、主導権","example":"The mayor launched a new initiative to reduce traffic in the city center.","exampleJa":"市長は、市の中心部の交通量を減らすための新たな取り組みを開始した。","hint":"a new initiative(新しい取り組み)と、take the initiative(率先して動く)の両方で出る"},{"set":7,"word":"injury","pos":"名詞","meaning":"けが","example":"The worker suffered a minor injury when a box fell from the shelf.","exampleJa":"棚から箱が落ちて、作業員は軽いけがを負った。","hint":"職場の安全掲示でよく見る語。minor injury(軽傷)、serious injury(重傷)。動詞はinjure"},{"set":7,"word":"input","pos":"名詞","meaning":"意見、入力","example":"We would appreciate your input on the draft before the final meeting.","exampleJa":"最終会議の前に、草案についてご意見をいただけるとありがたいです。","hint":"パソコンへの入力が基本。「We appreciate your input.」のように会議で「意見」の意味にもなる"},{"set":7,"word":"inquire","pos":"動詞","meaning":"問い合わせる","example":"Several applicants called to inquire about the available positions in our office.","exampleJa":"何人かの応募者が、当社で募集中の職について問い合わせるため電話をかけてきた。","hint":"inquire about ～(〜について問い合わせる)。名詞のinquiryは問い合わせ。enquireとも綴る"},{"set":7,"word":"installation","pos":"名詞","meaning":"設置、取り付け","example":"The installation of the new security cameras will be completed on Wednesday.","exampleJa":"新しい防犯カメラの設置は、水曜日に完了する予定だ。","hint":"install(設置する)の名詞形。エアコンやソフトの「free installation(無料取り付け)」で覚える"},{"set":7,"word":"instead","pos":"副詞","meaning":"代わりに","example":"The conference room is booked, so let's meet in the lounge instead.","exampleJa":"会議室は予約済みなので、代わりにラウンジで会いましょう。","hint":"「Let's meet on Friday instead.」のように代案を出す場面。instead of ～と区別する"},{"set":7,"word":"institute","pos":"名詞","meaning":"研究所、協会","example":"A research institute in Tokyo published the results of the survey yesterday.","exampleJa":"東京の研究所が、昨日その調査の結果を発表した。","hint":"research institute(研究所)のように機関名で見かける。名詞は「研究所・協会」の意味"},{"set":7,"word":"instruction","pos":"名詞","meaning":"指示、使用説明","example":"Please read the installation instructions carefully before assembling the desk.","exampleJa":"机を組み立てる前に、取り付けの説明書をよくお読みください。","hint":"follow the instructions(指示に従う)。取扱説明書の意味では複数形instructionsが多い"},{"set":7,"word":"instructor","pos":"名詞","meaning":"講師","example":"The driving instructor explained the safety rules to the new students.","exampleJa":"運転教習の講師は、新しい受講生に安全規則を説明した。","hint":"スポーツジムやスクールの先生の肩書き。a yoga instructorのように使う。-orは「人」を表す語尾"},{"set":8,"word":"instrument","pos":"名詞","meaning":"器具、楽器","example":"The technician carefully sterilized each surgical instrument before the procedure began.","exampleJa":"技師は処置が始まる前に、各手術器具を丁寧に滅菌した。","hint":"医療現場のメスや鉗子、オーケストラの楽器。どちらも「目的を果たす道具」と覚える"},{"set":8,"word":"intention","pos":"名詞","meaning":"意図","example":"We have no intention of raising prices during the holiday season.","exampleJa":"私たちは年末年始の期間中に価格を引き上げるつもりはありません。","hint":"intend(〜するつもり)の名詞形。have no intention of ～ing「〜する気はない」の形で頻出"},{"set":8,"word":"interest","pos":"名詞","meaning":"興味、利子","example":"The bank offers a low interest rate on small business loans.","exampleJa":"その銀行は中小企業向け融資に低い金利を提示している。","hint":"「関心」と「利子」の二役。ローン契約書で interest rate を見る場面を思い浮かべる"},{"set":8,"word":"interested","pos":"形容詞","meaning":"興味がある","example":"Interested candidates should submit their résumés to the personnel office by Friday.","exampleJa":"ご興味のある応募者は、金曜日までに履歴書を人事部へ提出してください。","hint":"求人広告の定番。Interested candidates should apply…で「関心のある応募者」"},{"set":8,"word":"internal","pos":"形容詞","meaning":"内部の","example":"This internal report should not be shared with anyone outside the company.","exampleJa":"この社内報告書は社外の誰とも共有してはいけません。","hint":"in(内)のイメージ。社内限りの internal memo を連想。反対は external"},{"set":8,"word":"international","pos":"形容詞","meaning":"国際的な","example":"Our company has opened an international sales office in Singapore.","exampleJa":"当社はシンガポールに海外営業所を開設した。","hint":"inter(間)+national(国の)＝国と国の間。空港の「国際線ターミナル」を連想"},{"set":8,"word":"interview","pos":"名詞","meaning":"面接","example":"Ms. Lee has a job interview with the marketing director tomorrow morning.","exampleJa":"リーさんは明日の朝、マーケティング部長との採用面接がある。","hint":"inter(互いに)+view(見る)＝面と向かって見合う場。job interview で面接"},{"set":8,"word":"introduce","pos":"動詞","meaning":"紹介する、導入する","example":"The company plans to introduce a new line of electric bicycles next spring.","exampleJa":"同社は来春、電動自転車の新シリーズを発売する予定だ。","hint":"人を紹介する場面と、新商品・新制度を導入する場面の二つをセットで覚える"},{"set":8,"word":"introduction","pos":"名詞","meaning":"紹介、導入","example":"The introduction of the new software has greatly reduced our processing time.","exampleJa":"新しいソフトウェアの導入により、処理時間が大幅に短縮された。","hint":"introduce の名詞。講演の冒頭の「紹介」や新システムの「導入」で使う"},{"set":8,"word":"invest","pos":"動詞","meaning":"投資する","example":"The firm decided to invest heavily in renewable energy technology this year.","exampleJa":"その会社は今年、再生可能エネルギー技術に多額の投資をすることを決めた。","hint":"invest in ～ の形で覚える。設備や株にお金をつぎ込むイメージ"},{"set":8,"word":"investor","pos":"名詞","meaning":"投資家","example":"The CEO presented the quarterly results to a room full of investors.","exampleJa":"CEOは会場いっぱいの投資家に四半期の業績を発表した。","hint":"invest に「人」を表す -or がついた形。決算説明会に集まる人たちを想像"},{"set":8,"word":"invitation","pos":"名詞","meaning":"招待(状)","example":"Thank you for the invitation to your annual company banquet next month.","exampleJa":"来月の貴社の年次懇親会にご招待いただき、ありがとうございます。","hint":"invite の名詞。結婚式やパーティーの「招待状」を思い浮かべる。accept / decline と相性がよい"},{"set":8,"word":"invite","pos":"動詞","meaning":"招待する","example":"The committee will invite proposals from local contractors until the end of June.","exampleJa":"委員会は6月末まで、地元の施工業者からの提案を募集する。","hint":"人を招く以外に、invite applications「応募を募る」のように意見や応募を求める使い方もある"},{"set":8,"word":"involve","pos":"動詞","meaning":"含む、関わらせる","example":"The project will involve several departments working closely together over six months.","exampleJa":"そのプロジェクトには、複数の部署が6か月にわたり緊密に協力することが必要となる。","hint":"be involved in ～ で「〜に関わっている」。渦に巻き込まれるイメージで覚える"},{"set":8,"word":"item","pos":"名詞","meaning":"品目、項目","example":"The next item on the agenda is the proposed budget for the new office.","exampleJa":"議題の次の項目は、新オフィスの予算案です。","hint":"議題リストの一行、買い物かごの一点など、リストの「1個ずつ」を指す"},{"set":8,"word":"journal","pos":"名詞","meaning":"専門誌、日誌","example":"Her research on supply chains was published in a leading business journal.","exampleJa":"サプライチェーンに関する彼女の研究は、主要なビジネス専門誌に掲載された。","hint":"学会の専門誌や航海日誌など、定期的・継続的に記録する出版物や日誌の感覚"},{"set":8,"word":"knowledgeable","pos":"形容詞","meaning":"知識豊富な","example":"Our knowledgeable staff can answer any questions about the warranty terms.","exampleJa":"知識豊富なスタッフが、保証条件に関するどんなご質問にもお答えします。","hint":"knowledge に -able。店で何を聞いても答えてくれる店員を思い浮かべる"},{"set":8,"word":"label","pos":"名詞","meaning":"ラベル","example":"Please attach the shipping label to the box before the courier arrives.","exampleJa":"配送業者が到着する前に、箱に配送ラベルを貼り付けてください。","hint":"荷物に貼る shipping label や食品の成分表示ラベル。貼り付ける札のイメージ"},{"set":8,"word":"labor","pos":"名詞","meaning":"労働、労働力","example":"Rising labor costs have forced the factory to review its production schedule.","exampleJa":"人件費の上昇により、工場は生産計画の見直しを迫られた。","hint":"labor costs「人件費」の形でよく出る。働き手や労働力というお金に直結する話題"},{"set":8,"word":"lack","pos":"名詞","meaning":"不足","example":"A lack of funding caused the team to postpone the research project.","exampleJa":"資金不足のため、チームはその調査プロジェクトを延期した。","hint":"a lack of ～ で「〜の不足」。不足の原因を説明する文で多用される"},{"set":8,"word":"landscape","pos":"名詞","meaning":"景観、造園","example":"The hotel hired a designer to improve the landscape around its main entrance.","exampleJa":"そのホテルは正面玄関周辺の景観を整えるため、デザイナーを雇った。","hint":"land(土地)+scape(景色)という見た目の組み合わせ。公園や庭の景観・造園の話で出る"},{"set":8,"word":"lane","pos":"名詞","meaning":"車線、小道","example":"One lane of the bridge will be closed for repairs next week.","exampleJa":"来週、修理のため橋の1車線が閉鎖される。","hint":"高速道路の「車線」。lane closure(車線規制)の道路情報を連想"},{"set":8,"word":"laptop","pos":"名詞","meaning":"ノートパソコン","example":"All employees must bring a laptop to tomorrow's software training session.","exampleJa":"社員は全員、明日のソフトウェア研修にノートパソコンを持参しなければならない。","hint":"lap(ひざ)の上(top)で使うパソコン。会議やリモート出張の持ち物リストに登場"},{"set":8,"word":"latest","pos":"形容詞","meaning":"最新の","example":"Customers lined up outside the store to buy the latest smartphone model.","exampleJa":"客たちは最新のスマートフォンを買うために店の外に列を作った。","hint":"late の最上級で「一番遅い→一番新しい」。the latest model/news のセットで覚える"},{"set":8,"word":"layout","pos":"名詞","meaning":"配置、レイアウト","example":"We changed the layout of the showroom to make it easier to browse.","exampleJa":"私たちは見て回りやすくするため、ショールームの配置を変更した。","hint":"lay(置く)+out で「並べ置いた配置」。オフィスや売り場の模様替え話で出る"},{"set":8,"word":"lead","pos":"動詞","meaning":"導く、率いる","example":"Mr. Tanaka will lead the new sales team starting next month.","exampleJa":"田中さんは来月から新しい営業チームを率いる。","hint":"先頭で引っ張る動詞。lead a team は「率いる」、lead to ～ は「〜につながる」"},{"set":8,"word":"leader","pos":"名詞","meaning":"指導者","example":"As a market leader, the firm sets the standard for customer service.","exampleJa":"市場のリーダーとして、その会社は顧客サービスの基準を打ち立てている。","hint":"lead(導く)+-er で導く人。market leader「業界首位企業」の使い方も押さえる"},{"set":8,"word":"leadership","pos":"名詞","meaning":"指導力","example":"She was promoted to director because of her outstanding leadership during the merger.","exampleJa":"合併の間の彼女の卓越したリーダーシップが評価され、彼女は取締役に昇進した。","hint":"leader に性質を表す -ship。昇進や研修の話で leadership skills とセットで出る"},{"set":8,"word":"leading","pos":"形容詞","meaning":"一流の、主要な","example":"Hartman Industries is a leading supplier of medical equipment in Asia.","exampleJa":"ハートマン・インダストリーズは、アジアにおける医療機器の大手供給会社である。","hint":"「先頭を行く」→「一流の・主要な」。a leading company は広告文の定番"},{"set":8,"word":"leak","pos":"名詞","meaning":"漏れ","example":"A maintenance worker found a small water leak in the basement ceiling.","exampleJa":"保守作業員が地下室の天井に小さな水漏れを見つけた。","hint":"配管からの水漏れやガス漏れの現場を思い浮かべる。情報漏洩にも使える"},{"set":8,"word":"leave","pos":"名詞","meaning":"休暇","example":"Employees may take unpaid leave for up to three months with approval.","exampleJa":"社員は承認を得れば、最長3か月間の無給休暇を取ることができる。","hint":"名詞では「休暇」。sick leave、maternity leave のように種類を前に付ける"},{"set":8,"word":"lecture","pos":"名詞","meaning":"講義","example":"The professor will give a lecture on international trade next Tuesday.","exampleJa":"教授は来週の火曜日に国際貿易についての講義を行う。","hint":"大学や研修会場で、先生が前で話し続ける「講義」。give a lecture が定番"},{"set":8,"word":"length","pos":"名詞","meaning":"長さ","example":"Please state the length of your contract in the first paragraph.","exampleJa":"最初の段落に契約期間を明記してください。","hint":"long の名詞形で、形が似ている。契約期間や文書の長さにも使う"},{"set":8,"word":"level","pos":"名詞","meaning":"水準、階","example":"We are committed to maintaining a high level of customer satisfaction.","exampleJa":"私たちは高い水準の顧客満足度を維持することに力を入れている。","hint":"水平な段が原義。entry-level「初級の」や level of service「サービス水準」で使う"},{"set":8,"word":"license","pos":"名詞","meaning":"免許","example":"You must hold a valid license to operate this type of machinery.","exampleJa":"この種の機械を操作するには、有効な免許を持っている必要がある。","hint":"運転免許証や営業許可証。「許可をもらった証明書」と考える"},{"set":8,"word":"likely","pos":"形容詞","meaning":"ありそうな","example":"Sales are likely to increase once the new advertising campaign begins.","exampleJa":"新しい広告キャンペーンが始まれば、売上は伸びる見込みだ。","hint":"like(似ている)と音が近い連想で「いかにもそうなりそう」。be likely to ～ の形で頻出"},{"set":8,"word":"limit","pos":"名詞","meaning":"制限","example":"There is a strict time limit for submitting expense reports each month.","exampleJa":"経費報告書の毎月の提出には厳しい期限がある。","hint":"速度制限の標識のように「越えてはいけない線」。time limit / speed limit で覚える"},{"set":8,"word":"limited","pos":"形容詞","meaning":"限られた","example":"Seating is limited, so please register early for the seminar.","exampleJa":"席数に限りがございますので、セミナーのお申し込みはお早めに。","hint":"limit された状態。limited seating(席数に限り)や期間限定のチラシ文句"},{"set":8,"word":"load","pos":"動詞","meaning":"積む","example":"Workers began to load the truck with boxes right after lunch.","exampleJa":"作業員たちは昼食直後に、トラックへ箱の積み込みを始めた。","hint":"倉庫のloading dock でトラックに荷物を積む場面。反対語は unload"},{"set":8,"word":"loan","pos":"名詞","meaning":"貸付、融資","example":"The owner applied for a bank loan to open a second restaurant.","exampleJa":"オーナーは2軒目のレストランを開くため、銀行融資を申し込んだ。","hint":"銀行の窓口で借りる/貸す「融資」。apply for a loan と動詞 apply とセットで覚える"},{"set":8,"word":"local","pos":"形容詞","meaning":"地元の","example":"The festival is organized in cooperation with local businesses and residents.","exampleJa":"そのお祭りは地元の企業や住民の協力を得て運営されている。","hint":"「その土地の」。local time(現地時間)や local residents(地元住民)で使う"},{"set":8,"word":"locate","pos":"動詞","meaning":"位置する、見つける","example":"Our headquarters is located on the tenth floor of the Grand Tower.","exampleJa":"当社の本社はグランドタワーの10階にあります。","hint":"be located in/on ～ で「〜にある」。所在地案内の定番。「探し当てる」の意味もある"},{"set":8,"word":"location","pos":"名詞","meaning":"場所、店舗","example":"The restaurant moved to a more convenient location near the train station.","exampleJa":"そのレストランは、駅近くのより便利な場所に移転した。","hint":"locate の名詞。出店場所や支店そのものを指す。convenient location の組み合わせで覚える"},{"set":8,"word":"luxury","pos":"名詞","meaning":"贅沢(品)","example":"The resort offers luxury accommodations with a private beach and spa.","exampleJa":"そのリゾートは、専用ビーチとスパを備えた豪華な宿泊施設を提供している。","hint":"高級ホテルや高級ブランド品の世界。形容詞的に luxury hotel の形でもよく使う"},{"set":8,"word":"machine","pos":"名詞","meaning":"機械","example":"The copy machine on the third floor is out of paper again.","exampleJa":"3階のコピー機がまた紙切れになっている。","hint":"vending machine や copy machine など、身近な機械の名前にくっつく語"},{"set":8,"word":"machinery","pos":"名詞","meaning":"機械類","example":"The plant has invested in new machinery to speed up production.","exampleJa":"その工場は生産を早めるため、新しい機械設備に投資した。","hint":"machine の集まりを表す不可算名詞。a を付けず、heavy machinery の形で覚える"},{"set":8,"word":"magazine","pos":"名詞","meaning":"雑誌","example":"Our latest product was featured in a popular business magazine.","exampleJa":"当社の最新製品が、人気のビジネス雑誌で特集された。","hint":"雑誌の定期購読 subscription を連想。広告掲載や取材の話によく出る"},{"set":8,"word":"maintain","pos":"動詞","meaning":"維持する、整備する","example":"Regular inspections help us maintain the quality of our products.","exampleJa":"定期的な検査は、私たちが製品の品質を維持するのに役立っている。","hint":"機械を整備して状態を保つ、品質を保つ、など「現状を保つ」感覚。名詞は maintenance"},{"set":8,"word":"major","pos":"形容詞","meaning":"主要な、大きな","example":"A major client has asked us to deliver the order a week earlier.","exampleJa":"主要顧客の一社が、注文品を1週間早く納品するよう求めてきた。","hint":"野球のメジャーリーグを連想。「大きい・主要な」。反対は minor"},{"set":8,"word":"majority","pos":"名詞","meaning":"大多数","example":"The majority of staff members voted in favor of the new schedule.","exampleJa":"スタッフの大多数が新しいスケジュールに賛成票を投じた。","hint":"major の名詞。the majority of ～ で「〜の大多数」。投票や調査結果の文で出る"},{"set":8,"word":"manage","pos":"動詞","meaning":"管理する、何とか〜する","example":"She managed to finish the report before the deadline despite the delays.","exampleJa":"遅れがあったにもかかわらず、彼女は期限前に何とか報告書を仕上げた。","hint":"「管理する」と、manage to ～「なんとか〜する」の二つ。後者は苦労の末の成功"},{"set":8,"word":"management","pos":"名詞","meaning":"経営(陣)、管理","example":"Senior management announced a plan to open two new branches next year.","exampleJa":"上級経営陣は、来年2つの新支店を開設する計画を発表した。","hint":"「経営陣」の意味と、time management のような「管理」の意味を区別する"},{"set":8,"word":"manual","pos":"名詞","meaning":"説明書","example":"Please read the user manual carefully before installing the printer.","exampleJa":"プリンターを設置する前に、取扱説明書をよくお読みください。","hint":"家電や機械に付属する取扱説明書。user manual のセットで覚える。形容詞「手動の」もある"},{"set":8,"word":"manufacture","pos":"動詞","meaning":"製造する","example":"The company manufactures automobile parts for several major carmakers.","exampleJa":"その会社は、複数の大手自動車メーカー向けに自動車部品を製造している。","hint":"工場で大規模に作る。manufacturer(製造業者)も一緒に覚える"},{"set":8,"word":"manufacturing","pos":"名詞","meaning":"製造(業)","example":"The manufacturing industry has added thousands of jobs in the region this year.","exampleJa":"製造業は今年、その地域で何千もの雇用を生み出した。","hint":"工場での「製造(業)」。manufacturing plant や manufacturing industry の形で見る"},{"set":8,"word":"market","pos":"名詞","meaning":"市場","example":"The firm hopes to enter the European market by the end of next year.","exampleJa":"その会社は来年末までにヨーロッパ市場へ参入したいと考えている。","hint":"商品が売買される「市場」。enter the market(市場に参入)や market share で覚える"},{"set":8,"word":"marketing","pos":"名詞","meaning":"マーケティング","example":"The marketing team is preparing a new campaign for the summer launch.","exampleJa":"マーケティングチームは、夏の発売に向けた新しいキャンペーンを準備している。","hint":"market に -ing で、売れる仕組みづくりの活動。marketing team や campaign と一緒に出る"},{"set":8,"word":"material","pos":"名詞","meaning":"材料、資料","example":"Please distribute the training materials to all participants before the session.","exampleJa":"研修が始まる前に、すべての参加者へ研修資料を配布してください。","hint":"建築や製造の「材料」と、研修用の「資料」の二つ。複数形 materials でよく使う"},{"set":8,"word":"matter","pos":"名詞","meaning":"問題、事柄","example":"The legal department is handling this matter with great care.","exampleJa":"法務部がこの件を細心の注意を払って扱っている。","hint":"「重要である」という動詞用法もあるが、名詞では「事柄・問題」。a matter of time の形で覚える"},{"set":8,"word":"maximum","pos":"形容詞","meaning":"最大の","example":"The maximum capacity of the conference room is thirty people.","exampleJa":"その会議室の最大収容人数は30人だ。","hint":"max と省略されるのと同じ。「最大の」。capacity(定員)などの上限の話で使う"},{"set":8,"word":"measure","pos":"名詞","meaning":"対策、寸法","example":"The factory introduced new safety measures after the minor accident.","exampleJa":"工場は小さな事故の後、新しい安全対策を導入した。","hint":"名詞で「対策」。safety measures のように複数形で使うことが多い。動詞「測る」とも同じ語"},{"set":8,"word":"mechanic","pos":"名詞","meaning":"整備士","example":"A mechanic inspected the delivery van and replaced the worn brakes.","exampleJa":"整備士は配送用バンを点検し、すり減ったブレーキを交換した。","hint":"自動車修理工場で車を直す人。machine と似た綴りで機械に強い人と覚える"},{"set":8,"word":"media","pos":"名詞","meaning":"報道機関、メディア","example":"The merger received extensive coverage in the national media this week.","exampleJa":"その合併は、今週、全国の報道機関で大きく取り上げられた。","hint":"新聞・テレビ・SNSなど情報を伝える手段全体。social media や media coverage で覚える"},{"set":8,"word":"medical","pos":"形容詞","meaning":"医療の","example":"All new employees are required to undergo a medical checkup in their first month.","exampleJa":"新入社員は全員、入社1か月以内に健康診断を受けなければならない。","hint":"medicine(薬・医学)に形が近い。medical checkup や medical records と結びつける"},{"set":8,"word":"membership","pos":"名詞","meaning":"会員資格","example":"Your gym membership will expire at the end of this month unless renewed.","exampleJa":"更新しない限り、あなたのジム会員資格は今月末で失効します。","hint":"会員になる資格。ジムや協会の membership fee(会費)や renew を連想"},{"set":8,"word":"method","pos":"名詞","meaning":"方法","example":"Customers can choose their preferred payment method at the checkout page.","exampleJa":"お客様は、決済ページでご希望の支払い方法をお選びいただけます。","hint":"やり方・手順。payment method(支払い方法)がレジ前での定番の場面"},{"set":8,"word":"minimum","pos":"形容詞","meaning":"最小の、最低限の","example":"The store requires a minimum purchase of fifty dollars for free delivery.","exampleJa":"その店では、送料無料にするには最低50ドルの購入が必要だ。","hint":"min と略される。minimum order(最低注文数)や minimum wage で、下限の話"},{"set":8,"word":"mission","pos":"名詞","meaning":"使命","example":"Our mission is to provide affordable healthcare to every community.","exampleJa":"私たちの使命は、すべての地域社会に手頃な価格の医療を提供することです。","hint":"会社のホームページにある mission statement。「果たすべき使命」を一文で示したもの"},{"set":8,"word":"moderate","pos":"形容詞","meaning":"適度な","example":"The café serves excellent meals at moderate prices near the station.","exampleJa":"そのカフェは駅の近くで、手頃な価格で素晴らしい料理を出している。","hint":"高くも低くもない「ほどほど」。moderate prices はお手頃価格の宣伝文句"},{"set":8,"word":"motivate","pos":"動詞","meaning":"やる気にさせる","example":"Offering performance bonuses is one way to motivate employees to work harder.","exampleJa":"業績賞与の支給は、社員がより熱心に働く意欲を引き出す一つの方法だ。","hint":"motivation(やる気)の動詞形。上司が部下の気持ちを盛り上げる場面を思い浮かべる"},{"set":8,"word":"moving","pos":"名詞","meaning":"引っ越し","example":"A moving company will transport all the office furniture on Saturday.","exampleJa":"土曜日に、引っ越し業者がオフィスの家具をすべて運び出す。","hint":"move+ing で、オフィスや家の「引っ越し」。moving company は引っ越し業者"},{"set":8,"word":"nearby","pos":"形容詞","meaning":"近くの","example":"Several nearby restaurants offer special lunch menus for office workers.","exampleJa":"近くのいくつかのレストランが、会社員向けの特別ランチメニューを提供している。","hint":"near と by が合体した「すぐ近く」。ホテルの案内文で a nearby restaurant の形"},{"set":8,"word":"necessary","pos":"形容詞","meaning":"必要な","example":"Please bring all necessary documents to the interview next Monday.","exampleJa":"来週月曜日の面接には、必要な書類をすべてご持参ください。","hint":"なくてはならない。if necessary(必要であれば)は文末に付ける便利な定型句"},{"set":8,"word":"neighborhood","pos":"名詞","meaning":"近所、地域","example":"The new gym is popular with people living in the neighborhood.","exampleJa":"その新しいジムは、近隣に住む人々に人気がある。","hint":"neighbor(隣人)が住む範囲。a quiet neighborhood と不動産広告を連想"},{"set":8,"word":"net","pos":"形容詞","meaning":"正味の","example":"The company reported a net profit of two million dollars last year.","exampleJa":"その会社は昨年、200万ドルの純利益を計上したと報告した。","hint":"差し引き後の「正味」。net profit は経費を引いた純利益で、反対は gross"},{"set":8,"word":"network","pos":"名詞","meaning":"網、人脈","example":"The IT team is upgrading the office network over the weekend.","exampleJa":"IT部門は週末にかけて、オフィスのネットワークをアップグレードしている。","hint":"net(網)+work。コンピューターの回線だけでなく、人脈づくりの意味でも使う"},{"set":8,"word":"newsletter","pos":"名詞","meaning":"会報、ニュースレター","example":"Subscribe to our monthly newsletter to receive news about upcoming events.","exampleJa":"今後のイベント情報を受け取るには、月刊ニュースレターをご購読ください。","hint":"会社やクラブから定期的に届く会報メール。subscribe や sign up と結びつく"},{"set":8,"word":"note","pos":"名詞","meaning":"メモ、注意","example":"Please note that the office will be closed on Monday for the holiday.","exampleJa":"祝日のため、月曜日は事務所が休みになりますのでご注意ください。","hint":"手元のメモ。Please note that ～ はお知らせ文でよく使う「ご注意ください」"},{"set":8,"word":"notice","pos":"名詞","meaning":"通知、掲示","example":"The parking lot will remain closed until further notice because of construction.","exampleJa":"工事のため、駐車場は追って通知があるまで閉鎖されたままとなる。","hint":"掲示や通知。until further notice(追って通知があるまで)の決まり文句で覚える"},{"set":8,"word":"notification","pos":"名詞","meaning":"通知","example":"You will receive an email notification as soon as your order ships.","exampleJa":"ご注文品が発送され次第、メールで通知が届きます。","hint":"アプリやメールが知らせてくれる通知。notify の名詞形で、email notification の形"},{"set":8,"word":"nutrition","pos":"名詞","meaning":"栄養","example":"The cafeteria posts nutrition information next to every item on its menu.","exampleJa":"社員食堂は、メニューのすべての品目の横に栄養情報を掲示している。","hint":"食品パッケージの栄養表示や健康的な食事の話。nutritious との関連で覚える"},{"set":8,"word":"occur","pos":"動詞","meaning":"起こる","example":"The system error occurred just after the software update was installed.","exampleJa":"システムエラーは、ソフトウェアの更新がインストールされた直後に発生した。","hint":"予想外のトラブルや現象が「起こる」。happen よりも硬い語で、エラーや事故の報告に出る"},{"set":8,"word":"offer","pos":"名詞","meaning":"申し出、提供","example":"She accepted the job offer after discussing the salary with the manager.","exampleJa":"彼女は部長と給与について話し合った後、採用の申し出を受け入れた。","hint":"相手に差し出すもの。job offer(採用の申し出)や special offer(特別価格)の二つで覚える"},{"set":8,"word":"official","pos":"名詞","meaning":"役員、職員","example":"A city official explained the new recycling rules at the public meeting.","exampleJa":"市の職員が公開会議で、新しいリサイクルの規則を説明した。","hint":"名詞で「公的な立場の人」。government official や city official のように使う"},{"set":8,"word":"opening","pos":"名詞","meaning":"開店、欠員","example":"There is a job opening for a sales assistant at our Chicago branch.","exampleJa":"当社のシカゴ支店で、営業アシスタントの欠員募集があります。","hint":"お店の「開店」と、求人の「空きポスト」の二つ。job opening は求人広告の定番"},{"set":8,"word":"operation","pos":"名詞","meaning":"運営、操業","example":"The new plant has been in operation since the beginning of March.","exampleJa":"新工場は3月初めから操業している。","hint":"事業の運営・稼働。複数形 business operations や in operation(稼働中)で使う"},{"set":8,"word":"opportunity","pos":"名詞","meaning":"機会","example":"This internship offers a great opportunity to learn about international trade.","exampleJa":"このインターンシップは、国際貿易について学ぶ絶好の機会を提供する。","hint":"チャンス。a business opportunity や opportunity to ～ の形で、求人・案内文によく出る"},{"set":8,"word":"option","pos":"名詞","meaning":"選択肢","example":"Customers have several payment options, including credit cards and bank transfers.","exampleJa":"お客様には、クレジットカードや銀行振込を含む複数の支払い方法がある。","hint":"opt(選ぶ)に近い。payment options のように選べる複数の候補を示す"},{"set":8,"word":"organization","pos":"名詞","meaning":"組織","example":"She volunteers for a nonprofit organization that supports local students.","exampleJa":"彼女は地元の学生を支援する非営利団体でボランティアをしている。","hint":"会社・団体・NPOなどの「組織」。nonprofit organization が頻出パターン"},{"set":8,"word":"organize","pos":"動詞","meaning":"企画する、整理する","example":"Mr. Brown will organize the annual conference at the downtown hotel.","exampleJa":"ブラウンさんが、市内中心部のホテルで年次会議を企画する。","hint":"イベントを「企画・運営する」と、書類を「整理する」の二つの場面で使う"},{"set":8,"word":"original","pos":"形容詞","meaning":"元の、独創的な","example":"Please present the original receipt when you return the item.","exampleJa":"商品を返品する際は、元のレシートをご提示ください。","hint":"origin(起源)に -al。「元の」receipt と「独創的な」design の二つの意味をセットで"},{"set":8,"word":"outdoor","pos":"形容詞","meaning":"屋外の","example":"The café offers outdoor seating during the warm summer months.","exampleJa":"そのカフェは、暖かい夏の間、屋外席を提供している。","hint":"out+door で「ドアの外」。反対は indoor。outdoor seating はカフェのテラス席"},{"set":8,"word":"outline","pos":"名詞","meaning":"概要","example":"Could you send me a brief outline of the proposal by noon?","exampleJa":"正午までに、提案書の簡単な概要を送っていただけますか。","hint":"out+line で外枠の線。細部ではなく全体の骨組みを示す「概要」"},{"set":8,"word":"output","pos":"名詞","meaning":"生産高","example":"The factory increased its monthly output by ten percent after the upgrade.","exampleJa":"工場は設備更新後、月間の生産高を10パーセント増やした。","hint":"out+put で出てくるもの。工場の生産量やPCからの出力。反対は input"},{"set":8,"word":"overall","pos":"形容詞","meaning":"全体的な","example":"The overall cost of the renovation was lower than we had expected.","exampleJa":"改装の総費用は、私たちが予想していたよりも低かった。","hint":"over+all で全体を上から見渡す。overall cost(総費用)や overall satisfaction(総合満足度)"},{"set":8,"word":"overnight","pos":"副詞","meaning":"一晩で、翌日配達で","example":"We can ship your order overnight for an additional fee.","exampleJa":"追加料金をいただければ、ご注文品を翌日配達でお送りできます。","hint":"夜を越えて、つまり「一晩で・翌日に」。ship overnight は宅配の速達便の場面"},{"set":8,"word":"overseas","pos":"形容詞","meaning":"海外の","example":"The company plans to open overseas branches in Brazil and India.","exampleJa":"その会社は、ブラジルとインドに海外支店を開設する計画だ。","hint":"over(越えて)+seas(海)。overseas branch(海外支店)や出張の話で出る"},{"set":8,"word":"owner","pos":"名詞","meaning":"所有者","example":"The owner of the bakery plans to open a second location downtown.","exampleJa":"そのパン屋のオーナーは、中心街に2号店を出す計画だ。","hint":"own(所有する)+-er。store owner(店主)や business owner と連想"},{"set":8,"word":"package","pos":"名詞","meaning":"小包、一式","example":"The company offers a generous benefits package, including health insurance and paid vacation.","exampleJa":"その会社は、健康保険や有給休暇を含む手厚い福利厚生一式を提供している。","hint":"宅配の小包と、福利厚生などの「一式」の二つ。benefits package や package tour で覚える"},{"set":8,"word":"packaging","pos":"名詞","meaning":"包装","example":"The firm switched to eco-friendly packaging to reduce plastic waste.","exampleJa":"その会社はプラスチックごみを減らすため、環境に優しい包装に切り替えた。","hint":"商品の箱や袋などの包装全体。eco-friendly packaging は環境配慮の宣伝文句"},{"set":9,"word":"parcel","pos":"名詞","meaning":"小包","example":"The parcel containing the sample products arrived at our office this morning.","exampleJa":"サンプル製品が入った小包が、今朝私たちのオフィスに届きました。","hint":"宅配の「パーセル」で届く小さな荷物。package より小ぶりな郵送物のイメージ"},{"set":9,"word":"partner","pos":"名詞","meaning":"共同経営者、提携先","example":"Our business partner in Osaka will host the product demonstration next week.","exampleJa":"大阪の当社の提携先が、来週製品のデモンストレーションを主催します。","hint":"「パートナー」は事業を一緒に担う相手。a business partner の形で覚える"},{"set":9,"word":"partnership","pos":"名詞","meaning":"提携","example":"The two firms formed a partnership to develop environmentally friendly packaging.","exampleJa":"その2社は、環境に優しい包装材を開発するために提携しました。","hint":"partner に状態を表す -ship が付いた形(friendship と同じ型)。form a partnership with の形で"},{"set":9,"word":"passenger","pos":"名詞","meaning":"乗客","example":"All passengers must show their boarding passes before entering the departure gate.","exampleJa":"乗客は全員、出発ゲートに入る前に搭乗券を提示しなければなりません。","hint":"空港・駅のアナウンスで必ず聞く語。Attention, passengers で始まる場面を思い出す"},{"set":9,"word":"payment","pos":"名詞","meaning":"支払い","example":"Please send your payment by the end of the month to avoid a late fee.","exampleJa":"延滞料金を避けるため、月末までにお支払いをお送りください。","hint":"pay に名詞化の -ment。請求書の payment due date(支払期日)の場面で覚える"},{"set":9,"word":"performance","pos":"名詞","meaning":"業績、公演","example":"Her outstanding performance last quarter earned her a promotion to team leader.","exampleJa":"前四半期の彼女の優れた業績により、彼女はチームリーダーに昇進しました。","hint":"perform の名詞。社員なら「業績・成績」、劇場なら「公演」と場面で訳し分ける"},{"set":9,"word":"period","pos":"名詞","meaning":"期間","example":"Customers may return any item within the thirty-day return period for a full refund.","exampleJa":"お客様は30日間の返品期間内であれば、どの商品も全額返金で返品できます。","hint":"文末のピリオドは文の区切り、時間の区切りが「期間」。a trial period が定番"},{"set":9,"word":"permanent","pos":"形容詞","meaning":"恒久的な、正社員の","example":"After a six-month contract, he was offered a permanent position in the finance department.","exampleJa":"6か月の契約期間の後、彼は経理部の正社員の職を提示されました。","hint":"求人広告で temporary(臨時の)と対にして、permanent position=正社員の職と覚える"},{"set":9,"word":"permission","pos":"名詞","meaning":"許可","example":"You must get permission from your supervisor before using the company vehicle.","exampleJa":"社用車を使う前に、上司から許可を得なければなりません。","hint":"permit(許可する)の名詞形。get permission / without permission の形で"},{"set":9,"word":"personal","pos":"形容詞","meaning":"個人の","example":"Please keep your personal belongings in the lockers provided in the staff room.","exampleJa":"私物は、休憩室に備え付けのロッカーに入れておいてください。","hint":"person の形容詞形。personal information(個人情報)や私物の場面で使う"},{"set":9,"word":"phase","pos":"名詞","meaning":"段階","example":"The first phase of the construction project will be completed by the end of June.","exampleJa":"建設プロジェクトの第1段階は、6月末までに完了する予定です。","hint":"月の満ち欠けも phase。プロジェクトが進む「ひと区切りの段階」"},{"set":9,"word":"photocopy","pos":"名詞","meaning":"コピー","example":"Could you make a photocopy of this contract for each member of the committee?","exampleJa":"委員会の各メンバー用に、この契約書のコピーを取っていただけますか。","hint":"コピー機(photocopier)で取る写し。make a photocopy の形で覚える"},{"set":9,"word":"plant","pos":"名詞","meaning":"工場、植物","example":"The company plans to open a new manufacturing plant near the port next year.","exampleJa":"その会社は来年、港の近くに新しい製造工場を開設する計画です。","hint":"植物の plant と同じ綴り。TOEIC では manufacturing plant など「工場」の意味が頻出"},{"set":9,"word":"platform","pos":"名詞","meaning":"(駅の)ホーム、基盤","example":"The express train to Boston will depart from Platform 3 in ten minutes.","exampleJa":"ボストン行きの急行列車は、10分後に3番ホームから出発します。","hint":"駅の「プラットホーム」。転じて、オンラインサービスの土台(基盤)も指す"},{"set":9,"word":"pleased","pos":"形容詞","meaning":"喜んで","example":"We are pleased to announce that Ms. Tanaka will join our board of directors.","exampleJa":"田中さんが当社の取締役会に加わることをお知らせでき、うれしく思います。","hint":"please の過去分詞が形容詞化。be pleased to announce は発表文の決まり文句"},{"set":9,"word":"position","pos":"名詞","meaning":"職、位置","example":"I would like to apply for the sales manager position advertised on your website.","exampleJa":"御社のウェブサイトに掲載されている営業部長の職に応募したいと考えております。","hint":"組織の中で置かれた場所＝「職、ポスト」。apply for the position は求人の定番"},{"set":9,"word":"post","pos":"動詞","meaning":"掲示する、投稿する","example":"Please post the updated schedule on the bulletin board in the break room.","exampleJa":"更新されたスケジュールを休憩室の掲示板に掲示してください。","hint":"掲示板に貼る→ネットに投稿する。post a notice / post a job opening"},{"set":9,"word":"potential","pos":"形容詞","meaning":"潜在的な、見込みのある","example":"The sales team contacted several potential customers after the trade show.","exampleJa":"営業チームは、展示会の後に数社の見込み客に連絡を取りました。","hint":"「まだ表に出ていない可能性を持つ」というイメージ。potential customers=見込み客"},{"set":9,"word":"practice","pos":"名詞","meaning":"慣行、練習","example":"Sending a thank-you note after an interview is a common practice in this industry.","exampleJa":"面接の後にお礼状を送るのは、この業界ではよくある慣行です。","hint":"スポーツの「練習」だけでなく、会社で繰り返される「慣行・やり方」。business practices"},{"set":9,"word":"predict","pos":"動詞","meaning":"予測する","example":"Analysts predict that smartphone sales will rise sharply during the holiday season.","exampleJa":"アナリストは、休暇シーズンにスマートフォンの売上が大きく伸びると予測しています。","hint":"pre(前もって)+dict(言う)。dictionary や dictate と同じ「言う」系の仲間"},{"set":9,"word":"prefer","pos":"動詞","meaning":"好む","example":"Most of our clients prefer receiving invoices by email to receiving paper copies.","exampleJa":"当社の顧客のほとんどは、紙の請求書よりメールでの請求書受け取りを好みます。","hint":"prefer A to B(BよりAを好む)。than ではなく to を使う点が試験の落とし穴"},{"set":9,"word":"preference","pos":"名詞","meaning":"好み","example":"Please indicate your meal preference on the registration form for the banquet.","exampleJa":"宴会の登録用紙に、お食事のご希望をご記入ください。","hint":"prefer の名詞形。アンケートの seating preference(座席のご希望)を思い浮かべる"},{"set":9,"word":"preparation","pos":"名詞","meaning":"準備","example":"The staff worked late in preparation for the arrival of the foreign delegation.","exampleJa":"スタッフは、海外からの代表団の到着に備えて遅くまで働きました。","hint":"prepare の名詞形。in preparation for ～(〜に備えて)のセットで覚える"},{"set":9,"word":"prepare","pos":"動詞","meaning":"準備する","example":"I need to prepare a summary of the budget for tomorrow's board meeting.","exampleJa":"明日の取締役会に向けて、予算の概要を準備する必要があります。","hint":"pre(前もって)+ 整える。会議資料を前日までに用意する場面を想像"},{"set":9,"word":"presentation","pos":"名詞","meaning":"発表","example":"Mr. Lee will give a presentation on the new marketing strategy this afternoon.","exampleJa":"リー氏は今日の午後、新しいマーケティング戦略について発表を行います。","hint":"present(示す)の名詞形。give a presentation=会議室でスライドを見せて発表する"},{"set":9,"word":"preserve","pos":"動詞","meaning":"保存する、保護する","example":"The city council voted to preserve the historic theater downtown.","exampleJa":"市議会は、中心街にある歴史的な劇場を保存することを票決しました。","hint":"ジャムの「プリザーブ」と同じ語。傷まないよう保つ→保存・保護する"},{"set":9,"word":"president","pos":"名詞","meaning":"社長、会長","example":"The company president thanked all employees for their hard work this year.","exampleJa":"社長は、今年の全従業員の尽力に感謝を述べました。","hint":"preside(議長を務める)と同系統の語。会社のトップ、vice president が副社長"},{"set":9,"word":"press","pos":"名詞","meaning":"報道機関","example":"The firm will hold a press conference to announce its merger with a rival.","exampleJa":"その会社は、競合他社との合併を発表するため記者会見を開きます。","hint":"印刷機を押す→報道機関の意味に。press release / press conference で覚える"},{"set":9,"word":"prevent","pos":"動詞","meaning":"防ぐ","example":"Regular maintenance helps prevent costly equipment failures on the production line.","exampleJa":"定期的な保守点検は、生産ラインでの高額な設備故障を防ぐのに役立ちます。","hint":"「事故を未然に防ぐ」場面で。prevent A from -ing の形も頻出"},{"set":9,"word":"pricing","pos":"名詞","meaning":"価格設定","example":"Our competitive pricing has helped us attract many new customers this year.","exampleJa":"競争力のある価格設定のおかげで、今年は多くの新規顧客を獲得できました。","hint":"price に -ing が付いて「値段をつける行為」。competitive pricing(競争力のある価格設定)"},{"set":9,"word":"priority","pos":"名詞","meaning":"優先(事項)","example":"Customer satisfaction remains our top priority as we expand into new markets.","exampleJa":"新しい市場へ拡大する中でも、顧客満足は引き続き当社の最優先事項です。","hint":"prior(先の)と同じ仲間。top priority=最優先事項、priority seating=優先席"},{"set":9,"word":"private","pos":"形容詞","meaning":"個人的な、私立の","example":"The two executives held a private meeting to discuss the confidential merger plan.","exampleJa":"2人の役員は、機密の合併計画について話し合うため非公開の会議を開きました。","hint":"public(公の)の反対語。private sector(民間部門)、private meeting で覚える"},{"set":9,"word":"prize","pos":"名詞","meaning":"賞品","example":"The winner of the sales contest will receive a trip to Hawaii as a prize.","exampleJa":"販売コンテストの優勝者には、賞品としてハワイ旅行が贈られます。","hint":"コンテストの「賞品」。win first prize の場面。price(価格)と綴りを混同しない"},{"set":9,"word":"process","pos":"名詞","meaning":"過程、手順","example":"The hiring process usually takes about three weeks from application to job offer.","exampleJa":"採用プロセスは通常、応募から内定まで約3週間かかります。","hint":"物事が前へ進む一連の流れ。the hiring process(採用プロセス)で覚える"},{"set":9,"word":"produce","pos":"動詞","meaning":"生産する、(名)農産物","example":"The factory can produce over ten thousand units of this model every week.","exampleJa":"その工場は、このモデルを毎週1万台以上生産することができます。","hint":"動詞は「プロデュース」、名詞(アクセントが前)は農産物。fresh produce は青果売り場"},{"set":9,"word":"product","pos":"名詞","meaning":"製品","example":"The company will launch its latest product at the trade show in March.","exampleJa":"その会社は、3月の展示会で最新製品を発売する予定です。","hint":"produce(作る)で生まれた物＝製品。a new product / product line"},{"set":9,"word":"production","pos":"名詞","meaning":"生産、制作","example":"Production at the plant was temporarily suspended due to a shortage of parts.","exampleJa":"部品不足のため、工場での生産は一時的に停止されました。","hint":"produce の名詞形。mass production(大量生産)や production costs で使う"},{"set":9,"word":"profession","pos":"名詞","meaning":"職業","example":"Teaching is a demanding profession that requires patience and strong communication skills.","exampleJa":"教職は、忍耐力と高いコミュニケーション能力を必要とする大変な職業です。","hint":"医師や弁護士のように専門知識を要する職業。the medical profession の形"},{"set":9,"word":"professional","pos":"形容詞","meaning":"専門的な、プロの","example":"The company offers professional development courses to help employees improve their skills.","exampleJa":"その会社は、従業員の技能向上を支援するため、能力開発講座を提供しています。","hint":"profession の形容詞形。「プロの」だけでなく professional development(能力開発)も頻出"},{"set":9,"word":"profile","pos":"名詞","meaning":"経歴、紹介","example":"Each speaker's profile is posted on the conference website along with a photo.","exampleJa":"各講演者の経歴は、写真と共に会議のウェブサイトに掲載されています。","hint":"横顔の輪郭が語源の連想から、人や会社の「紹介・経歴」。SNSのプロフィールを思い出す"},{"set":9,"word":"profit","pos":"名詞","meaning":"利益","example":"The retailer reported a ten percent increase in profit for the third quarter.","exampleJa":"その小売業者は、第3四半期の利益が10パーセント増加したと報告しました。","hint":"決算の場面で。net profit(純利益)、make a profit(利益を出す)"},{"set":9,"word":"program","pos":"名詞","meaning":"計画、番組","example":"All new employees must complete the training program during their first month.","exampleJa":"新入社員は全員、最初の1か月間に研修プログラムを修了しなければなりません。","hint":"コンピュータのプログラムだけでなく、研修などの「計画・企画」。training program"},{"set":9,"word":"progress","pos":"名詞","meaning":"進捗","example":"Please be quiet because an important interview is currently in progress.","exampleJa":"重要な面接が現在進行中ですので、お静かにお願いします。","hint":"前進するイメージ。in progress(進行中)の表現は看板や掲示でよく見る"},{"set":9,"word":"project","pos":"名詞","meaning":"計画、事業","example":"The project manager updated the team on the schedule for the renovation project.","exampleJa":"プロジェクト責任者は、改装プロジェクトのスケジュールについてチームに最新情報を伝えました。","hint":"仕事で前に進める計画。project manager(プロジェクト責任者)で覚える"},{"set":9,"word":"promote","pos":"動詞","meaning":"昇進させる、販売促進する","example":"Ms. Garcia was promoted to regional director after three years with the company.","exampleJa":"ガルシアさんは、入社3年で地域統括責任者に昇進しました。","hint":"人なら「昇進させる」、商品なら「販売促進する」。目的語で意味が変わる"},{"set":9,"word":"proof","pos":"名詞","meaning":"証明","example":"Please bring proof of purchase if you wish to exchange or return an item.","exampleJa":"商品の交換または返品をご希望の場合は、購入証明をお持ちください。","hint":"prove の名詞形。レシートは proof of purchase(購入証明)"},{"set":9,"word":"proper","pos":"形容詞","meaning":"適切な","example":"Employees must follow the proper procedures when reporting a safety concern.","exampleJa":"従業員は、安全上の懸念を報告する際、適切な手順に従わなければなりません。","hint":"「きちんとした、ふさわしい」。proper attire(適切な服装)は規則文の定番"},{"set":9,"word":"propose","pos":"動詞","meaning":"提案する","example":"The committee proposed a new schedule to reduce waiting times for customers.","exampleJa":"委員会は、お客様の待ち時間を減らすための新しいスケジュールを提案しました。","hint":"会議で案を出す場面。「プロポーズ」は結婚の提案、ここは仕事の提案"},{"set":9,"word":"protect","pos":"動詞","meaning":"保護する","example":"We use advanced software to protect our customers' personal data from hackers.","exampleJa":"当社は、お客様の個人データをハッカーから守るため、高度なソフトウェアを使用しています。","hint":"個人情報や設備を危険から守る場面。protect A from B の形"},{"set":9,"word":"protective","pos":"形容詞","meaning":"保護用の","example":"Workers must wear protective gear whenever they enter the chemical storage area.","exampleJa":"作業員は、化学薬品の保管区域に入るときは常に防護具を着用しなければなりません。","hint":"protect の形容詞形。工事現場のヘルメットや手袋＝protective gear"},{"set":9,"word":"prove","pos":"動詞","meaning":"証明する、〜と判明する","example":"The new scheduling software proved to be very useful for our busy sales team.","exampleJa":"新しいスケジュール管理ソフトは、多忙な営業チームにとって非常に役立つとわかりました。","hint":"prove to be ～ は「結果的に〜だとわかる」。証拠で示すだけでなく、後から判明するニュアンス"},{"set":9,"word":"provide","pos":"動詞","meaning":"提供する","example":"The hotel provides all guests with free breakfast and wireless Internet access.","exampleJa":"そのホテルは、すべての宿泊客に無料の朝食と無線インターネット接続を提供しています。","hint":"provide A with B / provide B for A の2つの型を押さえる"},{"set":9,"word":"provider","pos":"名詞","meaning":"提供者、業者","example":"Our Internet service provider promised to restore the connection by this afternoon.","exampleJa":"当社のインターネット接続業者は、今日の午後までに接続を復旧させると約束しました。","hint":"provide する人・会社。service provider(サービス提供業者)で覚える"},{"set":9,"word":"public","pos":"形容詞","meaning":"公共の","example":"The new museum will be open to the public starting next Saturday.","exampleJa":"新しい博物館は、来週の土曜日から一般公開されます。","hint":"private の反対。public transportation(公共交通機関)、open to the public(一般公開)"},{"set":9,"word":"publication","pos":"名詞","meaning":"出版(物)","example":"This monthly publication features interviews with leading figures in the travel industry.","exampleJa":"この月刊誌は、旅行業界の第一人者へのインタビューを特集しています。","hint":"publish の名詞形。雑誌など定期刊行物は a monthly publication"},{"set":9,"word":"publish","pos":"動詞","meaning":"出版する、公表する","example":"The research institute will publish its annual report on its website next week.","exampleJa":"その研究所は、来週ウェブサイトで年次報告書を公表する予定です。","hint":"public(公)と響きが近い。本や報告書を世の中に出す、と連想すると覚えやすい(語源の断定ではなく連想)"},{"set":9,"word":"publisher","pos":"名詞","meaning":"出版社","example":"The publisher plans to release the author's new novel in early spring.","exampleJa":"出版社は、その著者の新作小説を早春に刊行する予定です。","hint":"publish する人・会社＝出版社。著者(author)と編集者の間に立つ存在"},{"set":9,"word":"quality","pos":"名詞","meaning":"品質","example":"Our inspectors check the quality of every product before it leaves the factory.","exampleJa":"当社の検査員は、工場から出荷される前にすべての製品の品質を確認します。","hint":"quantity(量)と対。quality control(品質管理)は工場の定番語"},{"set":9,"word":"quantity","pos":"名詞","meaning":"数量","example":"We offer a discount to customers who order large quantities of office supplies.","exampleJa":"事務用品を大量に注文されるお客様には、割引をご提供しています。","hint":"quality(質)と綴りが似ているので注意。quantity discount=大量購入割引"},{"set":9,"word":"raise","pos":"動詞","meaning":"上げる、集める","example":"The charity organized a dinner event to raise funds for the new children's hospital.","exampleJa":"その慈善団体は、新しい小児病院のための資金を集めるため、夕食会を開催しました。","hint":"他動詞で「上げる」。raise prices(値上げ)、raise funds(資金集め)。rise(自動詞)と区別"},{"set":9,"word":"range","pos":"名詞","meaning":"範囲、品揃え","example":"The store offers a wide range of furniture at reasonable prices.","exampleJa":"その店は、手頃な価格で幅広い品揃えの家具を提供しています。","hint":"端から端までの幅。a wide range of ～(幅広い〜)は広告で頻出"},{"set":9,"word":"rate","pos":"名詞","meaning":"料金、割合","example":"The hotel offers a special rate for guests who book more than a month ahead.","exampleJa":"そのホテルは、1か月以上前に予約した宿泊客に特別料金を提供しています。","hint":"ホテルの room rate、為替の exchange rate、interest rate など「率・料金」"},{"set":9,"word":"reach","pos":"動詞","meaning":"届く、連絡がつく","example":"You can reach me at my office extension if you have any questions.","exampleJa":"ご質問があれば、私のオフィスの内線番号にご連絡ください。","hint":"手が届く→電話やメールで連絡がつく。You can reach me at ～ は連絡先を伝える定型"},{"set":9,"word":"reasonably","pos":"副詞","meaning":"手頃に、かなり","example":"The restaurant serves delicious meals that are reasonably priced for office workers.","exampleJa":"そのレストランは、会社員にとって手頃な価格のおいしい食事を提供しています。","hint":"reasonable(手頃な)の副詞形。reasonably priced=値段が手頃な、は広告の定番"},{"set":9,"word":"receive","pos":"動詞","meaning":"受け取る","example":"We received your order on Monday and will ship it within two business days.","exampleJa":"月曜日にご注文を受け取りました。2営業日以内に発送いたします。","hint":"注文書や支払いが届く場面。receive an order / receive payment。ie と ei の綴りに注意"},{"set":9,"word":"reception","pos":"名詞","meaning":"受付、歓迎会","example":"Guests should check in at the reception desk located in the main lobby.","exampleJa":"お客様は、メインロビーにある受付でチェックインしてください。","hint":"ホテルや会社の「受付」。また、歓迎会・祝賀会の意味もある(welcome reception)"},{"set":9,"word":"recognize","pos":"動詞","meaning":"認識する、表彰する","example":"The manager was recognized for her excellent service at the annual awards ceremony.","exampleJa":"その部長は、年次表彰式で優れたサービスを称えられました。","hint":"「見て分かる」から転じて、功績を認めて表彰する意味に。be recognized for ～"},{"set":9,"word":"reduce","pos":"動詞","meaning":"減らす","example":"The new system will reduce our energy costs by nearly twenty percent.","exampleJa":"新しいシステムにより、当社のエネルギー費用は20パーセント近く減る見込みです。","hint":"コスト削減の場面で。reduce costs / reduced prices(値下げ価格)"},{"set":9,"word":"reduction","pos":"名詞","meaning":"削減","example":"The reduction in shipping costs allowed us to lower prices for our customers.","exampleJa":"配送費の削減により、お客様向けの価格を下げることができました。","hint":"reduce の名詞形。price reduction / cost reduction の組み合わせで覚える"},{"set":9,"word":"reflect","pos":"動詞","meaning":"反映する","example":"The revised menu reflects customer feedback collected over the past six months.","exampleJa":"改訂されたメニューには、過去6か月間に集められたお客様の意見が反映されています。","hint":"鏡が光を返すように、状況を「映し出す」。reflect customer needs=顧客ニーズを反映"},{"set":9,"word":"region","pos":"名詞","meaning":"地域","example":"Sales in the western region increased significantly after we opened two new stores.","exampleJa":"新店舗を2つ開いてから、西部地域の売上が大幅に増加しました。","hint":"国より小さい、ひとまとまりの「地域」。the northern region のように使う"},{"set":9,"word":"regional","pos":"形容詞","meaning":"地域の","example":"The regional manager visits each branch office once a month to review operations.","exampleJa":"地域担当部長は、業務を確認するため、月に一度各支店を訪れます。","hint":"region の形容詞形。regional manager(地域担当部長)は支社組織の定番"},{"set":9,"word":"register","pos":"動詞","meaning":"登録する","example":"Please register for the workshop online by the end of this week.","exampleJa":"今週末までに、オンラインでワークショップにご登録ください。","hint":"名簿に名前を載せる場面。register for ～(〜に登録する)は前置詞 for が目印"},{"set":9,"word":"regret","pos":"動詞","meaning":"残念に思う","example":"We regret to inform you that your flight has been canceled due to bad weather.","exampleJa":"誠に残念ですが、悪天候のためお客様の便は欠航となりました。","hint":"We regret to inform you that ～ は不採用や欠航の通知文によく出る丁寧な定型文"},{"set":9,"word":"reject","pos":"動詞","meaning":"却下する","example":"The board rejected the proposal because it would cost too much to implement.","exampleJa":"実施に費用がかかりすぎるため、取締役会はその提案を却下しました。","hint":"提案や申請を突き返す場面。reject the proposal(提案を却下する)"},{"set":9,"word":"release","pos":"動詞","meaning":"発売する、公開する","example":"The company will release its new tablet computer in stores next month.","exampleJa":"その会社は、来月、新しいタブレット型パソコンを店頭で発売します。","hint":"人を解放する「リリース」と同じ。新製品を世に放つ→発売・公開。press release もセット"},{"set":9,"word":"relevant","pos":"形容詞","meaning":"関連のある","example":"Applicants should have at least two years of relevant experience in accounting.","exampleJa":"応募者は、経理で少なくとも2年間の関連する経験が必要です。","hint":"irrelevant(無関係な)と対。求人の relevant experience(関連する経験)で覚える"},{"set":9,"word":"remain","pos":"動詞","meaning":"残る、〜のままである","example":"The main entrance will remain open during the renovation of the lobby.","exampleJa":"ロビーの改装中も、正面玄関は開いたままとなります。","hint":"店や窓口が「開いたままである」場面。remain open / remaining balance(残高)"},{"set":9,"word":"remark","pos":"名詞","meaning":"発言","example":"The director made a few opening remarks before introducing the guest speaker.","exampleJa":"部長は、ゲスト講演者を紹介する前に、簡単な開会のあいさつを述べました。","hint":"会議やスピーチでの「ひと言」。opening remarks(開会のあいさつ)で覚える"},{"set":9,"word":"remote","pos":"形容詞","meaning":"遠隔の","example":"Many employees now prefer remote work because it saves them commuting time.","exampleJa":"通勤時間が節約できるため、今では多くの従業員がリモートワークを好んでいます。","hint":"remote control(リモコン)は「遠くから操作」。remote work=離れた場所での勤務"},{"set":9,"word":"removal","pos":"名詞","meaning":"除去","example":"The building's maintenance staff will arrange the removal of the old furniture tomorrow.","exampleJa":"ビルの管理スタッフが、明日、古い家具の撤去を手配します。","hint":"remove の名詞形。snow removal(除雪)、trash removal(ごみ収集)などサービス名で出る"},{"set":9,"word":"remove","pos":"動詞","meaning":"取り除く","example":"Please remove all personal items from your desk before the office renovation begins.","exampleJa":"オフィスの改装が始まる前に、机の上の私物をすべて片付けてください。","hint":"re(離して)+move の形。古いカーペットや不要な物を取り去る場面"},{"set":9,"word":"rent","pos":"名詞","meaning":"家賃","example":"The office rent will increase by five percent starting in January.","exampleJa":"事務所の家賃は、1月から5パーセント上がります。","hint":"毎月払う「家賃」。pay rent。動詞なら rent a car(車を借りる)"},{"set":9,"word":"rental","pos":"名詞","meaning":"賃貸、レンタル","example":"Please read the rental agreement carefully before signing it.","exampleJa":"署名する前に、賃貸契約書をよくお読みください。","hint":"「レンタカー」のレンタル。car rental / rental agreement(賃貸契約)"},{"set":9,"word":"reporter","pos":"名詞","meaning":"記者","example":"A newspaper reporter interviewed the CEO about the company's expansion plans.","exampleJa":"新聞記者が、会社の拡大計画についてCEOにインタビューしました。","hint":"report する人＝記者。新聞社や TV 局の取材の場面を思い浮かべる"},{"set":9,"word":"represent","pos":"動詞","meaning":"代表する","example":"Ms. Park will represent our company at the international trade conference in Seoul.","exampleJa":"パクさんが、ソウルでの国際貿易会議で当社を代表します。","hint":"会社の代わりに出席する営業担当を想像。represent A at B の形"},{"set":9,"word":"reputation","pos":"名詞","meaning":"評判","example":"The restaurant has built an excellent reputation for its fresh local ingredients.","exampleJa":"そのレストランは、新鮮な地元食材で非常に高い評判を築いてきました。","hint":"人や会社についての世間の「評判」。an excellent reputation / reputation for ～"},{"set":9,"word":"request","pos":"名詞","meaning":"依頼","example":"Additional copies of the brochure are available upon request at the front desk.","exampleJa":"パンフレットの追加分は、フロントでご要望に応じてお渡しします。","hint":"upon request(ご要望に応じて)は案内文の定番。make a request で「依頼する」"},{"set":9,"word":"require","pos":"動詞","meaning":"必要とする","example":"All visitors are required to wear a name badge while in the building.","exampleJa":"来訪者は全員、建物内では名札を着用することが求められています。","hint":"規則で「必要とする」。be required to ～(〜する必要がある)の受け身形が頻出"},{"set":9,"word":"research","pos":"名詞","meaning":"研究、調査","example":"The marketing team conducted market research before launching the new product line.","exampleJa":"マーケティングチームは、新しい製品ラインを発売する前に市場調査を行いました。","hint":"何度も探して調べる→調査。market research(市場調査)は企業の定番"},{"set":9,"word":"reserve","pos":"動詞","meaning":"予約する、取っておく","example":"I would like to reserve a conference room for Thursday afternoon.","exampleJa":"木曜日の午後に会議室を予約したいのですが。","hint":"レストランの席などを取っておく場面。reserve a table。All rights reserved は版権表示"},{"set":9,"word":"resident","pos":"名詞","meaning":"住民","example":"Local residents were invited to a public meeting about the new shopping center.","exampleJa":"地元住民は、新しいショッピングセンターに関する公開会議に招待されました。","hint":"reside(住む)の仲間。local residents(地元住民)は自治体のお知らせによく出る"},{"set":9,"word":"resource","pos":"名詞","meaning":"資源、人材","example":"Please contact the human resources department if you have questions about your benefits.","exampleJa":"福利厚生についてご質問があれば、人事部にご連絡ください。","hint":"企業が使える資産。human resources は「人的資源」から人事部のこと"},{"set":9,"word":"respond","pos":"動詞","meaning":"返答する、対応する","example":"Our customer service team always responds to inquiries within twenty-four hours.","exampleJa":"当社のカスタマーサービスチームは、常に24時間以内に問い合わせに返答します。","hint":"問い合わせに「返事をする」。respond to ～ と to が必要(自動詞)な点に注意"},{"set":9,"word":"response","pos":"名詞","meaning":"返答、反応","example":"In response to your inquiry, I have attached our latest product catalog.","exampleJa":"お問い合わせにお応えして、最新の製品カタログを添付いたしました。","hint":"respond の名詞形。in response to ～(〜に応えて)はメール冒頭の定型"},{"set":9,"word":"responsible","pos":"形容詞","meaning":"責任がある、担当の","example":"Mr. Kim is responsible for training all new employees in the sales department.","exampleJa":"キム氏は、営業部の新入社員全員の研修を担当しています。","hint":"be responsible for ～ は「〜の担当だ、責任がある」。担当業務の説明で使う"},{"set":9,"word":"restore","pos":"動詞","meaning":"修復する","example":"Technicians worked through the night to restore power to the entire building.","exampleJa":"技術者たちは、ビル全体の電力を復旧させるため、夜通し作業しました。","hint":"壊れたものを元の状態に戻す。restore power(電力の復旧)、古い建物の修復"},{"set":9,"word":"resume","pos":"動詞","meaning":"再開する","example":"Normal train service will resume once the repairs on the track are finished.","exampleJa":"線路の修理が終わり次第、通常の列車運行が再開されます。","hint":"中断した後に「再び始める」。名詞の résumé(履歴書)とは別語で、動詞は「リズューム」"},{"set":9,"word":"retailer","pos":"名詞","meaning":"小売業者","example":"Several online retailers have lowered their prices in order to attract more shoppers.","exampleJa":"より多くの買い物客を引きつけるため、複数のオンライン小売業者が価格を下げました。","hint":"retail(小売)の人・会社。メーカー→卸売→retailer→消費者と流れを思い浮かべる"},{"set":9,"word":"review","pos":"名詞","meaning":"評価、見直し","example":"Each employee will receive a performance review from their manager in December.","exampleJa":"各従業員は、12月に上司から人事評価を受けます。","hint":"もう一度見直す。customer reviews(顧客の評価)と performance review(人事評価)が頻出"},{"set":10,"word":"reward","pos":"名詞","meaning":"報酬、特典","example":"Employees who exceed their targets will receive a generous reward at the end of the year.","exampleJa":"目標を上回った従業員は、年末に手厚い報酬を受け取ります。","hint":"頑張った社員に贈るボーナスや、買い物ポイントの特典をイメージ"},{"set":10,"word":"rise","pos":"名詞","meaning":"上昇","example":"The report shows a sharp rise in online sales during the holiday season.","exampleJa":"報告書は、休暇シーズン中にオンライン売上が急増したことを示しています。","hint":"グラフの線が右上がりになる場面。a rise in ～ の形で覚える"},{"set":10,"word":"risk","pos":"名詞","meaning":"危険(性)","example":"We must assess the risk before investing in a new overseas market.","exampleJa":"新しい海外市場に投資する前に、そのリスクを評価しなければなりません。","hint":"「リスク管理」でおなじみ。take a risk(危険を冒す)とセットで"},{"set":10,"word":"route","pos":"名詞","meaning":"経路、路線","example":"The driver chose a different route to avoid the construction on Main Street.","exampleJa":"運転手はメインストリートの工事を避けるため、別の経路を選びました。","hint":"地図アプリの経路検索。バス路線や配送ルートの「ルート」"},{"set":10,"word":"routine","pos":"名詞","meaning":"日課、決まった手順","example":"Checking the inventory every morning is part of the warehouse team's daily routine.","exampleJa":"毎朝在庫を確認することは、倉庫チームの日課の一部です。","hint":"毎朝のメールチェックのように、いつも決まってやる手順"},{"set":10,"word":"safety","pos":"名詞","meaning":"安全","example":"All visitors must follow the safety rules when entering the factory floor.","exampleJa":"来訪者は全員、工場の作業フロアに入る際に安全規則を守らなければなりません。","hint":"工事現場の「安全第一」の掲示。safe の名詞形"},{"set":10,"word":"salary","pos":"名詞","meaning":"給料","example":"The company offers a competitive salary and a full benefits package.","exampleJa":"その会社は、競争力のある給与と充実した福利厚生を提供しています。","hint":"毎月決まって振り込まれる給料。時給中心の賃金 wage との対比で覚える"},{"set":10,"word":"salesperson","pos":"名詞","meaning":"販売員","example":"The salesperson explained the features of the new laptop to the customer.","exampleJa":"販売員はお客様に新しいノートパソコンの特長を説明しました。","hint":"店頭や営業先でお客さんに商品を勧める人。salesman の性別を問わない言い方"},{"set":10,"word":"satisfaction","pos":"名詞","meaning":"満足","example":"Customer satisfaction improved significantly after we shortened the response time.","exampleJa":"対応時間を短縮してから、顧客満足度が大幅に向上しました。","hint":"アンケートの「顧客満足度」の項目でよく見る語"},{"set":10,"word":"satisfy","pos":"動詞","meaning":"満足させる","example":"We hope this new policy will satisfy both customers and employees.","exampleJa":"この新方針が、顧客と従業員の両方を満足させることを期待しています。","hint":"お客さんの要望を満たして「満足」させる。be satisfied with ～ も頻出"},{"set":10,"word":"schedule","pos":"名詞","meaning":"予定(表)","example":"The construction project is running two weeks behind schedule because of the bad weather.","exampleJa":"悪天候のため、建設プロジェクトは予定より2週間遅れています。","hint":"手帳の予定表。ahead of / behind schedule で進捗を表す"},{"set":10,"word":"scheduled","pos":"形容詞","meaning":"予定された","example":"The scheduled maintenance will begin at midnight and last about three hours.","exampleJa":"予定されている保守作業は深夜に始まり、約3時間続きます。","hint":"カレンダーに入っている会議や便に使う。be scheduled for/to の形が頻出"},{"set":10,"word":"section","pos":"名詞","meaning":"区分、部門","example":"Please read the safety section of the manual before operating the machine.","exampleJa":"機械を操作する前に、マニュアルの安全に関する項を読んでください。","hint":"新聞の経済面、会社の課など、全体を区切った一区画"},{"set":10,"word":"secure","pos":"動詞","meaning":"確保する","example":"Our sales team managed to secure a major contract with a European retailer.","exampleJa":"当社の営業チームは、ヨーロッパの小売業者との大型契約を獲得することに成功しました。","hint":"動詞は「しっかり確保する」。契約や資金を勝ち取る場面で使う"},{"set":10,"word":"security","pos":"名詞","meaning":"安全、警備","example":"Security at the main entrance has been strengthened after the recent incident.","exampleJa":"先日の事件を受けて、正面入口の警備が強化されました。","hint":"ビルの入館ゲートや警備員、情報の守りを思い浮かべる"},{"set":10,"word":"seek","pos":"動詞","meaning":"探し求める","example":"The firm is seeking an experienced accountant to join its finance department.","exampleJa":"その会社は、経理部に加わる経験豊富な会計士を募集しています。","hint":"求人広告の「We are seeking ～」。look for より硬い響き"},{"set":10,"word":"select","pos":"動詞","meaning":"選ぶ","example":"Please select your preferred delivery date from the options on the screen.","exampleJa":"画面上の選択肢から、ご希望の配達日をお選びください。","hint":"プルダウンメニューから選ぶ操作。choose よりやや改まった語"},{"set":10,"word":"selection","pos":"名詞","meaning":"品揃え、選択","example":"The store offers a wide selection of office furniture at reasonable prices.","exampleJa":"その店は、手頃な価格で幅広い品揃えのオフィス家具を扱っています。","hint":"店の棚にずらりと並ぶ品揃え。a wide selection of ～ で使う"},{"set":10,"word":"seminar","pos":"名詞","meaning":"セミナー","example":"Our department will hold a seminar on time management next Tuesday.","exampleJa":"私たちの部署は、来週火曜日にタイムマネジメントに関するセミナーを開催します。","hint":"会場で講師の話を聞く勉強会。workshop は実習寄りという違い"},{"set":10,"word":"senior","pos":"形容詞","meaning":"上級の","example":"A senior manager will review the proposal before it is sent to the client.","exampleJa":"提案書は顧客に送られる前に、上級管理職が確認します。","hint":"役職や経験が上の人に付く。junior との対比で覚える"},{"set":10,"word":"separate","pos":"形容詞","meaning":"別々の","example":"Each department keeps a separate budget for travel and training expenses.","exampleJa":"各部署は、出張費と研修費について別々の予算を管理しています。","hint":"形容詞は「別々の」。領収書を別々にしたい時の separate checks"},{"set":10,"word":"serve","pos":"動詞","meaning":"仕える、(料理を)出す","example":"The hotel restaurant serves a complimentary breakfast to all registered guests.","exampleJa":"ホテルのレストランは、宿泊客全員に無料の朝食を提供しています。","hint":"レストランでは料理を出し、窓口では客に応対する。「仕える」が原義"},{"set":10,"word":"service","pos":"名詞","meaning":"サービス、業務","example":"Our customer service team is available around the clock to answer your questions.","exampleJa":"当社のカスタマーサービスチームは、ご質問に答えるため24時間対応しています。","hint":"serve の名詞。customer service や service charge で頻出"},{"set":10,"word":"session","pos":"名詞","meaning":"会合、期間","example":"The afternoon session will focus on new tools for project management.","exampleJa":"午後のセッションでは、プロジェクト管理の新しいツールに焦点を当てます。","hint":"研修や質疑応答など、時間を区切って行う一回の会"},{"set":10,"word":"setting","pos":"名詞","meaning":"設定、環境","example":"You can change the privacy settings from the account menu at any time.","exampleJa":"プライバシー設定は、アカウントメニューからいつでも変更できます。","hint":"スマホの「設定」画面か、会議が行われる環境・雰囲気"},{"set":10,"word":"settle","pos":"動詞","meaning":"解決する、精算する","example":"The two companies agreed to settle the dispute without going to court.","exampleJa":"両社は、裁判にせずに紛争を解決することで合意しました。","hint":"もめ事を落ち着かせる、または代金をきっちり支払って片付ける"},{"set":10,"word":"share","pos":"名詞","meaning":"株、共有","example":"The company increased its share of the domestic smartphone market to thirty percent.","exampleJa":"その会社は、国内スマートフォン市場でのシェアを30パーセントに伸ばしました。","hint":"株式の「シェア」。market share(市場占有率)は決算発表で頻出"},{"set":10,"word":"shelf","pos":"名詞","meaning":"棚","example":"Please place the new products on the top shelf near the entrance.","exampleJa":"新商品は、入口近くの一番上の棚に並べてください。","hint":"店の棚や本棚。複数形は f が v に変わり shelves になる"},{"set":10,"word":"shift","pos":"名詞","meaning":"勤務時間帯、変化","example":"Employees on the night shift receive an additional allowance for working late hours.","exampleJa":"夜勤シフトの従業員には、遅い時間帯に働くための追加手当が支給されます。","hint":"アルバイトのシフト表。早番・遅番のように交代で働く時間帯"},{"set":10,"word":"shipping","pos":"名詞","meaning":"発送、配送","example":"Shipping is free for orders over fifty dollars placed on our website.","exampleJa":"当社ウェブサイトからの50ドルを超えるご注文は、配送料が無料です。","hint":"ネット通販の「送料無料(free shipping)」の表示で覚える"},{"set":10,"word":"signature","pos":"名詞","meaning":"署名","example":"The contract is not valid until it bears the signature of both parties.","exampleJa":"契約書は、双方の署名があるまで有効になりません。","hint":"契約書の末尾にサインする欄。sign の名詞形"},{"set":10,"word":"site","pos":"名詞","meaning":"用地、現場、サイト","example":"The safety inspector visited the construction site early this morning.","exampleJa":"安全検査官は今朝早く、建設現場を訪れました。","hint":"工事現場、ネットの web site、候補地など「場所」を指す"},{"set":10,"word":"situation","pos":"名詞","meaning":"状況","example":"The manager explained the current situation to the board of directors.","exampleJa":"部長は取締役会に現在の状況を説明しました。","hint":"トラブル時の「この状況では」という場面で使う。current situation が定番"},{"set":10,"word":"skill","pos":"名詞","meaning":"技能","example":"Strong communication skills are essential for anyone working in customer support.","exampleJa":"カスタマーサポートで働く人には、高いコミュニケーション能力が欠かせません。","hint":"履歴書のスキル欄。communication skills のように複数形でよく使う"},{"set":10,"word":"solution","pos":"名詞","meaning":"解決策","example":"Our engineers are working together to find a solution to the network problem.","exampleJa":"当社の技術者たちは、ネットワークの問題の解決策を見つけるために協力して取り組んでいます。","hint":"問題を solve した答え。IT企業の「ソリューション事業」の語"},{"set":10,"word":"source","pos":"名詞","meaning":"源、出所","example":"Tourism is the main source of income for many towns along the coast.","exampleJa":"観光は、沿岸の多くの町にとって主要な収入源です。","hint":"川の水源のように、情報や収入のもとになるところ。ニュースの情報源にも"},{"set":10,"word":"speaker","pos":"名詞","meaning":"講演者","example":"The keynote speaker will talk about the future of renewable energy.","exampleJa":"基調講演者は、再生可能エネルギーの将来について話します。","hint":"スピーカーは音の出る機器だけでなく、壇上で話す人も指す"},{"set":10,"word":"specialist","pos":"名詞","meaning":"専門家","example":"We hired a tax specialist to help us prepare the annual report.","exampleJa":"年次報告書の作成を手伝ってもらうため、税務の専門家を雇いました。","hint":"特定分野に詳しい人。IT specialist のように分野名と組む"},{"set":10,"word":"specialize","pos":"動詞","meaning":"専門にする","example":"Our law firm specializes in intellectual property and international trade.","exampleJa":"当法律事務所は、知的財産と国際取引を専門としています。","hint":"specialize in ～ の形で「〜を専門にする」。前置詞は in"},{"set":10,"word":"specific","pos":"形容詞","meaning":"具体的な、特定の","example":"Please give us specific examples of how the new system saved time.","exampleJa":"新しいシステムがどのように時間を節約したか、具体的な例を挙げてください。","hint":"「もっと具体的に」と言いたい時の語。general の反対"},{"set":10,"word":"staff","pos":"名詞","meaning":"職員","example":"All staff members are required to attend the safety briefing on Monday.","exampleJa":"職員は全員、月曜日の安全説明会に出席する必要があります。","hint":"職員全体を一括して指す。a staff member で一人を表す"},{"set":10,"word":"stage","pos":"名詞","meaning":"段階、舞台","example":"The new software is still in the early stage of development.","exampleJa":"その新しいソフトウェアは、まだ開発の初期段階にあります。","hint":"舞台だけでなく、プロジェクトの進行段階も表す。early stage が定番"},{"set":10,"word":"standard","pos":"名詞","meaning":"基準","example":"All of our products must meet strict quality standards before they are shipped.","exampleJa":"当社の製品はすべて、出荷前に厳格な品質基準を満たさなければなりません。","hint":"品質の「基準」。meet the standards(基準を満たす)の形で覚える"},{"set":10,"word":"statement","pos":"名詞","meaning":"明細書、声明","example":"Please check your bank statement for any charges you do not recognize.","exampleJa":"身に覚えのない請求がないか、銀行の取引明細書をご確認ください。","hint":"月末に届く銀行やカードの明細書。「声明」の意味でも使う"},{"set":10,"word":"station","pos":"名詞","meaning":"駅、持ち場","example":"Each workstation in the new office is equipped with two monitors.","exampleJa":"新しいオフィスの各作業スペースには、モニターが2台備え付けられています。","hint":"駅だけでなく、workstation や fire station のように持ち場・拠点も指す"},{"set":10,"word":"status","pos":"名詞","meaning":"状況、地位","example":"You can check the status of your order by logging in to your account.","exampleJa":"アカウントにログインすると、ご注文の状況を確認できます。","hint":"配送状況の確認画面の「ステータス」。進み具合や現在の立場"},{"set":10,"word":"stock","pos":"名詞","meaning":"在庫、株","example":"The blue model is currently out of stock, but it will arrive next week.","exampleJa":"青いモデルは現在在庫切れですが、来週入荷する予定です。","hint":"倉庫や店にある在庫。in stock / out of stock の対で覚える"},{"set":10,"word":"strategy","pos":"名詞","meaning":"戦略","example":"The marketing team presented a new strategy for reaching younger customers.","exampleJa":"マーケティングチームは、若い顧客層に訴求するための新しい戦略を発表しました。","hint":"経営会議で語られる大きな方針。細かな手順の tactics より大局的"},{"set":10,"word":"strength","pos":"名詞","meaning":"強み","example":"One of our greatest strengths is the loyalty of our long-term customers.","exampleJa":"当社の最大の強みの一つは、長年のお客様の忠誠心です。","hint":"面接で聞かれる「あなたの強みは?」。weakness の反対"},{"set":10,"word":"structure","pos":"名詞","meaning":"構造、建物","example":"The consultant suggested changing the structure of the sales department.","exampleJa":"コンサルタントは、営業部の組織構造を変更することを提案しました。","hint":"組織図や建物の骨組みなど、組み立てられた全体の形"},{"set":10,"word":"subject","pos":"名詞","meaning":"件名、主題","example":"Please write the order number in the subject line of your email.","exampleJa":"メールの件名欄に、注文番号を記入してください。","hint":"メールの件名欄(subject line)を思い浮かべる。subject to ～ は「〜の可能性あり」"},{"set":10,"word":"succeed","pos":"動詞","meaning":"成功する、後を継ぐ","example":"She worked hard to succeed in the competitive world of international finance.","exampleJa":"彼女は競争の激しい国際金融の世界で成功するために懸命に働きました。","hint":"succeed in ～ は成功する、succeed ～ は後任になる。後ろの前置詞の有無で区別"},{"set":10,"word":"successful","pos":"形容詞","meaning":"成功した","example":"The successful candidate will begin working at our Chicago office in March.","exampleJa":"採用された候補者は、3月にシカゴ事務所で勤務を開始します。","hint":"success に -ful が付いた形。successful candidate は採用通知の定番"},{"set":10,"word":"suggest","pos":"動詞","meaning":"提案する","example":"I suggest that we postpone the launch until all the tests are complete.","exampleJa":"すべてのテストが完了するまで、発売を延期することを提案します。","hint":"会議で案を出す時の動詞。suggest that 主語 (should) 原形 の形に注意"},{"set":10,"word":"suggestion","pos":"名詞","meaning":"提案","example":"Employees are encouraged to leave their suggestions in the box near the cafeteria.","exampleJa":"従業員は、カフェテリア近くの箱に提案を入れるよう奨励されています。","hint":"社内の「意見箱(suggestion box)」に入れる案"},{"set":10,"word":"suit","pos":"動詞","meaning":"合う","example":"We offer several plans designed to suit the needs of small businesses.","exampleJa":"当社は、小規模事業者のニーズに合うよう設計された複数のプランをご用意しています。","hint":"動詞は「〜に合う」。suit your needs で、希望にぴったり合うという宣伝文句"},{"set":10,"word":"suitable","pos":"形容詞","meaning":"適した","example":"This conference room is suitable for meetings of up to twenty people.","exampleJa":"この会議室は、最大20人までの会議に適しています。","hint":"suit(合う)+ able で「合わせられる」。suitable for ～ の形が頻出"},{"set":10,"word":"summary","pos":"名詞","meaning":"要約","example":"Please send me a brief summary of yesterday's meeting by this afternoon.","exampleJa":"昨日の会議の簡単な要約を、今日の午後までに送ってください。","hint":"長い報告書の冒頭に付く要点の短いまとめ。executive summary が定番"},{"set":10,"word":"supervise","pos":"動詞","meaning":"監督する","example":"She was asked to supervise the new interns during their first month.","exampleJa":"彼女は、新しいインターンの最初の1か月間を監督するよう依頼されました。","hint":"現場で部下の仕事を見守る上司。supervisor(監督者)とセットで"},{"set":10,"word":"supply","pos":"名詞","meaning":"供給、用品","example":"The office manager orders new supplies whenever the storage cabinet runs low.","exampleJa":"事務長は、収納棚の在庫が少なくなるたびに新しい用品を発注します。","hint":"名詞は供給や、複数形で事務用品(supplies)。demand との対比でも"},{"set":10,"word":"support","pos":"名詞","meaning":"支援","example":"Our technical support team is available by phone from nine to five.","exampleJa":"当社のテクニカルサポートチームは、9時から5時まで電話で対応しています。","hint":"困った時の「テクニカルサポート」窓口。助けや支援の名詞"},{"set":10,"word":"surface","pos":"名詞","meaning":"表面","example":"Wipe the surface of the desk with a clean, dry cloth.","exampleJa":"机の表面は、清潔で乾いた布で拭いてください。","hint":"机や床など、物の一番外側の面。清掃や塗装の説明文で出る"},{"set":10,"word":"surround","pos":"動詞","meaning":"囲む","example":"The hotel is surrounded by gardens and several popular restaurants.","exampleJa":"そのホテルは庭園と人気のレストランいくつかに囲まれています。","hint":"ぐるっと周りを取り巻く。the surrounding area(周辺地域)の形でよく出る"},{"set":10,"word":"switch","pos":"動詞","meaning":"切り替える","example":"Many customers decided to switch to the cheaper monthly plan.","exampleJa":"多くの顧客が、より安い月額プランに切り替えることを決めました。","hint":"スイッチを入れ替えるように、取引先やプランを乗り換える"},{"set":10,"word":"symptom","pos":"名詞","meaning":"症状","example":"Employees who have flu symptoms are advised to stay home and rest.","exampleJa":"インフルエンザの症状がある従業員は、自宅で休養するよう勧められています。","hint":"病院で医師に伝える「体の変化」。風邪やインフルエンザの症状"},{"set":10,"word":"system","pos":"名詞","meaning":"仕組み、制度","example":"The new accounting system will make it easier to track monthly expenses.","exampleJa":"新しい会計システムにより、毎月の経費をより簡単に管理できるようになります。","hint":"パソコンの OS や社内の仕組み全体。部品がつながって動くイメージ"},{"set":10,"word":"target","pos":"名詞","meaning":"目標、対象","example":"Our team has already reached its sales target for the third quarter.","exampleJa":"私たちのチームは、すでに第3四半期の売上目標を達成しました。","hint":"弓矢の的から、売上目標や販売対象の意味に広がった"},{"set":10,"word":"task","pos":"名詞","meaning":"作業、任務","example":"Updating the customer database is the first task on my list today.","exampleJa":"顧客データベースの更新が、今日の私のリストの最初の作業です。","hint":"ToDoリストに並ぶ一つひとつの作業。task force は特別対策チーム"},{"set":10,"word":"technical","pos":"形容詞","meaning":"技術的な","example":"A technical problem caused the website to go offline for several hours.","exampleJa":"技術的な問題により、ウェブサイトは数時間オフラインになりました。","hint":"technical difficulties(技術的な不具合)のアナウンスで頻出"},{"set":10,"word":"technician","pos":"名詞","meaning":"技術者","example":"A technician will visit your office tomorrow to repair the copy machine.","exampleJa":"明日、技術者がコピー機を修理するためにオフィスを訪問します。","hint":"機械や設備の修理・点検をする現場の人。-ian は「〜する人」"},{"set":10,"word":"technique","pos":"名詞","meaning":"技術、手法","example":"The workshop introduces simple techniques for managing a busy schedule.","exampleJa":"そのワークショップでは、忙しい予定を管理するための簡単な手法を紹介します。","hint":"職人技や営業のコツのような、具体的なやり方。発音は「テクニーク」"},{"set":10,"word":"technology","pos":"名詞","meaning":"技術","example":"The company invests heavily in new technology to improve production efficiency.","exampleJa":"その会社は、生産効率を高めるために新技術に多額の投資をしています。","hint":"IT 企業の紹介文に必ず出る「技術」。technical や technique と綴りを区別"},{"set":10,"word":"term","pos":"名詞","meaning":"条件、期間、用語","example":"Please read the terms of the agreement carefully before you sign.","exampleJa":"署名する前に、契約条件をよくお読みください。","hint":"契約の terms and conditions、学期や任期の「期間」、専門用語と複数の顔を持つ"},{"set":10,"word":"terminal","pos":"名詞","meaning":"ターミナル、端末","example":"Passengers should proceed to Terminal 2 to check in for the international flight.","exampleJa":"乗客は国際線のチェックインのため、第2ターミナルへお進みください。","hint":"電車やバスの終着駅、空港の旅客ターミナル。ターミナルケア同様「終点」のイメージ"},{"set":10,"word":"tourism","pos":"名詞","meaning":"観光業","example":"Tourism is one of the fastest-growing industries in the region.","exampleJa":"観光業は、その地域で最も急成長している産業の一つです。","hint":"ホテルや観光地を支える産業全体。tourist(観光客)との対比で"},{"set":10,"word":"trade","pos":"名詞","meaning":"貿易、取引","example":"Representatives from over fifty countries attended the international trade fair.","exampleJa":"50か国以上の代表者が、その国際見本市に出席しました。","hint":"国同士の貿易や、見本市(trade show)での商談を思い浮かべる"},{"set":10,"word":"traffic","pos":"名詞","meaning":"交通(量)","example":"Heavy traffic on the highway delayed the delivery by nearly an hour.","exampleJa":"高速道路の激しい渋滞のため、配達が1時間近く遅れました。","hint":"道路の渋滞(heavy traffic)や、ウェブサイトへのアクセス量にも使う"},{"set":10,"word":"trainee","pos":"名詞","meaning":"研修生","example":"Each trainee will be paired with an experienced mentor for the first month.","exampleJa":"研修生一人ひとりに、最初の1か月間は経験豊富な指導役が付きます。","hint":"-ee は「される側」。研修を受ける人で、教える側は trainer"},{"set":10,"word":"training","pos":"名詞","meaning":"研修","example":"New employees must complete a two-day training before they start working.","exampleJa":"新入社員は、業務を始める前に2日間の研修を修了しなければなりません。","hint":"新入社員が受ける研修。on-the-job training は実務をしながらの研修"},{"set":10,"word":"transport","pos":"動詞","meaning":"輸送する","example":"The company uses refrigerated trucks to transport fresh food across the country.","exampleJa":"その会社は、新鮮な食品を全国に輸送するために冷蔵トラックを使っています。","hint":"動詞はアクセントが後ろ(transPORT)、名詞は前(TRANSport)と覚える"},{"set":10,"word":"transportation","pos":"名詞","meaning":"交通機関、輸送","example":"The office is easily accessible by public transportation from the city center.","exampleJa":"そのオフィスは、市の中心部から公共交通機関で簡単に行けます。","hint":"電車・バスなどの交通機関。public transportation が定番で、米国式の語"},{"set":10,"word":"treat","pos":"動詞","meaning":"扱う、もてなす","example":"Our staff are trained to treat every customer with courtesy and respect.","exampleJa":"当社のスタッフは、すべてのお客様に礼儀と敬意をもって接するよう訓練されています。","hint":"客を「どう扱うか」と「ごちそうする」の二つの顔。treat A with respect の形も"},{"set":10,"word":"trial","pos":"名詞","meaning":"試用、試し","example":"New users can enjoy a thirty-day free trial of the premium service.","exampleJa":"新規ユーザーは、プレミアムサービスを30日間無料でお試しいただけます。","hint":"ソフトの「無料お試し期間(free trial)」で覚える。法廷の裁判の意味もある"},{"set":10,"word":"tutorial","pos":"名詞","meaning":"手引き、講習","example":"Watch the short tutorial to learn how to set up your new account.","exampleJa":"短い解説動画を見て、新しいアカウントの設定方法を学んでください。","hint":"ソフトの使い方を順に教える動画や手引き。tutor(個別指導者)の形容詞から"},{"set":10,"word":"typical","pos":"形容詞","meaning":"典型的な","example":"The typical response time for customer inquiries is within twenty-four hours.","exampleJa":"お客様からのお問い合わせへの一般的な対応時間は、24時間以内です。","hint":"a typical day(典型的な一日)のように、よくある普通の例を示す"},{"set":10,"word":"union","pos":"名詞","meaning":"組合","example":"The union and management reached an agreement on working hours last week.","exampleJa":"労働組合と経営陣は、先週、勤務時間について合意に達しました。","hint":"労働者が団結してつくる組織。labor union は労使交渉の記事に登場"},{"set":10,"word":"unique","pos":"形容詞","meaning":"独特な","example":"The designer created a unique logo that made the brand easy to recognize.","exampleJa":"デザイナーは、ブランドを認識しやすくする独特なロゴを作りました。","hint":"「ただ一つ」だけの特徴。very unique とは言わない点に注意"},{"set":10,"word":"update","pos":"動詞","meaning":"更新する","example":"Please update your contact information in the employee database by Friday.","exampleJa":"金曜日までに、従業員データベースの連絡先情報を更新してください。","hint":"スマホのアプリ更新通知。情報やデータを最新の状態にする動詞"},{"set":10,"word":"upgrade","pos":"動詞","meaning":"性能を上げる","example":"We plan to upgrade our computers to improve processing speed this summer.","exampleJa":"今年の夏、処理速度を向上させるためにコンピューターをアップグレードする予定です。","hint":"航空券の座席クラスを一段上げる、ソフトを高性能版にする"},{"set":10,"word":"usage","pos":"名詞","meaning":"使用(量)","example":"The report shows a steady decrease in energy usage since the new system was installed.","exampleJa":"報告書は、新システムの導入以来、エネルギー使用量が着実に減少していることを示しています。","hint":"電気や水道の検針票にある「使用量」。use の名詞形だが発音は「ユースィジ」"},{"set":10,"word":"valuable","pos":"形容詞","meaning":"貴重な","example":"The internship gave her valuable experience in the field of marketing.","exampleJa":"そのインターンシップは、彼女にマーケティング分野での貴重な経験を与えました。","hint":"価値(value)が高い。valuable experience(貴重な経験)や貴重品 valuables"},{"set":10,"word":"various","pos":"形容詞","meaning":"さまざまな","example":"The conference covered various topics, including finance and online security.","exampleJa":"その会議は、財務やオンラインセキュリティなど、さまざまな話題を扱いました。","hint":"「いろいろ」を表す形容詞。後ろは複数形で、various options のように使う"},{"set":10,"word":"vehicle","pos":"名詞","meaning":"車両","example":"Employees must register their vehicles to use the company parking lot.","exampleJa":"従業員は、会社の駐車場を使うために車両を登録しなければなりません。","hint":"車・トラック・バスなど乗り物の総称。語尾の h は発音しない(ヴィークル)"},{"set":10,"word":"volunteer","pos":"名詞","meaning":"ボランティア","example":"The charity is looking for volunteers to help organize the annual fundraising event.","exampleJa":"その慈善団体は、毎年恒例の資金集めイベントの運営を手伝うボランティアを探しています。","hint":"自ら進んで参加する人。名詞だけでなく「志願する」の動詞でも使う"},{"set":10,"word":"wage","pos":"名詞","meaning":"賃金","example":"The government plans to raise the minimum wage starting next April.","exampleJa":"政府は、来年4月から最低賃金を引き上げる計画です。","hint":"時給や日給で支払われる賃金。月給の salary との違いで整理"},{"set":10,"word":"wholesale","pos":"形容詞","meaning":"卸売りの","example":"The store buys its goods at wholesale prices directly from the manufacturer.","exampleJa":"その店は、メーカーから直接、卸売価格で商品を仕入れています。","hint":"メーカーから小売店へまとめて売る卸売り。retail(小売り)の反対"},{"set":10,"word":"withdraw","pos":"動詞","meaning":"引き出す、撤回する","example":"The company decided to withdraw its offer after the negotiations failed.","exampleJa":"交渉が決裂したため、その会社は申し出を撤回することを決めました。","hint":"ATM で預金を引き出す場面と、申し出を取り下げる場面の両方で使う"},{"set":10,"word":"workforce","pos":"名詞","meaning":"全従業員、労働力","example":"The factory has a workforce of nearly two thousand people.","exampleJa":"その工場には、2,000人近い従業員がいます。","hint":"会社や国で働く人の総数。リストラ記事の reduce the workforce で覚える"},{"set":10,"word":"workplace","pos":"名詞","meaning":"職場","example":"The company is committed to creating a safe and friendly workplace for everyone.","exampleJa":"その会社は、誰にとっても安全で親しみやすい職場づくりに取り組んでいます。","hint":"オフィスや工場など働く場所。workplace safety は定番の組み合わせ"},{"set":10,"word":"worth","pos":"形容詞","meaning":"価値がある","example":"The new museum is definitely worth visiting if you have free time during your trip.","exampleJa":"旅行中に自由時間があるなら、その新しい美術館は間違いなく訪れる価値があります。","hint":"形容詞なのに直後に名詞や ～ing が来る。It is worth ～ing の形で覚える"},{"set":11,"word":"absenteeism","pos":"名詞","meaning":"欠勤、無断欠勤","example":"The company introduced a new policy to reduce absenteeism among warehouse staff.","exampleJa":"会社は倉庫スタッフの欠勤を減らすため、新しい方針を導入した。","hint":"absent(欠席)の仲間。人事レポートで「欠勤率」を語る場面で頻出"},{"set":11,"word":"adept","pos":"形容詞","meaning":"熟達した、巧みな","example":"Ms. Lee is adept at negotiating contracts with overseas suppliers.","exampleJa":"リーさんは海外の仕入先との契約交渉に長けている。","hint":"「at 〜」とセットで覚える。adept at -ing=〜が上手い、面接の自己PR向き"},{"set":11,"word":"affable","pos":"形容詞","meaning":"愛想の良い、気さくな","example":"Our affable receptionist makes every visitor feel welcome at the front desk.","exampleJa":"愛想の良い受付係のおかげで、来訪者は皆受付で歓迎されていると感じる。","hint":"人柄を褒める推薦状の定番語。ニコニコ話しかけやすい上司を想像"},{"set":11,"word":"amicable","pos":"形容詞","meaning":"友好的な、円満な","example":"The two firms reached an amicable agreement after several rounds of discussion.","exampleJa":"両社は数回の協議の末、円満な合意に達した。","hint":"amicable settlement/divorceの形で。揉めたあと握手で終わるイメージ"},{"set":11,"word":"appraisal","pos":"名詞","meaning":"評価、査定","example":"Your annual appraisal will be conducted by your direct supervisor in December.","exampleJa":"あなたの年次評価は、12月に直属の上司が行います。","hint":"年度末の面談で上司から受ける「査定」。performance appraisalで一括暗記"},{"set":11,"word":"apprentice","pos":"名詞","meaning":"見習い、徒弟","example":"The electrician hired a young apprentice to help with the office renovation.","exampleJa":"電気技師はオフィス改装を手伝わせるため、若い見習いを雇った。","hint":"親方の横で技を盗む若手の姿を連想。職人・技術職の見習い"},{"set":11,"word":"aptitude","pos":"名詞","meaning":"適性、才能","example":"Candidates must take an aptitude test before the final interview.","exampleJa":"応募者は最終面接の前に適性検査を受けなければならない。","hint":"apt(向いている)+tude。採用時のaptitude test=適性検査と結びつける"},{"set":11,"word":"ascertain","pos":"動詞","meaning":"確かめる、確認する","example":"Please ascertain the delivery date with the supplier before confirming the order.","exampleJa":"注文を確定する前に、仕入先に納期を確認してください。","hint":"certain(確か)が中に隠れている。確かな状態にする=確認する"},{"set":11,"word":"assertive","pos":"形容詞","meaning":"自己主張の強い、積極的な","example":"Being assertive in meetings helps you get your ideas heard by senior managers.","exampleJa":"会議で自己主張をすると、上級管理職に自分の考えを聞いてもらいやすくなる。","hint":"assert(主張)の形容詞。会議で遠慮せず意見を言える人。aggressiveとの違いに注意"},{"set":11,"word":"attrition","pos":"名詞","meaning":"自然減、人員の漸減","example":"The firm plans to cut costs through attrition rather than layoffs.","exampleJa":"その会社はレイオフではなく自然減によってコストを削減する予定だ。","hint":"解雇せず退職者の補充をしないで人が減る場面。「自然減」とセットで"},{"set":11,"word":"autonomy","pos":"名詞","meaning":"自主性、自律性","example":"Remote workers value the autonomy to organize their own schedules.","exampleJa":"リモートワーカーは、自分でスケジュールを組める自主性を重視する。","hint":"auto(自分)の仲間。上司に細かく指示されず自分で決める裁量のイメージ"},{"set":11,"word":"benchmark","pos":"名詞","meaning":"基準、指標","example":"We use last year's sales figures as a benchmark for this quarter's targets.","exampleJa":"今四半期の目標の基準として、昨年の売上数値を使っています。","hint":"他社や過去の数値と比べる「ものさし」。industry benchmarkの形で出やすい"},{"set":11,"word":"bonus","pos":"名詞","meaning":"賞与、ボーナス","example":"Employees will receive a bonus if the team exceeds its annual sales target.","exampleJa":"チームが年間売上目標を超えれば、従業員はボーナスを受け取れる。","hint":"給料にプラスされる臨時収入。year-end/performance bonusで使う"},{"set":11,"word":"burnout","pos":"名詞","meaning":"燃え尽き症候群","example":"Long hours and tight deadlines can lead to burnout among project managers.","exampleJa":"長時間労働と厳しい締め切りは、プロジェクトマネージャーの燃え尽きにつながりうる。","hint":"残業続きで火が消えたように働く気力が尽きた状態の絵を思い浮かべる"},{"set":11,"word":"camaraderie","pos":"名詞","meaning":"仲間意識、連帯感","example":"The annual retreat helps build camaraderie between the sales and design teams.","exampleJa":"年次研修旅行は、営業チームとデザインチームの連帯感を築く助けになる。","hint":"発音は「キャマラーダリー」。チームで苦労を乗り越えた後の一体感"},{"set":11,"word":"centralized","pos":"形容詞","meaning":"中央集権化された、一元化された","example":"A centralized purchasing system allows us to negotiate better prices with vendors.","exampleJa":"一元化された購買システムのおかげで、業者とより良い価格を交渉できる。","hint":"center(中心)に権限が集まる。decentralized(分散型)と対で覚える"},{"set":11,"word":"collegial","pos":"形容詞","meaning":"同僚間の、協力的な","example":"The new director has created a collegial environment where everyone shares ideas freely.","exampleJa":"新しい部長は、誰もが自由に意見を共有できる協力的な環境をつくった。","hint":"colleague(同僚)と綴りが似る。同僚どうしが協力し合う雰囲気"},{"set":11,"word":"commendable","pos":"形容詞","meaning":"称賛に値する、立派な","example":"Her commendable efforts saved the project from missing its deadline.","exampleJa":"彼女の称賛に値する努力が、プロジェクトを納期遅れから救った。","hint":"commend(褒める)+able。表彰式のスピーチで使いそうな語"},{"set":11,"word":"confidentiality","pos":"名詞","meaning":"守秘義務、機密性","example":"All new hires must sign a confidentiality agreement on their first day.","exampleJa":"新入社員は全員、初日に守秘義務契約書に署名しなければならない。","hint":"契約書の「秘密保持条項」の見出しに並ぶ語。confidentiality agreementで暗記"},{"set":11,"word":"conscientious","pos":"形容詞","meaning":"良心的な、誠実な","example":"He is a conscientious accountant who double-checks every figure before submitting reports.","exampleJa":"彼は、報告書を提出する前にすべての数字を再確認する誠実な会計士だ。","hint":"conscience(良心)が語中に見える。ミスなく丁寧に仕事をする人。発音注意"},{"set":11,"word":"cubicle","pos":"名詞","meaning":"仕切られた個人作業スペース","example":"My cubicle is next to the printer, so it can get quite noisy.","exampleJa":"私の仕切り席はプリンターの隣なので、かなり騒がしくなることがある。","hint":"cube(立方体)に似た音の連想。オフィスの低い間仕切りで囲まれた席"},{"set":11,"word":"deficient","pos":"形容詞","meaning":"不足している、欠陥のある","example":"The audit found that the warehouse was deficient in safety equipment.","exampleJa":"監査の結果、その倉庫は安全装備が不足していることが分かった。","hint":"deficit(赤字・不足)と同じ仲間と連想。in 〜を伴い「〜が足りない」"},{"set":11,"word":"demeanor","pos":"名詞","meaning":"態度、物腰","example":"The manager kept a calm demeanor throughout the difficult negotiation.","exampleJa":"その部長は、難しい交渉の間ずっと落ち着いた物腰を保った。","hint":"表情・口調・立ち居振る舞いの総合印象。professional demeanorで使う"},{"set":11,"word":"demotion","pos":"名詞","meaning":"降格","example":"After the serious error, he accepted a demotion to assistant manager.","exampleJa":"重大なミスの後、彼は副課長への降格を受け入れた。","hint":"promotion(昇進)の反対。pro→de の対比で覚える"},{"set":11,"word":"diligent","pos":"形容詞","meaning":"勤勉な","example":"Thanks to our diligent staff, the quarterly report was finished ahead of schedule.","exampleJa":"勤勉なスタッフのおかげで、四半期報告書は予定より早く完成した。","hint":"コツコツ手を抜かない人。diligent worker/effortsの組合せで頻出"},{"set":11,"word":"disciplinary","pos":"形容詞","meaning":"懲戒の、規律の","example":"Repeated violations of company rules may result in disciplinary action.","exampleJa":"会社規則に繰り返し違反すると、懲戒処分を受ける可能性がある。","hint":"discipline(規律)を破った人への処分。disciplinary actionで固定"},{"set":11,"word":"disgruntled","pos":"形容詞","meaning":"不満を持った","example":"A disgruntled former employee posted negative comments about the company online.","exampleJa":"不満を抱いた元従業員が、その会社についての否定的な書き込みをネットに投稿した。","hint":"grunt(ぶつぶつ不平を言う音)の連想。給与に不満な社員の愚痴の音"},{"set":11,"word":"dismissal","pos":"名詞","meaning":"解雇","example":"The employee filed a complaint claiming unfair dismissal from his position.","exampleJa":"その従業員は、職位からの不当解雇を訴える申し立てを行った。","hint":"dismiss(解散・解雇)の名詞。unfair dismissalは労働紛争の定番語"},{"set":11,"word":"downsizing","pos":"名詞","meaning":"人員削減、規模縮小","example":"Downsizing at the plant left nearly two hundred workers without jobs.","exampleJa":"工場の人員削減により、200人近い従業員が職を失った。","hint":"down+size。ニュースで「リストラ」と報じられる大幅縮小の場面"},{"set":11,"word":"ergonomic","pos":"形容詞","meaning":"人間工学に基づいた","example":"We replaced all desks with ergonomic models to reduce back pain among staff.","exampleJa":"スタッフの腰痛を減らすため、すべての机を人間工学に基づいたものに替えた。","hint":"腰や目に優しいオフィス家具のカタログに載る語。ergonomic chair/keyboard"},{"set":11,"word":"esteemed","pos":"形容詞","meaning":"尊敬されている","example":"We are honored to welcome our esteemed guest speaker, Dr. Brown.","exampleJa":"尊敬を集める来賓講演者のブラウン博士をお迎えでき、光栄です。","hint":"手紙・式典の呼びかけ「esteemed guests」で見る丁寧な敬称"},{"set":11,"word":"exemplary","pos":"形容詞","meaning":"模範的な","example":"She received an award for her exemplary customer service over the past year.","exampleJa":"彼女は過去1年間の模範的な顧客対応で表彰された。","hint":"example(手本)と綴りがほぼ同じ。見習うべきお手本となる"},{"set":11,"word":"exempt","pos":"形容詞","meaning":"免除された","example":"Nonprofit organizations are often exempt from corporate income tax.","exampleJa":"非営利団体は法人所得税が免除されることが多い。","hint":"exempt from 〜(税・義務)で使う。給与の「残業代なし」区分でも見かける"},{"set":11,"word":"expatriate","pos":"名詞","meaning":"海外駐在員","example":"The company provides housing assistance for expatriates working in its Singapore office.","exampleJa":"その会社は、シンガポール事務所で働く駐在員に住居補助を提供している。","hint":"略してexpat。日本から海外支社に赴任した社員のこと、と場面で覚える"},{"set":11,"word":"flextime","pos":"名詞","meaning":"フレックスタイム制","example":"Flextime allows employees to start work anywhere between seven and ten o'clock.","exampleJa":"フレックスタイム制では、従業員は7時から10時の間で自由に始業できる。","hint":"flex(曲げる)の連想。コアタイム以外は出退勤が柔軟なイメージ"},{"set":11,"word":"forfeit","pos":"動詞","meaning":"没収される、失う","example":"Customers who cancel late will forfeit their deposit under the contract terms.","exampleJa":"契約条件により、直前にキャンセルした顧客は預かり金を没収される。","hint":"ルール違反の罰として権利を取り上げられる。forfeit the right/depositで使う"},{"set":11,"word":"forthcoming","pos":"形容詞","meaning":"近く起こる、今度の","example":"Details of the forthcoming product launch will be announced at the staff meeting.","exampleJa":"近く行われる新製品発売の詳細は、スタッフ会議で発表される。","hint":"「近日公開予定」の告知文に多い。forthcoming event/bookの形で"},{"set":11,"word":"forthright","pos":"形容詞","meaning":"率直な","example":"I appreciate your forthright feedback on the draft proposal.","exampleJa":"企画書の草案に対する率直なご意見に感謝します。","hint":"遠回しにせず真正面から言う。forthcoming(これから来る)と形が似るが別語"},{"set":11,"word":"fringe","pos":"形容詞","meaning":"付加的な、周辺の","example":"The fringe benefits include health insurance and a generous travel allowance.","exampleJa":"付加給付には、健康保険と手厚い出張手当が含まれる。","hint":"fringe benefits(給料以外の付加給付)の形で暗記。本体に付く「房飾り」の連想"},{"set":11,"word":"furlough","pos":"名詞","meaning":"一時解雇、休職","example":"Several workers were placed on furlough when orders dropped sharply last spring.","exampleJa":"昨春に注文が急減したとき、数人の従業員が一時帰休となった。","hint":"発音は「ファーロウ」。工場の操業停止時に無給で自宅待機になる場面"},{"set":11,"word":"gauge","pos":"動詞","meaning":"測る、評価する","example":"We sent a survey to gauge customer reaction to the new packaging.","exampleJa":"新しい包装に対する顧客の反応を測るため、アンケートを送った。","hint":"発音は「ゲイジ」。計器(ゲージ)で目盛りを読む=反応や状況を見極める"},{"set":11,"word":"grievance","pos":"名詞","meaning":"苦情、不満","example":"Employees may file a grievance with the HR department if they feel mistreated.","exampleJa":"不当な扱いを受けたと感じた従業員は、人事部に苦情を申し立てることができる。","hint":"grieve(深く嘆く)と同系。労働組合や人事への正式な苦情申立てで使う"},{"set":11,"word":"groom","pos":"動詞","meaning":"育成する、養成する","example":"The CEO is grooming her deputy to take over the division next year.","exampleJa":"CEOは来年部門を引き継げるよう、副官を育成している。","hint":"「花婿」と同じ綴りだが別義。次期リーダー候補を手塩にかけて育てる絵"},{"set":11,"word":"headcount","pos":"名詞","meaning":"人員数、従業員数","example":"The finance department asked each manager to submit a headcount plan for next year.","exampleJa":"経理部は各管理職に、来年の人員計画を提出するよう求めた。","hint":"head(頭)を数える=人数。予算会議で「増員枠」の話に出る"},{"set":11,"word":"hectic","pos":"形容詞","meaning":"非常に忙しい","example":"The week before the trade show was hectic for the entire marketing team.","exampleJa":"展示会前の1週間は、マーケティングチーム全員にとって非常に慌ただしかった。","hint":"決算期や展示会前の、息つく暇もない日々の様子。hectic scheduleで固定"},{"set":11,"word":"hierarchy","pos":"名詞","meaning":"階層、序列","example":"In a strict hierarchy, junior staff rarely contact executives directly.","exampleJa":"厳格な階層組織では、若手社員が役員に直接連絡することはまれだ。","hint":"社長→部長→課長→担当と並ぶ組織図の縦の序列を思い浮かべる"},{"set":11,"word":"impartial","pos":"形容詞","meaning":"公平な、偏りのない","example":"An impartial committee will review all the applications fairly.","exampleJa":"公平な委員会が、すべての申請を公正に審査する。","hint":"partial(偏った)にim(否定)。審判や調停人に求められる中立さ"},{"set":11,"word":"incumbent","pos":"形容詞","meaning":"現職の","example":"The incumbent director will remain in office until a successor is chosen.","exampleJa":"現職の取締役は、後任が選ばれるまで在任する。","hint":"選挙や人事で「今その席に座っている人」。現職vs新人の対比で覚える"},{"set":11,"word":"induction","pos":"名詞","meaning":"導入研修、入社案内","example":"New employees attend a two-day induction before joining their departments.","exampleJa":"新入社員は、各部署に配属される前に2日間の導入研修を受ける。","hint":"英国系の英語で新入社員の入門研修。induction training/dayで頻出"},{"set":11,"word":"interim","pos":"形容詞","meaning":"暫定の、仮の","example":"An interim CEO was appointed while the board searched for a permanent leader.","exampleJa":"取締役会が正式な後任を探す間、暫定CEOが任命された。","hint":"inter(間)の音から連想。後任が決まるまでの「つなぎ」。interim report/CEO"},{"set":11,"word":"jeopardize","pos":"動詞","meaning":"危うくする","example":"Missing this deadline could jeopardize our relationship with our biggest client.","exampleJa":"この期限を逃すと、最大の顧客との関係が危うくなりかねない。","hint":"発音は「ジェパダイズ」。ミス一つで契約や信用が崖っぷちになる絵"},{"set":11,"word":"layoff","pos":"名詞","meaning":"一時解雇、レイオフ","example":"The manufacturer announced layoffs affecting about ten percent of its workforce.","exampleJa":"そのメーカーは、従業員の約1割に影響するレイオフを発表した。","hint":"景気悪化で会社側の都合により職を離れさせる。本人の落ち度でない点が解雇と違う"},{"set":11,"word":"lenient","pos":"形容詞","meaning":"寛大な","example":"The company has a lenient policy on remote work during winter.","exampleJa":"その会社は冬季のリモートワークに寛大な方針をとっている。","hint":"strict(厳格)の反対。遅刻や提出遅れに目をつぶってくれる上司のイメージ"},{"set":11,"word":"liaison","pos":"名詞","meaning":"連絡係、連携","example":"She serves as the liaison between our engineers and the overseas client.","exampleJa":"彼女は、当社の技術者と海外の顧客との連絡役を務めている。","hint":"発音は「リエイゾン」。2つの部署や会社の間に立つ橋渡し役"},{"set":11,"word":"maternity","pos":"名詞","meaning":"産休、母性","example":"She will return from maternity leave in early March.","exampleJa":"彼女は3月初めに産休から復帰する予定だ。","hint":"maternity leave(産休)と一緒に覚える。対はpaternity(父親の)"},{"set":11,"word":"meticulous","pos":"形容詞","meaning":"細心の、几帳面な","example":"The editor is meticulous and catches even the smallest errors in every manuscript.","exampleJa":"その編集者は几帳面で、どの原稿でも最も小さな誤りまで見つけ出す。","hint":"契約書の誤字を一文字も見逃さない校正係のような細かさ"},{"set":11,"word":"moonlighting","pos":"名詞","meaning":"副業、かけもち仕事","example":"Our contract prohibits moonlighting for competing firms without written approval.","exampleJa":"当社の契約では、書面による承認なしに競合他社で副業することを禁じている。","hint":"moon(月)+light。昼の本業のあと月明かりの下で別の仕事、という連想"},{"set":11,"word":"morale","pos":"名詞","meaning":"士気","example":"The surprise holiday party really lifted morale after a difficult quarter.","exampleJa":"思いがけない休暇パーティーは、厳しい四半期の後で士気を大いに高めた。","hint":"moral(道徳)と綴りが近いが別語。語尾にアクセントがあり「モラール」と読む"},{"set":11,"word":"mundane","pos":"形容詞","meaning":"ありふれた、日常的な","example":"Automation frees employees from mundane tasks so they can focus on creative work.","exampleJa":"自動化により、従業員は平凡な作業から解放され、創造的な仕事に集中できる。","hint":"毎日の伝票入力や備品発注のような、刺激のない日常業務"},{"set":11,"word":"negligent","pos":"形容詞","meaning":"怠慢な、不注意な","example":"The court found the owner negligent in maintaining the building's fire alarms.","exampleJa":"裁判所は、所有者がビルの火災報知器の保守を怠ったと認定した。","hint":"neglect(放置する)の仲間。安全点検を怠った管理者が責任を問われる場面"},{"set":11,"word":"nepotism","pos":"名詞","meaning":"縁故主義","example":"Employees complained that nepotism, not merit, determined who received promotions.","exampleJa":"従業員は、昇進を決めるのは実力ではなく縁故主義だと不満を述べた。","hint":"社長の親族ばかり昇進する会社を想像。fairness(公正)と対立する語"},{"set":11,"word":"offshoring","pos":"名詞","meaning":"海外移転","example":"Offshoring customer support helped the firm lower its operating costs significantly.","exampleJa":"顧客サポートを海外に移転したことで、同社は運営費を大幅に下げられた。","hint":"outsourcing(外注)と混同しやすい。こちらは業務の「場所」を海外へ移す点がポイント"},{"set":11,"word":"onboarding","pos":"名詞","meaning":"新人研修、受け入れ手続き","example":"Effective onboarding helps new hires become productive within their first month.","exampleJa":"効果的な受け入れ研修により、新入社員は最初の1か月で戦力になれる。","hint":"飛行機や船に乗せる感覚で、新人を会社という船に乗せ業務に慣れさせる"},{"set":11,"word":"orientation","pos":"名詞","meaning":"新人向け説明会、方向づけ","example":"The orientation covers company policies, benefits, and the office safety procedures.","exampleJa":"オリエンテーションでは、会社の方針、福利厚生、オフィスの安全手順を説明する。","hint":"入社初日のオリエンテーション。オフィス案内や規則の説明を受ける場面"},{"set":11,"word":"outgoing","pos":"形容詞","meaning":"社交的な、退任する","example":"The outgoing chairman will introduce his successor at tomorrow's ceremony.","exampleJa":"退任する会長は、明日の式典で後任者を紹介する。","hint":"外向きに出ていく人=人懐っこい。また「出ていく」で退任する人も表す2義語"},{"set":11,"word":"overhaul","pos":"動詞","meaning":"全面的に見直す、改修する","example":"The board voted to overhaul the outdated accounting system next year.","exampleJa":"取締役会は、来年、時代遅れの会計システムを全面的に見直すことを決議した。","hint":"飛行機を一度すべて点検・整備するイメージ。制度を根本から作り直す時にも使う"},{"set":11,"word":"paramount","pos":"形容詞","meaning":"最も重要な","example":"Customer safety is paramount, so every product undergoes rigorous testing.","exampleJa":"顧客の安全が最優先なので、すべての製品が厳格な試験を受ける。","hint":"of paramount importanceで固定。他のすべてに優先する最重要事項"},{"set":11,"word":"peer","pos":"名詞","meaning":"同僚、同等の者","example":"Each engineer's design is checked by a peer before it goes to production.","exampleJa":"各技術者の設計は、生産に移る前に同僚によって確認される。","hint":"上下関係でなく横並びの人。peer reviewは同分野の仲間による審査"},{"set":11,"word":"pending","pos":"形容詞","meaning":"保留中の、未決定の","example":"The merger remains pending until regulators complete their review.","exampleJa":"規制当局が審査を終えるまで、合併は保留のままだ。","hint":"pend(ぶら下がる)の連想で、決裁待ちの書類が宙に浮いている状態"},{"set":11,"word":"pension","pos":"名詞","meaning":"年金","example":"The company contributes to each employee's pension every month.","exampleJa":"会社は毎月、各従業員の年金に拠出している。","hint":"退職後に毎月受け取るお金。pension plan/fundの形で頻出"},{"set":11,"word":"perk","pos":"名詞","meaning":"役得、特典","example":"Free lunches are one of the perks of working at our headquarters.","exampleJa":"無料の昼食は、当社本社で働くことの特典の一つだ。","hint":"給料以外の「おまけ」。社食無料やジム会員など。複数形perksでよく使う"},{"set":11,"word":"pertinent","pos":"形容詞","meaning":"関連のある、適切な","example":"Please include only pertinent details in your summary of the incident.","exampleJa":"事故の概要には、関連のある詳細のみを含めてください。","hint":"relevantの堅い言い換え。「pertinent to 〜」で話題に直結することを示す"},{"set":11,"word":"pivotal","pos":"形容詞","meaning":"中心的な、重要な","example":"His pivotal decision to expand overseas doubled the company's revenue.","exampleJa":"海外進出という彼の重要な決断が、会社の収益を倍増させた。","hint":"pivot(軸)の形容詞。ドアの蝶番のように全体が回る要の存在"},{"set":11,"word":"proactive","pos":"形容詞","meaning":"先を見越した、積極的な","example":"We need a proactive approach to identify risks before they affect production.","exampleJa":"生産に影響が出る前にリスクを特定するため、先を見越した対応が必要だ。","hint":"問題が起きてから動く reactive の反対。先回りして動く人材像"},{"set":11,"word":"probation","pos":"名詞","meaning":"試用期間、保護観察","example":"New hires are on probation for the first three months of employment.","exampleJa":"新入社員は、雇用開始から最初の3か月間は試用期間となる。","hint":"入社後の「お試し期間」。probationary employeeも一緒に覚える"},{"set":11,"word":"proficient","pos":"形容詞","meaning":"熟達した","example":"Applicants should be proficient in spreadsheet software and basic data analysis.","exampleJa":"応募者は、表計算ソフトと基本的なデータ分析に習熟している必要がある。","hint":"求人票のskills欄で「in 〜」と使う。languageやsoftwareの習熟度を示す"},{"set":11,"word":"redeploy","pos":"動詞","meaning":"再配置する","example":"Management decided to redeploy several engineers to the new research project.","exampleJa":"経営陣は、数名の技術者を新しい研究プロジェクトに再配置することを決めた。","hint":"re(再び)+deploy(配備)。閉鎖する部署の人員を別の部署へ回す場面"},{"set":11,"word":"reprimand","pos":"動詞","meaning":"叱責する","example":"The supervisor reprimanded him for repeatedly ignoring safety regulations.","exampleJa":"監督者は、彼が繰り返し安全規則を無視したことを叱責した。","hint":"人前で上司に厳しく叱られる場面。公式な注意・戒告にも使う堅い語"},{"set":11,"word":"retention","pos":"名詞","meaning":"維持、引き留め","example":"Higher salaries and flexible hours improved employee retention at the firm.","exampleJa":"給与の引き上げと柔軟な勤務時間が、同社の従業員定着率を改善した。","hint":"retain(保持)の名詞。人材を手放さない施策。employee retentionで頻出"},{"set":11,"word":"rotation","pos":"名詞","meaning":"配置転換、ローテーション","example":"Our job rotation program lets graduates experience several departments in two years.","exampleJa":"当社のジョブローテーション制度では、新卒者が2年間で複数の部署を経験できる。","hint":"rotate(回る)から。数年おきに部署を順に回る人事制度の絵を連想"},{"set":11,"word":"sabbatical","pos":"名詞","meaning":"長期休暇、研究休暇","example":"The professor took a one-year sabbatical to finish writing her book.","exampleJa":"その教授は、著書の執筆を終えるため1年間のサバティカルを取った。","hint":"教授や研究者が数か月〜1年、仕事から離れて学びや執筆に専念する休暇"},{"set":11,"word":"scrutiny","pos":"名詞","meaning":"精査、綿密な調査","example":"The company's financial records have come under close scrutiny from auditors.","exampleJa":"会社の財務記録は、監査人から厳しい精査を受けている。","hint":"虫眼鏡で隅々まで見られる感覚。under scrutinyで「厳しい目にさらされる」"},{"set":11,"word":"secondment","pos":"名詞","meaning":"出向","example":"His six-month secondment to the Paris office gave him valuable international experience.","exampleJa":"6か月間のパリ事務所への出向は、彼に貴重な国際経験をもたらした。","hint":"発音は「セコンドメント」でsecondのアクセントが後ろ。元の会社に籍を残して一時的に他社へ"},{"set":11,"word":"severance","pos":"名詞","meaning":"退職金、解雇手当","example":"Laid-off workers will receive severance pay equal to three months' salary.","exampleJa":"解雇された従業員は、3か月分の給与に相当する退職手当を受け取る。","hint":"sever(切る)の連想。雇用関係を切る時に会社が払うお金。severance pay"},{"set":11,"word":"shortlist","pos":"名詞","meaning":"最終候補者リスト","example":"Three candidates made the shortlist for the marketing director position.","exampleJa":"マーケティング部長職の最終候補者リストに3名が残った。","hint":"大勢の応募者から数名に絞り込んだ名簿。採用や入札の最終段階で使う"},{"set":11,"word":"stimulating","pos":"形容詞","meaning":"刺激的な、やる気を起こさせる","example":"We offer a stimulating workplace where employees are encouraged to try new ideas.","exampleJa":"当社は、従業員が新しいアイデアに挑戦するよう奨励される、刺激的な職場を提供します。","hint":"頭に良い刺激を与えて意欲が湧く。求人広告のstimulating environmentの形"},{"set":11,"word":"stint","pos":"名詞","meaning":"一定期間の仕事、任期","example":"After a brief stint in sales, she moved to the legal department.","exampleJa":"短期間の営業勤務の後、彼女は法務部に異動した。","hint":"期間限定の勤務を指す。経歴紹介で「a stint at 〜」と書かれる使い方"},{"set":11,"word":"stipend","pos":"名詞","meaning":"手当、奨学金","example":"Interns receive a modest stipend to cover transportation and lunch costs.","exampleJa":"インターンは、交通費と昼食代をまかなうための少額の手当を受け取る。","hint":"給料というより、インターンや研修生に出る定額の生活費・助成金"},{"set":11,"word":"subordinate","pos":"名詞","meaning":"部下","example":"A good manager listens carefully to the concerns of every subordinate.","exampleJa":"優れた管理職は、すべての部下の懸念に注意深く耳を傾ける。","hint":"sub(下)の仲間。superior(上司)の対。名詞では「部下」。形容詞は「下位の」"},{"set":11,"word":"tactful","pos":"形容詞","meaning":"機転の利く、如才ない","example":"A tactful reply to the complaint can prevent the situation from getting worse.","exampleJa":"苦情に対する機転の利いた返答は、事態の悪化を防ぐことができる。","hint":"取引先に悪い知らせを角が立たないよう伝える場面。tact(機転)+ful"},{"set":11,"word":"telecommute","pos":"動詞","meaning":"在宅勤務する","example":"Employees are allowed to telecommute up to three days a week.","exampleJa":"従業員は週に最大3日まで在宅勤務することが認められている。","hint":"tele(遠隔)の音はtelephoneやtelevisionと同じ連想。通勤せず画面越しに働く"},{"set":11,"word":"tenure","pos":"名詞","meaning":"在職期間、終身雇用権","example":"During her tenure as director, the museum doubled its annual attendance.","exampleJa":"彼女が館長を務めた期間に、美術館の年間来場者数は倍増した。","hint":"役職・地位に就いている期間。大学では終身在職権の意味でも出る"},{"set":11,"word":"turnover","pos":"名詞","meaning":"離職率、総売上高","example":"The restaurant chain has struggled with high staff turnover in recent years.","exampleJa":"そのレストランチェーンは、近年、従業員の離職率の高さに悩まされている。","hint":"ひっくり返る=入れ替わる。人の出入り(離職率)と売上の2義を場面で区別"},{"set":11,"word":"underperform","pos":"動詞","meaning":"期待以下の成果しか出さない","example":"Several regional branches continued to underperform compared with last year's results.","exampleJa":"いくつかの地方支店は、昨年の実績と比べて引き続き期待を下回る成績だった。","hint":"under+perform。株や社員が期待・市場平均を下回る。outperformの反対"},{"set":11,"word":"versatile","pos":"形容詞","meaning":"多才な、多目的の","example":"We are looking for a versatile designer who can handle both print and web projects.","exampleJa":"私たちは、印刷物とウェブの両方の案件を扱える多才なデザイナーを探しています。","hint":"営業も経理もこなせる何でも屋の人材。multi-purposeな道具にも使う"},{"set":11,"word":"vested","pos":"形容詞","meaning":"確定した、既得の","example":"Many shareholders have a vested interest in the success of the merger.","exampleJa":"多くの株主は、合併の成功に既得の利害関係を持っている。","hint":"vested interest(既得権益)の形が最頻出。退職金の権利が確定する場面でも使う"},{"set":11,"word":"vigilant","pos":"形容詞","meaning":"油断のない、警戒している","example":"Staff must remain vigilant against phishing emails that target company accounts.","exampleJa":"従業員は、会社のアカウントを狙うフィッシングメールに対して警戒を怠ってはならない。","hint":"夜勤の警備員のように目を光らせる。vigilant against fraudで詐欺への警戒"},{"set":11,"word":"vocational","pos":"形容詞","meaning":"職業の、職業訓練の","example":"The government funds vocational training to help workers learn new technical skills.","exampleJa":"政府は、労働者が新しい技術を習得できるよう職業訓練に資金を提供している。","hint":"vocation(職業・天職)の形容詞。専門学校や技能の訓練を指す語"},{"set":11,"word":"whistleblower","pos":"名詞","meaning":"内部告発者","example":"The law protects any whistleblower who reports illegal activity within the company.","exampleJa":"その法律は、社内の違法行為を通報する内部告発者を保護している。","hint":"笛を吹いて不正を知らせる審判の連想。内部告発者を守る法律の話で出る"},{"set":11,"word":"zealous","pos":"形容詞","meaning":"熱心な、熱狂的な","example":"The zealous young manager worked every weekend to launch the new service.","exampleJa":"その熱心な若手管理職は、新サービスを立ち上げるため毎週末働いた。","hint":"発音は「ゼラス」。zeal(熱意)の形容詞。やる気が行き過ぎるほどの熱心さ"},{"set":12,"word":"advocacy","pos":"名詞","meaning":"支持、擁護活動","example":"The nonprofit's advocacy for workers' rights has influenced several new labor laws.","exampleJa":"その非営利団体による労働者の権利の擁護活動は、いくつかの新しい労働法に影響を与えた。","hint":"advocate(支持する人)と同じ語幹。「〜の擁護・支持活動」で NPO のニュースによく出る"},{"set":12,"word":"ambassador","pos":"名詞","meaning":"大使、広告塔","example":"Our new brand ambassador will appear in all of next season's advertising campaigns.","exampleJa":"当社の新しいブランドアンバサダーは、来シーズンのすべての広告キャンペーンに登場する予定です。","hint":"国の代表が「大使」、企業の顔なら「広告塔」。brand ambassador の形で覚える"},{"set":12,"word":"bespoke","pos":"形容詞","meaning":"特注の、オーダーメイドの","example":"The agency designed a bespoke software solution to match the client's unique workflow.","exampleJa":"その代理店は、顧客独自の業務の流れに合わせた特注のソフトウェアを設計した。","hint":"「話しかけて注文する」イメージ。英国の仕立て屋の bespoke suit が定番"},{"set":12,"word":"bestseller","pos":"名詞","meaning":"ベストセラー","example":"Her management guide became a bestseller within two weeks of its release.","exampleJa":"彼女の経営指南書は、発売から2週間でベストセラーになった。","hint":"best+seller の複合語。書店の「売れ筋ランキング1位」の場面を想像"},{"set":12,"word":"billboard","pos":"名詞","meaning":"広告看板","example":"We rented a billboard along the highway to promote our grand opening.","exampleJa":"私たちは開店記念を宣伝するため、幹線道路沿いに広告看板を借りた。","hint":"高速道路沿いの巨大な広告板を思い浮かべる。board の付く語"},{"set":12,"word":"booth","pos":"名詞","meaning":"展示ブース","example":"Please visit our booth in Hall B to try the latest model.","exampleJa":"最新モデルをお試しいただくために、Bホールの当社ブースにぜひお越しください。","hint":"展示会の小さな区画。「ブース」とカタカナでも使うが綴りの oo に注意"},{"set":12,"word":"branding","pos":"名詞","meaning":"ブランディング、銘柄構築","example":"Consistent branding across all channels helps customers recognize our products instantly.","exampleJa":"すべてのチャネルで一貫したブランディングを行うことで、顧客は当社製品をすぐに認識できる。","hint":"brand に -ing。会社のロゴや印象を統一して育てる活動の場面で覚える"},{"set":12,"word":"brick-and-mortar","pos":"形容詞","meaning":"実店舗の","example":"Many brick-and-mortar retailers have launched online stores to reach more customers.","exampleJa":"多くの実店舗型の小売業者が、より多くの顧客に届くようオンラインストアを開設した。","hint":"レンガとモルタルでできた店＝ネット店舗と対比される実店舗。online と対で覚える"},{"set":12,"word":"broker","pos":"名詞","meaning":"仲介業者","example":"The broker negotiated a favorable lease for our new regional office.","exampleJa":"その仲介業者は、当社の新しい地方事務所のために有利な賃貸契約を交渉してくれた。","hint":"売り手と買い手の間に立つ人。stock broker, insurance broker などの連想で"},{"set":12,"word":"bundling","pos":"名詞","meaning":"抱き合わせ販売","example":"Product bundling allows customers to save money while increasing our average order value.","exampleJa":"商品の抱き合わせ販売により、顧客は節約でき、当社は平均注文額を増やせる。","hint":"bundle(束)の -ing。スマホと回線をセットで売る場面を連想"},{"set":12,"word":"cannibalize","pos":"動詞","meaning":"自社製品同士で共食いする","example":"The cheaper model may cannibalize sales of our flagship product.","exampleJa":"より安いモデルは、当社の主力製品の売上を食ってしまうかもしれない。","hint":"cannibal(人食い)が語源の動詞。自社の新製品が旧製品を「食う」イメージ"},{"set":12,"word":"canvass","pos":"動詞","meaning":"勧誘する、意見を募る","example":"Volunteers will canvass local residents to gather opinions about the proposed store.","exampleJa":"ボランティアが地元住民を回り、出店案についての意見を集める予定だ。","hint":"canvas(帆布)とは綴りが違う別語。「一軒ずつ回って意見や票を集める」場面で覚える"},{"set":12,"word":"catalog","pos":"名詞","meaning":"カタログ、目録","example":"Our spring catalog features more than two hundred new items.","exampleJa":"当社の春のカタログには、200点以上の新商品が掲載されています。","hint":"通販の分厚い商品冊子を連想。英国綴りは catalogue"},{"set":12,"word":"churn","pos":"名詞","meaning":"解約率、顧客離れ","example":"Offering loyalty discounts helped us lower customer churn by five percent last quarter.","exampleJa":"ロイヤルティ割引を提供したことで、前四半期の顧客解約率を5パーセント下げることができた。","hint":"バターを「攪拌する」動作から、客がどんどん入れ替わるイメージ（連想）。churn rate で頻出"},{"set":12,"word":"cold-call","pos":"動詞","meaning":"飛び込み営業電話をする","example":"New sales staff are expected to cold-call at least thirty prospects every day.","exampleJa":"新人の営業担当者は、毎日少なくとも30人の見込み客に飛び込みで電話をかけることになっている。","hint":"cold は「冷えた＝関係がまだ温まっていない」相手。紹介なしで電話をかける営業"},{"set":12,"word":"copyright","pos":"名詞","meaning":"著作権","example":"The photographer holds the copyright to every image on the website.","exampleJa":"その写真家は、ウェブサイト上のすべての画像の著作権を保有している。","hint":"copy する right（権利）。本・音楽・ソフトの無断コピー禁止の場面で"},{"set":12,"word":"cross-sell","pos":"動詞","meaning":"関連商品を合わせて販売する","example":"Our representatives are trained to cross-sell insurance when customers open a new account.","exampleJa":"当社の担当者は、顧客が新規口座を開く際に保険を合わせて販売するよう訓練されている。","hint":"cross は「横断して」。ノートPCを買った客にマウスも薦める場面で覚える"},{"set":12,"word":"decision-maker","pos":"名詞","meaning":"意思決定者","example":"Please confirm who the final decision-maker is before we schedule the demonstration.","exampleJa":"実演の日程を決める前に、最終的な意思決定者が誰なのかを確認してください。","hint":"decision+maker のまま。営業で「誰が最終決定者か」を確認する場面"},{"set":12,"word":"deflate","pos":"動詞","meaning":"価格を下げる、しぼませる","example":"Intense competition could deflate prices across the entire electronics sector.","exampleJa":"激しい競争は、電子機器業界全体の価格を押し下げる可能性がある。","hint":"inflate(膨らます)の反対。風船の空気が抜ける様子、物価が下がる場面"},{"set":12,"word":"demographics","pos":"名詞","meaning":"人口統計、客層データ","example":"The survey shows that our core demographics are shifting toward younger consumers.","exampleJa":"調査によると、当社の中心的な客層はより若い消費者へと移りつつある。","hint":"年齢・性別・所得などの客層データ。複数形で使うことが多い"},{"set":12,"word":"differentiate","pos":"動詞","meaning":"差別化する","example":"We must differentiate our service from competitors by offering faster delivery.","exampleJa":"より速い配送を提供することで、当社のサービスを競合他社と差別化しなければならない。","hint":"different の仲間。「違いを際立たせる」＝競合との差別化"},{"set":12,"word":"door-to-door","pos":"形容詞","meaning":"戸別訪問の","example":"The company still relies on door-to-door sales to reach rural customers.","exampleJa":"その会社は、地方の顧客に届けるために、今でも戸別訪問販売に頼っている。","hint":"玄関から玄関へ。訪問販売員がチャイムを押して回る場面"},{"set":12,"word":"e-commerce","pos":"名詞","meaning":"電子商取引","example":"E-commerce now accounts for nearly half of the retailer's total revenue.","exampleJa":"電子商取引は現在、その小売業者の総売上のほぼ半分を占めている。","hint":"e は electronic の頭文字。ネット通販サイトや決済の話題で頻出"},{"set":12,"word":"exorbitant","pos":"形容詞","meaning":"法外な、途方もなく高い","example":"Customers complained about the exorbitant fees charged for express shipping.","exampleJa":"顧客は、速達配送に課される法外な手数料について不満を述べた。","hint":"ex-（外）で始まる語。「相場の外に出た」ほど高い、というイメージで覚える"},{"set":12,"word":"focus-group","pos":"名詞","meaning":"フォーカスグループ、集団調査","example":"We held a focus group to gather reactions to the new packaging design.","exampleJa":"新しい包装デザインへの反応を集めるため、フォーカスグループを開いた。","hint":"数人の消費者を集めて意見を聞く会。新商品の試作品を囲む会議室の場面"},{"set":12,"word":"franchise","pos":"名詞","meaning":"フランチャイズ、加盟店","example":"She invested her savings in a coffee franchise near the train station.","exampleJa":"彼女は貯蓄を、駅近くのコーヒーチェーンのフランチャイズ店に投資した。","hint":"コンビニなど本部の看板を借りて開く店。franchisee（加盟店主）とセットで"},{"set":12,"word":"gatekeeper","pos":"名詞","meaning":"門番、取次役","example":"The receptionist acted as a gatekeeper and screened every call to the director.","exampleJa":"受付係は取次役として、部長宛てのすべての電話を選別していた。","hint":"門番。社長への電話を取り次ぐ秘書や受付が営業にとっての関門"},{"set":12,"word":"generic","pos":"形容詞","meaning":"一般的な、ノーブランドの","example":"The pharmacy offers generic versions of most popular medications at lower prices.","exampleJa":"その薬局は、ほとんどの人気薬のジェネリック版をより安い価格で提供している。","hint":"ブランド名のない薬や商品。generic drug（ジェネリック医薬品）で覚える"},{"set":12,"word":"giveaway","pos":"名詞","meaning":"無料配布品、景品","example":"Each visitor received a free giveaway at the product launch event.","exampleJa":"製品発表会では、来場者全員が無料の景品を受け取った。","hint":"give away（ただで配る）の名詞化。展示会で配られる粗品を想像"},{"set":12,"word":"handbill","pos":"名詞","meaning":"チラシ、ビラ","example":"Staff members distributed handbills outside the station to announce the sale.","exampleJa":"スタッフは、セールを知らせるために駅の外でチラシを配った。","hint":"駅前で手渡しされる一枚もののチラシ。hand（手）で渡す bill（紙）の連想"},{"set":12,"word":"hard-sell","pos":"名詞","meaning":"強引な販売手法","example":"Customers disliked the hard-sell tactics used by the telephone sales team.","exampleJa":"顧客は、電話営業チームが使う強引な販売手法を嫌がった。","hint":"しつこく迫る売り方。soft-sell とセットで対比して覚える"},{"set":12,"word":"high-end","pos":"形容詞","meaning":"高級な","example":"The boutique specializes in high-end furniture imported from Italy.","exampleJa":"そのブティックは、イタリアから輸入した高級家具を専門に扱っている。","hint":"価格帯の上の端。low-end の反対で、高級ブランドの売り場を連想"},{"set":12,"word":"house-brand","pos":"名詞","meaning":"自社ブランド、プライベートブランド","example":"The supermarket's house-brand cereal costs thirty percent less than name brands.","exampleJa":"そのスーパーの自社ブランドのシリアルは、有名ブランド品より30パーセント安い。","hint":"スーパー自社のラベルが付いた商品。national brand との対比で覚える"},{"set":12,"word":"imitation","pos":"名詞","meaning":"模倣品、模造品","example":"The company filed a complaint against a seller of cheap imitations of its handbags.","exampleJa":"その会社は、自社のハンドバッグの安価な模造品を売る業者に対して告発を行った。","hint":"imitate の名詞形。本物そっくりに作った偽の革製品などを連想"},{"set":12,"word":"impulse","pos":"名詞","meaning":"衝動","example":"Placing snacks near the register encourages impulse purchases by shoppers.","exampleJa":"レジの近くにお菓子を置くと、買い物客の衝動買いが促される。","hint":"レジ横の菓子をつい買ってしまう場面。impulse buying（衝動買い）で覚える"},{"set":12,"word":"inflate","pos":"動詞","meaning":"価格をつり上げる、膨らませる","example":"Some retailers inflate prices before offering a so-called discount.","exampleJa":"一部の小売業者は、いわゆる割引を行う前に価格をつり上げる。","hint":"風船に空気を入れる動作。価格や数字が「ふくらむ」場面、deflate と対"},{"set":12,"word":"infomercial","pos":"名詞","meaning":"通販番組、インフォマーシャル","example":"The cookware company bought airtime for a thirty-minute infomercial on Sunday mornings.","exampleJa":"その調理器具会社は、日曜朝に30分間の通販番組の放送枠を購入した。","hint":"info と commercial を合成した混成語。長尺の商品紹介番組を想像"},{"set":12,"word":"kiosk","pos":"名詞","meaning":"小売店、売店","example":"A small kiosk near the entrance sells newspapers and prepaid phone cards.","exampleJa":"入口近くの小さな売店では、新聞やプリペイド式の電話カードを販売している。","hint":"駅やモールにある小さな売店・端末スタンド。「キオスク」の音そのまま"},{"set":12,"word":"knockoff","pos":"名詞","meaning":"模倣品、コピー商品","example":"Customs officers seized a shipment of knockoffs bearing a famous designer's logo.","exampleJa":"税関職員は、有名デザイナーのロゴが付いた模倣品の積荷を押収した。","hint":"有名ブランドをまねた安いコピー品。fake よりもやや日常的な語"},{"set":12,"word":"leaflet","pos":"名詞","meaning":"チラシ、パンフレット","example":"A leaflet describing the new membership plan was included in every package.","exampleJa":"新しい会員プランを説明するチラシが、すべての荷物に同封されていた。","hint":"leaf（葉・紙の一枚）に小さいを表す -let。折り込みの小さなチラシ"},{"set":12,"word":"legitimate","pos":"形容詞","meaning":"合法的な、正当な","example":"Please make sure the supplier is a legitimate business before signing the contract.","exampleJa":"契約書に署名する前に、その納入業者が合法的な事業者であることを確認してください。","hint":"legal と響きが近い連想。「正当で筋が通っている」。legit と略される"},{"set":12,"word":"lifestyle","pos":"名詞","meaning":"ライフスタイル、生活様式","example":"The magazine targets readers who value an active, health-conscious lifestyle.","exampleJa":"その雑誌は、活動的で健康志向のライフスタイルを大切にする読者を対象にしている。","hint":"life+style。起床から趣味まで、客の暮らし方を基準に市場を分ける場面"},{"set":12,"word":"loss-leader","pos":"名詞","meaning":"客寄せ用の目玉商品","example":"The store sells bottled water as a loss-leader to attract more shoppers.","exampleJa":"その店は、より多くの買い物客を呼び込むために、ボトル入りの水を目玉商品として売っている。","hint":"赤字(loss)でも客を引っぱる(lead)商品。特売の卵や牛乳の場面"},{"set":12,"word":"mail-order","pos":"形容詞","meaning":"通信販売の","example":"The company began as a small mail-order business selling gardening tools.","exampleJa":"その会社は、園芸用品を売る小さな通信販売事業として始まった。","hint":"郵便で注文して届く方式。カタログ通販の昔ながらのイメージ"},{"set":12,"word":"markdown","pos":"名詞","meaning":"値下げ","example":"The final markdown on winter coats will take effect this Friday.","exampleJa":"冬物コートの最終値下げは、今週金曜日から適用される。","hint":"値札を下に書き直す動作。markup と対で覚える。セール後の値引きの場面"},{"set":12,"word":"markup","pos":"名詞","meaning":"値上げ幅、利益上乗せ","example":"Retailers typically apply a fifty percent markup to the wholesale price.","exampleJa":"小売業者は通常、卸売価格に50パーセントの利益を上乗せする。","hint":"仕入れ値に上乗せして値札を上げる。markdown と対にして覚える"},{"set":12,"word":"metric","pos":"名詞","meaning":"指標、測定基準","example":"Customer satisfaction is the most important metric in our quarterly review.","exampleJa":"顧客満足度は、当社の四半期レビューにおいて最も重要な指標である。","hint":"meter（メートル）と同系統の「測る」感覚。KPI などの数値指標の意味で使う"},{"set":12,"word":"mid-range","pos":"形容詞","meaning":"中価格帯の","example":"Most of our customers prefer the mid-range model because it balances price and features.","exampleJa":"顧客の大半は、価格と機能のバランスが取れているため、中価格帯のモデルを好む。","hint":"high-end と low-end の真ん中。価格帯が手頃な家電の売り場を連想"},{"set":12,"word":"middleman","pos":"名詞","meaning":"仲介業者","example":"By selling directly online, we eliminated the middleman and lowered our prices.","exampleJa":"オンラインで直接販売することで、当社は仲介業者を省き、価格を下げた。","hint":"生産者と消費者の間の人。cut out the middleman（中抜き）の形で覚える"},{"set":12,"word":"monopoly","pos":"名詞","meaning":"独占","example":"Regulators investigated whether the firm held an illegal monopoly in the region.","exampleJa":"規制当局は、その企業が地域内で違法な独占状態にあるかどうかを調査した。","hint":"mono-（一つ）の仲間。ボードゲームのモノポリーも「独り占め」を競う遊び"},{"set":12,"word":"niche","pos":"名詞","meaning":"ニッチ、隙間市場","example":"The startup found a profitable niche selling eco-friendly pet products.","exampleJa":"そのスタートアップは、環境に優しいペット用品を売ることで、利益の出るニッチ市場を見つけた。","hint":"壁のくぼみにすっぽり収まる小さな場所＝大手が狙わない隙間市場"},{"set":12,"word":"objection","pos":"名詞","meaning":"異議、反対意見","example":"The sales manager answered each objection raised by the buyer politely.","exampleJa":"営業部長は、購入者から出された異議のひとつひとつに丁寧に答えた。","hint":"object（反対する）の名詞形。商談で客が出す「でも…」という懸念の場面"},{"set":12,"word":"opt-in","pos":"名詞","meaning":"事前承諾、オプトイン","example":"Under the new policy, newsletters can only be sent with the customer's opt-in.","exampleJa":"新しい方針のもとでは、ニュースレターは顧客の事前承諾がある場合にのみ送信できる。","hint":"opt（選ぶ）して in（参加）。自分でチェックを入れて購読を承諾する場面。opt-out と対"},{"set":12,"word":"outperform","pos":"動詞","meaning":"しのぐ、上回る成果を出す","example":"Our new sales team continues to outperform the industry average.","exampleJa":"当社の新しい営業チームは、引き続き業界平均を上回る成果を出している。","hint":"out（上回る）+perform。成績で相手を追い抜く。株や業績の記事で頻出"},{"set":12,"word":"outreach","pos":"名詞","meaning":"働きかけ、周知活動","example":"The library expanded its outreach to schools and senior centers this year.","exampleJa":"その図書館は今年、学校や高齢者施設への働きかけを拡大した。","hint":"手を外へ伸ばす。地域や顧客層に出向いて情報を届ける活動の場面"},{"set":12,"word":"overachieve","pos":"動詞","meaning":"期待以上の成果を上げる","example":"The regional team managed to overachieve its targets despite a difficult market.","exampleJa":"その地域チームは、厳しい市場にもかかわらず、目標を超過達成することができた。","hint":"over+achieve。目標を「超えて」達成する。underachieve の反対"},{"set":12,"word":"pavilion","pos":"名詞","meaning":"パビリオン、展示館","example":"Each country built its own pavilion to display products at the international fair.","exampleJa":"各国は、国際見本市で製品を展示するために、それぞれ独自のパビリオンを建設した。","hint":"博覧会の国別展示館のイメージ。テント風の建物を連想すると覚えやすい"},{"set":12,"word":"penetration","pos":"名詞","meaning":"市場浸透","example":"The company aims to increase its market penetration in Southeast Asia next year.","exampleJa":"その会社は、来年、東南アジアでの市場浸透を高めることを目指している。","hint":"penetrate（染み込む）の名詞形。商品が市場に深く入り込む場面"},{"set":12,"word":"pipeline","pos":"名詞","meaning":"販売見込み案件","example":"Our sales pipeline looks promising, with several large deals expected to close soon.","exampleJa":"当社の販売見込み案件は有望で、いくつかの大型契約がまもなく成立する見込みだ。","hint":"パイプに案件が流れ込むイメージ。成約前の商談リストを指す"},{"set":12,"word":"pitch","pos":"名詞","meaning":"売り込み、プレゼン","example":"She delivered a convincing pitch to potential investors in under ten minutes.","exampleJa":"彼女は、10分足らずで見込み投資家に説得力のある売り込みを行った。","hint":"野球の投球のように、相手へ提案を「投げ込む」連想。elevator pitch も有名"},{"set":12,"word":"placard","pos":"名詞","meaning":"プラカード、掲示","example":"Employees held placards outside the headquarters to protest the plant closure.","exampleJa":"従業員たちは、工場閉鎖に抗議するため、本社の外でプラカードを掲げた。","hint":"デモや店頭で掲げる大きな札。「プラカード」とほぼ同じ音で覚える"},{"set":12,"word":"point-of-sale","pos":"名詞","meaning":"販売時点、レジでの精算","example":"The new point-of-sale system records every transaction and updates inventory automatically.","exampleJa":"新しいPOSシステムは、すべての取引を記録し、在庫を自動的に更新する。","hint":"レジで売買が成立する地点。POS システムの P.O.S. がこの略"},{"set":12,"word":"poll","pos":"名詞","meaning":"世論調査","example":"A recent poll found that most customers prefer free shipping over discounts.","exampleJa":"最近の世論調査では、ほとんどの顧客が割引よりも送料無料を好むことがわかった。","hint":"「ポール」と読む。選挙の出口調査のように意見を聞く場面。pole（棒）と混同しない"},{"set":12,"word":"pop-up","pos":"形容詞","meaning":"期間限定の、ポップアップの","example":"The brand opened a pop-up shop in the shopping district for two weeks.","exampleJa":"そのブランドは、商業地区に2週間の期間限定ショップを開いた。","hint":"ぽんと現れてすぐ消える。期間限定の店が街に突然現れる場面"},{"set":12,"word":"premium","pos":"名詞","meaning":"割増料金、上乗せ分","example":"Customers are willing to pay a premium for organic ingredients.","exampleJa":"顧客は、有機栽培の食材に対しては割増料金を払ってもよいと考えている。","hint":"通常より上乗せする分。「プレミアが付く」と日本語でも使う。保険料の意味もある"},{"set":12,"word":"preorder","pos":"動詞","meaning":"予約注文する","example":"Customers can preorder the new tablet starting next Monday at our online store.","exampleJa":"顧客は、来週月曜日から当社のオンラインストアで新型タブレットを予約注文できる。","hint":"pre（前もって）+order。新作ゲームや新型スマホの発売前予約の場面"},{"set":12,"word":"price-cut","pos":"名詞","meaning":"値下げ","example":"The airline announced a major price-cut to attract more summer travelers.","exampleJa":"その航空会社は、夏の旅行客をより多く呼び込むため、大幅な値下げを発表した。","hint":"price を cut（切る）。値下げ競争のニュースで見出しによく出る"},{"set":12,"word":"prohibitive","pos":"形容詞","meaning":"法外に高い、禁止的な","example":"The prohibitive cost of shipping made overseas expansion unrealistic for the small firm.","exampleJa":"法外な輸送費のせいで、その小さな会社にとって海外進出は非現実的なものになった。","hint":"prohibit（禁じる）の仲間。高すぎて「事実上手が出せない」費用に使う"},{"set":12,"word":"rapport","pos":"名詞","meaning":"親密な関係、信頼関係","example":"A good salesperson builds rapport with customers before discussing price.","exampleJa":"優れた営業担当者は、価格を話し合う前に顧客と信頼関係を築く。","hint":"語末の t は発音しない（ラポール）。商談の前の雑談で打ち解ける場面"},{"set":12,"word":"ratings","pos":"名詞","meaning":"評価、視聴率","example":"High customer ratings have helped the restaurant attract a steady stream of diners.","exampleJa":"高い顧客評価のおかげで、そのレストランには客が絶えず訪れている。","hint":"rate の複数名詞形。レビューの星の数やテレビ番組の視聴率の場面"},{"set":12,"word":"reactivate","pos":"動詞","meaning":"再活性化する","example":"Customers can reactivate their suspended accounts by calling our support center.","exampleJa":"顧客は、サポートセンターに電話することで、停止中のアカウントを再開できる。","hint":"re（再び）+activate。止まっていた会員資格や口座を再び動かす場面"},{"set":12,"word":"rebate","pos":"名詞","meaning":"割戻金、リベート","example":"Buyers of the new refrigerator can claim a fifty-dollar rebate by mail.","exampleJa":"新型冷蔵庫の購入者は、郵送で50ドルのリベートを請求できる。","hint":"買った後に一部が戻ってくる現金。割引と違い「後からキャッシュバック」の連想"},{"set":12,"word":"rebrand","pos":"動詞","meaning":"ブランドを刷新する","example":"The software firm decided to rebrand itself after merging with a competitor.","exampleJa":"そのソフトウェア会社は、競合他社と合併した後、ブランドを刷新することを決めた。","hint":"re（再び）+brand。ロゴや社名を変えてイメージを刷新する場面"},{"set":12,"word":"referral","pos":"名詞","meaning":"紹介","example":"Most of our new clients come through referrals from satisfied customers.","exampleJa":"当社の新規顧客の大半は、満足した顧客からの紹介で来店している。","hint":"refer（紹介する）の名詞形。友達紹介で割引が受けられる場面"},{"set":12,"word":"reseller","pos":"名詞","meaning":"再販業者","example":"Our products are available only through authorized resellers in your area.","exampleJa":"当社の製品は、お住まいの地域の正規再販業者を通じてのみ購入できます。","hint":"re+seller。メーカーから仕入れて自社の名で再び売る業者"},{"set":12,"word":"rollout","pos":"名詞","meaning":"展開、発売","example":"The rollout of the updated app is scheduled to begin in March.","exampleJa":"更新版アプリの展開は、3月に開始される予定だ。","hint":"カーペットを roll out して広げるように、新製品や制度を順に展開していく場面"},{"set":12,"word":"sales-cycle","pos":"名詞","meaning":"販売サイクル","example":"The long sales-cycle for industrial equipment can last more than a year.","exampleJa":"産業用機器の長い販売サイクルは、1年以上に及ぶこともある。","hint":"cycle は一周する流れ。見込み客の発掘から成約までの期間の場面"},{"set":12,"word":"sampling","pos":"名詞","meaning":"試供品配布、サンプリング","example":"Product sampling in supermarkets boosted sales of the new snack significantly.","exampleJa":"スーパーでの試供品配布により、その新しいスナックの売上が大幅に伸びた。","hint":"sample を配る行為。デパ地下の試食コーナーの場面"},{"set":12,"word":"saturation","pos":"名詞","meaning":"飽和状態","example":"Market saturation has made it difficult for new smartphone makers to grow.","exampleJa":"市場の飽和により、新規のスマートフォンメーカーが成長するのは難しくなっている。","hint":"スポンジが水を吸い切ってもう入らない状態。市場にもう客がいないイメージ"},{"set":12,"word":"showcase","pos":"動詞","meaning":"紹介する、展示する","example":"The trade fair will showcase innovative products from more than fifty startups.","exampleJa":"その見本市では、50社以上のスタートアップの革新的な製品が紹介される予定だ。","hint":"名詞では「ガラスの陳列ケース」。動詞では魅力を引き立てて見せる"},{"set":12,"word":"showroom","pos":"名詞","meaning":"ショールーム","example":"Customers are welcome to test the sofas in our downtown showroom.","exampleJa":"お客様は、当社の中心街にあるショールームでソファをお試しいただけます。","hint":"車や家具を実物で見られる展示用の部屋。「ショールーム」のまま使える"},{"set":12,"word":"skimming","pos":"名詞","meaning":"上澄み吸収価格戦略","example":"Price skimming works well when a product is new and has few competitors.","exampleJa":"上澄み吸収価格戦略は、製品が新しく競合が少ない場合にうまく機能する。","hint":"牛乳の表面のクリームをすくう動作の連想。新製品を最初は高値で売る戦略"},{"set":12,"word":"slogan","pos":"名詞","meaning":"スローガン、標語","example":"The company's new slogan will appear on all packaging and advertisements.","exampleJa":"同社の新しいスローガンは、すべての包装と広告に掲載される予定だ。","hint":"短く覚えやすい企業の標語。ナイキの「Just do it」のような一言を連想"},{"set":12,"word":"soft-sell","pos":"名詞","meaning":"穏やかな販売手法","example":"The boutique prefers a soft-sell approach, letting customers browse without pressure.","exampleJa":"そのブティックは、客が圧力を感じずに見て回れる穏やかな販売手法を好んでいる。","hint":"押さずにそっと勧める売り方。hard-sell の反対で覚える"},{"set":12,"word":"sold-out","pos":"形容詞","meaning":"売り切れの","example":"The concert was sold-out within an hour of tickets going on sale.","exampleJa":"そのコンサートは、チケット発売から1時間以内に完売した。","hint":"sold+out で「全部売れた」。チケット完売の貼り紙の場面"},{"set":12,"word":"spotlight","pos":"名詞","meaning":"注目、スポットライト","example":"The new campaign puts the spotlight on our most popular product line.","exampleJa":"新しいキャンペーンは、当社で最も人気のある製品ラインに注目を集める。","hint":"舞台で一人を照らす照明。in the spotlight で「注目の的」"},{"set":12,"word":"tagline","pos":"名詞","meaning":"決まり文句、キャッチフレーズ","example":"Our agency created a catchy tagline that customers remember easily.","exampleJa":"当社の代理店は、顧客が簡単に覚えられるキャッチーなキャッチフレーズを作り出した。","hint":"商品名に添える一言。ロゴの下に付く短い文句の場面"},{"set":12,"word":"teaser","pos":"名詞","meaning":"予告、ティーザー広告","example":"The studio released a short teaser a month before the product's official debut.","exampleJa":"そのスタジオは、製品の正式発表の1か月前に、短いティーザー広告を公開した。","hint":"tease（じらす）の人・物。全貌を隠して期待をあおる予告広告"},{"set":12,"word":"tender","pos":"名詞","meaning":"入札","example":"Three contractors submitted a tender for the office renovation project.","exampleJa":"3社の請負業者が、オフィス改装プロジェクトの入札書を提出した。","hint":"入札書を出すこと。形容詞「優しい」とは別用法。submit a tender の形で"},{"set":12,"word":"territory","pos":"名詞","meaning":"営業担当地域","example":"Mr. Lee's sales territory covers the entire western region.","exampleJa":"リー氏の営業担当地域は、西部全域に及んでいる。","hint":"営業担当の持ち場（縄張り）。「西日本エリア担当」のような割り当ての場面"},{"set":12,"word":"testimonial","pos":"名詞","meaning":"推薦の言葉、お客様の声","example":"The website features testimonials from clients who have used our consulting services.","exampleJa":"そのウェブサイトには、当社のコンサルティングサービスを利用した顧客の推薦の声が掲載されている。","hint":"testify（証言する）の仲間。商品を使った人の推薦コメントの場面"},{"set":12,"word":"touchpoint","pos":"名詞","meaning":"顧客接点","example":"The website is now our most important touchpoint with new customers.","exampleJa":"そのウェブサイトは、今や新規顧客との最も重要な接点となっている。","hint":"客が会社に触れる地点。店頭・サイト・電話窓口など、すべての接点を想像"},{"set":12,"word":"trademark","pos":"名詞","meaning":"商標","example":"The firm registered the logo as a trademark to protect its brand.","exampleJa":"その会社は、ブランドを守るために、ロゴを商標として登録した。","hint":"商品に付ける識別マーク。ロゴの横の ™ や ® の記号を連想"},{"set":12,"word":"undercut","pos":"動詞","meaning":"安値で対抗する","example":"Smaller rivals often undercut our prices by using cheaper materials.","exampleJa":"規模の小さい競合は、より安い素材を使って、当社より安値で売ることがよくある。","hint":"相手の値段の「下を切り込む」イメージ。ライバル店より安く売る場面"},{"set":12,"word":"unveil","pos":"動詞","meaning":"発表する、お披露目する","example":"The automaker will unveil its first electric truck at next month's auto show.","exampleJa":"その自動車メーカーは、来月のモーターショーで初の電動トラックを発表する予定だ。","hint":"veil（覆い）を取る。除幕式の布をさっと外す場面を想像"},{"set":12,"word":"upscale","pos":"形容詞","meaning":"高級志向の","example":"The hotel chain plans to open an upscale resort targeting wealthy travelers.","exampleJa":"そのホテルチェーンは、裕福な旅行者をターゲットにした高級リゾートを開業する計画だ。","hint":"scale（段階）の上の方。高級ホテルや高級住宅街の場面"},{"set":12,"word":"upsell","pos":"動詞","meaning":"上位商品を売り込む","example":"Cashiers are encouraged to upsell customers to the larger size of drink.","exampleJa":"レジ係は、客により大きなサイズの飲み物を勧めて売り込むよう推奨されている。","hint":"up+sell。「セットにしますか？ 大きいサイズに？」と上位品を勧める店員の場面"},{"set":12,"word":"value-added","pos":"形容詞","meaning":"付加価値のある","example":"We offer value-added services such as free installation and extended warranties.","exampleJa":"当社は、無料の設置や保証期間の延長といった付加価値サービスを提供しています。","hint":"価値が「加えられた」。VAT（付加価値税）の V と同じ意味。基本サービス＋αの場面"},{"set":12,"word":"win-back","pos":"名詞","meaning":"顧客呼び戻し","example":"The win-back email offered lapsed subscribers a discount on their next renewal.","exampleJa":"その顧客呼び戻しのメールは、購読をやめた人に次回の更新の割引を提示した。","hint":"離れた客を「勝ち取り戻す」。解約者に特別オファーを送るメールの場面"},{"set":12,"word":"word-of-mouth","pos":"名詞","meaning":"口コミ","example":"The small bakery grew quickly thanks to positive word-of-mouth from local residents.","exampleJa":"その小さなパン屋は、地元住民の好意的な口コミのおかげで急速に成長した。","hint":"言葉が口から口へ。広告費ゼロでも広がる評判。by word-of-mouth の形で"},{"set":13,"word":"accrual","pos":"名詞","meaning":"発生、未払い費用の計上","example":"The accrual of unpaid wages must be recorded before the quarter closes.","exampleJa":"未払い賃金の計上は、四半期が終わる前に記録しなければならない。","hint":"決算前に「まだ払っていないけど発生済みの費用」を数える場面。accrue と同じ語源グループ。"},{"set":13,"word":"actuary","pos":"名詞","meaning":"保険数理士","example":"The insurer asked its actuary to estimate the cost of the new health plan.","exampleJa":"保険会社は新しい医療保険のコストを見積もるよう、保険数理士に依頼した。","hint":"保険会社で死亡率や事故率を数字で読み解く計算のプロ、というイメージで覚える。"},{"set":13,"word":"affidavit","pos":"名詞","meaning":"宣誓供述書","example":"The witness submitted a signed affidavit describing what happened on the night of the audit.","exampleJa":"証人は、監査の夜に起きたことを記した署名入りの宣誓供述書を提出した。","hint":"裁判所に出す「うそなら罰せられる」署名入りの書面。sign an affidavit の型で覚える。"},{"set":13,"word":"amendment","pos":"名詞","meaning":"修正、改正","example":"Both parties signed an amendment extending the contract by six months.","exampleJa":"両当事者は、契約を6か月延長する修正書に署名した。","hint":"契約書の「一部だけ直す」追補。an amendment to ～ とセットで覚える。"},{"set":13,"word":"amortization","pos":"名詞","meaning":"償却","example":"The amortization of the equipment loan will take place over five years.","exampleJa":"設備ローンの償却は5年かけて行われる。","hint":"ローン返済表が毎月少しずつ減っていく様子。長い語なので「アモーティゼーション＝少しずつ償却」と音ごと覚える。"},{"set":13,"word":"annuity","pos":"名詞","meaning":"年金、年金保険","example":"She bought an annuity to secure a steady income after retirement.","exampleJa":"彼女は退職後の安定した収入を確保するために年金保険を購入した。","hint":"老後に毎年一定額が振り込まれる保険。annual（毎年の）と見た目が似ていると覚える。"},{"set":13,"word":"antitrust","pos":"形容詞","meaning":"独占禁止の","example":"Regulators opened an antitrust investigation into the proposed merger of the two airlines.","exampleJa":"規制当局は、2つの航空会社の合併案について独占禁止法上の調査を開始した。","hint":"大企業の合併審査でよく出る語。anti-（反）が付くので「独占に反対」。antitrust law が定番。"},{"set":13,"word":"arbitration","pos":"名詞","meaning":"仲裁","example":"The supplier and the retailer agreed to resolve the dispute through arbitration.","exampleJa":"納入業者と小売業者は、その紛争を仲裁で解決することに同意した。","hint":"裁判所に行かず、第三者に判断を任せる紛争解決。go to arbitration の形で覚える。"},{"set":13,"word":"arrears","pos":"名詞","meaning":"延滞金、滞納","example":"The tenant was three months in arrears on the office rent.","exampleJa":"そのテナントは事務所の家賃を3か月分滞納していた。","hint":"家賃や税金が後ろ（rear）に溜まっているイメージ。in arrears の形で出る。複数形が基本。"},{"set":13,"word":"attorney","pos":"名詞","meaning":"弁護士、代理人","example":"Our attorney reviewed the lease agreement before we signed it.","exampleJa":"当社の弁護士は、私たちが署名する前にその賃貸契約書を確認した。","hint":"米国ドラマの法廷シーンで依頼人の隣にいる人。attorney-client privilege（弁護士・依頼者間の秘匿特権）も一緒に。"},{"set":13,"word":"bankruptcy","pos":"名詞","meaning":"破産","example":"The retailer filed for bankruptcy after losing its largest customer.","exampleJa":"その小売業者は最大の顧客を失った後、破産を申請した。","hint":"会社が資金繰りに行き詰まり、裁判所に申し立てる最終手段。file for bankruptcy で一語感覚に。"},{"set":13,"word":"beneficiary","pos":"名詞","meaning":"受益者","example":"The policyholder named her daughter as the sole beneficiary of the insurance.","exampleJa":"保険契約者は、娘を保険の唯一の受取人に指定した。","hint":"保険金や遺産を受け取る人。benefit（利益）と同じ bene- で始まると結びつける。"},{"set":13,"word":"bilateral","pos":"形容詞","meaning":"二国間の、双方の","example":"The two countries signed a bilateral trade agreement to lower import duties.","exampleJa":"両国は輸入関税を引き下げるため、二国間貿易協定に署名した。","hint":"bi- は bicycle の「2」。二国や二社が向き合う協定。反対語は unilateral。"},{"set":13,"word":"binding","pos":"形容詞","meaning":"拘束力のある","example":"Once signed by both parties, the agreement becomes legally binding.","exampleJa":"両当事者が署名すると、その合意は法的拘束力を持つようになる。","hint":"bind（縛る）から。署名した契約は「縛られる」＝逃げられない。legally binding が定番。"},{"set":13,"word":"bookkeeping","pos":"名詞","meaning":"簿記、経理事務","example":"A part-time clerk handles the bookkeeping for our small design studio.","exampleJa":"パートタイムの事務員が、当社の小さなデザイン事務所の経理事務を担当している。","hint":"帳簿（book）をつける地味な毎日の作業。oo と ee が二組続く綴りも覚えどころ。"},{"set":13,"word":"breach","pos":"名詞","meaning":"違反","example":"The vendor's late delivery was a clear breach of the service agreement.","exampleJa":"ベンダーの納品遅れは、サービス契約の明白な違反だった。","hint":"契約の壁に穴を開けるイメージ。breach of contract と、データ流出の data breach もセットで。"},{"set":13,"word":"bribery","pos":"名詞","meaning":"贈収賄","example":"The company introduced strict anti-bribery rules for all overseas offices.","exampleJa":"その会社は、すべての海外拠点に厳格な贈賄防止規則を導入した。","hint":"bribe（賄賂）の行為・罪としての名詞。ニュースの bribery scandal や anti-bribery policy で覚える。"},{"set":13,"word":"bylaw","pos":"名詞","meaning":"内規、定款","example":"The board voted to revise the bylaws governing shareholder meetings.","exampleJa":"取締役会は、株主総会に関する定款細則の改定を議決した。","hint":"会社や団体が自分たちで決める内部ルール。通常は複数形 bylaws で、定款の細則として登場する。"},{"set":13,"word":"capitalization","pos":"名詞","meaning":"資本金総額、資本化","example":"The firm's market capitalization passed one billion dollars last week.","exampleJa":"その会社の時価総額は、先週10億ドルを超えた。","hint":"株価×発行株式数を思い浮かべる。market capitalization（時価総額）が一番よく出る形。"},{"set":13,"word":"clause","pos":"名詞","meaning":"条項","example":"The termination clause allows either side to end the contract with thirty days' notice.","exampleJa":"解約条項により、どちらの側も30日前の通知で契約を終了できる。","hint":"契約書の「第○条」にあたる一区切り。termination clause や confidentiality clause のように名前付きで出る。"},{"set":13,"word":"collateral","pos":"名詞","meaning":"担保","example":"The bank required the owner to offer the warehouse as collateral for the loan.","exampleJa":"銀行は、融資の担保として倉庫を差し出すようオーナーに求めた。","hint":"融資を受けるとき銀行に差し出す不動産や設備。「お金を借りる代わりの人質」と連想。"},{"set":13,"word":"counsel","pos":"名詞","meaning":"顧問弁護士、助言","example":"The general counsel advised the board to postpone the announcement.","exampleJa":"法務顧問は、発表を延期するよう取締役会に助言した。","hint":"企業の法務部門のトップは general counsel。名詞では「法律顧問」、不可算で「助言」の意味も。"},{"set":13,"word":"covenant","pos":"名詞","meaning":"誓約、契約条項","example":"The borrower broke a loan covenant by exceeding the agreed debt ratio.","exampleJa":"借り手は、合意した負債比率を超えたことで融資契約上の誓約に違反した。","hint":"融資契約で「配当を出さない」「債務比率を守る」など借り手に課す約束。financial covenant の形で出る。"},{"set":13,"word":"deductible","pos":"形容詞","meaning":"控除できる","example":"Business travel expenses are usually deductible from taxable income.","exampleJa":"出張費は通常、課税所得から控除できる。","hint":"確定申告で「経費として引ける」かどうかを問う語。tax-deductible と一緒に。"},{"set":13,"word":"default","pos":"名詞","meaning":"債務不履行","example":"The company is in default after missing three consecutive loan payments.","exampleJa":"その会社は、ローンの返済を3回連続で怠り、債務不履行に陥っている。","hint":"返済期日にお金が払えず約束が崩れる状態。in default、default on a loan の形で。"},{"set":13,"word":"defendant","pos":"名詞","meaning":"被告","example":"The defendant denied all claims made by the supplier in court.","exampleJa":"被告は、法廷でその納入業者が主張したすべての請求を否認した。","hint":"裁判で訴えられた側。defend（守る）人と覚え、反対は plaintiff。"},{"set":13,"word":"deferral","pos":"名詞","meaning":"繰り延べ、延期","example":"The government granted a deferral of tax payments for small businesses.","exampleJa":"政府は中小企業に対し、納税の繰り延べを認めた。","hint":"defer（先送りにする）の名詞形。支払いや納税を「今は待ってもらう」場面で。"},{"set":13,"word":"delinquent","pos":"形容詞","meaning":"滞納した、違反の","example":"Collections staff contacted every customer with a delinquent account.","exampleJa":"債権回収担当者は、滞納口座のあるすべての顧客に連絡を取った。","hint":"期限が来ても払わない口座や顧客に貼られるレッテル。delinquent account で覚える。"},{"set":13,"word":"depreciation","pos":"名詞","meaning":"減価償却","example":"Annual depreciation on the delivery trucks reduced the company's reported profit.","exampleJa":"配送トラックの年間の減価償却により、その会社の報告利益は減少した。","hint":"新品のコピー機が毎年少しずつ帳簿上で安くなっていくイメージ。反対は appreciation。"},{"set":13,"word":"discrepancy","pos":"名詞","meaning":"食い違い、不一致","example":"The auditor found a discrepancy between the invoice and the payment record.","exampleJa":"監査人は、請求書と支払記録の間に食い違いを見つけた。","hint":"請求書と入金額の数字が合わない、あの違和感。between A and B の形で使う。"},{"set":13,"word":"divestiture","pos":"名詞","meaning":"事業売却、資産売却","example":"The divestiture of the chemicals division helped the firm reduce its debt.","exampleJa":"化学部門の売却は、その会社が負債を減らすのに役立った。","hint":"不採算の部門を手放す大企業のニュース。反対は acquisition（買収）。"},{"set":13,"word":"dividend","pos":"名詞","meaning":"配当金","example":"The board announced a higher dividend after a record year of earnings.","exampleJa":"取締役会は、過去最高の収益を上げた年を受けて、増配を発表した。","hint":"株主に年に数回振り込まれる利益の分け前。pay / declare a dividend の動詞とセットで。"},{"set":13,"word":"embezzlement","pos":"名詞","meaning":"横領","example":"The former accountant was convicted of embezzlement after stealing funds for years.","exampleJa":"元会計担当者は、何年にもわたり資金を盗んだ末に、横領で有罪判決を受けた。","hint":"経理担当者が会社の金を少しずつ自分の口座に移す不祥事。「預かった金を着服」という点が theft と違う。"},{"set":13,"word":"enforce","pos":"動詞","meaning":"施行する、強制する","example":"Managers must enforce the new safety policy on every factory floor.","exampleJa":"管理者は、すべての工場フロアで新しい安全方針を徹底させなければならない。","hint":"ルールを紙の上だけでなく実際に守らせる、というイメージ。enforce a rule / policy で覚える。"},{"set":13,"word":"equity","pos":"名詞","meaning":"自己資本、株式","example":"The startup raised new equity from investors to fund its expansion.","exampleJa":"そのスタートアップは、事業拡大の資金として投資家から新たな株式資本を調達した。","hint":"資産から負債を引いた株主の持ち分。「公平」の意味もあるが、財務では自己資本・株式の意味で出る。"},{"set":13,"word":"escrow","pos":"名詞","meaning":"第三者預託","example":"The buyer's deposit will be held in escrow until the inspection is complete.","exampleJa":"買主の手付金は、検査が完了するまで第三者預託として保管される。","hint":"不動産売買で、代金を第三者に預けて条件が揃うまで動かさない仕組み。in escrow の形で。"},{"set":13,"word":"fiduciary","pos":"形容詞","meaning":"信託の、受託者の","example":"Directors have a fiduciary duty to act in the interest of shareholders.","exampleJa":"取締役には、株主の利益のために行動する受託者責任がある。","hint":"他人の財産を預かる人が負う「信頼を裏切らない」義務。fiduciary duty が決まり文句。"},{"set":13,"word":"foreclosure","pos":"名詞","meaning":"抵当流れ、差し押さえ","example":"Many homeowners faced foreclosure when interest rates suddenly rose.","exampleJa":"金利が急に上昇したとき、多くの住宅所有者が抵当流れの危機に直面した。","hint":"住宅ローンが払えず銀行に家を取られるニュースの語。face / avoid foreclosure で。"},{"set":13,"word":"fraud","pos":"名詞","meaning":"詐欺","example":"The bank detected fraud involving several customer accounts last month.","exampleJa":"その銀行は先月、複数の顧客口座に関わる不正を検知した。","hint":"だまして金を取る行為全般。credit card fraud や accounting fraud など前に名詞を付けて覚える。"},{"set":13,"word":"goodwill","pos":"名詞","meaning":"のれん代、営業権","example":"The acquisition added a large amount of goodwill to the company's balance sheet.","exampleJa":"その買収により、会社の貸借対照表にはのれんが大きく計上された。","hint":"ブランド力や顧客の信頼が買収価格に上乗せされた分。「好意」の意味を貸借対照表に載せた語。"},{"set":13,"word":"hedge","pos":"動詞","meaning":"リスク回避する","example":"The airline buys fuel contracts to hedge against rising oil prices.","exampleJa":"その航空会社は、原油価格の上昇に備えて燃料契約を購入している。","hint":"庭の生け垣を連想し「備えを囲っておく」と覚える（連想）。hedge against ～ で「～に備える」。"},{"set":13,"word":"impairment","pos":"名詞","meaning":"減損","example":"The company recorded an impairment charge after its overseas plant lost value.","exampleJa":"その会社は、海外工場の価値が下がった後、減損損失を計上した。","hint":"買収した資産の価値が大きく下がり、帳簿を切り下げる場面。impair（損なう）の名詞形。"},{"set":13,"word":"indemnify","pos":"動詞","meaning":"補償する","example":"The contract requires the supplier to indemnify us against any legal claims.","exampleJa":"その契約は、納入業者があらゆる法的請求から当社を補償することを求めている。","hint":"「損害を受けても元通りにする」と覚える。indemnify A against B の形。名詞は indemnity。"},{"set":13,"word":"indemnity","pos":"名詞","meaning":"補償、補償金","example":"The insurer paid the full indemnity within two weeks of the claim.","exampleJa":"保険会社は、請求から2週間以内に補償金の全額を支払った。","hint":"事故や訴訟の損失を埋め合わせる約束・金。indemnify の名詞で、契約書では indemnity clause が頻出。"},{"set":13,"word":"infringement","pos":"名詞","meaning":"侵害","example":"The firm sued its rival for patent infringement over the new device.","exampleJa":"その会社は、新型機器をめぐる特許侵害で競合他社を訴えた。","hint":"他社の特許や商標を無断で使う場面。patent / copyright infringement と組で覚える。"},{"set":13,"word":"injunction","pos":"名詞","meaning":"差し止め命令","example":"The court issued an injunction preventing the company from selling the product.","exampleJa":"裁判所は、その会社による製品の販売を禁じる差し止め命令を出した。","hint":"「今すぐやめろ」と裁判所が出す命令。grant / seek an injunction と動詞を付けて覚える。"},{"set":13,"word":"insolvency","pos":"名詞","meaning":"支払い不能","example":"Rising debts pushed the manufacturer to the brink of insolvency.","exampleJa":"膨らむ負債により、そのメーカーは支払い不能の瀬戸際まで追い込まれた。","hint":"solvency（支払い能力）に否定の in- が付いた形。払うお金がなく倒産寸前の状態。"},{"set":13,"word":"jurisdiction","pos":"名詞","meaning":"管轄権","example":"The contract states that any dispute falls under the jurisdiction of New York courts.","exampleJa":"その契約には、いかなる紛争もニューヨークの裁判所の管轄に属すると定められている。","hint":"「この件はどこの裁判所・どの国の法が扱うか」という守備範囲。契約書の jurisdiction 欄を想像する。"},{"set":13,"word":"kickback","pos":"名詞","meaning":"不正な見返り金","example":"The purchasing manager was fired for accepting kickbacks from a supplier.","exampleJa":"購買部長は、納入業者から不正な見返り金を受け取ったとして解雇された。","hint":"取引を回してもらったお礼に裏で戻すお金（kick back）。賄賂に近い不正な謝礼。"},{"set":13,"word":"lawsuit","pos":"名詞","meaning":"訴訟","example":"Several employees filed a lawsuit against the firm over unpaid overtime.","exampleJa":"数人の従業員が、未払いの残業代をめぐり会社を相手取って訴訟を起こした。","hint":"「訴え（suit）を法（law）の場に」。file / settle a lawsuit の動詞とセットで。"},{"set":13,"word":"ledger","pos":"名詞","meaning":"元帳","example":"Every transaction is recorded in the general ledger at the end of each day.","exampleJa":"すべての取引は、毎日の終わりに総勘定元帳に記録される。","hint":"経理部の棚に並ぶ分厚い帳簿。general ledger（総勘定元帳）の形で出る。"},{"set":13,"word":"levy","pos":"動詞","meaning":"（税金を）課す","example":"The city plans to levy a new fee on commercial parking lots.","exampleJa":"市は、商業用駐車場に新たな手数料を課す計画だ。","hint":"政府が税や関税を「取り立てる」動詞。levy a tax / fee on ～ の形で覚える。"},{"set":13,"word":"liability","pos":"名詞","meaning":"負債、法的責任","example":"The company's total liabilities exceeded its assets for the first time.","exampleJa":"その会社の負債総額は、初めて資産を上回った。","hint":"貸借対照表の「負債」側。liable（責任がある）と同族で、法的責任の意味もある。"},{"set":13,"word":"lien","pos":"名詞","meaning":"先取特権、担保権","example":"The contractor placed a lien on the building until the invoice was paid.","exampleJa":"請負業者は、請求書が支払われるまでその建物に先取特権を設定した。","hint":"「リーン」と読む。未払いがある限り、相手の財産に「待った」をかける法的な権利。"},{"set":13,"word":"liquidity","pos":"名詞","meaning":"流動性","example":"The firm kept enough liquidity to cover three months of operating costs.","exampleJa":"その会社は、3か月分の運営費をまかなえるだけの流動性を確保していた。","hint":"liquid（液体）のようにさらさら現金化できる度合い。liquidity problem は資金繰りの悩み。"},{"set":13,"word":"litigation","pos":"名詞","meaning":"訴訟手続き","example":"The company is currently involved in litigation over a disputed software license.","exampleJa":"その会社は現在、係争中のソフトウェアライセンスをめぐる訴訟に関与している。","hint":"訴訟になると長引いて金がかかる、という場面で。be in litigation / pending litigation の形。"},{"set":13,"word":"maturity","pos":"名詞","meaning":"満期","example":"The investor will receive the full amount when the bond reaches maturity.","exampleJa":"債券が満期に達すると、投資家は全額を受け取ることになる。","hint":"債券や定期預金が「満期」を迎え、元本が戻ってくる日。maturity date でそのまま使う。"},{"set":13,"word":"mediation","pos":"名詞","meaning":"調停","example":"The union and management entered mediation to settle the wage dispute.","exampleJa":"組合と経営側は、賃金をめぐる争いを解決するため調停に入った。","hint":"対立する2者の間に調停人が立つ穏やかな解決法。arbitration と違い、判断を押し付けない点が対比。"},{"set":13,"word":"misconduct","pos":"名詞","meaning":"不正行為、職務違反","example":"The employee was dismissed for serious misconduct after the internal investigation.","exampleJa":"その従業員は、社内調査の後、重大な不正行為を理由に解雇された。","hint":"mis-（誤った）＋ conduct（行い）。職場の不正や規律違反で、serious misconduct は懲戒解雇の理由に。"},{"set":13,"word":"nondisclosure","pos":"名詞","meaning":"守秘、非開示","example":"All visitors must sign a nondisclosure agreement before touring the research lab.","exampleJa":"すべての訪問者は、研究所を見学する前に秘密保持契約に署名しなければならない。","hint":"NDA（nondisclosure agreement）の中身の語。「話してはいけない」という約束と結びつける。"},{"set":13,"word":"notary","pos":"名詞","meaning":"公証人","example":"The signature on the power of attorney was verified by a notary.","exampleJa":"委任状の署名は、公証人によって確認された。","hint":"書類に署名を見届けて公式な印を押す人。notary public の形でも出る。"},{"set":13,"word":"nullify","pos":"動詞","meaning":"無効にする","example":"A court ruling could nullify the agreement between the two firms.","exampleJa":"裁判所の判断によって、両社間の合意が無効になる可能性がある。","hint":"null（無効）を作る動詞。契約や判決を「ゼロに戻す」と覚える。"},{"set":13,"word":"ordinance","pos":"名詞","meaning":"条例","example":"A city ordinance limits the hours when restaurants may play outdoor music.","exampleJa":"市の条例により、レストランが屋外で音楽を流せる時間が制限されている。","hint":"国の法律（law）ではなく、市や町が定めるルール。zoning ordinance（用途地域条例）の形で出る。"},{"set":13,"word":"outlay","pos":"名詞","meaning":"支出","example":"The new factory required a large initial outlay for machinery.","exampleJa":"新工場には、機械設備のために多額の初期支出が必要だった。","hint":"プロジェクトを始めるときに最初に出ていく金。capital outlay や initial outlay で覚える。"},{"set":13,"word":"overdue","pos":"形容詞","meaning":"期限超過の、延滞の","example":"Please settle the overdue invoice as soon as possible to avoid a late fee.","exampleJa":"延滞料を避けるため、期限を過ぎた請求書をできるだけ早くお支払いください。","hint":"締切や支払期限を過ぎた状態。overdue invoice（期限超過の請求書）は督促メールの定番。"},{"set":13,"word":"payable","pos":"形容詞","meaning":"支払うべき","example":"Accounts payable increased because several large invoices arrived at month end.","exampleJa":"月末に大口の請求書が何通か届いたため、買掛金が増加した。","hint":"「払う側」の帳簿用語。accounts payable は買掛金、手形なら notes payable。後ろに置く点に注意。"},{"set":13,"word":"perjury","pos":"名詞","meaning":"偽証罪","example":"He was charged with perjury for lying under oath during the trial.","exampleJa":"彼は、裁判中に宣誓の上でうそをついたとして、偽証罪で起訴された。","hint":"法廷で誓ったのにうそをつく罪。commit perjury と、前の語 affidavit とセットで連想。"},{"set":13,"word":"plaintiff","pos":"名詞","meaning":"原告","example":"The plaintiff claims that the supplier failed to deliver the ordered goods.","exampleJa":"原告は、納入業者が注文した商品を納品しなかったと主張している。","hint":"訴えを起こす側。defendant（被告）と対にして覚える。"},{"set":13,"word":"precedent","pos":"名詞","meaning":"判例、先例","example":"The ruling set a precedent for how data privacy cases are decided.","exampleJa":"その判決は、データプライバシー訴訟がどう判断されるかについての先例となった。","hint":"「前例」。過去の判決が次の裁判の手本になる。set a precedent（前例を作る）の形で。"},{"set":13,"word":"prepaid","pos":"形容詞","meaning":"前払いの","example":"Customers can choose a prepaid plan instead of receiving a monthly bill.","exampleJa":"顧客は、毎月の請求書を受け取る代わりに前払いプランを選ぶことができる。","hint":"先に払ってあるカードやプラン。pre-（あらかじめ）が付くのは prepaid card、prepaid expenses など。"},{"set":13,"word":"principal","pos":"名詞","meaning":"元本、本人","example":"Each monthly payment covers both interest and a portion of the principal.","exampleJa":"毎月の支払いには、利息と元本の一部の両方が含まれている。","hint":"金融では「利息ではない元の借入額」。interest（利息）と対にして、principal and interest で覚える。"},{"set":13,"word":"receivable","pos":"形容詞","meaning":"未収の、受け取るべき","example":"Accounts receivable rose sharply because several clients delayed their payments.","exampleJa":"複数の顧客が支払いを遅らせたため、売掛金が大幅に増加した。","hint":"「受け取る側」の帳簿用語。accounts receivable は売掛金で、payable と対。"},{"set":13,"word":"reciprocal","pos":"形容詞","meaning":"相互の","example":"The two universities signed a reciprocal agreement to exchange visiting researchers.","exampleJa":"両大学は、客員研究者を交換する相互協定に署名した。","hint":"お互いに同じことをし合う関係。reciprocal agreement は「お互い様」の協定と考える。"},{"set":13,"word":"reconcile","pos":"動詞","meaning":"照合する、一致させる","example":"The accountant must reconcile the bank statement with the company's cash records.","exampleJa":"会計担当者は、銀行の取引明細書を会社の現金記録と照合しなければならない。","hint":"銀行の明細と社内の帳簿を突き合わせて数字を合わせる作業。reconcile A with B の形。"},{"set":13,"word":"remittance","pos":"名詞","meaning":"送金","example":"We confirmed receipt of your remittance of 5,000 dollars this morning.","exampleJa":"本日午前、5,000ドルのご送金を受領したことを確認いたしました。","hint":"海外の取引先や家族へ銀行から送るお金。remittance advice（送金通知書）という書類名も。"},{"set":13,"word":"restatement","pos":"名詞","meaning":"修正再表示","example":"The restatement of last year's earnings caused the share price to fall.","exampleJa":"昨年の決算の修正再表示により、株価が下落した。","hint":"過去の決算の誤りを直して発表し直す事態。投資家が最も嫌がるニュースの一つ。"},{"set":13,"word":"rider","pos":"名詞","meaning":"特約条項","example":"He added a rider to his policy to cover damage from natural disasters.","exampleJa":"彼は自然災害による損害を補償するため、保険に特約を追加した。","hint":"本体の契約に「乗っかる」追加条項。保険の insurance rider（特約）で覚える。"},{"set":13,"word":"royalty","pos":"名詞","meaning":"ロイヤルティ、使用料","example":"The author receives a ten percent royalty on every copy sold.","exampleJa":"その著者は、売れた一冊ごとに10パーセントの印税を受け取る。","hint":"作家や特許権者が売上に応じて受け取る使用料。複数形 royalties で使う場面が多い。"},{"set":13,"word":"shareholder","pos":"名詞","meaning":"株主","example":"Shareholders will vote on the merger proposal at the annual meeting.","exampleJa":"株主は、年次総会で合併案について投票する予定だ。","hint":"株式（share）を持つ（hold）人。株主総会（shareholders' meeting）に出席する人たち。"},{"set":13,"word":"solvency","pos":"名詞","meaning":"支払い能力","example":"Credit agencies regularly check the solvency of large insurance companies.","exampleJa":"格付け機関は、大手保険会社の支払い能力を定期的に確認している。","hint":"借金を返せる体力。反対語 insolvency とペアで、solvent（支払い能力のある）も一緒に。"},{"set":13,"word":"stakeholder","pos":"名詞","meaning":"利害関係者","example":"The CEO met with key stakeholders to explain the restructuring plan.","exampleJa":"CEOは、再編計画を説明するために主要な利害関係者と面会した。","hint":"株主だけでなく、従業員・顧客・地域住民など会社の動きに利害がある全員。"},{"set":13,"word":"statute","pos":"名詞","meaning":"制定法","example":"The new statute requires companies to report data breaches within 72 hours.","exampleJa":"新しい制定法は、企業にデータ漏えいを72時間以内に報告するよう義務づけている。","hint":"議会が正式に定めた成文の法律。判例（precedent）が裁判所発なのと対比する。"},{"set":13,"word":"stipulation","pos":"名詞","meaning":"規定、条項","example":"One stipulation of the lease prohibits subletting the space without written approval.","exampleJa":"その賃貸借契約の規定の一つは、書面による承認なしに部屋を転貸することを禁じている。","hint":"契約に「ただし～が条件」と明記する取り決め。stipulate（明記する）の名詞形。"},{"set":13,"word":"subpoena","pos":"名詞","meaning":"召喚状","example":"The committee issued a subpoena requiring the executive to testify.","exampleJa":"委員会は、その幹部に証言を求める召喚状を出した。","hint":"「サピーナ」と読む。無視すると罰せられる、法廷や書類提出への強制的な呼び出し状。"},{"set":13,"word":"surcharge","pos":"名詞","meaning":"追加料金","example":"A fuel surcharge will be added to all international shipments this quarter.","exampleJa":"今四半期は、すべての国際輸送に燃油サーチャージが加算される。","hint":"基本料金の上に乗る追加分。fuel surcharge（燃油サーチャージ）が最も身近。"},{"set":13,"word":"surety","pos":"名詞","meaning":"保証人、保証","example":"The contractor provided a surety to guarantee completion of the project.","exampleJa":"請負業者は、プロジェクトの完成を保証するために保証人を立てた。","hint":"借り手が払えないときに代わりに責任を負う保証人。surety bond（保証証券）の形でも出る。"},{"set":13,"word":"tariff","pos":"名詞","meaning":"関税","example":"The government raised the tariff on imported steel to protect local producers.","exampleJa":"政府は、国内の生産者を守るために輸入鉄鋼の関税を引き上げた。","hint":"輸入品にかかる税金。貿易摩擦のニュースで tariffs on steel のように出る。"},{"set":13,"word":"taxation","pos":"名詞","meaning":"課税","example":"The treaty prevents double taxation of income earned by overseas employees.","exampleJa":"その条約は、海外勤務の従業員が得た所得に対する二重課税を防いでいる。","hint":"tax は一つの税、taxation は課税の仕組み・制度全体。double taxation（二重課税）も頻出。"},{"set":13,"word":"testimony","pos":"名詞","meaning":"証言","example":"The manager's testimony helped the court understand how the contract was negotiated.","exampleJa":"その部長の証言は、契約がどのように交渉されたかを裁判所が理解する助けとなった。","hint":"証人が法廷で述べる言葉。give testimony や expert testimony の形で覚える。"},{"set":13,"word":"treasurer","pos":"名詞","meaning":"財務担当者、会計係","example":"The treasurer presented the budget report at the board meeting.","exampleJa":"財務担当者は、取締役会で予算報告を行った。","hint":"クラブや会社の「お金の番人」。treasure（宝）を扱う人と連想すると覚えやすい。"},{"set":13,"word":"trustee","pos":"名詞","meaning":"受託者","example":"The trustee manages the fund on behalf of the retired employees.","exampleJa":"受託者は、退職した従業員のためにその基金を管理している。","hint":"他人から財産を預けられて管理する人。trust（信託）を引き受ける側で、-ee が受け手の感じ。"},{"set":13,"word":"underwrite","pos":"動詞","meaning":"引き受ける","example":"Two major banks agreed to underwrite the company's new share offering.","exampleJa":"2つの大手銀行は、その会社の新株発行を引き受けることに同意した。","hint":"保険会社や銀行がリスクを引き受け、起債や保険契約に責任を持つ。under + write で「下に署名」と分解できる。"},{"set":13,"word":"unilateral","pos":"形容詞","meaning":"一方的な","example":"The sudden unilateral change to the contract terms upset our partners.","exampleJa":"契約条件の突然の一方的な変更は、当社のパートナーを憤慨させた。","hint":"uni- は「1つ」。相手に相談せず一方だけで決める。bilateral の反対。"},{"set":13,"word":"verdict","pos":"名詞","meaning":"評決","example":"The jury reached a verdict after two days of discussion.","exampleJa":"陪審は2日間の審議の後、評決に達した。","hint":"陪審員が出す「有罪か無罪か」の結論。reach / deliver a verdict の動詞と一緒に。"},{"set":13,"word":"void","pos":"形容詞","meaning":"無効な","example":"Any agreement signed under pressure may be declared void by the court.","exampleJa":"圧力の下で署名された合意は、裁判所によって無効と宣言される場合がある。","hint":"契約が最初から効力ゼロ。null and void（無効）というセット表現で覚える。"},{"set":13,"word":"waiver","pos":"名詞","meaning":"権利放棄書","example":"Participants must sign a waiver before joining the factory tour.","exampleJa":"参加者は、工場見学に加わる前に権利放棄書に署名しなければならない。","hint":"イベント参加前に署名する「怪我しても訴えません」の書類。waive（放棄する）の名詞形。"},{"set":13,"word":"withholding","pos":"名詞","meaning":"源泉徴収","example":"Payroll calculates the withholding for each employee before issuing paychecks.","exampleJa":"給与担当部門は、給与を支給する前に各従業員の源泉徴収額を計算する。","hint":"給与明細で支給額から天引きされる所得税。withholding tax と一緒に。"},{"set":13,"word":"write-down","pos":"名詞","meaning":"評価減","example":"The firm announced a major write-down of its unsold inventory.","exampleJa":"その会社は、売れ残った在庫の大幅な評価減を発表した。","hint":"資産の帳簿価額を実態に合わせて切り下げること。write-off（全額落とす）との違いは「一部か全部か」。"},{"set":13,"word":"write-off","pos":"名詞","meaning":"損金処理、帳消し","example":"The accountant recommended a write-off of the unpaid customer invoices.","exampleJa":"会計担当者は、未払いの顧客請求書を損金処理するよう勧めた。","hint":"回収できない売掛金を帳簿から消す処理。write-down が一部減額なのに対し、こちらは全額。"},{"set":13,"word":"yield","pos":"名詞","meaning":"利回り","example":"Investors prefer bonds with a higher yield, but they usually carry more risk.","exampleJa":"投資家は利回りの高い債券を好むが、そうした債券は通常リスクも大きい。","hint":"投資額に対して毎年どれだけ戻ってくるか。dividend yield や bond yield の形で出る。"},{"set":14,"word":"alignment","pos":"名詞","meaning":"整列、調整","example":"The two departments need better alignment on the product launch schedule.","exampleJa":"両部門は製品発売スケジュールについて、もっと足並みをそろえる必要がある。","hint":"line(線)に沿って揃えるイメージ。「ライン取りが合っている状態」と覚える(連想)"},{"set":14,"word":"alloy","pos":"名詞","meaning":"合金","example":"The new aircraft parts are made from a lightweight aluminum alloy.","exampleJa":"新しい航空機の部品は、軽量なアルミニウム合金で作られている。","hint":"「アロイ」はホイールの商品名でおなじみ。アルミ合金ホイールを思い出そう"},{"set":14,"word":"assurance","pos":"名詞","meaning":"保証","example":"The supplier gave us written assurance that the delivery would arrive on time.","exampleJa":"供給業者は、納品が期日どおりに届くと書面で保証してくれた。","hint":"assure(保証する)の名詞形。「品質保証=QA」のAはassurance"},{"set":14,"word":"backlog","pos":"名詞","meaning":"未処理の仕事、受注残","example":"We hired temporary staff to clear the backlog of customer orders.","exampleJa":"私たちは顧客注文の未処理分を片付けるため、臨時スタッフを雇った。","hint":"机の後ろに積み上がった未処理の書類の山を想像。clear a backlogの形で覚える"},{"set":14,"word":"backorder","pos":"名詞","meaning":"入荷待ち注文","example":"The item is on backorder until the next shipment arrives in March.","exampleJa":"その商品は、次の荷が3月に届くまで入荷待ちになっている。","hint":"在庫がなく「後回し」にされた注文。商品ページの「入荷待ち」表示の場面で"},{"set":14,"word":"barcode","pos":"名詞","meaning":"バーコード","example":"Please scan the barcode on each package before loading it onto the truck.","exampleJa":"トラックに積む前に、各荷物のバーコードをスキャンしてください。","hint":"bar(棒)+code(符号)。レジでピッと読み取る縞模様"},{"set":14,"word":"barge","pos":"名詞","meaning":"はしけ、運搬船","example":"The steel coils were shipped up the river on a barge.","exampleJa":"鋼板コイルははしけで川をさかのぼって輸送された。","hint":"川を「ゆったり」進む平らな船。「バージ」の響きでどっしり重い荷を連想(連想)"},{"set":14,"word":"batch","pos":"名詞","meaning":"一回分の生産単位","example":"Each batch of medicine is tested before it leaves the factory.","exampleJa":"医薬品は、1回の製造分ごとに工場を出る前に検査される。","hint":"クッキーを一度に焼く一回分。製造は「ロット単位」で作る感覚"},{"set":14,"word":"blemish","pos":"名詞","meaning":"傷、欠点","example":"We cannot sell the vase because it has a small blemish on the surface.","exampleJa":"表面に小さな傷があるため、その花瓶は販売できない。","hint":"新品のはずの商品にある小さなキズ。「ブレ+ミッシュ」で「見た目がブレた」と覚える(語呂)"},{"set":14,"word":"bottleneck","pos":"名詞","meaning":"ボトルネック、障害","example":"The slow inspection process has become a bottleneck in our production line.","exampleJa":"検査工程の遅さが、私たちの生産ラインのボトルネックになっている。","hint":"瓶の首が細くて中身が出にくい様子。工程の詰まり箇所を指す"},{"set":14,"word":"break-bulk","pos":"形容詞","meaning":"ばら積みの","example":"Heavy machinery is often shipped as break-bulk cargo rather than in containers.","exampleJa":"重機械はコンテナではなく、ばら積み貨物として出荷されることが多い。","hint":"コンテナ化せず、袋や箱をバラバラに積む貨物。break-bulk cargoのセットで"},{"set":14,"word":"buffer","pos":"名詞","meaning":"緩衝材、予備分","example":"We keep a buffer of extra parts in case the supplier is late.","exampleJa":"供給業者の遅れに備えて、余分な部品を予備として確保している。","hint":"衝突を和らげるクッション。納期や在庫の「余裕分」として使う"},{"set":14,"word":"byproduct","pos":"名詞","meaning":"副産物","example":"Sawdust is a byproduct of the lumber manufacturing process.","exampleJa":"おがくずは、木材の製造工程で出る副産物である。","hint":"by(そばの)+product。メイン製品のついでにできるもの"},{"set":14,"word":"calibrate","pos":"動詞","meaning":"較正する、調整する","example":"Technicians must calibrate the scales every month to ensure accurate measurements.","exampleJa":"正確な測定を保つため、技術者は毎月はかりを較正しなければならない。","hint":"体重計のゼロ点合わせの場面。測定機器を基準に合わせる動作"},{"set":14,"word":"cargo","pos":"名詞","meaning":"貨物","example":"The cargo was inspected at the port before it was released to the buyer.","exampleJa":"貨物は、買い手に引き渡される前に港で検査された。","hint":"「カーゴパンツ」のカーゴ。物をたくさん載せる・積むイメージ(連想)"},{"set":14,"word":"carrier","pos":"名詞","meaning":"運送業者","example":"We chose a different carrier because the previous one often delayed deliveries.","exampleJa":"以前の運送業者は配送をよく遅らせたため、別の業者を選んだ。","hint":"carry(運ぶ)する会社。FedExやUPSなどを思い浮かべる"},{"set":14,"word":"carton","pos":"名詞","meaning":"段ボール箱","example":"Each carton holds twenty-four bottles and must be labeled before shipping.","exampleJa":"各段ボール箱には24本入っており、出荷前にラベルを貼らなければならない。","hint":"牛乳パックや引っ越しの段ボール箱。boxより「厚紙製」の印象"},{"set":14,"word":"caustic","pos":"形容詞","meaning":"腐食性の","example":"Workers must wear gloves when handling caustic cleaning solutions.","exampleJa":"作業員は腐食性の洗浄液を扱うとき、手袋を着用しなければならない。","hint":"「コーステック」と読み、皮膚をただれさせる強い薬品。caustic sodaが定番"},{"set":14,"word":"changeover","pos":"名詞","meaning":"切り替え、段取り替え","example":"A faster changeover between products will reduce idle time on the line.","exampleJa":"製品間の段取り替えを速くすれば、ラインの遊休時間が減る。","hint":"ラインで製品Aから製品Bへ切り替える作業。時間のロスが課題になる"},{"set":14,"word":"combustible","pos":"形容詞","meaning":"可燃性の","example":"Combustible materials must be stored away from heat sources.","exampleJa":"可燃性の材料は、熱源から離して保管しなければならない。","hint":"combust(燃える)+ible。「火がつく可能性あり」の注意書きの場面"},{"set":14,"word":"commodity","pos":"名詞","meaning":"商品、コモディティ","example":"Rising commodity prices have increased our manufacturing costs this year.","exampleJa":"商品相場の上昇で、今年は当社の製造コストが増えている。","hint":"原油・小麦・銅など、どこで買っても同じ品質の取引商品。価格は相場で動く"},{"set":14,"word":"composite","pos":"形容詞","meaning":"複合の","example":"The bicycle frame is built from a lightweight composite material.","exampleJa":"その自転車のフレームは、軽量な複合素材で作られている。","hint":"compose(組み立てる)と同系の響き。炭素繊維など複数素材を合わせたもの(連想)"},{"set":14,"word":"consignment","pos":"名詞","meaning":"委託販売、委託貨物","example":"The gallery displays the artist's paintings on consignment and takes a commission.","exampleJa":"そのギャラリーは、画家の作品を委託販売で展示し、手数料を受け取っている。","hint":"店に商品を預け、売れた分だけ支払う仕組み。on consignmentで覚える"},{"set":14,"word":"consolidator","pos":"名詞","meaning":"混載業者","example":"A freight consolidator combined our small shipments to lower the shipping cost.","exampleJa":"貨物混載業者が当社の小口出荷をまとめて、輸送費を下げてくれた。","hint":"小口荷物を一つのコンテナに寄せ集める業者。consolidate(統合する)の人版"},{"set":14,"word":"contaminate","pos":"動詞","meaning":"汚染する","example":"Careless handling could contaminate the food products on the production line.","exampleJa":"不注意な取り扱いは、製造ラインの食品を汚染するおそれがある。","hint":"きれいな水に汚れが混ざる場面。contaminationは食品工場の最大の敵"},{"set":14,"word":"conveyor","pos":"名詞","meaning":"コンベヤー、運搬装置","example":"Boxes move along the conveyor to the packing station.","exampleJa":"箱はコンベヤーに乗って、梱包ステーションへ運ばれる。","hint":"空港の荷物受取所や工場で回るベルト。convey(運ぶ)する装置"},{"set":14,"word":"corrosive","pos":"形容詞","meaning":"腐食性の","example":"Corrosive liquids must be kept in specially designed containers.","exampleJa":"腐食性の液体は、特別に設計された容器に保管しなければならない。","hint":"corrode(錆びさせる)と同じ語幹。金属を溶かすほど強い酸のイメージ"},{"set":14,"word":"crate","pos":"名詞","meaning":"木箱","example":"The fragile glassware was packed in a sturdy wooden crate.","exampleJa":"壊れやすいガラス製品は、頑丈な木箱に詰められた。","hint":"果物やワインを運ぶ木枠の箱。「クレート」はペットのケージ名でも耳にする"},{"set":14,"word":"demurrage","pos":"名詞","meaning":"滞船料、保管超過料","example":"We paid extra demurrage because the container stayed at the port too long.","exampleJa":"コンテナが港に長く留まったため、追加の滞船料を支払った。","hint":"港で荷物を置きっぱなしにすると課される「延滞料」。語尾-ageが料金の響き(連想)"},{"set":14,"word":"deviation","pos":"名詞","meaning":"逸脱、偏差","example":"Any deviation from the approved procedure must be reported to the manager.","exampleJa":"承認された手順からの逸脱は、すべて管理者に報告しなければならない。","hint":"道からそれる(deviate)こと。規格や計画から外れたズレ"},{"set":14,"word":"diagram","pos":"名詞","meaning":"図、図表","example":"The manual includes a diagram showing how to assemble the machine.","exampleJa":"マニュアルには、機械の組み立て方を示す図が載っている。","hint":"マニュアルの組み立て手順図。graph・gramと同じく「書く」系の語"},{"set":14,"word":"dispatch","pos":"動詞","meaning":"発送する","example":"We will dispatch your order within two business days of payment.","exampleJa":"お支払い後、2営業日以内にご注文の品を発送いたします。","hint":"配達員や救急車を現場へ送り出す場面。ship out と同じ動き"},{"set":14,"word":"downtime","pos":"名詞","meaning":"稼働停止時間","example":"Regular maintenance helps keep unexpected downtime to a minimum.","exampleJa":"定期的な保守は、予期せぬ稼働停止時間を最小限に抑えるのに役立つ。","hint":"サーバーや機械が「ダウン」している時間。対義語はuptime"},{"set":14,"word":"effluent","pos":"名詞","meaning":"排水、排出物","example":"The plant must treat its effluent before releasing it into the river.","exampleJa":"その工場は、排水を川に放流する前に処理しなければならない。","hint":"工場から川へ流れ出る排水。fluは「流れる」でinfluence・fluidと仲間"},{"set":14,"word":"emission","pos":"名詞","meaning":"排出","example":"The company aims to cut its greenhouse gas emissions by half.","exampleJa":"その会社は、温室効果ガスの排出量を半減させることを目指している。","hint":"排気ガスの数値目標でよく見る語。emit(出す)の名詞形で、通常は複数形"},{"set":14,"word":"flammable","pos":"形容詞","meaning":"可燃性の","example":"Flammable liquids should never be stored near the loading dock.","exampleJa":"可燃性の液体は、荷積み場の近くに保管してはならない。","hint":"flame(炎)が語幹。ガスや溶剤の容器に貼られる警告ラベルの語"},{"set":14,"word":"flaw","pos":"名詞","meaning":"欠陥","example":"Inspectors found a flaw in the design before mass production began.","exampleJa":"検査員は、量産が始まる前に設計上の欠陥を見つけた。","hint":"ガラスやダイヤの小さなヒビ。仕様書にはdefectと並んで出てくる"},{"set":14,"word":"forklift","pos":"名詞","meaning":"フォークリフト","example":"Only trained staff are allowed to operate a forklift in the warehouse.","exampleJa":"倉庫でフォークリフトを操作できるのは、訓練を受けた職員だけだ。","hint":"フォーク状の爪で荷を持ち上げる倉庫の車両。fork+liftそのまま"},{"set":14,"word":"fulfillment","pos":"名詞","meaning":"注文処理、物流対応","example":"Our fulfillment center ships orders to customers within twenty-four hours.","exampleJa":"当社の物流センターは、注文を24時間以内に顧客へ発送する。","hint":"通販の「フルフィルメント」。注文を受けてから発送まで満たす一連の流れ"},{"set":14,"word":"haul","pos":"動詞","meaning":"運搬する","example":"The company hauls construction materials to job sites across the region.","exampleJa":"その会社は、地域全体の工事現場へ建設資材を運搬している。","hint":"重い綱をぐいっと引く動作から。長距離トラックの「ロングホール」で覚える(連想)"},{"set":14,"word":"hazardous","pos":"形容詞","meaning":"危険な","example":"Hazardous materials require special permits for transport.","exampleJa":"危険物の輸送には、特別な許可が必要である。","hint":"hazard(危険)の形容詞形。hazardous wasteは危険物処理の頻出表現"},{"set":14,"word":"heat-resistant","pos":"形容詞","meaning":"耐熱性の","example":"The oven gloves are made of a heat-resistant fabric.","exampleJa":"そのオーブン用手袋は、耐熱性のある生地でできている。","hint":"オーブン皿や耐熱ガラスの表示。heat+resistantで「熱に強い」"},{"set":14,"word":"humidity","pos":"名詞","meaning":"湿度","example":"High humidity in the warehouse can damage the paper products.","exampleJa":"倉庫内の高い湿度は、紙製品を傷める可能性がある。","hint":"梅雨のむしむし感。倉庫の温度と並んで湿度管理の対象になる"},{"set":14,"word":"hydraulic","pos":"形容詞","meaning":"油圧の、水圧の","example":"The truck is equipped with a hydraulic lift for loading heavy crates.","exampleJa":"そのトラックには、重い木箱を積み込むための油圧リフトが付いている。","hint":"hydro(水)と同系。ショベルカーのアームを動かす油圧装置の場面"},{"set":14,"word":"hygiene","pos":"名詞","meaning":"衛生","example":"Good hygiene practices are essential in every food processing facility.","exampleJa":"どの食品加工施設でも、良好な衛生習慣が欠かせない。","hint":"「ハイジーン」と発音。手洗い・清潔を守る衛生。食品や医療の場面で頻出"},{"set":14,"word":"idle","pos":"形容詞","meaning":"稼働していない、遊休の","example":"Several machines stood idle during the shortage of raw materials.","exampleJa":"原材料不足の間、数台の機械が稼働していなかった。","hint":"「アイドリング」と同系の語。エンジンがかかっても動かない状態を連想"},{"set":14,"word":"intermodal","pos":"形容詞","meaning":"複合輸送の","example":"Intermodal shipping lets containers move between ships, trains, and trucks easily.","exampleJa":"複合輸送により、コンテナは船、鉄道、トラックの間を容易に移動できる。","hint":"inter(間)+modal。船→鉄道→トラックと手段を乗り換えて運ぶ輸送"},{"set":14,"word":"kitting","pos":"名詞","meaning":"部品のキット組み","example":"Kitting saves assembly workers time by grouping all required parts together.","exampleJa":"キット組みは、必要な部品をまとめることで組立作業員の時間を節約する。","hint":"組み立てキットのように、必要な部品を一箱にそろえる作業"},{"set":14,"word":"lading","pos":"名詞","meaning":"積荷","example":"The bill of lading must be signed before the goods are released.","exampleJa":"貨物が引き渡される前に、船荷証券に署名しなければならない。","hint":"bill of lading(船荷証券)の形でそのまま覚える。船に積んだ荷物の意"},{"set":14,"word":"lead-time","pos":"名詞","meaning":"発注から納品までの期間","example":"The supplier promised to shorten the lead-time for custom parts.","exampleJa":"供給業者は、特注部品のリードタイムを短縮すると約束した。","hint":"注文ボタンを押してから商品が届くまでの待ち時間"},{"set":14,"word":"lot-number","pos":"名詞","meaning":"ロット番号","example":"Please include the lot-number when you report a defective product.","exampleJa":"不良品を報告する際は、ロット番号を記載してください。","hint":"食品パッケージの端に印字された英数字。不具合時に製造分を特定する番号"},{"set":14,"word":"lubricant","pos":"名詞","meaning":"潤滑剤","example":"Apply a small amount of lubricant to the moving parts each week.","exampleJa":"毎週、可動部に少量の潤滑剤を塗ってください。","hint":"自転車のチェーンに差す油。lubricate(油を差す)の名詞形"},{"set":14,"word":"manifest","pos":"名詞","meaning":"積荷目録","example":"Customs officers checked the cargo manifest against the actual containers.","exampleJa":"税関職員は、積荷目録と実際のコンテナを照合した。","hint":"空港や船で「何を積んだか」を一覧にした書類。形容詞の「明白な」と同じ綴り"},{"set":14,"word":"mold","pos":"名詞","meaning":"金型、鋳型","example":"The factory spent months designing a new mold for the plastic casing.","exampleJa":"その工場は、プラスチック製ケースの新しい金型の設計に数か月を費やした。","hint":"たい焼きの型のように、溶けた材料を流して形を作る道具"},{"set":14,"word":"packing-list","pos":"名詞","meaning":"梱包明細書","example":"Please attach a packing-list to each box before sending it to customs.","exampleJa":"税関に送る前に、各箱へ梱包明細書を添付してください。","hint":"箱の中身を一覧にした紙。packing slipとも言う。請求書(invoice)と対で出てくる"},{"set":14,"word":"pallet","pos":"名詞","meaning":"パレット","example":"Workers stacked forty cartons on each pallet before wrapping them.","exampleJa":"作業員たちは、各パレットに段ボール箱を40箱積んでから包装した。","hint":"フォークリフトが差し込む木の台。「パレット」は絵の具のpaletteとは別の綴り"},{"set":14,"word":"pilferage","pos":"名詞","meaning":"小口盗難","example":"Tighter security measures have reduced pilferage in the warehouse.","exampleJa":"警備強化により、倉庫での小口盗難が減少した。","hint":"社員がペンや部品を少しずつ持ち帰る盗み。theftより「こそ泥」感覚(連想)"},{"set":14,"word":"pneumatic","pos":"形容詞","meaning":"空気圧の","example":"The assembly line uses pneumatic tools powered by compressed air.","exampleJa":"その組立ラインでは、圧縮空気で動く空気圧工具を使用している。","hint":"最初のpは発音しない「ニューマティック」。タイヤの「ニューマチック」と同じ語"},{"set":14,"word":"pollutant","pos":"名詞","meaning":"汚染物質","example":"The factory installed filters to remove pollutants from its exhaust.","exampleJa":"その工場は、排気から汚染物質を除去するためにフィルターを設置した。","hint":"pollute(汚す)+ant。大気や水を汚す物質の総称"},{"set":14,"word":"precision","pos":"名詞","meaning":"精密さ、精度","example":"Precision is critical when manufacturing components for medical devices.","exampleJa":"医療機器の部品を製造する際には、精密さが極めて重要である。","hint":"時計やレンズなど、ミクロン単位の誤差も許さない「精密機器」の精密さ"},{"set":14,"word":"procurement","pos":"名詞","meaning":"調達","example":"The procurement team negotiated lower prices with several suppliers.","exampleJa":"調達チームは、複数の供給業者と交渉して価格を引き下げた。","hint":"会社が必要な資材や物品を探して買い入れる仕事。購買部の業務"},{"set":14,"word":"quarantine","pos":"名詞","meaning":"検疫","example":"The imported fruit was held in quarantine until inspectors cleared it.","exampleJa":"輸入された果物は、検査官が問題なしと認めるまで検疫のため留め置かれた。","hint":"輸入した動植物や食品を、安全が確認されるまで隔離する場面。「検疫」と「隔離」の両方の意"},{"set":14,"word":"raw-material","pos":"名詞","meaning":"原材料","example":"Rising prices for raw-material are putting pressure on our profit margins.","exampleJa":"原材料の価格上昇が、当社の利益率を圧迫している。","hint":"raw(生の)は「生肉」のraw。まだ加工されていない素材"},{"set":14,"word":"recall","pos":"動詞","meaning":"回収する","example":"The manufacturer decided to recall thousands of faulty heaters.","exampleJa":"メーカーは、欠陥のある数千台のヒーターを回収することを決めた。","hint":"メーカーが欠陥品を「呼び戻す」ニュースの場面。re+callで直感的"},{"set":14,"word":"recondition","pos":"動詞","meaning":"修理・整備して再生する","example":"The company will recondition old engines and sell them at a discount.","exampleJa":"その会社は古いエンジンを整備して再生し、割引価格で販売する予定だ。","hint":"re+condition。中古品を点検・修理して新品同様の状態にする"},{"set":14,"word":"replenish","pos":"動詞","meaning":"補充する","example":"Staff replenish the shelves with new stock every morning.","exampleJa":"スタッフは毎朝、棚に新しい在庫を補充する。","hint":"コンビニが売れた棚を再び満たす場面。re+「満ちる」の系統"},{"set":14,"word":"requisition","pos":"名詞","meaning":"請求書、要求書","example":"You must submit a requisition before buying any new office equipment.","exampleJa":"新しい事務機器を購入する前に、購買申請書を提出しなければならない。","hint":"require(要求する)の仲間。社内で「これを買ってください」と出す申請書"},{"set":14,"word":"residue","pos":"名詞","meaning":"残留物","example":"Workers cleaned the tank to remove any chemical residue.","exampleJa":"作業員たちは、化学残留物を取り除くためにタンクを清掃した。","hint":"鍋の底に残る焦げのように、処理後も残るもの。resident(居残る人)と同系の響き(連想)"},{"set":14,"word":"retrofit","pos":"動詞","meaning":"改修する、後付けする","example":"We plan to retrofit the old factory with energy-efficient lighting.","exampleJa":"私たちは、古い工場に省エネ照明を後付けして改修する予定だ。","hint":"古い建物や機械に新技術を後付けする。retro(昔)の設備に新装備のイメージ(連想)"},{"set":14,"word":"robotics","pos":"名詞","meaning":"ロボット工学","example":"The firm invested heavily in robotics to automate its assembly lines.","exampleJa":"その会社は、組立ラインを自動化するためロボット工学に多額の投資をした。","hint":"robot+ics。physicsやeconomicsと同じ「〜学・〜分野」の語尾"},{"set":14,"word":"robust","pos":"形容詞","meaning":"頑丈な、堅牢な","example":"The company needs a robust system that can handle heavy online traffic.","exampleJa":"その会社には、多くのオンラインアクセスに耐えられる堅牢なシステムが必要だ。","hint":"「ロバスト」=ちょっとやそっとでは壊れない。システムやデザインに使う"},{"set":14,"word":"rugged","pos":"形容詞","meaning":"頑丈な、タフな","example":"The tablet has a rugged case designed for use on construction sites.","exampleJa":"そのタブレットには、建設現場での使用を想定した頑丈なケースが付いている。","hint":"「ラグ」ッとした岩山のようなごつごつ感。アウトドア用の頑丈な機器に使う(連想)"},{"set":14,"word":"rustproof","pos":"形容詞","meaning":"錆びない","example":"The bolts are coated with a rustproof finish for outdoor installation.","exampleJa":"そのボルトは、屋外設置用に錆を防ぐ仕上げが施されている。","hint":"rust(錆)+proof(〜を通さない)。waterproofの錆版"},{"set":14,"word":"safeguard","pos":"動詞","meaning":"保護する","example":"New regulations aim to safeguard workers from dangerous chemicals.","exampleJa":"新しい規制は、危険な化学物質から作業員を守ることを目的としている。","hint":"safe+guard。ルールや仕組みで守る。名詞の「保護策」でも頻出"},{"set":14,"word":"sanitation","pos":"名詞","meaning":"衛生管理","example":"The inspector praised the plant for its high standards of sanitation.","exampleJa":"検査官は、その工場の高い衛生管理基準を称賛した。","hint":"sanitary(衛生的な)の名詞形。ゴミ処理・下水など公衆衛生の場面"},{"set":14,"word":"schematic","pos":"名詞","meaning":"概略図、回路図","example":"The engineer reviewed the electrical schematic before repairing the control panel.","exampleJa":"技術者は、制御盤を修理する前に電気回路図を確認した。","hint":"回路や配管を記号で簡略に示した図。diagramの技術者向けバージョン"},{"set":14,"word":"scrap","pos":"名詞","meaning":"くず、廃材","example":"The plant recycles scrap from the cutting process into new products.","exampleJa":"その工場は、切断工程で出た廃材を再利用して新製品にしている。","hint":"解体現場の鉄くず。「スクラップ&ビルド」の「スクラップ」"},{"set":14,"word":"sensor","pos":"名詞","meaning":"センサー、感知装置","example":"A temperature sensor stops the machine when it becomes too hot.","exampleJa":"温度センサーは、機械が熱くなりすぎると機械を停止させる。","hint":"sense(感じる)+or。自動ドアや温度計など、変化を感じ取る部品"},{"set":14,"word":"serial","pos":"形容詞","meaning":"一連の、連続の","example":"Please enter the serial number printed on the back of the device.","exampleJa":"機器の裏面に印字されているシリアル番号を入力してください。","hint":"series(連続)の形容詞形。製品ごとに連番が振られるserial numberで覚える"},{"set":14,"word":"shrink-wrap","pos":"動詞","meaning":"収縮包装する","example":"Workers shrink-wrap each pallet to protect the goods during transport.","exampleJa":"作業員は、輸送中に商品を守るため、各パレットを収縮包装する。","hint":"CDやパレットを覆う透明フィルム。熱を当てるとキュッと縮んで密着"},{"set":14,"word":"shrinkage","pos":"名詞","meaning":"目減り、棚卸減耗","example":"Retail shrinkage cost the chain millions of dollars last year.","exampleJa":"小売店の棚卸減耗は、昨年そのチェーンに数百万ドルの損失を与えた。","hint":"shrink(縮む)の名詞形。帳簿上の在庫より実在庫が減る、万引き・紛失による損失"},{"set":14,"word":"spoilage","pos":"名詞","meaning":"腐敗、劣化損失","example":"Better refrigeration helped the grocer reduce spoilage of fresh produce.","exampleJa":"冷蔵設備の改善により、その食料品店は生鮮品の劣化による損失を減らせた。","hint":"spoil(だめにする)+age。冷蔵が壊れて生鮮品が傷む損失"},{"set":14,"word":"stainless","pos":"形容詞","meaning":"さびない、ステンレスの","example":"The kitchen equipment is made of stainless steel for easy cleaning.","exampleJa":"その厨房機器は、掃除しやすいようステンレス鋼で作られている。","hint":"stain(汚れ・錆)+less。キッチンのステンレス流しを思い浮かべる"},{"set":14,"word":"sterile","pos":"形容詞","meaning":"滅菌された、無菌の","example":"Surgical tools must be kept in a sterile package until they are used.","exampleJa":"手術器具は、使用するまで無菌の包装に入れておかなければならない。","hint":"手術室や注射針の「無菌」状態。病院のドラマの場面で"},{"set":14,"word":"sturdy","pos":"形容詞","meaning":"頑丈な","example":"Please use a sturdy box to ship heavy items overseas.","exampleJa":"重い品物を海外へ送る際は、頑丈な箱を使ってください。","hint":"「スターディ」=どっしり安定。sturdy shelf, sturdy boxなど家具・容器に使う"},{"set":14,"word":"surplus","pos":"名詞","meaning":"余剰在庫","example":"The retailer sold its surplus stock at a deep discount.","exampleJa":"その小売業者は、余剰在庫を大幅な割引価格で販売した。","hint":"sur(超えて)+plus。需要を超えた余り。deficit(不足)と対"},{"set":14,"word":"tanker","pos":"名詞","meaning":"タンカー船","example":"A tanker carrying fuel arrived at the port on Monday morning.","exampleJa":"燃料を積んだタンカーが、月曜の朝に港へ到着した。","hint":"tank(タンク)+er。石油や化学薬品を液体のまま運ぶ船やトラック"},{"set":14,"word":"throughput","pos":"名詞","meaning":"処理能力","example":"The new equipment will double the throughput of our packaging line.","exampleJa":"新しい設備により、当社の包装ラインの処理能力は2倍になる。","hint":"through(通過)+put。一定時間にどれだけ流せるか。工場やネットワークの能力"},{"set":14,"word":"tolerance","pos":"名詞","meaning":"公差、許容範囲","example":"The parts must be cut within a tolerance of 0.1 millimeters.","exampleJa":"その部品は、0.1ミリの公差内で切断されなければならない。","hint":"tolerate(許容する)の名詞形。設計寸法からのズレをどこまで許すか"},{"set":14,"word":"tooling","pos":"名詞","meaning":"治工具一式","example":"Changing the tooling for the new model took nearly three weeks.","exampleJa":"新モデル用の治工具の交換に、ほぼ3週間かかった。","hint":"tool(工具)の集合。金型・治具・工具など生産準備の設備全体"},{"set":14,"word":"toxic","pos":"形容詞","meaning":"有毒な","example":"Toxic waste must be disposed of according to strict regulations.","exampleJa":"有毒廃棄物は、厳格な規制に従って処分しなければならない。","hint":"「トキシック」=毒性。ドクロマークの警告ラベルを連想"},{"set":14,"word":"traceability","pos":"名詞","meaning":"追跡可能性、トレーサビリティ","example":"Traceability allows us to identify the source of a contaminated ingredient quickly.","exampleJa":"トレーサビリティにより、汚染された原料の出どころをすばやく特定できる。","hint":"trace(たどる)+ability。商品の産地や製造履歴を後からさかのぼれる性質"},{"set":14,"word":"transit","pos":"名詞","meaning":"輸送中、通過","example":"The package was damaged while in transit between the two warehouses.","exampleJa":"その荷物は、2つの倉庫の間を輸送中に破損した。","hint":"trans(越えて)の仲間。「トランジット」は空港の乗り継ぎ。荷物は途中の状態"},{"set":14,"word":"truckload","pos":"名詞","meaning":"トラック1台分の積荷","example":"We ordered a full truckload of building materials for the new site.","exampleJa":"私たちは新しい現場用に、建築資材をトラック1台分注文した。","hint":"truck+load。荷台いっぱいの量。LTL(小口混載)と対比"},{"set":14,"word":"turnaround","pos":"名詞","meaning":"対応時間、転換","example":"The print shop promises a two-day turnaround on all orders.","exampleJa":"その印刷店は、すべての注文を2日で仕上げると約束している。","hint":"依頼を受けて仕上げて返すまでの所要時間。turn around(回して返す)の感覚"},{"set":14,"word":"uptime","pos":"名詞","meaning":"稼働時間","example":"The IT team guarantees ninety-nine percent uptime for the online store.","exampleJa":"IT部門は、オンラインストアの稼働率99パーセントを保証している。","hint":"up(動いている)+time。downtimeの反対で、稼働率を示す指標"},{"set":14,"word":"variance","pos":"名詞","meaning":"差異、分散","example":"The finance manager explained the variance between budgeted and actual expenses.","exampleJa":"財務部長は、予算と実際の経費の差異について説明した。","hint":"vary(変わる)の名詞形。会計では予算と実績の「差異」"},{"set":14,"word":"volatile","pos":"形容詞","meaning":"揮発性の、変動しやすい","example":"Volatile oil prices make it difficult to plan long-term budgets.","exampleJa":"変動の激しい原油価格のせいで、長期予算を立てるのは難しい。","hint":"アルコールのようにすぐ蒸発する性質。転じて相場が荒れる「不安定」の意でも使う"},{"set":14,"word":"waterproof","pos":"形容詞","meaning":"防水の","example":"The jacket has a waterproof coating that keeps hikers dry in heavy rain.","exampleJa":"そのジャケットには防水加工が施されており、大雨でもハイカーを濡らさない。","hint":"water+proof。スマホやジャケットの「防水」表示。proofは「〜を通さない」"},{"set":14,"word":"waybill","pos":"名詞","meaning":"運送状","example":"The driver handed the signed waybill to the receiving clerk.","exampleJa":"運転手は、署名済みの運送状を受け取り担当の事務員に手渡した。","hint":"way(道)+bill(書類)。荷物に付く運送状で、宅配の送り状の仲間"},{"set":15,"word":"abstain","pos":"動詞","meaning":"棄権する、控える","example":"Two board members chose to abstain from the vote on the merger proposal.","exampleJa":"取締役のうち2名は、合併案の採決を棄権することにした。","hint":"abstain from ～で「～を控える」。採決で手を挙げず、賛成にも反対にも回らない場面を思い浮かべる。"},{"set":15,"word":"adjourn","pos":"動詞","meaning":"休会する、中断する","example":"The chairperson decided to adjourn the meeting until Thursday morning.","exampleJa":"議長は会議を木曜の朝まで休会することに決めた。","hint":"議長が「本日はここまで」と宣言する場面。adjourn the meeting は会議終了の決まり文句。"},{"set":15,"word":"all-inclusive","pos":"形容詞","meaning":"全て込みの","example":"The all-inclusive rate covers accommodation, meals, and airport transfers for every guest.","exampleJa":"その全て込みの料金には、全宿泊客の宿泊費、食事代、空港送迎が含まれている。","hint":"「全部入り」のイメージ。宿泊・食事・飲み物まで料金に含む旅行プランの広告でよく見る。"},{"set":15,"word":"allergy","pos":"名詞","meaning":"アレルギー","example":"Please inform the caterer of any food allergy before the banquet on Friday.","exampleJa":"金曜の宴会の前に、食物アレルギーがあればケータリング業者にお知らせください。","hint":"社員食堂や機内食の注文で必ず確認される項目。have an allergy to ～ の形で覚える。"},{"set":15,"word":"ambience","pos":"名詞","meaning":"雰囲気、環境の感じ","example":"Guests praised the hotel restaurant for its elegant ambience and attentive staff.","exampleJa":"宿泊客は、そのホテルのレストランの上品な雰囲気と行き届いたスタッフを称賛した。","hint":"レストランやホテルの口コミに頻出。照明・音楽・内装が作る「居心地の空気感」を思い浮かべる。"},{"set":15,"word":"appease","pos":"動詞","meaning":"なだめる","example":"The manager offered a full refund to appease the dissatisfied customer.","exampleJa":"マネージャーは不満を抱く顧客をなだめるため、全額返金を申し出た。","hint":"「ピース」の音に注目し、怒りの火を静めて場を穏やかにするイメージ（音の連想）。"},{"set":15,"word":"badge","pos":"名詞","meaning":"名札、バッジ","example":"All visitors must wear a badge while they are inside the building.","exampleJa":"来訪者は全員、建物内にいる間はバッジを着用しなければならない。","hint":"受付で渡される入館証・名札。展示会では首から下げて入場する場面を思い浮かべる。"},{"set":15,"word":"bellhop","pos":"名詞","meaning":"ホテルのボーイ","example":"A bellhop carried our luggage to the room on the twelfth floor.","exampleJa":"ボーイが私たちの荷物を12階の部屋まで運んでくれた。","hint":"ホテルのロビーで荷物をカートに載せて部屋まで運んでくれる係。bell+hop の合成語と見ると覚えやすい。"},{"set":15,"word":"boarding-pass","pos":"名詞","meaning":"搭乗券","example":"Please have your boarding-pass and passport ready at the security checkpoint.","exampleJa":"保安検査場では、搭乗券とパスポートをご用意ください。","hint":"空港の保安検査場とゲートで必ず提示する紙（またはスマホ画面）。搭乗口で見せる場面で覚える。"},{"set":15,"word":"buffet","pos":"名詞","meaning":"ビュッフェ","example":"The conference fee includes a lunch buffet in the main hall.","exampleJa":"会議の参加費には、メインホールでの昼食ビュッフェが含まれている。","hint":"ホテルの朝食会場で好きな料理を皿に取る場面。アクセントは「ブッフェイ」と後ろ。"},{"set":15,"word":"bump","pos":"動詞","meaning":"予約客を別便に回す","example":"The airline had to bump several passengers because the flight was oversold.","exampleJa":"便が予約超過だったため、航空会社は数名の乗客を別便に回さなければならなかった。","hint":"ぶつかって押し出されるイメージ。満席の便で乗客が「席から押し出される」と考える。"},{"set":15,"word":"carry-on","pos":"名詞","meaning":"機内持ち込み手荷物","example":"Each passenger may bring one carry-on bag onto the aircraft free of charge.","exampleJa":"乗客は各自、機内持ち込み手荷物を1個まで無料で機内に持ち込める。","hint":"「持って乗る」荷物。機内の頭上の棚に入れる小さなバッグを思い浮かべる。"},{"set":15,"word":"chauffeur","pos":"名詞","meaning":"専属運転手","example":"The company sent a chauffeur to meet the visiting executives at the airport.","exampleJa":"会社は来訪した役員たちを空港で出迎えるため、専属運転手を差し向けた。","hint":"「ショーファー」と読む。要人を高級車の後部座席に乗せて運転する制服姿の人を想像する。"},{"set":15,"word":"cocktail","pos":"名詞","meaning":"カクテルパーティー","example":"A cocktail hour for all attendees will follow the keynote address.","exampleJa":"基調講演のあとは、全出席者を対象としたカクテルパーティーが開かれる。","hint":"飲み物だけでなく「立食の懇親会」の意味も。cocktail reception は歓迎会の定番表現。"},{"set":15,"word":"commemorate","pos":"動詞","meaning":"記念する","example":"The firm will hold a ceremony to commemorate its fiftieth anniversary.","exampleJa":"その会社は創業50周年を記念する式典を開く予定だ。","hint":"memo（メモ）と同じ「記憶」の響き。記念碑や記念式典で出来事を忘れず残すイメージ。"},{"set":15,"word":"concierge","pos":"名詞","meaning":"コンシェルジュ","example":"The concierge booked a table at a nearby restaurant for our client dinner.","exampleJa":"コンシェルジュが、顧客との夕食のために近くのレストランの席を予約してくれた。","hint":"ホテルのロビーデスクで、レストラン予約や観光の相談に乗ってくれる「何でも相談係」。"},{"set":15,"word":"congestion","pos":"名詞","meaning":"混雑、渋滞","example":"Heavy congestion on the highway made several employees late for the morning briefing.","exampleJa":"高速道路の激しい渋滞のせいで、何人かの従業員が朝の説明会に遅れた。","hint":"道路や空港、ネット回線が「ぎゅうぎゅう詰めで流れない」状態。traffic congestion で一語のように覚える。"},{"set":15,"word":"consulate","pos":"名詞","meaning":"領事館","example":"You can renew your passport at the consulate in downtown Chicago.","exampleJa":"パスポートはシカゴ中心部の領事館で更新できる。","hint":"embassy（大使館）との対比で覚える。大使館は首都、領事館は主要都市でビザや邸人保護を扱うことが多い。"},{"set":15,"word":"courteous","pos":"形容詞","meaning":"礼儀正しい","example":"The front desk staff were courteous and handled every request promptly.","exampleJa":"フロントのスタッフは礼儀正しく、あらゆる依頼に迅速に対応してくれた。","hint":"「コーティアス」と読む。接客評価のアンケートで polite と並んで出る褒め言葉。"},{"set":15,"word":"defuse","pos":"動詞","meaning":"緊張を和らげる","example":"A calm apology helped defuse the tension between the two departments.","exampleJa":"冷静な謝罪が、二つの部署の間の緊張を和らげるのに役立った。","hint":"爆弾の信管を外す映像から、対立や怒りの「爆発前に火を消す」比喩へ。defuse tension が定番。"},{"set":15,"word":"denomination","pos":"名詞","meaning":"額面、単位","example":"The exchange counter provides foreign currency in small denominations on request.","exampleJa":"両替所では、ご希望に応じて外貨を小額の紙幣や硬貨でお渡しします。","hint":"紙幣・硬貨の「1ドル札、5ドル札」といった種類の区分。両替窓口で聞かれる語として覚える。"},{"set":15,"word":"dietary","pos":"形容詞","meaning":"食事の","example":"Please let us know about any dietary needs when you register for the seminar.","exampleJa":"セミナーに登録する際は、食事面での要望があればお知らせください。","hint":"diet（食事）の形容詞形。dietary restrictions は出張手配やパーティー案内で必ず出る組み合わせ。"},{"set":15,"word":"dignitary","pos":"名詞","meaning":"要人、高官","example":"Security was tightened as several foreign dignitaries arrived for the summit.","exampleJa":"サミットのために外国の要人が数名到着し、警備が強化された。","hint":"dignity（威厳）に近い響きで、式典の最前列に座る大物。visiting dignitaries の形で出やすい。"},{"set":15,"word":"diplomatic","pos":"形容詞","meaning":"外交の、如才ない","example":"She gave a diplomatic answer to avoid offending the clients.","exampleJa":"彼女は顧客の気分を害さないよう、如才ない返答をした。","hint":"外交官のように角を立てない言い方をするイメージ。「外交の」と「如才ない」の二つの意味を対にする。"},{"set":15,"word":"divert","pos":"動詞","meaning":"迂回させる、転換する","example":"Bad weather forced the airline to divert the flight to a nearby airport.","exampleJa":"悪天候のため、航空会社は便を近隣の空港に迂回させざるを得なかった。","hint":"工事で道路が通行止めになり、車が別ルートへ誘導される場面。divert A to B の形で使う。"},{"set":15,"word":"doorman","pos":"名詞","meaning":"ドアマン","example":"The doorman hailed a taxi for the guests waiting outside the hotel.","exampleJa":"ドアマンは、ホテルの外で待つ宿泊客のためにタクシーを呼び止めた。","hint":"ホテルの正面玄関に立ち、ドアを開けてタクシーを呼んでくれる制服姿の人。"},{"set":15,"word":"double-book","pos":"動詞","meaning":"二重予約する","example":"The assistant apologized for having double-booked the conference room on Monday.","exampleJa":"アシスタントは、月曜日に会議室を二重予約してしまったことを謝罪した。","hint":"同じ時間に二つの予定を入れてしまうミス。カレンダーや会議室予約でありがちな失敗として覚える。"},{"set":15,"word":"dry-cleaning","pos":"名詞","meaning":"ドライクリーニング","example":"The hotel offers same-day dry-cleaning for business suits and formal shirts.","exampleJa":"そのホテルでは、ビジネススーツやフォーマルシャツの当日ドライクリーニングを行っている。","hint":"出張中にスーツのしわや汚れを頼むホテルのサービス。洗剤液で洗うので水で洗わない、と覚える。"},{"set":15,"word":"embassy","pos":"名詞","meaning":"大使館","example":"The embassy will host a reception for local business leaders next month.","exampleJa":"大使館は来月、地元の経済界の指導者を招いてレセプションを開く。","hint":"ビザやパスポートの相談で訪れる、自国の外交拠点。consulate との違いも合わせて整理する。"},{"set":15,"word":"empathy","pos":"名詞","meaning":"共感","example":"Good customer service representatives show empathy when handling complaints.","exampleJa":"優れた顧客対応担当者は、苦情に対応するとき共感を示す。","hint":"クレーム対応研修で必ず出る語。相手の気持ちを「自分のことのように感じる」力。sympathy は「同情」と対比。"},{"set":15,"word":"envoy","pos":"名詞","meaning":"使節、特使","example":"The president appointed a special envoy to lead the trade negotiations.","exampleJa":"大統領は貿易交渉を率いる特使を任命した。","hint":"首脳の代わりに他国へ送り出される代表者。special envoy（特使）で覚える。"},{"set":15,"word":"escalate","pos":"動詞","meaning":"上位に報告する、拡大する","example":"Agents should escalate unresolved complaints to a supervisor within one hour.","exampleJa":"担当者は、未解決の苦情を1時間以内に上司へ引き上げるべきだ。","hint":"自分で解決できない問題を、より上の担当者へ「段階を上げて」回す。escalate A to B の形で使う。"},{"set":15,"word":"etiquette","pos":"名詞","meaning":"礼儀作法","example":"The training session covers basic etiquette for international business meetings.","exampleJa":"その研修では、国際的なビジネス会議における基本的なマナーを扱う。","hint":"名刺交換や会食でのふるまい方。business etiquette は研修やマナー本の定番タイトル。"},{"set":15,"word":"excursion","pos":"名詞","meaning":"小旅行、遠足","example":"Participants can join an optional excursion to the harbor on Saturday afternoon.","exampleJa":"参加者は、土曜の午後に港へ出かける希望制の小旅行に加われる。","hint":"会議の合間や出張先で参加する観光ツアー。日帰りの「ちょっとした遠出」の感覚。"},{"set":15,"word":"forum","pos":"名詞","meaning":"討論会、フォーラム","example":"The city will host a forum where residents can discuss the new transit plan.","exampleJa":"市は、住民が新しい交通計画について話し合える討論会を開催する。","hint":"オンラインの掲示板も、会場での公開討論会も指す。意見を持ち寄る「広場」のイメージ。"},{"set":15,"word":"gracious","pos":"形容詞","meaning":"丁重な、上品な","example":"We are grateful for your gracious hospitality during our stay in Boston.","exampleJa":"ボストン滞在中の丁重なおもてなしに感謝申し上げます。","hint":"grace（優雅さ）の形容詞形。お礼状や招待への返事で「ご丁重なおもてなし」と言う感覚。"},{"set":15,"word":"gratuity","pos":"名詞","meaning":"チップ、謝礼","example":"A fifteen percent gratuity is automatically added for parties of six or more.","exampleJa":"6名様以上のグループには、15パーセントのチップが自動的に加算されます。","hint":"grateful（感謝している）と同じ「感」の響き。請求書に service charge と並んで載る心付け。"},{"set":15,"word":"gridlock","pos":"名詞","meaning":"交通の完全停滞","example":"Gridlock downtown delayed the delivery trucks by nearly three hours this morning.","exampleJa":"今朝は中心街の交通完全停滞により、配送トラックが3時間近く遅れた。","hint":"碁盤の目の交差点で、車が互いに塞ぎ合って全く動けない状態。"},{"set":15,"word":"head-table","pos":"名詞","meaning":"主賓席","example":"The company president and the guest speaker will sit at the head-table.","exampleJa":"社長とゲストスピーカーは主賓席に着く予定だ。","hint":"披露宴や表彰式で会場の正面に置かれ、主役や来賓が着く特別なテーブル。"},{"set":15,"word":"helpline","pos":"名詞","meaning":"相談窓口","example":"Employees can call the helpline at any time to report a technical problem.","exampleJa":"従業員は、技術的な問題を報告するためにいつでも相談窓口へ電話できる。","hint":"困ったときに電話する窓口。製品サポートや社員の相談など、call the helpline で使う。"},{"set":15,"word":"hotline","pos":"名詞","meaning":"直通電話","example":"The bank has set up a hotline for customers who lose their credit cards.","exampleJa":"その銀行は、クレジットカードを紛失した顧客のための直通電話を設置した。","hint":"緊急時や重要顧客用に、番号を回さずすぐ担当者へつながる専用回線のイメージ。"},{"set":15,"word":"housekeeping","pos":"名詞","meaning":"客室清掃","example":"Housekeeping will clean your room between ten a.m. and two p.m. daily.","exampleJa":"客室清掃係は、毎日午前10時から午後2時の間にお部屋を清掃します。","hint":"ホテルでベッドメイクやタオル交換をしてくれる部門。ドアノブの札と一緒に覚える。"},{"set":15,"word":"icebreaker","pos":"名詞","meaning":"緊張をほぐす話題","example":"The facilitator opened the workshop with a short icebreaker to help everyone relax.","exampleJa":"進行役は、全員がくつろげるよう短いアイスブレイクでワークショップを始めた。","hint":"初対面で凍りついた空気を「割る」軽いゲームや自己紹介。研修の冒頭で使う。"},{"set":15,"word":"immigration","pos":"名詞","meaning":"出入国審査、移民","example":"After landing, we waited forty minutes in line at immigration.","exampleJa":"着陸後、私たちは入国審査の列で40分待った。","hint":"入国時にパスポートを見せる窓口の列。「入ってくる」移民とセットで、入国管理の意味も押さえる。"},{"set":15,"word":"in-flight","pos":"形容詞","meaning":"機内の","example":"The airline plans to improve its in-flight Wi-Fi service next year.","exampleJa":"その航空会社は来年、機内Wi-Fiサービスを改善する計画だ。","hint":"飛行機に乗っている最中のサービスを表す。in-flight meal, in-flight magazine と一緒に覚える。"},{"set":15,"word":"inaugurate","pos":"動詞","meaning":"開始する、就任させる","example":"The mayor will inaugurate the new convention center at a ceremony on Monday.","exampleJa":"市長は月曜日の式典で、新しいコンベンションセンターの開所式を行う予定だ。","hint":"テープカットや就任式のように、新しい施設・制度・人物を正式にスタートさせる場面。"},{"set":15,"word":"interpreter","pos":"名詞","meaning":"通訳者","example":"An interpreter will assist during the negotiations with the overseas supplier.","exampleJa":"海外の供給業者との交渉の間は、通訳者が補助する。","hint":"会議の場で「話し言葉」を訳す人。文書を訳す translator との対比で覚える。"},{"set":15,"word":"irate","pos":"形容詞","meaning":"激怒した","example":"An irate customer called the help desk to complain about the late delivery.","exampleJa":"激怒した顧客が、配達の遅れに苦情を言うためヘルプデスクに電話してきた。","hint":"ire（怒り）系の語で、angry より強く、電話口でまくし立てる顧客のイメージ。"},{"set":15,"word":"jet-lag","pos":"名詞","meaning":"時差ぼけ","example":"She scheduled no meetings on her first day to recover from jet-lag.","exampleJa":"彼女は時差ぼけから回復するため、到着初日には会議を入れなかった。","hint":"海外出張の翌日に、頭が重く昼間に眠くなる状態。jet（飛行機）で時間がずれる、と見る。"},{"set":15,"word":"lanyard","pos":"名詞","meaning":"首から下げる紐","example":"Please wear the lanyard around your neck so that security can see your ID.","exampleJa":"警備員がIDを確認できるよう、ストラップを首から下げてください。","hint":"展示会やオフィスで、ID カードを首から下げるための紐。badge とセットで覚える。"},{"set":15,"word":"layover","pos":"名詞","meaning":"乗り継ぎ、途中降機","example":"We had a three-hour layover in Frankfurt before the connecting flight to Tokyo.","exampleJa":"私たちは東京への接続便に乗る前に、フランクフルトで3時間の乗り継ぎ待ちがあった。","hint":"乗り継ぎ便を待つ数時間。長いと空港で一休みする。stopover は宿泊を伴う長めの立ち寄りというニュアンスの違い。"},{"set":15,"word":"lectern","pos":"名詞","meaning":"演台","example":"The speaker placed her notes on the lectern and began her presentation.","exampleJa":"講演者は演台にメモを置き、プレゼンテーションを始めた。","hint":"スピーカーが原稿を置いて話す小さな台。podium は立つ壇、lectern は原稿を載せる台という対比。"},{"set":15,"word":"legroom","pos":"名詞","meaning":"脚を伸ばすスペース","example":"Passengers in the exit row enjoy more legroom than those in other seats.","exampleJa":"非常口の列の乗客は、他の座席の乗客より脚を伸ばせるスペースが広い。","hint":"飛行機の座席で、前の席との間に脚が伸ばせる余裕。extra legroom は座席指定の追加料金でよく見る。"},{"set":15,"word":"limousine","pos":"名詞","meaning":"リムジン","example":"The hotel arranged a limousine to take the board members to the airport.","exampleJa":"ホテルは、取締役たちを空港まで送るためにリムジンを手配した。","hint":"空港と高級ホテルを結ぶ、車体の長い黒塗りの送迎車。長い車体のイメージで覚える。"},{"set":15,"word":"minibar","pos":"名詞","meaning":"ミニバー","example":"Items taken from the minibar will be charged to your room account.","exampleJa":"ミニバーから取り出した品は、お部屋の勘定に請求されます。","hint":"客室内の小型冷蔵庫。取り出すと宿泊費に加算されるので、チェックアウト時の請求書と結びつける。"},{"set":15,"word":"mixer","pos":"名詞","meaning":"懇親会","example":"Newcomers can meet industry leaders at the networking mixer on Thursday evening.","exampleJa":"新規参加者は、木曜夜の交流懇親会で業界の指導者たちと会える。","hint":"mix（混ざる）人の集まり。業界の人が名刺を手に歩き回って交流する、気軽な懇親会。"},{"set":15,"word":"moderator","pos":"名詞","meaning":"司会者、進行役","example":"The moderator asked each panelist to keep their remarks under five minutes.","exampleJa":"司会者は、各パネリストに発言を5分以内に収めるよう求めた。","hint":"パネル討論の真ん中に座り、質問を振って時間配分も管理する人。moderate（調整する）の人。"},{"set":15,"word":"motion","pos":"名詞","meaning":"動議","example":"A board member made a motion to postpone the decision until next quarter.","exampleJa":"取締役の一人が、決定を来四半期まで延期する動議を出した。","hint":"議事で「動議を出します」と言って議論を動かし始める場面。move that ～ とも関連。"},{"set":15,"word":"no-show","pos":"名詞","meaning":"無断欠席","example":"The restaurant charges a fee to guests who are no-shows without notice.","exampleJa":"そのレストランは、連絡なしに現れなかった客に料金を請求する。","hint":"予約したのに「姿を見せない人」。レストランやホテルでキャンセル料が発生する原因。"},{"set":15,"word":"nonstop","pos":"形容詞","meaning":"直行の","example":"There is a nonstop flight from Seattle to Tokyo every morning.","exampleJa":"シアトルから東京へは、毎朝直行便がある。","hint":"途中で降りず、そのまま目的地へ。nonstop flight は直行便の決まり文句。"},{"set":15,"word":"outage","pos":"名詞","meaning":"供給停止","example":"A network outage prevented staff from accessing the system for two hours.","exampleJa":"ネットワークの障害により、スタッフは2時間システムに接続できなかった。","hint":"電気・水道・ネットなどが一時的に「供給されない」こと。power outage, network outage で覚える。"},{"set":15,"word":"overbook","pos":"動詞","meaning":"予約を定員以上に取る","example":"Airlines sometimes overbook flights because some passengers fail to show up.","exampleJa":"一部の乗客が現れないため、航空会社は時に便を定員以上に予約で受け付ける。","hint":"定員を超えてしまう over。ホテルや航空会社が欠席を見越して座席より多く売る場面。"},{"set":15,"word":"overhead","pos":"名詞","meaning":"諸経費、間接費","example":"Moving to a smaller office should significantly reduce our overhead.","exampleJa":"より小さなオフィスに移れば、当社の諸経費は大幅に減るはずだ。","hint":"頭上＝上にのしかかる経費、と考える。家賃・光熱費など、製品に直接結びつかない費用。"},{"set":15,"word":"pacify","pos":"動詞","meaning":"落ち着かせる、なだめる","example":"The supervisor quickly pacified the upset guest by moving him to a better room.","exampleJa":"上司は動揺した客をより良い部屋に移して、すばやくなだめた。","hint":"pac は「平和」を連想させる音（pacific と同じ響き）。泣く子や怒る客を静める。"},{"set":15,"word":"panelist","pos":"名詞","meaning":"パネリスト、討論参加者","example":"Each panelist will give a brief introduction before the discussion begins.","exampleJa":"討論が始まる前に、各パネリストが簡単な自己紹介を行う。","hint":"パネルディスカッションの壇上に並んで座る専門家。moderator（司会）との役割の違いで覚える。"},{"set":15,"word":"place-card","pos":"名詞","meaning":"席札","example":"The organizer set a place-card at each seat before the guests arrived.","exampleJa":"主催者は、客が到着する前に各席に席札を置いた。","hint":"晩餐会でテーブルに置かれる名前入りの小さなカード。自分の席がすぐ分かる。"},{"set":15,"word":"plenary","pos":"形容詞","meaning":"全体会議の","example":"All delegates are required to attend the plenary session on the first morning.","exampleJa":"全代表者は、初日午前の全体会議に出席する必要がある。","hint":"分科会ではなく、全参加者が一堂に会する会。plenary session は学会や国際会議の頻出表現。"},{"set":15,"word":"podium","pos":"名詞","meaning":"演壇","example":"The CEO walked up to the podium and thanked the audience for coming.","exampleJa":"CEOは演壇に歩み出て、来場者に感謝を述べた。","hint":"講演者が立つ一段高い壇。「ポディアム」と読み、表彰台の意味もある。"},{"set":15,"word":"porter","pos":"名詞","meaning":"ポーター、荷物運び係","example":"A porter helped us load the heavy equipment cases onto the cart.","exampleJa":"ポーターが、重い機材ケースをカートに積むのを手伝ってくれた。","hint":"駅や空港、ホテルで大きな荷物を運んでくれる人。port（運ぶ）を含む語、と覚える（transport と同じ要素）。"},{"set":15,"word":"proceedings","pos":"名詞","meaning":"議事録、会議録","example":"The proceedings of the annual conference will be published online next spring.","exampleJa":"年次会議の議事録は、来春オンラインで公開される予定だ。","hint":"必ず複数形。学会の発表をまとめた論文集や、会議の公式記録として使う。"},{"set":15,"word":"protocol","pos":"名詞","meaning":"儀礼、正式な手順","example":"Staff must follow safety protocol whenever they enter the laboratory.","exampleJa":"職員は研究室に入るときはいつも、安全手順に従わなければならない。","hint":"外交の場や社内で「このとおりにやる」と決められた作法・手順。follow protocol で覚える。"},{"set":15,"word":"proxy","pos":"名詞","meaning":"代理人、代理権","example":"Shareholders who cannot attend the meeting may vote by proxy.","exampleJa":"会議に出席できない株主は、代理人を通じて投票できる。","hint":"株主総会に出られない人が委任状で他人に投票を任せる場面。by proxy で「代理で」。"},{"set":15,"word":"quorum","pos":"名詞","meaning":"定足数","example":"The meeting could not begin because the board failed to reach a quorum.","exampleJa":"取締役会が定足数に達しなかったため、会議を始められなかった。","hint":"人数が足りないと、会議を開いても決議できない。「成立に必要な最低人数」と覚える。"},{"set":15,"word":"recompense","pos":"名詞","meaning":"補償、報酬","example":"The airline offered travel vouchers as recompense for the long delay.","exampleJa":"航空会社は、長時間の遅延に対する補償として旅行バウチャーを提供した。","hint":"遅延や損害に対して、お詫びとして払う「埋め合わせ」。compensation と近い意味で言い換える。"},{"set":15,"word":"rectify","pos":"動詞","meaning":"是正する、正す","example":"We will rectify the billing error and send you a corrected invoice.","exampleJa":"当社は請求の誤りを是正し、訂正した請求書をお送りします。","hint":"rect は「まっすぐ」を表す（correct と同じ響き）。曲がった間違いをまっすぐに直すイメージ。"},{"set":15,"word":"red-eye","pos":"名詞","meaning":"深夜便","example":"He took the red-eye from Los Angeles to arrive in New York by morning.","exampleJa":"彼は朝までにニューヨークに着くよう、ロサンゼルスからの深夜便に乗った。","hint":"夜通し飛んで寝不足の充血した目、という連想。夜に出発して朝に着く便。"},{"set":15,"word":"redress","pos":"名詞","meaning":"救済、是正","example":"Customers who were overcharged can seek redress through the company's complaints office.","exampleJa":"過剰請求された顧客は、会社の苦情窓口を通じて救済を求めることができる。","hint":"不当な扱いを受けた人が求める「是正・救済」。seek redress の形で、法的・公的な場面で使う。"},{"set":15,"word":"remedy","pos":"名詞","meaning":"救済策、解決策","example":"The only remedy for the faulty product was a full replacement.","exampleJa":"その欠陥製品に対する唯一の解決策は、新品との全面交換だった。","hint":"薬のように問題を「治す手段」。medicine の仲間の響きで、苦情への対処策に使う。"},{"set":15,"word":"room-service","pos":"名詞","meaning":"ルームサービス","example":"Room-service is available around the clock for guests on the executive floor.","exampleJa":"ルームサービスは、エグゼクティブフロアの宿泊客に24時間ご利用いただけます。","hint":"ホテルの部屋で電話一本で食事を届けてもらう場面。deliver to your room と結びつける。"},{"set":15,"word":"round-trip","pos":"形容詞","meaning":"往復の","example":"A round-trip ticket to Singapore costs less if you book three weeks ahead.","exampleJa":"シンガポールへの往復航空券は、3週間前に予約すると安くなる。","hint":"行って戻る「ぐるり」の旅。one-way（片道）との対比で、航空券の予約画面に出る。"},{"set":15,"word":"rsvp","pos":"動詞","meaning":"出欠を返事する","example":"Please rsvp by the end of this week so we can finalize the catering order.","exampleJa":"ケータリングの注文を確定できるよう、今週末までに出欠をご返信ください。","hint":"招待状の隅にある四文字。「出欠をお知らせください」という依頼で、動詞としても使う。"},{"set":15,"word":"seating","pos":"名詞","meaning":"座席配置","example":"The seating at the gala dinner was arranged by department.","exampleJa":"祝賀ディナーの座席配置は、部署ごとに行われた。","hint":"披露宴や会議の「誰がどこに座るか」の割り当て。seating chart と seating capacity の二つで覚える。"},{"set":15,"word":"shuttle","pos":"名詞","meaning":"シャトルバス","example":"A free shuttle runs between the hotel and the convention center every fifteen minutes.","exampleJa":"ホテルとコンベンションセンターの間を、15分おきに無料シャトルバスが運行している。","hint":"決まった二地点を行き来するバス。空港とホテル、駅と会場を結ぶ無料送迎として出る。"},{"set":15,"word":"simultaneous","pos":"形容詞","meaning":"同時の","example":"The conference offers simultaneous interpretation in English, Japanese, and Spanish.","exampleJa":"その会議では、英語、日本語、スペイン語の同時通訳が提供される。","hint":"二つのことが「同じ時に」起こる。同時通訳 simultaneous interpretation は国際会議の定番。"},{"set":15,"word":"standby","pos":"名詞","meaning":"補欠、待機","example":"Passengers on standby will be called to the gate if a seat becomes available.","exampleJa":"空席が出た場合は、キャンセル待ちの乗客が搭乗口に呼ばれる。","hint":"空席が出るのを待機する立場。on standby で「待機中」。満席便の空港カウンターの光景。"},{"set":15,"word":"stopover","pos":"名詞","meaning":"途中降機、立ち寄り","example":"Our trip includes a two-day stopover in Singapore on the way to Sydney.","exampleJa":"私たちの旅程には、シドニーへ向かう途中のシンガポールでの2日間の途中降機が含まれている。","hint":"乗り継ぎで目的地へ向かう途中、一泊するなど少し長めに降りること。layover との違いも意識。"},{"set":15,"word":"symposium","pos":"名詞","meaning":"シンポジウム","example":"Researchers from twelve countries will present their findings at the symposium.","exampleJa":"12か国の研究者が、そのシンポジウムで研究結果を発表する予定だ。","hint":"専門家が集まって特定のテーマを論じる会。conference よりやや学術的な響きがある。"},{"set":15,"word":"time-zone","pos":"名詞","meaning":"時間帯","example":"Please check which time-zone the webinar schedule is based on.","exampleJa":"ウェビナーの日程がどの時間帯を基準にしているか確認してください。","hint":"海外会議の日程調整で、「東京時間か現地時間か」を確認する場面。different time zones が定番。"},{"set":15,"word":"toast","pos":"名詞","meaning":"乾杯、祝杯の言葉","example":"The managing director raised her glass and proposed a toast to the new partnership.","exampleJa":"専務取締役はグラスを掲げ、新たな提携に乾杯の音頭を取った。","hint":"グラスを掲げて「乾杯！」と言う短いスピーチ。パンの toast と同じ綴りで、場面で区別する。"},{"set":15,"word":"toll","pos":"名詞","meaning":"通行料","example":"The toll on this bridge increases by one dollar next month.","exampleJa":"この橋の通行料は、来月から1ドル値上がりする。","hint":"高速道路や橋の料金所で払うお金。toll road, toll booth, toll-free（無料電話）とセットで覚える。"},{"set":15,"word":"translator","pos":"名詞","meaning":"翻訳者","example":"A professional translator will prepare the Japanese version of the user manual.","exampleJa":"プロの翻訳者が、取扱説明書の日本語版を作成する。","hint":"主に書かれた文書を訳す人。口頭で訳す interpreter との違いを意識する。"},{"set":15,"word":"troubleshoot","pos":"動詞","meaning":"問題解決する","example":"The technician spent an hour trying to troubleshoot the printer problem.","exampleJa":"技術者はプリンターの問題を解決しようと1時間を費やした。","hint":"trouble（問題）を探して直す、サポート担当者の仕事。troubleshooting guide は取扱説明書の章名。"},{"set":15,"word":"turbulence","pos":"名詞","meaning":"乱気流","example":"The pilot asked everyone to remain seated because of expected turbulence.","exampleJa":"機長は、乱気流が予想されるため、全員着席したままでいるよう求めた。","hint":"機内アナウンス「ベルト着用サイン」の理由。air turbulence、乱れた空気の揺れを思い浮かべる。"},{"set":15,"word":"valet","pos":"名詞","meaning":"駐車係、従者","example":"The valet parked our car and returned it as soon as we asked.","exampleJa":"駐車係は私たちの車を駐車し、依頼するとすぐに戻してくれた。","hint":"ホテルやレストランの入口で車を預けると、代わりに駐車してくれる人。valet parking で覚える。"},{"set":15,"word":"vegetarian","pos":"名詞","meaning":"菜食主義者","example":"The caterer prepared a separate meal for each vegetarian attending the luncheon.","exampleJa":"仕出し業者は、昼食会に出席する菜食主義者一人ひとりのために別の料理を用意した。","hint":"肉や魚を避ける人。機内食やケータリングの事前申告項目として出る。"},{"set":15,"word":"visa","pos":"名詞","meaning":"ビザ、査証","example":"You must obtain a work visa before starting your assignment overseas.","exampleJa":"海外での任務を始める前に、就労ビザを取得しなければならない。","hint":"パスポートに貼られる入国許可。海外出張の前に大使館や領事館で申請するもの。"},{"set":15,"word":"waitlist","pos":"名詞","meaning":"キャンセル待ちリスト","example":"Applicants who miss the deadline will be placed on the waitlist.","exampleJa":"締め切りに間に合わなかった申込者は、キャンセル待ちリストに載せられる。","hint":"満席のセミナーや便で、キャンセルが出たら繰り上げで入れる人の名簿。"},{"set":15,"word":"wake-up","pos":"名詞","meaning":"モーニングコール","example":"I would like to request a wake-up call at six tomorrow morning.","exampleJa":"明日の朝6時にモーニングコールをお願いしたいのですが。","hint":"wake-up call は、ホテルのフロントが指定時刻に電話で起こしてくれるサービス。「起こしの電話」と覚える。"},{"set":15,"word":"walk-in","pos":"形容詞","meaning":"予約なしの","example":"The clinic accepts walk-in patients every weekday afternoon without an appointment.","exampleJa":"そのクリニックは平日の午後、予約なしの患者を受け付けている。","hint":"予約せずに歩いて入ってくる人を想像する。walk-in customers は美容院や診療所で頻出。"},{"set":15,"word":"workaround","pos":"名詞","meaning":"回避策、応急処置","example":"The IT team found a temporary workaround while waiting for the software update.","exampleJa":"IT チームは、ソフトウェアの更新を待つ間の一時的な回避策を見つけた。","hint":"正式な修正を待つ間、障害の周りを回り込んで業務を続ける暫定手段。IT のサポート文書でよく見る。"}];
